INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主観", "is_correct": true, "explanation": "客観の対義語。「日記は主観で構わないが、新聞記事は客観」と対になる。"}, {"text": "感情", "is_correct": false, "explanation": "客観の対義語ではない。感情は見方そのものではない。"}, {"text": "空想", "is_correct": false, "explanation": "客観の対義語ではない。事実に基づかない想像で、対義関係は成立しない。"}, {"text": "直感", "is_correct": false, "explanation": "客観の対義語ではない。根拠を経ずに働く感覚で、対義関係は成立しない。"}], "correct_answer": "主観", "explanations": {"主観": "客観の対義語。「日記は主観で構わないが、新聞記事は客観」と対になる。", "感情": "客観の対義語ではない。感情は見方そのものではない。", "空想": "客観の対義語ではない。事実に基づかない想像で、対義関係は成立しない。", "直感": "客観の対義語ではない。根拠を経ずに働く感覚で、対義関係は成立しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「客観と自分の考え」で、二つを並べる正しい「と」。"}, {"text": "へ", "is_correct": false, "explanation": "「客観へ自分の考え」は方向の形になり、並列の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「客観から自分の考え」は起点の意味になり、文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「客観より自分の考え」は比較の意味になり、「ちがう」の文脈と合わない。"}], "correct_answer": "と", "explanations": {"と": "「客観と自分の考え」で、二つを並べる正しい「と」。", "へ": "「客観へ自分の考え」は方向の形になり、並列の意味にならない。", "から": "「客観から自分の考え」は起点の意味になり、文の意味が通らない。", "より": "「客観より自分の考え」は比較の意味になり、「ちがう」の文脈と合わない。"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主観", "is_correct": true, "explanation": "客観の対義語。「客観と主観をはっきり分けて書く」の対として成り立つ。"}, {"text": "推測", "is_correct": false, "explanation": "客観の対義語ではない。根拠に基づく予想で、対義関係にはならない。"}, {"text": "信念", "is_correct": false, "explanation": "客観の対義語ではない。確固とした考えを指し、見方の対にはならない。"}, {"text": "先入観", "is_correct": false, "explanation": "客観の対義語ではない。事前の思い込みで、対義関係は成立しない。"}], "correct_answer": "主観", "explanations": {"主観": "客観の対義語。「客観と主観をはっきり分けて書く」の対として成り立つ。", "推測": "客観の対義語ではない。根拠に基づく予想で、対義関係にはならない。", "信念": "客観の対義語ではない。確固とした考えを指し、見方の対にはならない。", "先入観": "客観の対義語ではない。事前の思い込みで、対義関係は成立しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の気持ちではなく、本当の事実のこと。", "primary_collocate": null, "pronunciation": "きゃっかん", "ipa": "kʲakkaɴ", "syllable_count": 4, "sentences": [{"text": "主観は自分の気持ちで、客観は本当の事実です。", "target_word": "客観", "complexity_tier": "T2", "furigana": "主観[しゅかん]は自分[じぶん]の気持[きも]ちで、客観[きゃっかん]は本当[ほんとう]の事実[じじつ]です。", "sentence_source": "generated"}, {"text": "「今日は気温が三十度だ」というのは客観です。", "target_word": "客観", "complexity_tier": "T2", "furigana": "「今日[きょう]は気温[きおん]が三十度[さんじゅうど]だ」というのは客観[きゃっかん]です。", "sentence_source": "generated"}, {"text": "気持ちは脇に置いて、客観だけで判断しよう。", "target_word": "客観", "complexity_tier": "T3", "furigana": "気持[きも]ちは脇[わき]に置[お]いて、客観[きゃっかん]だけで判断[はんだん]しよう。", "sentence_source": "generated"}, {"text": "日記は主観で構わないが、新聞記事は客観でなければならない。", "target_word": "客観", "complexity_tier": "T3", "furigana": "日記[にっき]は主観[しゅかん]で構[かま]わないが、新聞記事[しんぶんきじ]は客観[きゃっかん]でなければならない。", "sentence_source": "generated"}, {"text": "好きかどうかは主観で、重さや長さは客観だ。", "target_word": "客観", "complexity_tier": "T2", "furigana": "好[す]きかどうかは主観[しゅかん]で、重[おも]さや長[なが]さは客観[きゃっかん]だ。", "sentence_source": "generated"}, {"text": "けんかしたとき、客観の立場から話を聞いてくれる人が必要だった。", "target_word": "客観", "complexity_tier": "T3", "furigana": "けんかしたとき、客観[きゃっかん]の立場[たちば]から話[はなし]を聞[き]いてくれる人[ひと]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "先生は、生徒の主観と客観を分けて聞いた。", "target_word": "客観", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の主観[しゅかん]と客観[きゃっかん]を分[わ]けて聞[き]いた。", "sentence_source": "generated"}, {"text": "客観と自分の考えがちがうことは、よくある。", "target_word": "客観", "complexity_tier": "T3", "furigana": "客観[きゃっかん]と自分[じぶん]の考[かんが]えがちがうことは、よくある。", "sentence_source": "generated"}, {"text": "数字は客観だが、人の気持ちまでは示さない。", "target_word": "客観", "complexity_tier": "T3", "furigana": "数字[すうじ]は客観[きゃっかん]だが、人[ひと]の気持[きも]ちまでは示[しめ]さない。", "sentence_source": "generated"}, {"text": "作文では、客観と主観をはっきり分けて書こう。", "target_word": "客観", "complexity_tier": "T2", "furigana": "作文[さくぶん]では、客観[きゃっかん]と主観[しゅかん]をはっきり分[わ]けて書[か]こう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "客観", "label": "基本形"}, {"form": "客観的", "label": "形状詞(的)"}, {"form": "客観的に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "客観:自分の気持ちではない本当の事実(主観の対・やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客観", "is_correct": true, "explanation": "「〇〇は本当の事実です」の空所。本当の事実を指す語として文脈に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「感情は本当の事実です」では意味が通らない。感情は事実ではない。"}, {"text": "好み", "is_correct": false, "explanation": "「好みは本当の事実です」は、好みが事実ではないという点で文脈と矛盾する。"}, {"text": "直感", "is_correct": false, "explanation": "「直感は本当の事実です」は、直感が事実ではないという点で文脈と合わない。"}], "explanations": {"客観": "「〇〇は本当の事実です」の空所。本当の事実を指す語として文脈に合う。", "感情": "「感情は本当の事実です」では意味が通らない。感情は事実ではない。", "好み": "「好みは本当の事実です」は、好みが事実ではないという点で文脈と矛盾する。", "直感": "「直感は本当の事実です」は、直感が事実ではないという点で文脈と合わない。"}, "sentence_index": 0, "correct_answer": "客観"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "好きかどうかは、客観を食べて決める。", "explanation": "食べられるのは物などで、見方を表す客観は食べられない。ここは〈食べ物〉の意味。"}, {"text": "球場には客観が詰めかけた。", "explanation": "ここは〈観客〉の意味。客観は見方を表す語で、人の集まりは指さない。"}, {"text": "彼は合格の知らせに、客観を覚えた。", "explanation": "覚えるのは感慨や違和感などの感情で、見方を表す客観は覚えられない。ここは〈感慨〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客観", "is_correct": true, "explanation": "「生徒の主観と〇〇を分けて聞いた」の空所。主観と対になる見方として文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「主観と天気を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「主観と季節を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "「主観と教科書を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。"}], "explanations": {"客観": "「生徒の主観と〇〇を分けて聞いた」の空所。主観と対になる見方として文脈に合う。", "天気": "「主観と天気を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。", "季節": "「主観と季節を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。", "教科書": "「主観と教科書を分けて聞いた」は、主観と並べて分ける対象として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "客観"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の気持ちは客観として、よく伝わってきた。", "explanation": "気持ちは個人の感情なので主観。ここは〈客観〉の意味が逆になっている。"}, {"text": "感情を込めて朗読したように、客観を込めて朗読した。", "explanation": "込めるのは思いや気持ちで、見方を表す客観は込められない。ここは〈思い〉の意味。"}, {"text": "彼女は嘘をつかず、客観をついた。", "explanation": "つくのは偽りや冗談などで、見方を表す客観はつけない。ここは〈偽り〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "「寒い」と感じるのは客観だが、室温は客観だ。", "corrected_sentence": "「寒い」と感じるのは主観だが、室温は客観だ。", "error_description": "「寒い」と感じるのは個人の感覚なので「主観」が正しい。「客観」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気予報は客観を伝えるべきだ。", "corrected_sentence": "天気予報は客観的に伝えるべきだ。", "error_description": "「伝える」の様子は「客観的に」と副詞の形で示すので「客観的に伝える」が正しい。「客観を伝える」は名詞を目的語にする形で不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「客観の違い」で、「客観」に続けて「違い」を修飾する正しい連体の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「客観を違い」とは続かない。「違い」は対象を取る語ではない。"}, {"text": "に", "is_correct": false, "explanation": "「客観に違い」は不自然で、「違い」に続けるには合わない。"}, {"text": "で", "is_correct": false, "explanation": "「客観で違い」は手段や場所を表す形になり、文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「客観の違い」で、「客観」に続けて「違い」を修飾する正しい連体の「の」。", "を": "「客観を違い」とは続かない。「違い」は対象を取る語ではない。", "に": "「客観に違い」は不自然で、「違い」に続けるには合わない。", "で": "「客観で違い」は手段や場所を表す形になり、文の流れに合わない。"}, "error_tags": {"の": "連体修飾", "を": "対象", "に": "帰着点", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主観", "is_correct": true, "explanation": "客観の対義語。個人の感情による見方を指し、「感情を入れず客観に徹する」の対になる。"}, {"text": "感情", "is_correct": false, "explanation": "客観の対義語ではない。感情は見方そのものではなく、客観と対になる語とは言えない。"}, {"text": "空想", "is_correct": false, "explanation": "客観の対義語ではない。事実に基づかない想像で、主観とは別の概念。"}, {"text": "直感", "is_correct": false, "explanation": "客観の対義語ではない。根拠を経ずに働く感覚で、対義関係は成立しない。"}], "correct_answer": "主観", "explanations": {"主観": "客観の対義語。個人の感情による見方を指し、「感情を入れず客観に徹する」の対になる。", "感情": "客観の対義語ではない。感情は見方そのものではなく、客観と対になる語とは言えない。", "空想": "客観の対義語ではない。事実に基づかない想像で、主観とは別の概念。", "直感": "客観の対義語ではない。根拠を経ずに働く感覚で、対義関係は成立しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「客観の立場」で、「客観」に直接つき、「立場」を修飾する正しい連体の「の」。"}, {"text": "が", "is_correct": false, "explanation": "「客観が」は主語になるが、「立場」を修飾できず、文の流れに合わない。"}, {"text": "を", "is_correct": false, "explanation": "「客観を」は目的語になるが、「立場」を修飾せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「客観に」は帰着点を示し、「立場」を修飾しないため、「立場から問題を考えた」と噛み合わない。"}], "correct_answer": "の", "explanations": {"の": "「客観の立場」で、「客観」に直接つき、「立場」を修飾する正しい連体の「の」。", "が": "「客観が」は主語になるが、「立場」を修飾できず、文の流れに合わない。", "を": "「客観を」は目的語になるが、「立場」を修飾せず、文が成り立たない。", "に": "「客観に」は帰着点を示し、「立場」を修飾しないため、「立場から問題を考えた」と噛み合わない。"}, "error_tags": {"が": "主格", "を": "目的語", "に": "帰着点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主観", "is_correct": true, "explanation": "客観の対義語。「客観と主観をはっきり分けて書く」の対として成り立つ。"}, {"text": "憶測", "is_correct": false, "explanation": "客観の対義語ではない。根拠のない推量で、対義関係にはならない。"}, {"text": "信念", "is_correct": false, "explanation": "客観の対義語ではない。確固とした考えを指し、見方の対にはならない。"}, {"text": "先入観", "is_correct": false, "explanation": "客観の対義語ではない。事前の思い込みで、対義関係は成立しない。"}], "correct_answer": "主観", "explanations": {"主観": "客観の対義語。「客観と主観をはっきり分けて書く」の対として成り立つ。", "憶測": "客観の対義語ではない。根拠のない推量で、対義関係にはならない。", "信念": "客観の対義語ではない。確固とした考えを指し、見方の対にはならない。", "先入観": "客観の対義語ではない。事前の思い込みで、対義関係は成立しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "個人の考えや感情に左右されない、物事のありのままの状態や見方。", "primary_collocate": null, "pronunciation": "きゃっかん", "ipa": "kʲakkaɴ", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "客観", "complexity_tier": "T5", "furigana": "犯行[はんこう]の客観的[きゃっかんてき]裏付[うらづ]けという目的[もくてき]のため、この緻密[ちみつ]な照合[しょうごう]作業[さぎょう]を経[へ]て、初[はじ]めて不可謬[ふかびゅう]な身元[みもと]特定[とくてい]が達成[たっせい]されるのである。", "sentence_source": "mined"}, {"text": "主観と客観の違いを説明しなさい。", "target_word": "客観", "complexity_tier": "T3", "furigana": "主観[しゅかん]と客観[きゃっかん]の違[ちが]いを説明[せつめい]しなさい。", "sentence_source": "generated"}, {"text": "「おいしい」という感想は主観だが、測定した数字は客観である。", "target_word": "客観", "complexity_tier": "T3", "furigana": "「おいしい」という感想[かんそう]は主観[しゅかん]だが、測定[そくてい]した数字[すうじ]は客観[きゃっかん]である。", "sentence_source": "generated"}, {"text": "この記者は、感情を入れず客観に徹して記事を書く。", "target_word": "客観", "complexity_tier": "T4", "furigana": "この記者[きしゃ]は、感情[かんじょう]を入[い]れず客観[きゃっかん]に徹[てっ]して記事[きじ]を書[か]く。", "sentence_source": "generated"}, {"text": "哲学では、主観と客観の関係が長く議論されてきた。", "target_word": "客観", "complexity_tier": "T4", "furigana": "哲学[てつがく]では、主観[しゅかん]と客観[きゃっかん]の関係[かんけい]が長[なが]く議論[ぎろん]されてきた。", "sentence_source": "generated"}, {"text": "自分の作品について客観を保つのは、思ったより難しい。", "target_word": "客観", "complexity_tier": "T3", "furigana": "自分[じぶん]の作品[さくひん]について客観[きゃっかん]を保[たも]つのは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "事実をそのまま伝えるのが客観で、自分の感想を述べるのは主観だ。", "target_word": "客観", "complexity_tier": "T3", "furigana": "事実[じじつ]をそのまま伝[つた]えるのが客観[きゃっかん]で、自分[じぶん]の感想[かんそう]を述[の]べるのは主観[しゅかん]だ。", "sentence_source": "generated"}, {"text": "彼女は主観を捨てて、客観の立場から問題を考えた。", "target_word": "客観", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は主観[しゅかん]を捨[す]てて、客観[きゃっかん]の立場[たちば]から問題[もんだい]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "「塩分が多い」は客観で、「味が好きだ」は主観である。", "target_word": "客観", "complexity_tier": "T3", "furigana": "「塩分[えんぶん]が多[おお]い」は客観[きゃっかん]で、「味[あじ]が好[す]きだ」は主観[しゅかん]である。", "sentence_source": "generated"}, {"text": "裁判官には、感情に流されない客観が求められる。", "target_word": "客観", "complexity_tier": "T4", "furigana": "裁判官[さいばんかん]には、感情[かんじょう]に流[なが]されない客観[きゃっかん]が求[もと]められる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "客観", "label": "基本形"}, {"form": "客観的", "label": "形状詞(的)"}, {"form": "客観的に", "label": "連用形"}], "register": "formal", "sense_fingerprint": "客観:個人の感情に左右されない、物事のありのままの見方(主観の対)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客観", "is_correct": true, "explanation": "「犯行の〇〇的裏付け」の空所。「客観的裏付け」は個人の感情によらない証拠という意味で文脈に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「感情的な裏付け」は証拠として成り立たない。裏付けは事実に基づくもので、感情は証拠にならない。"}, {"text": "好み", "is_correct": false, "explanation": "「好み的な裏付け」では個人の判断になり、「不可謬な身元特定」を支える証拠の意味と噛み合わない。"}, {"text": "推測", "is_correct": false, "explanation": "「推測的な裏付け」は確かな証拠を指さず、文脈の「不可謬」と矛盾する。"}], "explanations": {"客観": "「犯行の〇〇的裏付け」の空所。「客観的裏付け」は個人の感情によらない証拠という意味で文脈に合う。", "感情": "「感情的な裏付け」は証拠として成り立たない。裏付けは事実に基づくもので、感情は証拠にならない。", "好み": "「好み的な裏付け」では個人の判断になり、「不可謬な身元特定」を支える証拠の意味と噛み合わない。", "推測": "「推測的な裏付け」は確かな証拠を指さず、文脈の「不可謬」と矛盾する。"}, "sentence_index": 0, "correct_answer": "客観"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "「おいしい」と言って、客観を味わった。", "explanation": "味わうのは味や雰囲気などの感覚で、見方を表す客観は味わえない。ここは〈感覚〉の意味。"}, {"text": "スタジアムは客観で満席になった。", "explanation": "ここは〈観客〉の意味。客観は見方を表す語で、人の集まりは指さない。"}, {"text": "彼は失敗の責任を客観に押しつけた。", "explanation": "客観は人や物を指す語ではないので、責任を押しつける相手にはならない。ここは〈他人〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客観", "is_correct": true, "explanation": "「事実をそのまま伝えるのが〇〇で」の空所。事実を示す見方は客観で、文脈に合う。"}, {"text": "偏見", "is_correct": false, "explanation": "「事実をそのまま伝えるのが偏見で」は意味が逆になり、文脈と噛み合わない。"}, {"text": "印象", "is_correct": false, "explanation": "印象は個人の受け取り方で、「事実をそのまま伝える」のとは合わない。"}, {"text": "思い込み", "is_correct": false, "explanation": "思い込みは主観的な決めつけで、事実を伝えることの説明には合わない。"}], "explanations": {"客観": "「事実をそのまま伝えるのが〇〇で」の空所。事実を示す見方は客観で、文脈に合う。", "偏見": "「事実をそのまま伝えるのが偏見で」は意味が逆になり、文脈と噛み合わない。", "印象": "印象は個人の受け取り方で、「事実をそのまま伝える」のとは合わない。", "思い込み": "思い込みは主観的な決めつけで、事実を伝えることの説明には合わない。"}, "sentence_index": 6, "correct_answer": "客観"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人は客観を込めて器を作った。", "explanation": "込めるのは思いや気持ちで、中立的な見方の客観は込められない。ここは〈思い〉の意味。"}, {"text": "長年の経験を客観に売り、若手を導いている。", "explanation": "売るのは商品や技術で、見方を表す客観は売り先にならない。ここは〈買い手〉の意味。"}, {"text": "彼は言葉を飾らず、客観をぶつけた。", "explanation": "ぶつけるのは本音や意見で、見方を表す客観は合わない。ここは〈本音〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "「甘い」という感想は客観だが、糖度の数字は客観である。", "corrected_sentence": "「甘い」という感想は主観だが、糖度の数字は客観である。", "error_description": "「感想」は個人の気持ちなので「主観」が正しい。「客観」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記者は感情を入れず、客観を徹して記事を書いた。", "corrected_sentence": "記者は感情を入れず、客観に徹して記事を書いた。", "error_description": "「徹する」は「に」で対象を示すので「客観に徹する」が正しい。「客観を」と助詞を誤ると、「徹する」の結び付きが成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「明らかな謬があり」で、存在する主語を示す正しい「が」。"}, {"text": "を", "is_correct": false, "explanation": "「明らかな謬を あり」は、存在を表す「ある」と結びつかず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「明らかな謬とあり」は並列の形にならず、存在を表す文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「明らかな謬からあり」は起点の形になり、存在を表す文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「明らかな謬があり」で、存在する主語を示す正しい「が」。", "を": "「明らかな謬を あり」は、存在を表す「ある」と結びつかず文が成り立たない。", "と": "「明らかな謬とあり」は並列の形にならず、存在を表す文として成り立たない。", "から": "「明らかな謬からあり」は起点の形になり、存在を表す文として成り立たない。"}, "error_tags": {"が": "主語", "を": "対象", "と": "並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「若い頃の謬を、彼は今でも悔やんでいる」で、悔やむ対象を示す正しい「を」。"}, {"text": "が", "is_correct": false, "explanation": "「若い頃の謬が、彼は今でも悔やんでいる」は主語が二つになり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「若い頃の謬へ、彼は今でも悔やんでいる」は方向の形になり、悔やむ対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「若い頃の謬より、彼は今でも悔やんでいる」は比較の形になり、文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「若い頃の謬を、彼は今でも悔やんでいる」で、悔やむ対象を示す正しい「を」。", "が": "「若い頃の謬が、彼は今でも悔やんでいる」は主語が二つになり、不自然。", "へ": "「若い頃の謬へ、彼は今でも悔やんでいる」は方向の形になり、悔やむ対象を示せない。", "より": "「若い頃の謬より、彼は今でも悔やんでいる」は比較の形になり、文脈に合わない。"}, "error_tags": {"を": "対象", "が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まちがいのこと。", "primary_collocate": null, "pronunciation": "びゅう", "ipa": "bʲɯː", "syllable_count": 2, "sentences": [{"text": "論証の謬を見つけるのは、思ったより難しい。", "target_word": "謬", "complexity_tier": "T3", "furigana": "論証[ろんしょう]の謬[びゅう]を見[み]つけるのは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼の説明には明らかな謬があり、誰も納得しなかった。", "target_word": "謬", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]には明[あき]らかな謬[びゅう]があり、誰[だれ]も納得[なっとく]しなかった。", "sentence_source": "generated"}, {"text": "歴史の謬を正すために、学者たちは資料を集めた。", "target_word": "謬", "complexity_tier": "T3", "furigana": "歴史[れきし]の謬[びゅう]を正[ただ]すために、学者[がくしゃ]たちは資料[しりょう]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "小さな謬でも、積み重なれば大きな失敗になる。", "target_word": "謬", "complexity_tier": "T3", "furigana": "小[ちい]さな謬[びゅう]でも、積[つ]み重[かさ]なれば大[おお]きな失敗[しっぱい]になる。", "sentence_source": "generated"}, {"text": "先生は作文の謬に赤ペンで線を引いた。", "target_word": "謬", "complexity_tier": "T3", "furigana": "先生[せんせい]は作文[さくぶん]の謬[びゅう]に赤[あか]ペンで線[せん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "謬に気づいた時点で、すぐに申し出るべきだ。", "target_word": "謬", "complexity_tier": "T3", "furigana": "謬[びゅう]に気[き]づいた時点[じてん]で、すぐに申[もう]し出[で]るべきだ。", "sentence_source": "generated"}, {"text": "翻訳の謬が原因で、契約の内容が誤解された。", "target_word": "謬", "complexity_tier": "T4", "furigana": "翻訳[ほんやく]の謬[びゅう]が原因[げんいん]で、契約[けいやく]の内容[ないよう]が誤解[ごかい]された。", "sentence_source": "generated"}, {"text": "若い頃の謬を、彼は今でも悔やんでいる。", "target_word": "謬", "complexity_tier": "T3", "furigana": "若[わか]い頃[ころ]の謬[びゅう]を、彼[かれ]は今[いま]でも悔[く]やんでいる。", "sentence_source": "generated"}, {"text": "辞書の謬を見つけて、出版社に知らせた。", "target_word": "謬", "complexity_tier": "T3", "furigana": "辞書[じしょ]の謬[びゅう]を見[み]つけて、出版社[しゅっぱんしゃ]に知[し]らせた。", "sentence_source": "generated"}, {"text": "数字の謬があったので、会議の資料を直した。", "target_word": "謬", "complexity_tier": "T3", "furigana": "数字[すうじ]の謬[びゅう]があったので、会議[かいぎ]の資料[しりょう]を直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "謬", "label": "基本形"}], "register": "文語的・書き言葉", "sense_fingerprint": "謬: 正しくないこと、まちがい(書き言葉)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "謬", "is_correct": true, "explanation": "「論証の〇〇を見つけるのは」の空所。論証の誤りを指す語として文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「論証の色を見つける」は文脈に合わず、論証の誤りを指さない。"}, {"text": "味", "is_correct": false, "explanation": "「論証の味を見つける」は文脈に合わず、論証の誤りを指さない。"}, {"text": "天気", "is_correct": false, "explanation": "「論証の天気を見つける」は文脈に合わず、論証の誤りを指さない。"}], "explanations": {"謬": "「論証の〇〇を見つけるのは」の空所。論証の誤りを指す語として文脈に合う。", "色": "「論証の色を見つける」は文脈に合わず、論証の誤りを指さない。", "味": "「論証の味を見つける」は文脈に合わず、論証の誤りを指さない。", "天気": "「論証の天気を見つける」は文脈に合わず、論証の誤りを指さない。"}, "sentence_index": 0, "correct_answer": "謬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は小さな謬をたくさん持ち、人を惹きつける。", "explanation": "謬は誤りを指し、人の個性や魅力は表さない。ここは〈個性〉の意味。"}, {"text": "彼は小さな謬を大声で歌い、周囲を楽しませた。", "explanation": "歌うのは曲や歌詞で、誤りを指す謬は歌えない。ここは〈曲〉の意味。"}, {"text": "小さな謬を一つずつ貯めて、大きな額にした。", "explanation": "貯めるのは小銭やお金で、謬は誤りなので貯められない。ここは〈小銭〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "謬", "is_correct": true, "explanation": "「翻訳の〇〇が原因で」の空所。翻訳の誤りを指す語として文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「翻訳の天気が原因で」は、誤訳の原因を指す語として文脈に合わない。"}, {"text": "無知", "is_correct": false, "explanation": "「翻訳の無知が原因で」は知識不足を指し、誤訳の原因としては意味がずれる。"}, {"text": "指輪", "is_correct": false, "explanation": "「翻訳の指輪が原因で」は、誤訳の原因を指す語として文脈に合わない。"}], "explanations": {"謬": "「翻訳の〇〇が原因で」の空所。翻訳の誤りを指す語として文脈に合う。", "天気": "「翻訳の天気が原因で」は、誤訳の原因を指す語として文脈に合わない。", "無知": "「翻訳の無知が原因で」は知識不足を指し、誤訳の原因としては意味がずれる。", "指輪": "「翻訳の指輪が原因で」は、誤訳の原因を指す語として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "謬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は数字の謬を描いて、会議に出した。", "explanation": "描くのは絵や情景で、誤りを指す謬は描けない。ここは〈絵〉の意味。"}, {"text": "会議で資料の謬を温めたので、説明がスムーズになった。", "explanation": "温めるのは料理や気持ちで、誤りを指す謬は温められない。ここは〈料理〉の意味。"}, {"text": "彼は数字の謬に恵まれていて、会議の資料を作った。", "explanation": "恵まれるのは才能や環境で、謬は人に備わるものではない。ここは〈才能〉の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生は論証の謬が見つけて、先生に相談した。", "corrected_sentence": "学生は論証の謬を見つけて、先生に相談した。", "error_description": "「見つける」は他動詞なので目的語に「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52617, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記者は記事の謬な箇所を指摘されて、すぐに訂正した。", "corrected_sentence": "記者は記事の謬の箇所を指摘されて、すぐに訂正した。", "error_description": "「謬」は名詞なので「な」で直接修飾できない。「謬の箇所」と「の」でつなぐ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わかる」は「〜がわかる」と主語を「が」で示すので、「身元がわかり」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、「わかる」は対象を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「身元で〜わかり」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示し、ここで「わかり」につながらない。"}], "correct_answer": "が", "explanations": {"が": "「わかる」は「〜がわかる」と主語を「が」で示すので、「身元がわかり」が正しい。", "を": "「を」は対象を示すが、「わかる」は対象を取らないので合わない。", "で": "「で」は手段や場所を示し、「身元で〜わかり」は文が成り立たない。", "より": "「より」は比較や起点を示し、ここで「わかり」につながらない。"}, "error_tags": {"が": "主語", "を": "対象", "で": "手段・場所", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「身元は」で話題を示し、「わからなかった」へつなぐので自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示し、「わからなかった」の主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示し、ここでは文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、わからなかった対象を表さないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「身元は」で話題を示し、「わからなかった」へつなぐので自然に成り立つ。", "に": "「に」は方向や相手を示し、「わからなかった」の主語を示せない。", "と": "「と」は並列や共同を示し、ここでは文が成り立たない。", "へ": "「へ」は方向を示し、わからなかった対象を表さないので合わない。"}, "error_tags": {"は": "主題", "に": "方向・相手", "と": "並列・共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある人がだれかわかること。", "primary_collocate": null, "pronunciation": "みもと", "ipa": "mimoto", "syllable_count": 3, "sentences": [{"text": "発見された遺体の身元が、ようやく判明した。", "target_word": "身元", "complexity_tier": "T3", "furigana": "発見[はっけん]された遺体[いたい]の身元[みもと]が、ようやく判明[はんめい]した。", "sentence_source": "generated"}, {"text": "犯人の身元がわかり、警察は逮捕に向かった。", "target_word": "身元", "complexity_tier": "T3", "furigana": "犯人[はんにん]の身元[みもと]がわかり、警察[けいさつ]は逮捕[たいほ]に向[む]かった。", "sentence_source": "generated"}, {"text": "迷子の子どもの身元を知るため、係員が名前を聞いた。", "target_word": "身元", "complexity_tier": "T3", "furigana": "迷子[まいご]の子[こ]どもの身元[みもと]を知[し]るため、係員[かかりいん]が名前[なまえ]を聞[き]いた。", "sentence_source": "generated"}, {"text": "病院に運ばれた旅行者は、身元がわからないままだった。", "target_word": "身元", "complexity_tier": "T3", "furigana": "病院[びょういん]に運[はこ]ばれた旅行者[りょこうしゃ]は、身元[みもと]がわからないままだった。", "sentence_source": "generated"}, {"text": "彼女は身元が割れるのを恐れて、顔を隠した。", "target_word": "身元", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は身元[みもと]が割[わ]れるのを恐[おそ]れて、顔[かお]を隠[かく]した。", "sentence_source": "generated"}, {"text": "指紋から容疑者の身元が特定された。", "target_word": "身元", "complexity_tier": "T3", "furigana": "指紋[しもん]から容疑者[ようぎしゃ]の身元[みもと]が特定[とくてい]された。", "sentence_source": "generated"}, {"text": "身元がはっきりしない人には、部屋を貸せない。", "target_word": "身元", "complexity_tier": "T3", "furigana": "身元[みもと]がはっきりしない人[ひと]には、部屋[へや]を貸[か]せない。", "sentence_source": "generated"}, {"text": "写真の人物の身元は、誰にもわからなかった。", "target_word": "身元", "complexity_tier": "T3", "furigana": "写真[しゃしん]の人物[じんぶつ]の身元[みもと]は、誰[だれ]にもわからなかった。", "sentence_source": "generated"}, {"text": "身元のわかる品が何もなく、捜査は難航した。", "target_word": "身元", "complexity_tier": "T4", "furigana": "身元[みもと]のわかる品[しな]が何[なに]もなく、捜査[そうさ]は難航[なんこう]した。", "sentence_source": "generated"}, {"text": "持ち主の身元が判明し、財布は無事に返された。", "target_word": "身元", "complexity_tier": "T3", "furigana": "持[も]ち主[ぬし]の身元[みもと]が判明[はんめい]し、財布[さいふ]は無事[ぶじ]に返[かえ]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身元", "label": "基本形"}], "register": "中立", "sense_fingerprint": "身元: ある人物が誰であるかが判明すること・その人の素性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身元", "is_correct": true, "explanation": "「遺体の身元が判明した」は、誰であるかがわかったという意味で通る。"}, {"text": "天気", "is_correct": false, "explanation": "遺体の天気が判明するという内容は成り立たず、身元の代わりにならない。"}, {"text": "味覚", "is_correct": false, "explanation": "遺体の味覚が判明するという内容は成り立たず、ここに入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は判明の対象としては不自然で、「遺体の〜が判明した」に合わない。"}], "explanations": {"身元": "「遺体の身元が判明した」は、誰であるかがわかったという意味で通る。", "天気": "遺体の天気が判明するという内容は成り立たず、身元の代わりにならない。", "味覚": "遺体の味覚が判明するという内容は成り立たず、ここに入らない。", "寿命": "寿命は判明の対象としては不自然で、「遺体の〜が判明した」に合わない。"}, "sentence_index": 0, "correct_answer": "身元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は身元が軽やかで、舞台でも目を引く動きをした。", "explanation": "ここは〈身のこなし〉（体の動かし方）の意味。身元は人を特定する情報で、体の動きは表さないので合わない。"}, {"text": "身元の品を整理して、部屋を空けた。", "explanation": "ここは〈身の回り〉（身の周りの持ち物）の意味。身元は持ち物を指さないので合わない。"}, {"text": "身元が足りず、電車に乗れなかった。", "explanation": "ここは〈所持金〉の意味。身元はお金の額を表さないので、電車に乗れない理由にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身元", "is_correct": true, "explanation": "「身元がはっきりしない人」は、誰であるかが不明な人という意味で通る。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息がはっきりしない人という表現は成り立たず、ここに入らない。"}, {"text": "年輪", "is_correct": false, "explanation": "年輪がはっきりしない人という表現は成り立たず、ここに入らない。"}, {"text": "足音", "is_correct": false, "explanation": "足音がはっきりしない人という表現は成り立たず、部屋を貸せない理由にならない。"}], "explanations": {"身元": "「身元がはっきりしない人」は、誰であるかが不明な人という意味で通る。", "寝息": "寝息がはっきりしない人という表現は成り立たず、ここに入らない。", "年輪": "年輪がはっきりしない人という表現は成り立たず、ここに入らない。", "足音": "足音がはっきりしない人という表現は成り立たず、部屋を貸せない理由にならない。"}, "sentence_index": 6, "correct_answer": "身元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は明るい身元で、誰とでもすぐ打ち解ける。", "explanation": "ここは〈人柄〉（性格や人となり）の意味。身元は誰かを示す情報で、性格は表さないので合わない。"}, {"text": "事件の身元を報告した。", "explanation": "ここは〈経過〉（物事の進みぐあい）の意味。身元は人を特定する情報で、事の進展は指さないので合わない。"}, {"text": "身元が少なく、引っ越しは楽だった。", "explanation": "ここは〈所持品〉の意味。身元は人の情報で、持ち物の量は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "行方不明の女性の身元を判明した。", "corrected_sentence": "行方不明の女性の身元が判明した。", "error_description": "「判明する」は自動詞なので「身元が判明する」。「身元を判明した」の「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52619, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犯人の身元を解決するため、捜査が続いている。", "corrected_sentence": "犯人の身元を明らかにするため、捜査が続いている。", "error_description": "「身元」には「明らかにする」が結びつく。「解決する」は事件や問題に使う語で、身元とは組み合わさない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」は対象を「を」で取るので、「身元を調べている」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「身元が調べている」では身元が調べる側になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すため、調べる対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、調べる対象を表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」は対象を「を」で取るので、「身元を調べている」が正しい。", "が": "「が」は主語を示すため、「身元が調べている」では身元が調べる側になり不自然。", "に": "「に」は方向や相手を示すため、調べる対象を表せない。", "へ": "「へ」は方向を示し、調べる対象を表せないので合わない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「保証する」は対象を「を」で取るので、「身元を保証してくれる」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「保証する」の対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すため、保証の対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、保証の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「保証する」は対象を「を」で取るので、「身元を保証してくれる」が正しい。", "へ": "「へ」は方向を示し、「保証する」の対象にならない。", "と": "「と」は並列や共同を示すため、保証の対象を表せない。", "から": "「から」は起点を示し、保証の対象にはならない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列・共同", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分が誰であるかを示す、名前や住所などの情報。", "primary_collocate": null, "pronunciation": "みもと", "ipa": "mimoto", "syllable_count": 3, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "身元", "complexity_tier": "T5", "furigana": "犯行[はんこう]の客観的[きゃっかんてき]裏付[うらづ]けという目的[もくてき]のため、この緻密[ちみつ]な照合[しょうごう]作業[さぎょう]を経[へ]て、初[はじ]めて不可謬[ふかびゅう]な身元[みもと]特定[とくてい]が達成[たっせい]されるのである。", "sentence_source": "mined"}, {"text": "警察は倒れていた男性の身元を調べている。", "target_word": "身元", "complexity_tier": "T3", "furigana": "警察[けいさつ]は倒[たお]れていた男性[だんせい]の身元[みもと]を調[しら]べている。", "sentence_source": "generated"}, {"text": "銀行で口座を作るときは、身元がわかる書類が必要だ。", "target_word": "身元", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]で口座[こうざ]を作[つく]るときは、身元[みもと]がわかる書類[しょるい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "身元を示すカードを落としたので、再発行を頼んだ。", "target_word": "身元", "complexity_tier": "T3", "furigana": "身元[みもと]を示[しめ]すカードを落[お]としたので、再発行[さいはっこう]を頼[たの]んだ。", "sentence_source": "generated"}, {"text": "事故の被害者は、持ち物から身元が確認された。", "target_word": "身元", "complexity_tier": "T3", "furigana": "事故[じこ]の被害者[ひがいしゃ]は、持[も]ち物[もの]から身元[みもと]が確認[かくにん]された。", "sentence_source": "generated"}, {"text": "このアパートは、入居者の身元を厳しく審査する。", "target_word": "身元", "complexity_tier": "T4", "furigana": "このアパートは、入居者[にゅうきょしゃ]の身元[みもと]を厳[きび]しく審査[しんさ]する。", "sentence_source": "generated"}, {"text": "彼は名前も住所も言わず、身元を隠したままだった。", "target_word": "身元", "complexity_tier": "T3", "furigana": "彼[かれ]は名前[なまえ]も住所[じゅうしょ]も言[い]わず、身元[みもと]を隠[かく]したままだった。", "sentence_source": "generated"}, {"text": "身元を保証してくれる人がいないと、就職は難しい。", "target_word": "身元", "complexity_tier": "T3", "furigana": "身元[みもと]を保証[ほしょう]してくれる人[ひと]がいないと、就職[しゅうしょく]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "免許証は、身元を証明するために使える。", "target_word": "身元", "complexity_tier": "T3", "furigana": "免許証[めんきょしょう]は、身元[みもと]を証明[しょうめい]するために使[つか]える。", "sentence_source": "generated"}, {"text": "手紙の差出人の身元は、結局わからなかった。", "target_word": "身元", "complexity_tier": "T3", "furigana": "手紙[てがみ]の差出人[さしだしにん]の身元[みもと]は、結局[けっきょく]わからなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身元", "label": "基本形"}], "register": "中立", "sense_fingerprint": "身元: 名前・住所・経歴など、その人が誰かを示す情報", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身元", "is_correct": true, "explanation": "「不可謬な身元特定」は、人が誰かを特定することを表し、ここで意味が通る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は人物の素性ではないので、「不可謬な〜特定」に入らない。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は人を特定する情報ではなく、「〜特定」の対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は人が誰かを示す情報ではなく、ここでは「特定」の対象として不自然。"}], "explanations": {"身元": "「不可謬な身元特定」は、人が誰かを特定することを表し、ここで意味が通る。", "天気": "天気は人物の素性ではないので、「不可謬な〜特定」に入らない。", "味覚": "味覚は人を特定する情報ではなく、「〜特定」の対象にならない。", "寿命": "寿命は人が誰かを示す情報ではなく、ここでは「特定」の対象として不自然。"}, "sentence_index": 0, "correct_answer": "身元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は身元が重く、階段を上がるのに苦労した。", "explanation": "ここは〈身体〉の重さの意味。身元は人の情報で、体の重さは表さないので合わない。"}, {"text": "犯人は身元を拘束され、警察署に連れて行かれた。", "explanation": "ここは〈身柄〉（人そのもの）の意味。拘束するのは人で、身元は情報なので合わない。"}, {"text": "この店は、身元を値下げして客を呼び込んだ。", "explanation": "ここは〈値段〉の意味。身元は人の情報で、商品の値段は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身元", "is_correct": true, "explanation": "「身元を隠したまま」は、誰であるかの情報を隠すという意味で自然に通る。"}, {"text": "年輪", "is_correct": false, "explanation": "年輪は木の成長の跡で、人の情報として隠すものではないので入らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は隠す対象として不自然で、名前や住所と並ぶ文脈に合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は隠す対象にならず、「隠したまま」と結びつかない。"}], "explanations": {"身元": "「身元を隠したまま」は、誰であるかの情報を隠すという意味で自然に通る。", "年輪": "年輪は木の成長の跡で、人の情報として隠すものではないので入らない。", "季節": "季節は隠す対象として不自然で、名前や住所と並ぶ文脈に合わない。", "寝息": "寝息は隠す対象にならず、「隠したまま」と結びつかない。"}, "sentence_index": 6, "correct_answer": "身元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は身元を広げて、朝のストレッチを始めた。", "explanation": "ここは〈身体〉の意味。身元は人の情報で、体そのものは表さないので合わない。"}, {"text": "彼は身元がだらしないので、面接で落とされた。", "explanation": "ここは〈身なり〉（服装や外見）の意味。身元は人を特定する情報で、外見の様子は表さないので合わない。"}, {"text": "この壺の身元は、古い記録に残っている。", "explanation": "ここは〈来歴〉（物の由来や経緯）の意味。身元は人を特定する情報で、物には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "受付で身元に確かめるため、免許証を出した。", "corrected_sentence": "受付で身元を確かめるため、免許証を出した。", "error_description": "「確かめる」は「〜を確かめる」と対象を「を」で示す。「身元に」は誤りで、正しくは「身元を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52620, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は身元に偽って、会社に入った。", "corrected_sentence": "彼は身元を偽って、会社に入った。", "error_description": "「偽る」は対象を「を」で示す。「身元に」は誤りで、正しくは「身元を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「解き明かす」の対象を「を」で示すので、「謎を解き明かした」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「謎が解き明かした」は主語の形になり、他動詞の対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示し、解き明かす対象を表せないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「謎で解き明かした」は手段や場所を示し、対象の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「解き明かす」の対象を「を」で示すので、「謎を解き明かした」が正しい。", "が": "「謎が解き明かした」は主語の形になり、他動詞の対象を示せない。", "に": "「に」は方向や相手を示し、解き明かす対象を表せないので合わない。", "で": "「謎で解き明かした」は手段や場所を示し、対象の意味にならない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「解き明かす」の対象を「を」で示すので、「謎を解き明かす」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「謎へ解き明かす」は方向を示し、解き明かす対象を表せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示し、解き明かす対象を表せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「謎の解き明かす鍵」は所属や修飾を示し、動詞「解き明かす」の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「解き明かす」の対象を「を」で示すので、「謎を解き明かす」が正しい。", "へ": "「謎へ解き明かす」は方向を示し、解き明かす対象を表せないので合わない。", "に": "「に」は方向や相手を示し、解き明かす対象を表せないので合わない。", "の": "「謎の解き明かす鍵」は所属や修飾を示し、動詞「解き明かす」の対象にならない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列・共同", "に": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "わからなかったことを、はっきりわかるようにする。", "primary_collocate": null, "pronunciation": "ときあかす", "ipa": "tokiakasɯ", "syllable_count": 5, "sentences": [{"text": "長年の謎を解き明かしたとき、彼は思わず叫んだ。", "target_word": "解き明かした", "complexity_tier": "T3", "furigana": "長年[ながねん]の謎[なぞ]を解[と]き明[あ]かしたとき、彼[かれ]は思[おも]わず叫[さけ]んだ。", "sentence_source": "generated"}, {"text": "名探偵は、残された手がかりから事件の謎を解き明かした。", "target_word": "解き明かした", "complexity_tier": "T3", "furigana": "名探偵[めいたんてい]は、残[のこ]された手[て]がかりから事件[じけん]の謎[なぞ]を解[と]き明[あ]かした。", "sentence_source": "generated"}, {"text": "私は祖父の過去を解き明かしたくて、古い日記を読んだ。", "target_word": "解き明かし", "complexity_tier": "T3", "furigana": "私[わたし]は祖父[そふ]の過去[かこ]を解[と]き明[あ]かしたくて、古[ふる]い日記[にっき]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "生き物の不思議な行動を解き明かすのが、私の夢だ。", "target_word": "解き明かす", "complexity_tier": "T3", "furigana": "生[い]き物[もの]の不思議[ふしぎ]な行動[こうどう]を解[と]き明[あ]かすのが、私[わたし]の夢[ゆめ]だ。", "sentence_source": "generated"}, {"text": "暗号を解き明かすまでに、三日もかかった。", "target_word": "解き明かす", "complexity_tier": "T3", "furigana": "暗号[あんごう]を解[と]き明[あ]かすまでに、三日[みっか]もかかった。", "sentence_source": "generated"}, {"text": "先生は数学の難問を、順を追って解き明かした。", "target_word": "解き明かした", "complexity_tier": "T3", "furigana": "先生[せんせい]は数学[すうがく]の難問[なんもん]を、順[じゅん]を追[お]って解[と]き明[あ]かした。", "sentence_source": "generated"}, {"text": "彼の沈黙の理由を解き明かそうと、友人は話を聞き続けた。", "target_word": "解き明かそう", "complexity_tier": "T4", "furigana": "彼[かれ]の沈黙[ちんもく]の理由[りゆう]を解[と]き明[あ]かそうと、友人[ゆうじん]は話[はなし]を聞[き]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "この謎を解き明かす鍵は、まだ見つかっていない。", "target_word": "解き明かす", "complexity_tier": "T3", "furigana": "この謎[なぞ]を解[と]き明[あ]かす鍵[かぎ]は、まだ見[み]つかっていない。", "sentence_source": "generated"}, {"text": "彼女は夢の意味を解き明かす本を読んでいる。", "target_word": "解き明かす", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は夢[ゆめ]の意味[いみ]を解[と]き明[あ]かす本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "博士は星の動きから暦の仕組みを解き明かした。", "target_word": "解き明かした", "complexity_tier": "T4", "furigana": "博士[はかせ]は星[ほし]の動[うご]きから暦[こよみ]の仕組[しく]みを解[と]き明[あ]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解き明かす", "label": "終止形"}, {"form": "解き明かした", "label": "過去形"}, {"form": "解き明かして", "label": "て形"}, {"form": "解き明かさない", "label": "否定形"}, {"form": "解き明かせば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "解き明かす: わからなかった謎や疑問をはっきりさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解き明かした", "is_correct": true, "explanation": "「長年の謎を解き明かしたとき」は、謎がはっきりした時点を表し、過去形で意味が通る。"}, {"text": "数えた", "is_correct": false, "explanation": "長年の謎を数えたとき、という内容は意味をなさず、この文脈に合わない。"}, {"text": "売り払った", "is_correct": false, "explanation": "長年の謎を売り払ったときという内容は成り立たず、叫んだ場面とも合わない。"}, {"text": "踏み潰した", "is_correct": false, "explanation": "長年の謎を踏み潰したときという内容は文脈に合わず、思わず叫ぶ理由にならない。"}], "explanations": {"解き明かした": "「長年の謎を解き明かしたとき」は、謎がはっきりした時点を表し、過去形で意味が通る。", "数えた": "長年の謎を数えたとき、という内容は意味をなさず、この文脈に合わない。", "売り払った": "長年の謎を売り払ったときという内容は成り立たず、叫んだ場面とも合わない。", "踏み潰した": "長年の謎を踏み潰したときという内容は文脈に合わず、思わず叫ぶ理由にならない。"}, "sentence_index": 0, "correct_answer": "解き明かした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は彼の誕生日を解き明かすことにした。", "explanation": "ここは〈祝う〉の意味。解き明かすは隠れた事柄を説明する語で、祝い事には使えないので合わない。"}, {"text": "彼女はきれいな服を解き明かして出かけた。", "explanation": "ここは〈着る〉の意味。解き明かすは謎を説明することで、衣服を身につける意味は持たないので合わない。"}, {"text": "靴を解き明かして、ピカピカにした。", "explanation": "ここは〈磨く〉の意味。解き明かすは隠れた事柄を明らかにする語で、表面をこする意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解き明かそう", "is_correct": true, "explanation": "「理由を解き明かそうと、友人は話を聞き続けた」は、理由を明らかにしようとという意味で通る。"}, {"text": "焼き払おう", "is_correct": false, "explanation": "理由を焼き払うと、という内容は成り立たず、友人が話を聞く流れに合わない。"}, {"text": "織ろう", "is_correct": false, "explanation": "理由を織るという内容は意味をなさず、この文脈に入らない。"}, {"text": "摘もう", "is_correct": false, "explanation": "理由を摘むという内容は文脈に合わず、話を聞き続ける理由にならない。"}], "explanations": {"解き明かそう": "「理由を解き明かそうと、友人は話を聞き続けた」は、理由を明らかにしようとという意味で通る。", "焼き払おう": "理由を焼き払うと、という内容は成り立たず、友人が話を聞く流れに合わない。", "織ろう": "理由を織るという内容は意味をなさず、この文脈に入らない。", "摘もう": "理由を摘むという内容は文脈に合わず、話を聞き続ける理由にならない。"}, "sentence_index": 6, "correct_answer": "解き明かそう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農夫は朝早くから畑を解き明かした。", "explanation": "ここは〈耕す〉（土を掘り返す）の意味。解き明かすは隠れた事柄を説明する語で、土を掘る意味には使えないので合わない。"}, {"text": "母はシャツの破れを解き明かした。", "explanation": "ここは〈縫う〉（糸でつなぐ）の意味。解き明かすは謎を説明することで、布を縫う意味は持たないので合わない。"}, {"text": "彼は週末に山を解き明かした。", "explanation": "ここは〈登る〉（上へ進む）の意味。解き明かすは隠れた事柄を明らかにする語で、山を上る意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は星の謎を解き明かしたいが願った。", "corrected_sentence": "研究者は星の謎を解き明かしたいと願った。", "error_description": "「〜したいと願う」の「と」が必要。「が」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "解き明かした", "is_correct": true, "explanation": "「名探偵は〜を解き明かした」と、過去の出来事を述べる過去形が正しい。"}, {"text": "解き明かして", "is_correct": false, "explanation": "「解き明かして」は文を終えられず、述語として成り立たない。"}, {"text": "解き明かせば", "is_correct": false, "explanation": "「解き明かせば」は仮定の形で、出来事を述べる文末にはならない。"}, {"text": "解き明かさ", "is_correct": false, "explanation": "「解き明かさ」は未然形で、文を終える形として成り立たない。"}], "correct_form": "解き明かした", "base_form": "解き明かす", "form_label": "過去形", "sentence_index": 1, "explanations": {"解き明かした": "「名探偵は〜を解き明かした」と、過去の出来事を述べる過去形が正しい。", "解き明かして": "「解き明かして」は文を終えられず、述語として成り立たない。", "解き明かせば": "「解き明かせば」は仮定の形で、出来事を述べる文末にはならない。", "解き明かさ": "「解き明かさ」は未然形で、文を終える形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52621, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人は、彼が隠す本心を解決しようと努力した。", "corrected_sentence": "友人は、彼が隠す本心を解き明かそうと努力した。", "error_description": "「本心」には「解き明かす」が結びつく。「解決する」は問題や事件に使う語で、本心とは組み合わさない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "解き明かす", "is_correct": true, "explanation": "「この謎を解き明かす鍵は」と、後ろの名詞を修飾する連体形（辞書形と同じ形）が正しい。"}, {"text": "解き明かせ", "is_correct": false, "explanation": "「解き明かせ」は命令形で、名詞「鍵」を修飾する形としては成り立たない。"}, {"text": "解き明かし", "is_correct": false, "explanation": "「解き明かし」は連用形で、「鍵は」に続く形として成り立たない。"}, {"text": "解き明かされ", "is_correct": false, "explanation": "「解き明かされ」は受身の連用形で、名詞を修飾する形として成り立たない。"}], "correct_form": "解き明かす", "base_form": "解き明かす", "form_label": "連体形", "sentence_index": 7, "explanations": {"解き明かす": "「この謎を解き明かす鍵は」と、後ろの名詞を修飾する連体形（辞書形と同じ形）が正しい。", "解き明かせ": "「解き明かせ」は命令形で、名詞「鍵」を修飾する形としては成り立たない。", "解き明かし": "「解き明かし」は連用形で、「鍵は」に続く形として成り立たない。", "解き明かされ": "「解き明かされ」は受身の連用形で、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「〜ようとする」の「と」で、意志を伴う動作を示すので「解き明かそうと」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「解き明かそうが」では主語や対象を示せず、後ろの「してきた」につながらない。"}, {"text": "に", "is_correct": false, "explanation": "「解き明かそうに」は方向や時点を示し、ここでは文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「解き明かそうで」は手段や場所を示し、続く動詞と結びつかない。"}], "correct_answer": "と", "explanations": {"と": "「〜ようとする」の「と」で、意志を伴う動作を示すので「解き明かそうと」が正しい。", "が": "「解き明かそうが」では主語や対象を示せず、後ろの「してきた」につながらない。", "に": "「解き明かそうに」は方向や時点を示し、ここでは文が成り立たない。", "で": "「解き明かそうで」は手段や場所を示し、続く動詞と結びつかない。"}, "error_tags": {"と": "引用・意向", "が": "主語", "に": "方向・時点", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
