INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複雑で隠れていた事柄を、はっきりと理解できるように説明したり、明らかにしたりすること。", "primary_collocate": null, "pronunciation": "ときあかす", "ipa": "tokiakasɯ", "syllable_count": 5, "sentences": [{"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "解き明かす", "complexity_tier": "T5", "furigana": "真実[しんじつ]を解[と]き明[あ]かすための静謐[せいひつ]かつ論理的[ろんりてき]なプロセス、それこそが指紋[しもん]分析[ぶんせき]の真髄[しんずい]と言[い]えよう。", "sentence_source": "mined"}, {"text": "科学者たちは長年、星の誕生の謎を解き明かそうとしてきた。", "target_word": "解き明かそう", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちは長年[ながねん]、星[ほし]の誕生[たんじょう]の謎[なぞ]を解[と]き明[あ]かそうとしてきた。", "sentence_source": "generated"}, {"text": "探偵は事件の真相を解き明かし、犯人を指摘した。", "target_word": "解き明かし", "complexity_tier": "T3", "furigana": "探偵[たんてい]は事件[じけん]の真相[しんそう]を解[と]き明[あ]かし、犯人[はんにん]を指摘[してき]した。", "sentence_source": "generated"}, {"text": "この本は、日本語の成り立ちを解き明かしている。", "target_word": "解き明かして", "complexity_tier": "T3", "furigana": "この本[ほん]は、日本語[にほんご]の成[な]り立[た]ちを解[と]き明[あ]かしている。", "sentence_source": "generated"}, {"text": "古代遺跡に隠された秘密を解き明かすため、調査が始まった。", "target_word": "解き明かす", "complexity_tier": "T4", "furigana": "古代[こだい]遺跡[いせき]に隠[かく]された秘密[ひみつ]を解[と]き明[あ]かすため、調査[ちょうさ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "彼女は難しい理論をやさしい言葉で解き明かしてくれた。", "target_word": "解き明かして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は難[むずか]しい理論[りろん]をやさしい言葉[ことば]で解[と]き明[あ]かしてくれた。", "sentence_source": "generated"}, {"text": "病気の原因を解き明かせば、新しい薬が作れるかもしれない。", "target_word": "解き明かせ", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]を解[と]き明[あ]かせば、新[あたら]しい薬[くすり]が作[つく]れるかもしれない。", "sentence_source": "generated"}, {"text": "研究チームは遺伝子の働きを解き明かした。", "target_word": "解き明かした", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは遺伝子[いでんし]の働[はたら]きを解[と]き明[あ]かした。", "sentence_source": "generated"}, {"text": "歴史家は古い手紙から当時の暮らしを解き明かした。", "target_word": "解き明かした", "complexity_tier": "T3", "furigana": "歴史家[れきしか]は古[ふる]い手紙[てがみ]から当時[とうじ]の暮[く]らしを解[と]き明[あ]かした。", "sentence_source": "generated"}, {"text": "先生は、複雑な仕組みを図で解き明かして見せた。", "target_word": "解き明かして", "complexity_tier": "T3", "furigana": "先生[せんせい]は、複雑[ふくざつ]な仕組[しく]みを図[ず]で解[と]き明[あ]かして見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解き明かす", "label": "終止形"}, {"form": "解き明かした", "label": "過去形"}, {"form": "解き明かして", "label": "て形"}, {"form": "解き明かさない", "label": "否定形"}, {"form": "解き明かせば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "解き明かす: 複雑で隠れた事柄を説明して明らかにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解き明かす", "is_correct": true, "explanation": "「真実を解き明かすためのプロセス」は、隠れた事柄を明らかにするという意味で通る。"}, {"text": "売り払う", "is_correct": false, "explanation": "真実を売り払うという内容は成り立たず、「〜ための」の前に入らない。"}, {"text": "数える", "is_correct": false, "explanation": "真実を数えるという内容は意味をなさず、この文脈に合わない。"}, {"text": "踏み潰す", "is_correct": false, "explanation": "真実を踏み潰すという内容は文脈に合わず、説明のプロセスとは結びつかない。"}], "explanations": {"解き明かす": "「真実を解き明かすためのプロセス」は、隠れた事柄を明らかにするという意味で通る。", "売り払う": "真実を売り払うという内容は成り立たず、「〜ための」の前に入らない。", "数える": "真実を数えるという内容は意味をなさず、この文脈に合わない。", "踏み潰す": "真実を踏み潰すという内容は文脈に合わず、説明のプロセスとは結びつかない。"}, "sentence_index": 0, "correct_answer": "解き明かす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は結んだ靴ひもを解き明かして、立ち上がった。", "explanation": "ここは〈解く〉（結び目をほどく）の意味。解き明かすは隠れた事柄を説明する語で、結び目をほどく意味は持たないので合わない。"}, {"text": "彼は契約を解き明かし、事務所を辞めた。", "explanation": "ここは〈解約〉（契約を途中でやめる）の意味。解き明かすは隠れた事柄を説明する語で、契約を終わらせる意味は持たないので合わない。"}, {"text": "空欄を解き明かして、答案を出した。", "explanation": "ここは〈埋める〉（空いた所を満たす）の意味。解き明かすは謎を説明することで、空所を満たす意味は持たないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解き明かせ", "is_correct": true, "explanation": "「病気の原因を解き明かせば」は、原因を明らかにすればという仮定で、ここで意味が通る。"}, {"text": "売れば", "is_correct": false, "explanation": "病気の原因を売ればという内容は成り立たず、「〜ば」の前に入らない。"}, {"text": "眠らせば", "is_correct": false, "explanation": "病気の原因を眠らせばという内容は文脈に合わず、説明の仮定にならない。"}, {"text": "磨けば", "is_correct": false, "explanation": "病気の原因を磨けばという内容は意味をなさず、新しい薬につながらない。"}], "explanations": {"解き明かせ": "「病気の原因を解き明かせば」は、原因を明らかにすればという仮定で、ここで意味が通る。", "売れば": "病気の原因を売ればという内容は成り立たず、「〜ば」の前に入らない。", "眠らせば": "病気の原因を眠らせばという内容は文脈に合わず、説明の仮定にならない。", "磨けば": "病気の原因を磨けばという内容は意味をなさず、新しい薬につながらない。"}, "sentence_index": 6, "correct_answer": "解き明かせ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は部品を解き明かして、機械を作った。", "explanation": "ここは〈組み立てる〉の意味。解き明かすは隠れた事柄を説明する語で、部品をつなぐ意味では使わないので合わない。"}, {"text": "彼女は部屋を花で解き明かした。", "explanation": "ここは〈飾る〉（美しく整える）の意味。解き明かすは説明の意味で、装飾の意味は持たないので合わない。"}, {"text": "彼は優勝を解き明かした。", "explanation": "ここは〈宣言する〉（公に告げる）の意味。解き明かすは隠れた事柄を明らかにするもので、公に告げる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記者が事件の真相を解き明かせ、記事にした。", "corrected_sentence": "記者が事件の真相を解き明かし、記事にした。", "error_description": "文中で動詞を続けるときの形は連用形の「解き明かし」。「解き明かせ」は仮定形や命令形で、文の途中では使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "解き明かそう", "is_correct": true, "explanation": "「〜しようとしてきた」の前は意向形の「解き明かそう」で、意図を表すので正しい。"}, {"text": "解き明かせ", "is_correct": false, "explanation": "「解き明かせ」は命令形や仮定形で、「〜としてきた」の前には入らない。"}, {"text": "解き明かさない", "is_correct": false, "explanation": "「解き明かさない」は否定形で、「〜としてきた」と意図の文にならない。"}, {"text": "解き明かせる", "is_correct": false, "explanation": "「解き明かせる」は可能形で、意向を表す「〜しようとする」とは結びつかない。"}], "correct_form": "解き明かそう", "base_form": "解き明かす", "form_label": "意向形", "sentence_index": 1, "explanations": {"解き明かそう": "「〜しようとしてきた」の前は意向形の「解き明かそう」で、意図を表すので正しい。", "解き明かせ": "「解き明かせ」は命令形や仮定形で、「〜としてきた」の前には入らない。", "解き明かさない": "「解き明かさない」は否定形で、「〜としてきた」と意図の文にならない。", "解き明かせる": "「解き明かせる」は可能形で、意向を表す「〜しようとする」とは結びつかない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、宇宙の始まりを解き明かそうが努力している。", "corrected_sentence": "研究者は、宇宙の始まりを解き明かそうと努力している。", "error_description": "「〜ようと努力する」の形では「と」が必要。「が」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "解き明かした", "is_correct": true, "explanation": "「研究チームは〜を解き明かした」と、過去の出来事を述べる過去形が正しい。"}, {"text": "解き明かして", "is_correct": false, "explanation": "「解き明かして」は文を終えられず、述語として成り立たない。"}, {"text": "解き明かせば", "is_correct": false, "explanation": "「解き明かせば」は仮定の形で、出来事を述べる文末にはならない。"}, {"text": "解き明かされ", "is_correct": false, "explanation": "「解き明かされ」は受身の連用形で、文を終える形として成り立たない。"}], "correct_form": "解き明かした", "base_form": "解き明かす", "form_label": "過去形", "sentence_index": 7, "explanations": {"解き明かした": "「研究チームは〜を解き明かした」と、過去の出来事を述べる過去形が正しい。", "解き明かして": "「解き明かして」は文を終えられず、述語として成り立たない。", "解き明かせば": "「解き明かせば」は仮定の形で、出来事を述べる文末にはならない。", "解き明かされ": "「解き明かされ」は受身の連用形で、文を終える形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「教育の真髄」の「の」。教育と真髄を所属の関係で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「教育を真髄」は目的語の形にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「教育に真髄」は場所や対象として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「教育へ真髄」は方向の意味になり、語の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「教育の真髄」の「の」。教育と真髄を所属の関係で結ぶ。", "を": "「教育を真髄」は目的語の形にならず、文が成り立たない。", "に": "「教育に真髄」は場所や対象として意味が通らない。", "へ": "「教育へ真髄」は方向の意味になり、語の関係が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
