INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もののいちばんたいせつなところ。", "primary_collocate": null, "pronunciation": "しんずい", "ipa": "ɕinzɯi", "syllable_count": 4, "sentences": [{"text": "俳句の真髄は、短い言葉に深い思いを込めることだ。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "はいくのしんずいは、みじかいことばにふかいおもいをこめることだ。", "sentence_source": "generated"}, {"text": "先生は、教育の真髄は生徒を信じることだと話した。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "せんせいは、きょういくのしんずいはせいとをしんじることだとはなした。", "sentence_source": "generated"}, {"text": "彼女の演奏には、クラシック音楽の真髄が感じられた。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "かのじょのえんそうには、クラシックおんがくのしんずいがかんじられた。", "sentence_source": "generated"}, {"text": "柔道の真髄を学ぶには、技より先に礼儀を身につけなければならない。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "じゅうどうのしんずいをまなぶには、わざよりさきにれいぎをみにつけなければならない。", "sentence_source": "generated"}, {"text": "この寺の庭には、日本の美の真髄が表れている。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "このてらのにわには、にほんのびのしんずいがあらわれている。", "sentence_source": "generated"}, {"text": "職人は、ものづくりの真髄を若者に伝えようとしている。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "しょくにんは、ものづくりのしんずいをわかものにつたえようとしている。", "sentence_source": "generated"}, {"text": "彼は表面的な知識だけで、学問の真髄を理解していない。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "かれはひょうめんてきなちしきだけで、がくもんのしんずいをりかいしていない。", "sentence_source": "generated"}, {"text": "禅の真髄は、言葉では説明しにくい。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "ぜんのしんずいは、ことばではせつめいしにくい。", "sentence_source": "generated"}, {"text": "長い旅を終えて、人生の真髄に少し近づけた気がする。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "ながいたびをおえて、じんせいのしんずいにすこしちかづけたきがする。", "sentence_source": "generated"}, {"text": "スポーツの真髄とは、勝つことよりも全力を尽くすことだと思う。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "スポーツのしんずいとは、かつことよりもぜんりょくをつくすことだとおもう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真髄", "label": "基本形"}], "register": "formal", "sense_fingerprint": "ものの一番大切な部分。芸・学問・道などの奥義", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真髄", "is_correct": true, "explanation": "「俳句の真髄」は俳句の最も大切な部分を指し、文の主題に合う。"}, {"text": "誤植", "is_correct": false, "explanation": "誤植は印刷の誤りを指し、俳句の大切な部分とは関係がない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸で、俳句の本質を表す語にならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、俳句の本質を述べる文脈に合わない。"}], "explanations": {"真髄": "「俳句の真髄」は俳句の最も大切な部分を指し、文の主題に合う。", "誤植": "誤植は印刷の誤りを指し、俳句の大切な部分とは関係がない。", "寝息": "寝息は眠っている時の呼吸で、俳句の本質を表す語にならない。", "天気": "天気は空模様を指し、俳句の本質を述べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "真髄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "待ち合わせの真髄を決めた。", "explanation": "ここは〈時刻〉の意味。真髄は抽象的な本質なので、約束の時間には使わない。"}, {"text": "壁の真髄を塗り替えた。", "explanation": "ここは〈色〉の意味。真髄は色を表さないので、塗り替える対象にはならない。"}, {"text": "庭の真髄を刈り込んだ。", "explanation": "ここは〈芝生〉の意味。真髄は植物ではないので、刈り込む対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真髄", "is_correct": true, "explanation": "「学問の真髄」は学問の核心を指し、「を理解していない」と結びつく。"}, {"text": "雑音", "is_correct": false, "explanation": "「学問の雑音を理解」は意味が通らず、学問の本質を示せない。"}, {"text": "煎餅", "is_correct": false, "explanation": "「学問の煎餅」は意味が成り立たず、理解の対象にならない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は学問に属さない語で、「理解していない」の対象にならない。"}], "explanations": {"真髄": "「学問の真髄」は学問の核心を指し、「を理解していない」と結びつく。", "雑音": "「学問の雑音を理解」は意味が通らず、学問の本質を示せない。", "煎餅": "「学問の煎餅」は意味が成り立たず、理解の対象にならない。", "霧": "霧は学問に属さない語で、「理解していない」の対象にならない。"}, "sentence_index": 6, "correct_answer": "真髄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題の真髄を先生に提出した。", "explanation": "ここは〈課題〉の意味。真髄は物事の大事なところを指すので、提出する物にはならない。"}, {"text": "電池の真髄を入れ替えた。", "explanation": "ここは〈バッテリー〉の意味。真髄は物ではないので、入れ替える部品にはならない。"}, {"text": "絵の具の真髄を溶いた。", "explanation": "ここは〈顔料〉の意味。真髄は物事の大事なところを指すので、溶いて使う材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "師の教えの真髄に理解するには、基礎を疑わないことだ。", "corrected_sentence": "師の教えの真髄を理解するには、基礎を疑わないことだ。", "error_description": "「真髄」の後の助詞が「に」になっている。「理解する」の目的語を示す「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52623, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "武道の真髄を砕くには、型を正しく繰り返すことだ。", "corrected_sentence": "武道の真髄を磨くには、型を正しく繰り返すことだ。", "error_description": "「真髄」と組む動詞が「砕く」になっている。本質に対しては「磨く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「茶道の真髄」の「の」。茶道と真髄を所属の関係で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「茶道を真髄は」は目的語の形にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「茶道で真髄」は手段の意味になり、文の内容と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「茶道へ真髄」は方向の意味になり、語の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「茶道の真髄」の「の」。茶道と真髄を所属の関係で結ぶ。", "を": "「茶道を真髄は」は目的語の形にならず、文が成り立たない。", "で": "「茶道で真髄」は手段の意味になり、文の内容と合わない。", "へ": "「茶道へ真髄」は方向の意味になり、語の関係が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「真髄が分かる」の「が」。分かる対象の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「真髄を分かる」は目的語になり、「分かる」の形と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「真髄へ分かる」は方向の意味になり、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「真髄の分かる」は連体修飾になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「真髄が分かる」の「が」。分かる対象の主語を示す。", "を": "「真髄を分かる」は目的語になり、「分かる」の形と合わない。", "へ": "「真髄へ分かる」は方向の意味になり、成り立たない。", "の": "「真髄の分かる」は連体修飾になり、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の本質や核心となる部分。", "primary_collocate": null, "pronunciation": "しんずい", "ipa": "ɕinzɯi", "syllable_count": 4, "sentences": [{"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "しんじつをときあかすためのせいひつかつろんりてきなプロセス、それこそがしもんぶんせきのしんずいといえよう。", "sentence_source": "mined"}, {"text": "茶道の真髄は、形ではなく相手を思う心にある。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "さどうのしんずいは、かたちではなくあいてをおもうこころにある。", "sentence_source": "generated"}, {"text": "師匠から武道の真髄を学ぶために、十年間修行を続けた。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "ししょうからぶどうのしんずいをまなぶために、じゅうねんかんしゅぎょうをつづけた。", "sentence_source": "generated"}, {"text": "この映画は、喜劇の真髄を見せてくれる傑作だ。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "このえいがは、きげきのしんずいをみせてくれるけっさくだ。", "sentence_source": "generated"}, {"text": "彼は難しい理論を使わず、経営の真髄を一言で説明した。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "かれはむずかしいりろんをつかわず、けいえいのしんずいをひとことでせつめいした。", "sentence_source": "generated"}, {"text": "日本料理の真髄を知りたければ、まず出汁の取り方から学ぶべきだ。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "にほんりょうりのしんずいをしりたければ、まずだしのとりかたからまなぶべきだ。", "sentence_source": "generated"}, {"text": "技術をいくら覚えても、芸の真髄に触れなければ人を感動させられない。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "ぎじゅつをいくらおぼえても、げいのしんずいにふれなければひとをかんどうさせられない。", "sentence_source": "generated"}, {"text": "この本を読めば、孫子の兵法の真髄が分かる。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "このほんをよめば、そんしのへいほうのしんずいがわかる。", "sentence_source": "generated"}, {"text": "外見だけをまねしても、伝統の真髄までは受け継げない。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "がいけんだけをまねしても、でんとうのしんずいまではうけつげない。", "sentence_source": "generated"}, {"text": "長年の経験を積んで、ようやく仕事の真髄が見えてきた。", "target_word": "真髄", "complexity_tier": "T3", "furigana": "ながねんのけいけんをつんで、ようやくしごとのしんずいがみえてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真髄", "label": "基本形"}], "register": "formal", "sense_fingerprint": "物事の本質・核心。道や芸などの最も大切な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真髄", "is_correct": true, "explanation": "「指紋分析の真髄」は分析の最も核心的な部分を指し、「それこそが〜と言えよう」に合う。"}, {"text": "誤差", "is_correct": false, "explanation": "誤差は測定のずれを指すため、静謐で論理的なプロセスを称える文脈に合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然は予期せぬ出来事を表し、プロセスの核心を言い表せないので不適。"}, {"text": "欠陥", "is_correct": false, "explanation": "欠陥は弱点を表し、プロセスを称える「それこそが」の文脈と逆になる。"}], "explanations": {"真髄": "「指紋分析の真髄」は分析の最も核心的な部分を指し、「それこそが〜と言えよう」に合う。", "誤差": "誤差は測定のずれを指すため、静謐で論理的なプロセスを称える文脈に合わない。", "偶然": "偶然は予期せぬ出来事を表し、プロセスの核心を言い表せないので不適。", "欠陥": "欠陥は弱点を表し、プロセスを称える「それこそが」の文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "真髄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "届いた箱を開けて、真髄を確かめた。", "explanation": "ここは〈中身〉の意味。真髄は抽象的な本質なので、箱の中の物には使わない。"}, {"text": "帰り道に、大きな真髄を買った。", "explanation": "ここは〈購入〉の意味。真髄は抽象的な本質なので、売り買いの対象にはならない。"}, {"text": "頂上まで登って、真髄の景色を楽しんだ。", "explanation": "ここは〈絶景〉の意味。真髄は抽象的な本質なので、眺めの良さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真髄", "is_correct": true, "explanation": "「芸の真髄」は芸の核心を指し、「に触れなければ」と自然に結びつく。"}, {"text": "誤解", "is_correct": false, "explanation": "「芸の誤解に触れる」は意味が通らず、芸の本質を示せない。"}, {"text": "雑音", "is_correct": false, "explanation": "「芸の雑音」は芸の本質ではなく、触れる対象として不自然。"}, {"text": "天候", "is_correct": false, "explanation": "天候は芸に属さない語で、文脈に合わない。"}], "explanations": {"真髄": "「芸の真髄」は芸の核心を指し、「に触れなければ」と自然に結びつく。", "誤解": "「芸の誤解に触れる」は意味が通らず、芸の本質を示せない。", "雑音": "「芸の雑音」は芸の本質ではなく、触れる対象として不自然。", "天候": "天候は芸に属さない語で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "真髄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食の鍋に入れる真髄を買ってきた。", "explanation": "ここは〈材料〉の意味。真髄は抽象的な本質なので、店で買う品物には使わない。"}, {"text": "来週の真髄を先生と相談した。", "explanation": "ここは〈日程〉の意味。真髄は本質の意味で、予定の組み方には使わない。"}, {"text": "修理の真髄を先に払った。", "explanation": "ここは〈代金〉の意味。真髄は金額を表さないので、支払いの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この庭の真髄を、静けさにある。", "corrected_sentence": "この庭の真髄は、静けさにある。", "error_description": "「真髄」の後の助詞が「を」になっている。主題を示す「は」が正しく、「〜にある」の文型に合う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52624, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この一冊で、孫子の兵法の真髄が溶ける。", "corrected_sentence": "この一冊で、孫子の兵法の真髄がつかめる。", "error_description": "「真髄」と組む動詞が「溶ける」になっている。本質に対しては「つかむ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚偽", "is_correct": true, "explanation": "虚偽は真実の対義語で、偽りを表すため、ここで対になる語として正しい。"}, {"text": "空想", "is_correct": false, "explanation": "空想は現実にないことを思い描くことで、真実の対義語ではない。"}, {"text": "事実", "is_correct": false, "explanation": "事実は真実と近い意味の語で、対義語ではないため不正解。"}, {"text": "現実", "is_correct": false, "explanation": "現実は真実と近い関係の語で、反対の意味ではないため不正解。"}], "correct_answer": "虚偽", "explanations": {"虚偽": "虚偽は真実の対義語で、偽りを表すため、ここで対になる語として正しい。", "空想": "空想は現実にないことを思い描くことで、真実の対義語ではない。", "事実": "事実は真実と近い意味の語で、対義語ではないため不正解。", "現実": "現実は真実と近い関係の語で、反対の意味ではないため不正解。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嘘", "is_correct": true, "explanation": "嘘は真実の対義語で、事実と反対のことを表すため、ここで対になる語として正しい。"}, {"text": "伝説", "is_correct": false, "explanation": "伝説は言い伝えられた話で、真実の対義語とは言えない。"}, {"text": "理想", "is_correct": false, "explanation": "理想は目指す姿を表し、真実の対義語にはならない。"}, {"text": "本音", "is_correct": false, "explanation": "本音は本心の意味で、真実と近い関係にあるため対義語ではない。"}], "correct_answer": "嘘", "explanations": {"嘘": "嘘は真実の対義語で、事実と反対のことを表すため、ここで対になる語として正しい。", "伝説": "伝説は言い伝えられた話で、真実の対義語とは言えない。", "理想": "理想は目指す姿を表し、真実の対義語にはならない。", "本音": "本音は本心の意味で、真実と近い関係にあるため対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当のこと。うそじゃないこと。", "primary_collocate": null, "pronunciation": "しんじつ", "ipa": "ɕindʑitsɯ", "syllable_count": 4, "sentences": [{"text": "母は私の顔を見て、真実を話してほしいと言った。", "target_word": "真実", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の顔[かお]を見[み]て、真実[しんじつ]を話[はな]してほしいと言[い]った。", "sentence_source": "generated"}, {"text": "彼が言ったことは、すべて真実だった。", "target_word": "真実", "complexity_tier": "T3", "furigana": "彼[かれ]が言[い]ったことは、すべて真実[しんじつ]だった。", "sentence_source": "generated"}, {"text": "子どもは正直なので、大人が隠したがる真実もそのまま口にする。", "target_word": "真実", "complexity_tier": "T3", "furigana": "子[こ]どもは正直[しょうじき]なので、大人[おとな]が隠[かく]したがる真実[しんじつ]もそのまま口[くち]にする。", "sentence_source": "generated"}, {"text": "彼女はうそをやめて、真実を打ち明けた。", "target_word": "真実", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はうそをやめて、真実[しんじつ]を打[う]ち明[あ]けた。", "sentence_source": "generated"}, {"text": "ニュースの内容が真実かどうか、確かめる必要がある。", "target_word": "真実", "complexity_tier": "T3", "furigana": "ニュースの内容[ないよう]が真実[しんじつ]かどうか、確[たし]かめる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "真実を知るのは怖いが、知らないままでいるのはもっと苦しい。", "target_word": "真実", "complexity_tier": "T3", "furigana": "真実[しんじつ]を知[し]るのは怖[こわ]いが、知[し]らないままでいるのはもっと苦[くる]しい。", "sentence_source": "generated"}, {"text": "友達に真実を隠していたことを、ずっと後悔している。", "target_word": "真実", "complexity_tier": "T3", "furigana": "友達[ともだち]に真実[しんじつ]を隠[かく]していたことを、ずっと後悔[こうかい]している。", "sentence_source": "generated"}, {"text": "彼の話は面白いが、どこまでが真実なのか分からない。", "target_word": "真実", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は面白[おもしろ]いが、どこまでが真実[しんじつ]なのか分[わ]からない。", "sentence_source": "generated"}, {"text": "先生は生徒に、真実だけを書くように言った。", "target_word": "真実", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、真実[しんじつ]だけを書[か]くように言[い]った。", "sentence_source": "generated"}, {"text": "長い沈黙のあと、彼女は真実を口にした。", "target_word": "真実", "complexity_tier": "T3", "furigana": "長[なが]い沈黙[ちんもく]のあと、彼女[かのじょ]は真実[しんじつ]を口[くち]にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真実", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "本当のこと。うそではないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真実", "is_correct": true, "explanation": "「真実を話してほしい」の「真実」。話す内容として自然に入る。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤を話してほしい」は意味が通らず、話す対象にならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を話してほしい」は不自然で、話す内容にならない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯ブラシは話す内容にならず、文脈に合わない。"}], "explanations": {"真実": "「真実を話してほしい」の「真実」。話す内容として自然に入る。", "洗剤": "「洗剤を話してほしい」は意味が通らず、話す対象にならない。", "砂糖": "「砂糖を話してほしい」は不自然で、話す内容にならない。", "歯ブラシ": "歯ブラシは話す内容にならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "真実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関の真実をかけて出かけた。", "explanation": "真実は抽象的な事実なので、錠をかける対象にならない。"}, {"text": "花瓶に真実を生けた。", "explanation": "真実は花ではないので、花瓶に生ける対象にならない。"}, {"text": "雨が降ってきたので、真実を差した。", "explanation": "真実は道具ではないので、傘を差す対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真実", "is_correct": true, "explanation": "「友達に真実を隠していた」の「真実」。隠す対象として自然。"}, {"text": "天気", "is_correct": false, "explanation": "「友達に天気を隠していた」は意味が通らず、隠す対象にならない。"}, {"text": "雑巾", "is_correct": false, "explanation": "雑巾は隠す内容として不自然で、後悔の文脈に合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は隠す対象として不自然で、文脈に合わない。"}], "explanations": {"真実": "「友達に真実を隠していた」の「真実」。隠す対象として自然。", "天気": "「友達に天気を隠していた」は意味が通らず、隠す対象にならない。", "雑巾": "雑巾は隠す内容として不自然で、後悔の文脈に合わない。", "寝言": "寝言は隠す対象として不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "真実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい真実をかけて、本を読んだ。", "explanation": "真実は物ではないので、眼鏡をかける対象にならない。"}, {"text": "新しい真実を改札に通した。", "explanation": "真実は切符ではないので、改札を通す対象にならない。"}, {"text": "買ったお菓子を真実に入れた。", "explanation": "真実は容器ではないので、お菓子を入れる場所にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、昔の話の真実に孫に語った。", "corrected_sentence": "祖母は、昔の話の真実を孫に語った。", "error_description": "「真実」の後の助詞が「に」になっている。「語る」の対象を示す「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52625, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その真実で、誰にも知られていない。", "corrected_sentence": "その真実が、誰にも知られていない。", "error_description": "誤: 真実で / 正: 真実が。「知られていない」の主語は「が」で示すので、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「事件の真実」の「の」。事件と真実を所属の関係で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「事件を真実」は目的語の形にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「事件に真実」は場所や対象として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「事件で真実」は手段の意味になり、語の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「事件の真実」の「の」。事件と真実を所属の関係で結ぶ。", "を": "「事件を真実」は目的語の形にならず、文が成り立たない。", "に": "「事件に真実」は場所や対象として意味が通らない。", "で": "「事件で真実」は手段の意味になり、語の関係が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚偽", "is_correct": true, "explanation": "虚偽は真実の対義語で、偽りを表すため、ここで対になる語として正しい。"}, {"text": "季節", "is_correct": false, "explanation": "季節は真実と対になる語ではなく、対義語ではないため不正解。"}, {"text": "事実", "is_correct": false, "explanation": "事実は真実と近い意味の語で、対義語ではないため不正解。"}, {"text": "現実", "is_correct": false, "explanation": "現実は真実と近い関係の語で、反対の意味ではないため不正解。"}], "correct_answer": "虚偽", "explanations": {"虚偽": "虚偽は真実の対義語で、偽りを表すため、ここで対になる語として正しい。", "季節": "季節は真実と対になる語ではなく、対義語ではないため不正解。", "事実": "事実は真実と近い意味の語で、対義語ではないため不正解。", "現実": "現実は真実と近い関係の語で、反対の意味ではないため不正解。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「真実が分かってしまう」の「が」。分かる対象を示す主語になる。"}, {"text": "の", "is_correct": false, "explanation": "「真実の分かってしまう」は連体修飾になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「真実へ分かってしまう」は方向の意味になり、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「真実より分かってしまう」は比較の意味になり、文の内容と合わない。"}], "correct_answer": "が", "explanations": {"が": "「真実が分かってしまう」の「が」。分かる対象を示す主語になる。", "の": "「真実の分かってしまう」は連体修飾になり、文が成り立たない。", "へ": "「真実へ分かってしまう」は方向の意味になり、不自然になる。", "より": "「真実より分かってしまう」は比較の意味になり、文の内容と合わない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嘘", "is_correct": true, "explanation": "嘘は真実の対義語で、事実と反対のことを表すため、ここで対になる語として正しい。"}, {"text": "伝説", "is_correct": false, "explanation": "伝説は言い伝えられた話で、真実の対義語とは言えない。"}, {"text": "理想", "is_correct": false, "explanation": "理想は目指す姿を表し、真実の対義語にはならない。"}, {"text": "本音", "is_correct": false, "explanation": "本音は本心の意味で、真実と近い関係にあるため対義語ではない。"}], "correct_answer": "嘘", "explanations": {"嘘": "嘘は真実の対義語で、事実と反対のことを表すため、ここで対になる語として正しい。", "伝説": "伝説は言い伝えられた話で、真実の対義語とは言えない。", "理想": "理想は目指す姿を表し、真実の対義語にはならない。", "本音": "本音は本心の意味で、真実と近い関係にあるため対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に存在する事実。偽りのない状態。", "primary_collocate": null, "pronunciation": "しんじつ", "ipa": "ɕindʑitsɯ", "syllable_count": 4, "sentences": [{"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "真実", "complexity_tier": "T3", "furigana": "しんじつをときあかすためのせいひつかつろんりてきなプロセス、それこそがしもんぶんせきのしんずいといえよう。", "sentence_source": "mined"}, {"text": "彼女は裁判で、事件の真実をすべて話した。", "target_word": "真実", "complexity_tier": "T3", "furigana": "かのじょはさいばんで、じけんのしんじつをすべてはなした。", "sentence_source": "generated"}, {"text": "真実を知ったとき、彼は言葉を失った。", "target_word": "真実", "complexity_tier": "T3", "furigana": "しんじつをしったとき、かれはことばをうしなった。", "sentence_source": "generated"}, {"text": "噂は広まったが、真実とはまったく違っていた。", "target_word": "真実", "complexity_tier": "T3", "furigana": "うわさはひろまったが、しんじつとはまったくちがっていた。", "sentence_source": "generated"}, {"text": "記者は長い調査の末に、隠されていた真実を明らかにした。", "target_word": "真実", "complexity_tier": "T3", "furigana": "きしゃはながいちょうさのすえに、かくされていたしんじつをあきらかにした。", "sentence_source": "generated"}, {"text": "痛い真実でも、聞いておいたほうがいい。", "target_word": "真実", "complexity_tier": "T3", "furigana": "いたいしんじつでも、きいておいたほうがいい。", "sentence_source": "generated"}, {"text": "証拠がそろい、ようやく真実が見えてきた。", "target_word": "真実", "complexity_tier": "T3", "furigana": "しょうこがそろい、ようやくしんじつがみえてきた。", "sentence_source": "generated"}, {"text": "嘘をついても、いつかは真実が分かってしまう。", "target_word": "真実", "complexity_tier": "T3", "furigana": "うそをついても、いつかはしんじつがわかってしまう。", "sentence_source": "generated"}, {"text": "この映画は、あの事件の真実を丁寧に描いている。", "target_word": "真実", "complexity_tier": "T3", "furigana": "このえいがは、あのじけんのしんじつをていねいにえがいている。", "sentence_source": "generated"}, {"text": "目撃者の証言によって、事故の真実が初めて明らかになった。", "target_word": "真実", "complexity_tier": "T3", "furigana": "もくげきしゃのしょうげんによって、じこのしんじつがはじめてあきらかになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真実", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "実際にある事実。偽りのない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 解き明かす (Zipf 2.8), 静謐 (Zipf 2.66), 指紋 (Zipf 3.67), 真髄 (Zipf 2.84)']::text[], '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真実", "is_correct": true, "explanation": "「真実を解き明かす」の「真実」。解き明かす対象として自然に入る。"}, {"text": "雨", "is_correct": false, "explanation": "「雨を解き明かす」は意味が通らず、文の内容と合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を解き明かす」は不自然で、解明の対象にならない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は解き明かす対象にならず、文脈に合わない。"}], "explanations": {"真実": "「真実を解き明かす」の「真実」。解き明かす対象として自然に入る。", "雨": "「雨を解き明かす」は意味が通らず、文の内容と合わない。", "砂糖": "「砂糖を解き明かす」は不自然で、解明の対象にならない。", "洗剤": "洗剤は解き明かす対象にならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "真実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の真実を棚に並べた。", "explanation": "真実は偽りのない事実を表す抽象語で、棚に並べる物としては使えない。"}, {"text": "駅に近い真実を探している。", "explanation": "真実は事実や状態を表す語で、部屋や土地を指す言葉としては使えない。"}, {"text": "古い真実を広げて、道を確かめた。", "explanation": "真実は抽象的な事実で、広げて道を確かめる物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真実", "is_correct": true, "explanation": "「ようやく真実が見えてきた」の「真実」。見えてくる対象として自然。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は目に見える現象ではなく、証拠の後に見えてくるものとして文脈に合わない。"}, {"text": "雑草", "is_correct": false, "explanation": "「ようやく雑草が見えてきた」は文脈に合わず、意味がつながらない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は証拠の流れで見えてくる対象にならず、文脈に合わない。"}], "explanations": {"真実": "「ようやく真実が見えてきた」の「真実」。見えてくる対象として自然。", "湿気": "湿気は目に見える現象ではなく、証拠の後に見えてくるものとして文脈に合わない。", "雑草": "「ようやく雑草が見えてきた」は文脈に合わず、意味がつながらない。", "食器": "食器は証拠の流れで見えてくる対象にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "真実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "買ってきた真実を冷蔵庫にしまった。", "explanation": "真実は偽りのない事実で、冷蔵庫に入れる食材の意味にはならない。"}, {"text": "初対面の人と、真実を交換した。", "explanation": "真実は事実や状態を指し、相手と交換する物としては使えない。"}, {"text": "床に落ちた真実を拾った。", "explanation": "真実は抽象的な事実で、床から拾い上げる物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事件の真実を、まだ誰にも分からない。", "corrected_sentence": "事件の真実は、まだ誰にも分からない。", "error_description": "「真実」の後の助詞が「を」になっている。主題を示す「は」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その証言で、事故を真実が明らかになった。", "corrected_sentence": "その証言で、事故の真実が明らかになった。", "error_description": "「事故の真実」の「の」が「を」になっている。名詞を修飾する「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「草を使った擬装で」は手段を表し、草を使って偽装したという意味になり文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「擬装を」と置くと擬装が目的語になり、「擬装を空から見えなかった」は主語と述語が噛み合わず文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「擬装に」は帰着点を表すが、「擬装に空から見えなかった」では手段の関係が表せず意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「擬装と」は相手や並列を表し、「草を使った擬装と空から見えなかった」は手段の意味にならず不自然。"}], "correct_answer": "で", "explanations": {"で": "「草を使った擬装で」は手段を表し、草を使って偽装したという意味になり文脈に合う。", "を": "「擬装を」と置くと擬装が目的語になり、「擬装を空から見えなかった」は主語と述語が噛み合わず文として成り立たない。", "に": "「擬装に」は帰着点を表すが、「擬装に空から見えなかった」では手段の関係が表せず意味が通らない。", "と": "「擬装と」は相手や並列を表し、「草を使った擬装と空から見えなかった」は手段の意味にならず不自然。"}, "error_tags": {"を": "目的語の役割", "に": "帰着点", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
