INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "本当のすがたをかくすこと。", "primary_collocate": null, "pronunciation": "ぎそう", "ipa": "ɡisoː", "syllable_count": 3, "sentences": [{"text": "兵士たちは木の枝で戦車を擬装した。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは木[き]の枝[えだ]で戦車[せんしゃ]を擬装[ぎそう]した。", "sentence_source": "generated"}, {"text": "森の中の基地は、草を使った擬装で空から見えなかった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]の基地[きち]は、草[くさ]を使[つか]った擬装[ぎそう]で空[そら]から見[み]えなかった。", "sentence_source": "generated"}, {"text": "その船は漁船に擬装して、国境の海に近づいた。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "その船[ふね]は漁船[ぎょせん]に擬装[ぎそう]して、国境[こっきょう]の海[うみ]に近[ちか]づいた。", "sentence_source": "generated"}, {"text": "敵に見つからないように、トラックに擬装を施した。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "敵[てき]に見[み]つからないように、トラックに擬装[ぎそう]を施[ほどこ]した。", "sentence_source": "generated"}, {"text": "警察は、商店に擬装した小屋を見つけた。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、商店[しょうてん]に擬装[ぎそう]した小屋[こや]を見[み]つけた。", "sentence_source": "generated"}, {"text": "擬装がうまくて、近くに行くまで基地だと気づかなかった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "擬装[ぎそう]がうまくて、近[ちか]くに行[い]くまで基地[きち]だと気[き]づかなかった。", "sentence_source": "generated"}, {"text": "倉庫は住宅に擬装されていたため、だれも気づかなかった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "倉庫[そうこ]は住宅[じゅうたく]に擬装[ぎそう]されていたため、だれも気[き]づかなかった。", "sentence_source": "generated"}, {"text": "雪の上では、白い布で擬装すれば目立たない。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]では、白[しろ]い布[ぬの]で擬装[ぎそう]すれば目立[めだ]たない。", "sentence_source": "generated"}, {"text": "彼らは荷物を野菜に擬装して運び込んだ。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "彼[かれ]らは荷物[にもつ]を野菜[やさい]に擬装[ぎそう]して運[はこ]び込[こ]んだ。", "sentence_source": "generated"}, {"text": "空から見ても分からないほど、擬装は完ぺきだった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "空[そら]から見[み]ても分[わ]からないほど、擬装[ぎそう]は完[かん]ぺきだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "擬装", "label": "基本形"}, {"form": "擬装する", "label": "する動詞形"}, {"form": "擬装した", "label": "過去形"}, {"form": "擬装される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "草や布などで本来の姿を隠し、周りに溶け込ませること（カムフラージュ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擬装", "is_correct": true, "explanation": "「木の枝で戦車を擬装した」は本来の姿を木の枝で隠した意味になり、文脈に合う。"}, {"text": "感動", "is_correct": false, "explanation": "感動は心が動くこと。「戦車を感動した」は文として成り立たない。"}, {"text": "依存", "is_correct": false, "explanation": "依存は頼ること。「戦車を依存した」は意味が通らない。"}, {"text": "謙遜", "is_correct": false, "explanation": "謙遜は自分を低く言うこと。「戦車を謙遜した」は文として成り立たない。"}], "explanations": {"擬装": "「木の枝で戦車を擬装した」は本来の姿を木の枝で隠した意味になり、文脈に合う。", "感動": "感動は心が動くこと。「戦車を感動した」は文として成り立たない。", "依存": "依存は頼ること。「戦車を依存した」は意味が通らない。", "謙遜": "謙遜は自分を低く言うこと。「戦車を謙遜した」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "擬装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は決算書を擬装して、利益を多く見せた。", "explanation": "ここは〈偽装〉（中身をごまかす・偽る）の意味。〈擬装〉は本当の姿を隠して別のものに見せかける意味で、数字の改ざんには使えない。"}, {"text": "証拠を擬装して、現場から隠した。", "explanation": "ここは〈隠蔽〉（証拠を隠す）の意味。〈擬装〉は別のものに見せかけることで、証拠を消す行為は表せない。"}, {"text": "この漫画は擬装が多く、場面の迫力が伝わる。", "explanation": "ここは〈擬音〉（音をまねた語）の意味。〈擬装〉は本物らしく見せかけることで、音の表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擬装", "is_correct": true, "explanation": "「住宅に擬装されていた」は住宅のように見せかけられていた意味で、倉庫の文脈に合う。"}, {"text": "解説", "is_correct": false, "explanation": "解説は説明すること。「住宅に解説された」は文として成り立たない。"}, {"text": "減速", "is_correct": false, "explanation": "減速は速度を落とすこと。「住宅に減速された」は意味が通らない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かすこと。「住宅に解凍された」は文として成り立たない。"}], "explanations": {"擬装": "「住宅に擬装されていた」は住宅のように見せかけられていた意味で、倉庫の文脈に合う。", "解説": "解説は説明すること。「住宅に解説された」は文として成り立たない。", "減速": "減速は速度を落とすこと。「住宅に減速された」は意味が通らない。", "解凍": "解凍は凍ったものを溶かすこと。「住宅に解凍された」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "擬装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パスポートを擬装して、入国審査を通った。", "explanation": "ここは〈偽造〉（公的な書類を偽って作ること）の意味。〈擬装〉は本当の姿を隠して別のものに見せかける意味で、書類を偽る行為は表せない。"}, {"text": "店は有名店の味を擬装して売った。", "explanation": "ここは〈模倣〉（まねること）の意味。〈擬装〉は本当の姿を隠す意味で、まねして作ることは表せない。"}, {"text": "店の外壁を擬装して、請求額を減らした。", "explanation": "ここは〈減額〉の意味。〈擬装〉は本当の姿を隠して別のものに見せかける意味で、請求額を変える行為は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "見つからないように、荷台に擬装で施した。", "corrected_sentence": "見つからないように、荷台に擬装を施した。", "error_description": "「施す」の目的語には「を」が必要。「で」だと手段の意味になり、「擬装で施した」は文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52627, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "見つからないよう、船を漁船に擬装するした。", "corrected_sentence": "見つからないよう、船を漁船に擬装した。", "error_description": "「擬装」はサ変動詞なので「擬装した」と言う。「擬装する」に「した」を重ねると誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「観光客に擬装して」は観光客のように見せかけて、の意味で、犯人が装った文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「観光客を擬装して」だと観光客を装わせる意味になり、犯人自身が装ったという文脈と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「観光客で擬装して」は手段の意味になるが、「観光客で擬装する」は不自然で、観光客のように見せかける関係を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「観光客の擬装して」は連体の「の」が動詞につながらず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「観光客に擬装して」は観光客のように見せかけて、の意味で、犯人が装った文脈に合う。", "を": "「観光客を擬装して」だと観光客を装わせる意味になり、犯人自身が装ったという文脈と合わない。", "で": "「観光客で擬装して」は手段の意味になるが、「観光客で擬装する」は不自然で、観光客のように見せかける関係を表せない。", "の": "「観光客の擬装して」は連体の「の」が動詞につながらず、文として成り立たない。"}, "error_tags": {"を": "目的語の役割", "で": "手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「擬装の手段」の「の」は後ろの名詞を修飾する連体助詞で、擬装という手段を表し文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「擬装を手段が」だと擬装が目的語になり、「手段が」との続きが噛み合わず、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「擬装に手段」は帰着点の「に」で名詞句がつながらず、「擬装の手段」の意味を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「擬装と手段」は二つを並べる意味になり、一つの名詞句「擬装の手段」として文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「擬装の手段」の「の」は後ろの名詞を修飾する連体助詞で、擬装という手段を表し文脈に合う。", "を": "「擬装を手段が」だと擬装が目的語になり、「手段が」との続きが噛み合わず、文として成り立たない。", "に": "「擬装に手段」は帰着点の「に」で名詞句がつながらず、「擬装の手段」の意味を表せない。", "と": "「擬装と手段」は二つを並べる意味になり、一つの名詞句「擬装の手段」として文脈に合わない。"}, "error_tags": {"を": "目的語の役割", "に": "帰着点", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "本当の姿や目的を隠すために、別のものに見せかけること。また、そのための手段や方法。", "primary_collocate": null, "pronunciation": "ぎそう", "ipa": "ɡisoː", "syllable_count": 3, "sentences": [{"text": "工場は、遠くから見ると公園に見える擬装がされていた。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、遠[とお]くから見[み]ると公園[こうえん]に見[み]える擬装[ぎそう]がされていた。", "sentence_source": "generated"}, {"text": "犯人は、観光客に擬装して町に入りこんだ。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "犯人[はんにん]は、観光客[かんこうきゃく]に擬装[ぎそう]して町[まち]に入[はい]りこんだ。", "sentence_source": "generated"}, {"text": "その車は、ふつうの配達車に擬装した警察車両だった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "その車[くるま]は、ふつうの配達車[はいたつしゃ]に擬装[ぎそう]した警察[けいさつ]車両[しゃりょう]だった。", "sentence_source": "generated"}, {"text": "軍の施設を畑に見せかける擬装の方法が研究された。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "軍[ぐん]の施設[しせつ]を畑[はたけ]に見[み]せかける擬装[ぎそう]の方法[ほうほう]が研究[けんきゅう]された。", "sentence_source": "generated"}, {"text": "探検隊は、岩と同じ色の布で小屋を擬装した。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "探検隊[たんけんたい]は、岩[いわ]と同[おな]じ色[いろ]の布[ぬの]で小屋[こや]を擬装[ぎそう]した。", "sentence_source": "generated"}, {"text": "その看板は、本物の店に見せかけるための擬装だった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "その看板[かんばん]は、本物[ほんもの]の店[みせ]に見[み]せかけるための擬装[ぎそう]だった。", "sentence_source": "generated"}, {"text": "港の倉庫は、荷を隠すために古い工場に擬装された。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "港[みなと]の倉庫[そうこ]は、荷[に]を隠[かく]すために古[ふる]い工場[こうじょう]に擬装[ぎそう]された。", "sentence_source": "generated"}, {"text": "地図には載らない擬装の手段が、いくつも使われていた。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "地図[ちず]には載[の]らない擬装[ぎそう]の手段[しゅだん]が、いくつも使[つか]われていた。", "sentence_source": "generated"}, {"text": "病院に擬装した建物が、実は秘密の研究所だった。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "病院[びょういん]に擬装[ぎそう]した建物[たてもの]が、実[じつ]は秘密[ひみつ]の研究所[けんきゅうじょ]だった。", "sentence_source": "generated"}, {"text": "このアンテナは木に擬装してあり、景色をこわさない。", "target_word": "擬装", "complexity_tier": "T3", "furigana": "このアンテナは木[き]に擬装[ぎそう]してあり、景色[けしき]をこわさない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "擬装", "label": "基本形"}, {"form": "擬装する", "label": "する動詞形"}, {"form": "擬装して", "label": "て形"}, {"form": "擬装された", "label": "受身過去形"}], "register": "formal", "sense_fingerprint": "本当の姿や目的を隠すため、別のものに見せかけること、またその手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擬装", "is_correct": true, "explanation": "「公園に見える擬装がされていた」は公園のように見せかけた工夫を表し、文脈に合う。"}, {"text": "感動", "is_correct": false, "explanation": "感動は心が動くこと。「擬装が」の位置に入れると意味が通らない。"}, {"text": "依存", "is_correct": false, "explanation": "依存は頼ること。「公園に見える依存がされていた」は文として成り立たない。"}, {"text": "謙遜", "is_correct": false, "explanation": "謙遜は自分を低く言うこと。「公園に見える謙遜がされていた」は意味が通らない。"}], "explanations": {"擬装": "「公園に見える擬装がされていた」は公園のように見せかけた工夫を表し、文脈に合う。", "感動": "感動は心が動くこと。「擬装が」の位置に入れると意味が通らない。", "依存": "依存は頼ること。「公園に見える依存がされていた」は文として成り立たない。", "謙遜": "謙遜は自分を低く言うこと。「公園に見える謙遜がされていた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "擬装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の原因を擬装して、調査を妨げた。", "explanation": "ここは〈隠蔽〉（事実を隠す）の意味。〈擬装〉は別のものに見せかける意味で、事実を隠して調査を妨げる行為は表せない。"}, {"text": "このマンガは擬装が多く、動きが伝わる。", "explanation": "ここは〈擬音〉（音や動きをまねた語）の意味。〈擬装〉は本物らしく見せかけることで、音の表現には使えない。"}, {"text": "食品の産地表示を擬装して販売した。", "explanation": "ここは〈偽装〉（偽って表示すること）の意味。〈擬装〉は本当の姿を隠して別のものに見せかける意味で、表示の偽りには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擬装", "is_correct": true, "explanation": "「古い工場に擬装された」は古い工場のように見せかけられたことを表し、荷を隠す文脈に合う。"}, {"text": "解説", "is_correct": false, "explanation": "解説は説明すること。「古い工場に解説された」は文として成り立たない。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えること。「古い工場に換気された」は場所を物のように扱う文として成り立たない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かすこと。「古い工場に解凍された」は文として成り立たない。"}], "explanations": {"擬装": "「古い工場に擬装された」は古い工場のように見せかけられたことを表し、荷を隠す文脈に合う。", "解説": "解説は説明すること。「古い工場に解説された」は文として成り立たない。", "換気": "換気は空気を入れ替えること。「古い工場に換気された」は場所を物のように扱う文として成り立たない。", "解凍": "解凍は凍ったものを溶かすこと。「古い工場に解凍された」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "擬装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "役者は擬装を入念に整えた。", "explanation": "ここは〈扮装〉（役に合わせて装うこと）の意味。〈擬装〉は本当の姿を隠すために別のものに見せかける意味で、役作りの衣装には使えない。"}, {"text": "広場の木を電飾で擬装した。", "explanation": "ここは〈装飾〉（飾ること）の意味。〈擬装〉は本当の姿を隠す意味で、飾り付けには使えない。"}, {"text": "身分証を擬装した。", "explanation": "ここは〈偽造〉（公的な書類を偽って作ること）の意味。〈擬装〉は別のものに見せかける意味で、身分証を偽って作る行為は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場は、遠くから見ると公園に見える擬装で施されていた。", "corrected_sentence": "工場は、遠くから見ると公園に見える擬装が施されていた。", "error_description": "「施す」の受け身では施された対象が主語になり「が」で示す。「擬装で」は手段の「で」で主語を示せず誤り。正しくは「擬装が施されていた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上の小屋は、木に擬装あり、気づかれにくい。", "corrected_sentence": "山の上の小屋は、木に擬装してあり、気づかれにくい。", "error_description": "「擬装」を動詞句にするには「して」が必要。「擬装あり」では文として成り立たない。正しくは「擬装してあり」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
