INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52630, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "力や能力がなく、何もできないこと。また、そのさま。", "primary_collocate": null, "pronunciation": "むりょく", "ipa": "mɯɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "いかなる偽装も、この厳密な科学的検証の前では無力だ。", "target_word": "無力", "complexity_tier": "T3", "furigana": "いかなるぎそうも、このげんみつなかがくてきけんしょうのまえではむりょくだ。", "sentence_source": "generated"}, {"text": "大きな災害の前では、人間は無力だと感じることがある。", "target_word": "無力", "complexity_tier": "T3", "furigana": "おおきなさいがいのまえでは、にんげんはむりょくだとかんじることがある。", "sentence_source": "generated"}, {"text": "病気の友達を前にして、自分の無力が悔しかった。", "target_word": "無力", "complexity_tier": "T3", "furigana": "びょうきのともだちをまえにして、じぶんのむりょくがくやしかった。", "sentence_source": "generated"}, {"text": "医者は、あらゆる手を尽くしても助けられない無力な状況に苦しんだ。", "target_word": "無力", "complexity_tier": "T3", "furigana": "いしゃは、あらゆるてをつくしてもたすけられないむりょくなじょうきょうにくるしんだ。", "sentence_source": "generated"}, {"text": "子どもの泣き声を聞いても、何もできず無力に立ちつくした。", "target_word": "無力", "complexity_tier": "T3", "furigana": "こどものなきごえをきいても、なにもできずむりょくにたちつくした。", "sentence_source": "generated"}, {"text": "武器を持たない市民は、軍隊の前では無力だった。", "target_word": "無力", "complexity_tier": "T3", "furigana": "ぶきをもたないしみんは、ぐんたいのまえではむりょくだった。", "sentence_source": "generated"}, {"text": "彼は自分の無力を認めて、周りに助けを求めた。", "target_word": "無力", "complexity_tier": "T3", "furigana": "かれはじぶんのむりょくをみとめて、まわりにたすけをもとめた。", "sentence_source": "generated"}, {"text": "相手が強すぎて、私の作戦はまったく無力だった。", "target_word": "無力", "complexity_tier": "T3", "furigana": "あいてがつよすぎて、わたしのさくせんはまったくむりょくだった。", "sentence_source": "generated"}, {"text": "戦争の前では、言葉はあまりにも無力に思える。", "target_word": "無力", "complexity_tier": "T3", "furigana": "せんそうのまえでは、ことばはあまりにもむりょくにおもえる。", "sentence_source": "generated"}, {"text": "一人ひとりは無力だと感じても、声を合わせれば社会を動かせる。", "target_word": "無力", "complexity_tier": "T3", "furigana": "ひとりひとりはむりょくだとかんじても、こえをあわせればしゃかいをうごかせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無力", "label": "基本形"}, {"form": "無力だ", "label": "断定形"}, {"form": "無力な", "label": "連体形"}, {"form": "無力に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "力や能力がなく何もできないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 立ちつくし (Zipf 1.74)']::text[], '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無力", "is_correct": true, "explanation": "「検証の前では偽装が無力だ」の「無力」。力が及ばない状態を表し、文脈に合う。"}, {"text": "無念", "is_correct": false, "explanation": "無念は悔しさを表す語で、偽装の状態を述べる文脈には合わない。"}, {"text": "無礼", "is_correct": false, "explanation": "無礼は失礼の意味で、偽装の性質を述べる文脈には合わない。"}, {"text": "無口", "is_correct": false, "explanation": "無口は口数が少ない意味で、偽装の状態を述べる文脈には合わない。"}], "explanations": {"無力": "「検証の前では偽装が無力だ」の「無力」。力が及ばない状態を表し、文脈に合う。", "無念": "無念は悔しさを表す語で、偽装の状態を述べる文脈には合わない。", "無礼": "無礼は失礼の意味で、偽装の性質を述べる文脈には合わない。", "無口": "無口は口数が少ない意味で、偽装の状態を述べる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "無力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼のプレーは無力で、誰も止められなかった。", "explanation": "無力は力がないことで、強さで相手を寄せ付けない意味は表せない。"}, {"text": "期限が過ぎたので、このクーポンは無力になった。", "explanation": "無力は人や組織の力のなさを表し、期限切れで使えなくなる物の意味にはならない。"}, {"text": "この美術館は週末、入場が無力になる。", "explanation": "無力は力がないことを表し、料金がかからない意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無力", "is_correct": true, "explanation": "「自分の無力」は自分の力のなさを指し、それを認めて助けを求める流れに合う。"}, {"text": "無縁", "is_correct": false, "explanation": "「自分の無縁」は関係がないことで、認めて助けを求める文脈に合わない。"}, {"text": "無傷", "is_correct": false, "explanation": "「自分の無傷」は傷がないことで、認めるという内容と合わない。"}, {"text": "無害", "is_correct": false, "explanation": "「自分の無害」は害がないことで、助けを求める理由にならない。"}], "explanations": {"無力": "「自分の無力」は自分の力のなさを指し、それを認めて助けを求める流れに合う。", "無縁": "「自分の無縁」は関係がないことで、認めて助けを求める文脈に合わない。", "無傷": "「自分の無傷」は傷がないことで、認めるという内容と合わない。", "無害": "「自分の無害」は害がないことで、助けを求める理由にならない。"}, "sentence_index": 6, "correct_answer": "無力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は考え事をしながら、無力に机を指で叩いていた。", "explanation": "無力は力がないことで、無意識に体を動かす様子は表せない。"}, {"text": "迷ったときは、無力な服を選ぶのが一番だ。", "explanation": "無力は力がないことで、失敗のない穏当な選択の意味にはならない。"}, {"text": "その日程では間に合わないので、無力だと伝えた。", "explanation": "無力は力のなさを表し、できないと断る理由の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医者は、無力の状況に苦しんだ。", "corrected_sentence": "医者は、無力な状況に苦しんだ。", "error_description": "誤: 無力の状況 / 正: 無力な状況。形状詞は名詞を修飾するとき「な」を付け、「の」は付けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無力", "is_correct": true, "explanation": "「無力だと感じる」の語幹。断定の「だ」の前に来る形で、人間が力のない状態だと述べる文に合う。"}, {"text": "無力な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。「無力な〜」となり、「だと感じる」の前には置けない。"}, {"text": "無力に", "is_correct": false, "explanation": "連用形で動詞を修飾する形。「無力にだと感じる」は成り立たず、述語の位置に入らない。"}, {"text": "無力で", "is_correct": false, "explanation": "中止・て形。続けて述べる形で、「だと感じる」の前には置けず文がつながらない。"}], "correct_form": "無力", "base_form": "無力", "form_label": "語幹（断定「だ」の前）", "sentence_index": 1, "explanations": {"無力": "「無力だと感じる」の語幹。断定の「だ」の前に来る形で、人間が力のない状態だと述べる文に合う。", "無力な": "連体形で名詞を修飾する形。「無力な〜」となり、「だと感じる」の前には置けない。", "無力に": "連用形で動詞を修飾する形。「無力にだと感じる」は成り立たず、述語の位置に入らない。", "無力で": "中止・て形。続けて述べる形で、「だと感じる」の前には置けず文がつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自分の無力に認めて、仲間に助けを求めた。", "corrected_sentence": "彼は自分の無力を認めて、仲間に助けを求めた。", "error_description": "誤: 無力に認めて / 正: 無力を認めて。「認める」は対象を「を」で受けるので、ここの「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無力", "is_correct": true, "explanation": "「無力だった」の語幹。過去の断定の前に来る形で、作戦が効かなかったと述べる文に合う。"}, {"text": "無力だ", "is_correct": false, "explanation": "断定形そのもの。「無力だだった」となり、過去の断定「だった」と重ならないので文が成り立たない。"}, {"text": "無力であった", "is_correct": false, "explanation": "文語的な過去の形。「だった」と重ねられず、語幹の位置には入らない。"}, {"text": "無力だろう", "is_correct": false, "explanation": "推量の形。「無力だろうだった」は成り立たず、過去の断定と重ならない。"}], "correct_form": "無力", "base_form": "無力", "form_label": "語幹（断定の過去「だった」の前）", "sentence_index": 7, "explanations": {"無力": "「無力だった」の語幹。過去の断定の前に来る形で、作戦が効かなかったと述べる文に合う。", "無力だ": "断定形そのもの。「無力だだった」となり、過去の断定「だった」と重ならないので文が成り立たない。", "無力であった": "文語的な過去の形。「だった」と重ねられず、語幹の位置には入らない。", "無力だろう": "推量の形。「無力だろうだった」は成り立たず、過去の断定と重ならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "マクロ", "is_correct": true, "explanation": "ミクロ（小さな世界）の対義語で、大きな規模の世界を指すので対になる。"}, {"text": "光線", "is_correct": false, "explanation": "光の経路を表す語で、ミクロと対になる語ではない。"}, {"text": "砂漠", "is_correct": false, "explanation": "地形を表す語で、規模の対にはならない。"}, {"text": "水分", "is_correct": false, "explanation": "液体の成分を表す語で、ミクロの対義語にはならない。"}], "correct_answer": "マクロ", "explanations": {"マクロ": "ミクロ（小さな世界）の対義語で、大きな規模の世界を指すので対になる。", "光線": "光の経路を表す語で、ミクロと対になる語ではない。", "砂漠": "地形を表す語で、規模の対にはならない。", "水分": "液体の成分を表す語で、ミクロの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ミクロ」を修飾し、「ミクロの世界」として番組の内容を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ミクロが世界を紹介する」となり、番組を修飾する形にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「ミクロ」と「世界」を結べない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、「ミクロ」と「世界」をつなぐ役割にはならない。"}], "correct_answer": "の", "explanations": {"の": "「ミクロ」を修飾し、「ミクロの世界」として番組の内容を示す。", "が": "「ミクロが世界を紹介する」となり、番組を修飾する形にならない。", "から": "起点を表し、「ミクロ」と「世界」を結べない。", "より": "比較を表す助詞で、「ミクロ」と「世界」をつなぐ役割にはならない。"}, "error_tags": {"が": "主格", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "マクロ", "is_correct": true, "explanation": "ミクロの対義語で、大きな規模から見る世界を指すので対になる。"}, {"text": "青空", "is_correct": false, "explanation": "空の景色を表す語で、ミクロと対になる語ではない。"}, {"text": "湖", "is_correct": false, "explanation": "地形を表す語で、規模の対にはならない。"}, {"text": "旅館", "is_correct": false, "explanation": "建物を表す語で、ミクロの対義語にはならない。"}], "correct_answer": "マクロ", "explanations": {"マクロ": "ミクロの対義語で、大きな規模から見る世界を指すので対になる。", "青空": "空の景色を表す語で、ミクロと対になる語ではない。", "湖": "地形を表す語で、規模の対にはならない。", "旅館": "建物を表す語で、ミクロの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とても小さいものや、細かい部分を表す言葉です。", "primary_collocate": null, "pronunciation": "みくろ", "ipa": "mikɯɾo", "syllable_count": 3, "sentences": [{"text": "顕微鏡を使うと、ミクロの世界が見えてくる。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]を使[つか]うと、ミクロの世界[せかい]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "この虫の羽は、ミクロのレベルで見ると美しい模様がある。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "この虫[むし]の羽[はね]は、ミクロ[みくろ]のレベルで見[み]ると美[うつく]しい模様[もよう]がある。", "sentence_source": "generated"}, {"text": "洗顔料のミクロの粒が、毛穴の汚れを落としてくれる。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "洗顔料[せんがんりょう]のミクロの粒[つぶ]が、毛穴[けあな]の汚[よご]れを落[お]としてくれる。", "sentence_source": "generated"}, {"text": "精密な機械は、ミクロの違いでも動かなくなることがある。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "精密[せいみつ]な機械[きかい]は、ミクロの違[ちが]いでも動[うご]かなくなることがある。", "sentence_source": "generated"}, {"text": "写真をミクロの部分まで拡大して、傷の様子を確認した。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "写真[しゃしん]をミクロの部分[ぶぶん]まで拡大[かくだい]して、傷[きず]の様子[ようす]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "水一滴の中にも、ミクロの生き物がたくさんいる。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "水一滴[みずいってき]の中[なか]にも、ミクロの生[い]き物[もの]がたくさんいる。", "sentence_source": "generated"}, {"text": "職人はミクロの狂いも見逃さず、部品を磨き上げた。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "職人[しょくにん]はミクロの狂[くる]いも見逃[みのが]さず、部品[ぶひん]を磨[みが]き上[あ]げた。", "sentence_source": "generated"}, {"text": "子どもたちは、ミクロの世界を紹介する番組に夢中になった。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ミクロの世界[せかい]を紹介[しょうかい]する番組[ばんぐみ]に夢中[むちゅう]になった。", "sentence_source": "generated"}, {"text": "この工場では、ミクロ単位の精度で部品を作っている。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、ミクロ単位[たんい]の精度[せいど]で部品[ぶひん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "雪の結晶をミクロの目で見ると、ひとつずつ形がちがう。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "雪[ゆき]の結晶[けっしょう]をミクロの目[め]で見[み]ると、ひとつずつ形[かたち]がちがう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミクロ", "label": "基本形"}, {"form": "ミクロな", "label": "連体形"}], "register": "中立・話し言葉", "sense_fingerprint": "肉眼では見えないほど非常に小さいものや細部(ミクロの世界)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "肉眼で見えない小さな世界を指し、顕微鏡で見える対象に合う。"}, {"text": "深夜", "is_correct": false, "explanation": "時間を表す語で、顕微鏡で見える世界とは合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、顕微鏡で見る対象にはならない。"}, {"text": "地平線", "is_correct": false, "explanation": "遠くの景色を表す語で、顕微鏡の対象ではない。"}], "explanations": {"ミクロ": "肉眼で見えない小さな世界を指し、顕微鏡で見える対象に合う。", "深夜": "時間を表す語で、顕微鏡で見える世界とは合わない。", "夕焼け": "空の現象で、顕微鏡で見る対象にはならない。", "地平線": "遠くの景色を表す語で、顕微鏡の対象ではない。"}, "sentence_index": 0, "correct_answer": "ミクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ミクロに大きな声で叫んで、会場を驚かせた。", "explanation": "ここは〈大声で〉の意味。ミクロは小ささを表す語なので、大きな声の様子には合わない。"}, {"text": "土の中には、ミクロがたくさんいる。", "explanation": "ここは「微生物」の意味。ミクロは小さな世界を指す語で、生き物そのものは表さないので合わない。"}, {"text": "見上げるほどの、ミクロな山脈が広がっている。", "explanation": "ここは〈大きい〉の意味。ミクロは小さいものを指す語なので、見上げるほどの山脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "「の狂い」に続けて、非常に小さな精度の差を表すので、ここに入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖の狂い」は成り立たず、ここでは合わない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震の狂い」は意味が通らず、部品の精度の文脈に合わない。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草の狂い」は成り立たず、磨き上げる部品の文脈と合わない。"}], "explanations": {"ミクロ": "「の狂い」に続けて、非常に小さな精度の差を表すので、ここに入る。", "砂糖": "「砂糖の狂い」は成り立たず、ここでは合わない。", "地震": "「地震の狂い」は意味が通らず、部品の精度の文脈に合わない。", "雑草": "「雑草の狂い」は成り立たず、磨き上げる部品の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "ミクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "馬は、ミクロな速さでゴールに駆け込んだ。", "explanation": "ここは〈猛烈な速さ〉の意味。ミクロは小ささを表す語なので、速さの程度には合わない。"}, {"text": "測定のミクロが大きくて、計算が合わなかった。", "explanation": "ここは「誤差」の意味。ミクロはずれの大きさを表す語ではないので、この文には合わない。"}, {"text": "このボールのミクロは三センチだ。", "explanation": "ここは「直径」の意味。ミクロは大きさの数値を表す語ではないので、長さの説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "顕微鏡で見るミクロに世界は美しい。", "corrected_sentence": "顕微鏡で見るミクロの世界は美しい。", "error_description": "「ミクロ」と名詞「世界」をつなぐ助詞は「の」。「に」にすると名詞を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52631, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部品はミクロ単語で管理されている。", "corrected_sentence": "この部品はミクロ単位で管理されている。", "error_description": "「ミクロ」の後に続く語は「単位」など小さな量を示す語。「単語」は組み合わず、不自然な誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "マクロ", "is_correct": true, "explanation": "ミクロの対義語で、全体の傾向から見る視点を表すので、この語義と対になる。"}, {"text": "具体的", "is_correct": false, "explanation": "ミクロではなく「抽象的」の対義語で、この語義とは対を成さない。"}, {"text": "一般的", "is_correct": false, "explanation": "個々の小さな単位を示す語ではないので、ミクロの対義語にならない。"}, {"text": "厳密な", "is_correct": false, "explanation": "正確さを表す語で、視点の規模の対にはならない。"}], "correct_answer": "マクロ", "explanations": {"マクロ": "ミクロの対義語で、全体の傾向から見る視点を表すので、この語義と対になる。", "具体的": "ミクロではなく「抽象的」の対義語で、この語義とは対を成さない。", "一般的": "個々の小さな単位を示す語ではないので、ミクロの対義語にならない。", "厳密な": "正確さを表す語で、視点の規模の対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "マクロ", "is_correct": true, "explanation": "ミクロの対義語で、全体から見る視点を表すので、この語義と対になる。"}, {"text": "直接的", "is_correct": false, "explanation": "作用の仕方を表す語で、視点の規模を表すミクロとは対にならない。"}, {"text": "理論的", "is_correct": false, "explanation": "考え方の性質を表す語で、ミクロの対義語ではない。"}, {"text": "機械的", "is_correct": false, "explanation": "動作の性質を表す語で、規模や視点の対にはならない。"}], "correct_answer": "マクロ", "explanations": {"マクロ": "ミクロの対義語で、全体から見る視点を表すので、この語義と対になる。", "直接的": "作用の仕方を表す語で、視点の規模を表すミクロとは対にならない。", "理論的": "考え方の性質を表す語で、ミクロの対義語ではない。", "機械的": "動作の性質を表す語で、規模や視点の対にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "全体の中の個別の小さな単位や、微視的な視点を指す語。", "primary_collocate": null, "pronunciation": "みくろ", "ipa": "mikɯɾo", "syllable_count": 3, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "グローバルな金融市場[きんゆうしじょう]やサプライチェーンといった社会経済的文脈[しゃかいけいざいてきぶんみゃく]において、個々[ここ]の企業[きぎょう]や投資家[とうしか]といったミクロな主体[しゅたい]による局所的[きょくしょてき]な意思決定[いしけってい]は、決[けっ]して単純[たんじゅん]な線形[せんけい]モデルでは捉[とら]えきれない。", "sentence_source": "mined"}, {"text": "経済をミクロな視点で見ると、一軒の店の売り上げが何で決まるかが分かる。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "経済[けいざい]をミクロな視点[してん]で見[み]ると、一軒[いっけん]の店[みせ]の売[う]り上[あ]げが何[なに]で決[き]まるかが分[わ]かる。", "sentence_source": "generated"}, {"text": "国全体の景気ではなく、ミクロな家計の動きを調べた。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "国全体[くにぜんたい]の景気[けいき]ではなく、ミクロな家計[かけい]の動[うご]きを調[しら]べた。", "sentence_source": "generated"}, {"text": "個人の選択というミクロな動きが、社会全体の流れをつくる。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "個人[こじん]の選択[せんたく]というミクロな動[うご]きが、社会全体[しゃかいぜんたい]の流[なが]れをつくる。", "sentence_source": "generated"}, {"text": "全体の数字だけでは分からないので、ミクロの視点で一人ひとりの行動を分析した。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の数字[すうじ]だけでは分[わ]からないので、ミクロの視点[してん]で一人[ひとり]ひとりの行動[こうどう]を分析[ぶんせき]した。", "sentence_source": "generated"}, {"text": "国の政策は、ミクロな実態を把握せずには成功しない。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "国[くに]の政策[せいさく]は、ミクロ[みくろ]な実態[じったい]を把握[はあく]せずには成功[せいこう]しない。", "sentence_source": "generated"}, {"text": "彼の研究は、ミクロな事例を積み重ねて全体の傾向を説明している。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "彼[かれ]の研究[けんきゅう]は、ミクロな事例[じれい]を積[つ]み重[かさ]ねて全体[ぜんたい]の傾向[けいこう]を説明[せつめい]している。", "sentence_source": "generated"}, {"text": "町全体の人口ではなく、ミクロなレベルで各家庭の事情を調べる必要がある。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "町全体[まちぜんたい]の人口[じんこう]ではなく、ミクロなレベルで各家庭[かくかてい]の事情[じじょう]を調[しら]べる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "社長は会社全体の戦略を考えるが、現場の課長はミクロな視点から業務の細部を改善する。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は会社[かいしゃ]全体[ぜんたい]の戦略[せんりゃく]を考[かんが]えるが、現場[げんば]の課長[かちょう]はミクロ[みくろ]な視点[してん]から業務[ぎょうむ]の細部[さいぶ]を改善[かいぜん]する。", "sentence_source": "generated"}, {"text": "ミクロな視点とマクロな視点の両方がなければ、問題の本質は見えてこない。", "target_word": "ミクロ", "complexity_tier": "T3", "furigana": "ミクロな視点[してん]とマクロな視点[してん]の両方[りょうほう]がなければ、問題[もんだい]の本質[ほんしつ]は見[み]えてこない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミクロ", "label": "語幹"}, {"form": "ミクロな", "label": "連体形"}, {"form": "ミクロに", "label": "連用形"}, {"form": "ミクロだ", "label": "断定形"}], "register": "学術的・書き言葉", "sense_fingerprint": "全体ではなく個々の小さな単位から見る微視的な視点(マクロの対)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "「個々の企業や投資家」を修飾し、個別の小さな単位を表すので、ここに入る。"}, {"text": "全体的", "is_correct": false, "explanation": "「個々の」と矛盾し、個別の主体を表す語として成り立たない。"}, {"text": "抽象的", "is_correct": false, "explanation": "企業や投資家という具体的な主体には合わない。"}, {"text": "平均的", "is_correct": false, "explanation": "個々の主体を平均で表すのは、ここの文脈と噛み合わない。"}], "explanations": {"ミクロ": "「個々の企業や投資家」を修飾し、個別の小さな単位を表すので、ここに入る。", "全体的": "「個々の」と矛盾し、個別の主体を表す語として成り立たない。", "抽象的": "企業や投資家という具体的な主体には合わない。", "平均的": "個々の主体を平均で表すのは、ここの文脈と噛み合わない。"}, "sentence_index": 0, "correct_answer": "ミクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政策は、ミクロな国家レベルで設計すると効果が出やすい。", "explanation": "ここは〈マクロ〉の意味（国全体の規模）。ミクロは個々の小さな単位を指す語なので、国家レベルの話には合わない。"}, {"text": "この先生は生徒の性格にミクロに合わせて、授業を組み立てている。", "explanation": "ここは「個別に」の意味。ミクロは規模や視点を表す語で、「合わせる」という動作の仕方には使えない。"}, {"text": "景気の先行きを、ミクロな大局の視点で予測した。", "explanation": "ここは〈マクロ〉の意味（全体の規模）。ミクロは個々の小さな単位を指す語なので、全体の見方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "個別の事例を修飾し、全体の傾向と対比される小さな単位の意味に合う。"}, {"text": "感情的", "is_correct": false, "explanation": "研究の事例を修飾する語として不自然で、文脈に合わない。"}, {"text": "はなやかな", "is_correct": false, "explanation": "事例を積み重ねて傾向を説明する研究の文脈と合わず、「はなやかな事例」は意味が通らない。"}, {"text": "不規則", "is_correct": false, "explanation": "規則性から傾向を導く文脈で、事例の性質として合わない。"}], "explanations": {"ミクロ": "個別の事例を修飾し、全体の傾向と対比される小さな単位の意味に合う。", "感情的": "研究の事例を修飾する語として不自然で、文脈に合わない。", "はなやかな": "事例を積み重ねて傾向を説明する研究の文脈と合わず、「はなやかな事例」は意味が通らない。", "不規則": "規則性から傾向を導く文脈で、事例の性質として合わない。"}, "sentence_index": 6, "correct_answer": "ミクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全国の経済の姿を、ミクロな全体像として一度に示す。", "explanation": "ここは〈マクロ〉の意味（全体の規模）。ミクロは個々の小さな単位を指す語なので、全体像には合わない。"}, {"text": "報告書は、ミクロにまとめられていて、細部まで詳しく書いてあった。", "explanation": "ここは〈簡潔〉の意味。ミクロは個々の小さな単位や微視的な視点を指す語で、要約の仕方には使わない。"}, {"text": "詳細を省いて説明したので、ミクロを省いたことになる。", "explanation": "ここは〈細部〉の意味。ミクロは規模や視点を表す語で、省く対象の細部とは意味が違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ミクロに視点で見ると、個人の行動パターンが見えてくる。", "corrected_sentence": "ミクロな視点で見ると、個人の行動パターンが見えてくる。", "error_description": "形状詞「ミクロ」は名詞を修飾するとき「ミクロな」になる。「ミクロに」は連用形で、直後の名詞「視点」を修飾できないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "語幹の形。形状詞「ミクロ」の基本形で、この問いの答えとして語幹を選ぶ。"}, {"text": "ミクロな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、この問いで求めている語幹とは別の形。"}, {"text": "ミクロに", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、語幹を求める問いには合わない。"}, {"text": "ミクロだ", "is_correct": false, "explanation": "断定形。文末で述語になる形で、語幹を求める問いには合わない。"}], "correct_form": "ミクロ", "base_form": "ミクロ", "form_label": "語幹", "sentence_index": 1, "explanations": {"ミクロ": "語幹の形。形状詞「ミクロ」の基本形で、この問いの答えとして語幹を選ぶ。", "ミクロな": "連体形。名詞を修飾する形で、この問いで求めている語幹とは別の形。", "ミクロに": "連用形。動詞や形容詞を修飾する形で、語幹を求める問いには合わない。", "ミクロだ": "断定形。文末で述語になる形で、語幹を求める問いには合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ミクロな体重で見ると、客一人ひとりの買い方が分かる。", "corrected_sentence": "ミクロな視点で見ると、客一人ひとりの買い方が分かる。", "error_description": "「ミクロな」の後には「視点」など微視的な見方を表す語が続く。「体重」は意味が組み合わず、コロケーションとして誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ミクロ", "is_correct": true, "explanation": "語幹の形。形状詞「ミクロ」の基本形で、この問いの答えとして語幹を選ぶ。"}, {"text": "ミクロだった", "is_correct": false, "explanation": "断定形の過去形。文末で過去を表す述語の形で、語幹を求める問いの答えにはならない。"}, {"text": "ミクロではない", "is_correct": false, "explanation": "否定形。「ではない」で打ち消す形で、語幹そのものを答えとする問いには当たらない。"}, {"text": "ミクロなら", "is_correct": false, "explanation": "仮定形。条件を表す形で、この問いの語幹とは異なる。"}], "correct_form": "ミクロ", "base_form": "ミクロ", "form_label": "語幹", "sentence_index": 7, "explanations": {"ミクロ": "語幹の形。形状詞「ミクロ」の基本形で、この問いの答えとして語幹を選ぶ。", "ミクロだった": "断定形の過去形。文末で過去を表す述語の形で、語幹を求める問いの答えにはならない。", "ミクロではない": "否定形。「ではない」で打ち消す形で、語幹そのものを答えとする問いには当たらない。", "ミクロなら": "仮定形。条件を表す形で、この問いの語幹とは異なる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「正負がある」の主語を示す「が」。電池に存在する性質として正負があるので、この形が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語をとらない動詞なので、「正負を」は不可。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、存在を表す「ある」の文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」だと名詞修飾になり、「あるので」に続く主語が立たない。"}], "correct_answer": "が", "explanations": {"が": "「正負がある」の主語を示す「が」。電池に存在する性質として正負があるので、この形が正しい。", "を": "「ある」は目的語をとらない動詞なので、「正負を」は不可。", "へ": "方向を示す「へ」は、存在を表す「ある」の文には合わない。", "の": "連体修飾の「の」だと名詞修飾になり、「あるので」に続く主語が立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「正負の両面」の連体修飾の「の」。正負という対が両面を修飾する形で、この文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「正負を両面がある」では目的語が立たず、「ある」とも合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」だと「正負で両面がある」となり、存在の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、両面が存在する文には合わない。"}], "correct_answer": "の", "explanations": {"の": "「正負の両面」の連体修飾の「の」。正負という対が両面を修飾する形で、この文に合う。", "を": "「正負を両面がある」では目的語が立たず、「ある」とも合わない。", "で": "手段の「で」だと「正負で両面がある」となり、存在の文として成り立たない。", "へ": "方向の「へ」は、両面が存在する文には合わない。"}, "error_tags": {"を": "目的語の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「せいふ」は、プラスとマイナス、いいこととわるいこと、というように、反対の二つのことをまとめて言うことばです。", "primary_collocate": null, "pronunciation": "せいふ", "ipa": "seːɸɯ", "syllable_count": 3, "sentences": [{"text": "先生は黒板に、数の正負を分けて書いた。", "target_word": "正負", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に、数[かず]の正負[せいふ]を分[わ]けて書[か]いた。", "sentence_source": "generated"}, {"text": "電池には正負があるので、向きを間違えてはいけない。", "target_word": "正負", "complexity_tier": "T3", "furigana": "電池[でんち]には正負[せいふ]があるので、向[む]きを間違[まちが]えてはいけない。", "sentence_source": "generated"}, {"text": "テストの点数が上がったか下がったかは、正負で表せる。", "target_word": "正負", "complexity_tier": "T3", "furigana": "テストの点数[てんすう]が上[あ]がったか下[さ]がったかは、正負[せいふ]で表[あらわ]せる。", "sentence_source": "generated"}, {"text": "数の計算では、まず正負を見ることが大切だ。", "target_word": "正負", "complexity_tier": "T3", "furigana": "数[かず]の計算[けいさん]では、まず正負[せいふ]を見[み]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "正負の数の足し算を、ノートで練習した。", "target_word": "正負", "complexity_tier": "T3", "furigana": "正負[せいふ]の数[かず]の足[た]し算[ざん]を、ノートで練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "新しい町の計画は、住民の暮らしに正負の影響を与えると考えられる。", "target_word": "正負", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]の計画[けいかく]は、住民[じゅうみん]の暮[く]らしに正負[せいふ]の影響[えいきょう]を与[あた]えると考[かんが]えられる。", "sentence_source": "generated"}, {"text": "温度が0度より上か下かは、正負で分けて考える。", "target_word": "正負", "complexity_tier": "T3", "furigana": "温度[おんど]が0度[ど]より上[うえ]か下[した]かは、正負[せいふ]で分[わ]けて考[かんが]える。", "sentence_source": "generated"}, {"text": "その仕事には正負の両面があるので、よく考えて決めよう。", "target_word": "正負", "complexity_tier": "T3", "furigana": "その仕事[しごと]には正負[せいふ]の両面[りょうめん]があるので、よく考[かんが]えて決[き]めよう。", "sentence_source": "generated"}, {"text": "正負をまちがえたので、答えが逆になってしまった。", "target_word": "正負", "complexity_tier": "T3", "furigana": "正負[せいふ]をまちがえたので、答[こた]えが逆[ぎゃく]になってしまった。", "sentence_source": "generated"}, {"text": "宿題の問題で、答えの正負だけ先に予想した。", "target_word": "正負", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]の問題[もんだい]で、答[こた]えの正負[せいふ]だけ先[さき]に予想[よそう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "正負", "label": "基本形"}, {"form": "正負の", "label": "連体修飾(の)"}, {"form": "正負を", "label": "目的格"}], "register": "中立・丁寧", "sense_fingerprint": "プラスとマイナス、良いことと悪いことなど反対の二つをまとめて言う語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正負", "is_correct": true, "explanation": "ここは〈正負〉（プラスとマイナス、良いことと悪いことなど反対の二つをまとめて言う語）の意味。数を二つに分けて書く文脈に合う。"}, {"text": "筆順", "is_correct": false, "explanation": "漢字を書く順序を指す語。「数の筆順を分けて書いた」では意味が通らない。"}, {"text": "余白", "is_correct": false, "explanation": "紙の空いている部分を指す語。数を分類して書く文脈には入らない。"}, {"text": "行間", "is_correct": false, "explanation": "行と行のあいだを指す語。数を分けて書く対象にはならず、文が成り立たない。"}], "explanations": {"正負": "ここは〈正負〉（プラスとマイナス、良いことと悪いことなど反対の二つをまとめて言う語）の意味。数を二つに分けて書く文脈に合う。", "筆順": "漢字を書く順序を指す語。「数の筆順を分けて書いた」では意味が通らない。", "余白": "紙の空いている部分を指す語。数を分類して書く文脈には入らない。", "行間": "行と行のあいだを指す語。数を分けて書く対象にはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "正負"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テスト問題の正負を確かめた。", "explanation": "正負には〈正誤〉の意味がない。正誤の確認には使えず、この文は成り立たない。"}, {"text": "電報の正負を読み解いた。", "explanation": "正負は＋と−の符号を指すが、電報の記号列には使えず、この文は成り立たない。"}, {"text": "ピアノで正負を練習した。", "explanation": "正負には〈音階〉の意味がない。楽器の練習対象にはならず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正負", "is_correct": true, "explanation": "ここは〈正負〉（プラスとマイナス）の意味。温度が0度より上か下かで二つに分けて考える文脈に合う。"}, {"text": "鉄道", "is_correct": false, "explanation": "鉄のレールを走る乗り物を指す語。温度を分けて考える手段にはならず、文が通らない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を調理することを指す語。温度の上下を分ける方法にはならない。"}, {"text": "彫刻", "is_correct": false, "explanation": "立体の美術作品を指す語。温度の上下を分ける文脈では合わない。"}], "explanations": {"正負": "ここは〈正負〉（プラスとマイナス）の意味。温度が0度より上か下かで二つに分けて考える文脈に合う。", "鉄道": "鉄のレールを走る乗り物を指す語。温度を分けて考える手段にはならず、文が通らない。", "料理": "食べ物を調理することを指す語。温度の上下を分ける方法にはならない。", "彫刻": "立体の美術作品を指す語。温度の上下を分ける文脈では合わない。"}, "sentence_index": 6, "correct_answer": "正負"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の正負だけ先に予想した。", "explanation": "正負には〈勝敗〉の意味がない。試合の結果の予想には使えず、この文は成り立たない。"}, {"text": "実験の正負を乗り越えた。", "explanation": "正負には〈障害〉の意味がない。乗り越える対象にはならず、この文は成り立たない。"}, {"text": "講座には正負を超える申し込みがあった。", "explanation": "正負には〈定員〉の意味がない。人数の上限は表せず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数の正負をわかれば、計算は楽になる。", "corrected_sentence": "数の正負がわかれば、計算は楽になる。", "error_description": "「わかる」は主語に「が」をとる。「正負を」は誤りで、正しくは「正負が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52633, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "答えの正負を予想すって、確かめた。", "corrected_sentence": "答えの正負を予想して、確かめた。", "error_description": "「予想する」の て形は「予想して」。「予想すって」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「正負が分かれる」の主語を示す「が」。分かれる主体が正負という対なので、この形が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「分かれる」は目的語をとらない自動詞なので、「正負を分かれて」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "行き先を示す「へ」は、対が二つに分かれて並ぶ結果の様子には合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞どうしをつなぐだけで、動詞「分かれて」の主語にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「正負が分かれる」の主語を示す「が」。分かれる主体が正負という対なので、この形が正しい。", "を": "「分かれる」は目的語をとらない自動詞なので、「正負を分かれて」は成り立たない。", "へ": "行き先を示す「へ」は、対が二つに分かれて並ぶ結果の様子には合わない。", "の": "連体修飾の「の」は名詞どうしをつなぐだけで、動詞「分かれて」の主語にならず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「正負を含める」の目的語を示す「を」。含める対象が正負なので、この形が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「正負が含める」では正負が含む側になり、含められる対象の役割を果たせない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」だと「正負で含める」となり、目的語が立たず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」だと「正負と含める」となり、含める対象を示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「正負を含める」の目的語を示す「を」。含める対象が正負なので、この形が正しい。", "が": "「正負が含める」では正負が含む側になり、含められる対象の役割を果たせない。", "で": "手段を示す「で」だと「正負で含める」となり、目的語が立たず文が成り立たない。", "と": "並列の「と」だと「正負と含める」となり、含める対象を示せず不自然。"}, "error_tags": {"が": "主語の誤り", "で": "手段の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「正負」は、数学や物理などで、正（プラス）と負（マイナス）の二つの符号や性質を合わせて指す語。また、良い面と悪い面、肯定的な要素と否定的な要素を対にして表すこともあります。", "primary_collocate": null, "pronunciation": "せいふ", "ipa": "seːɸɯ", "syllable_count": 3, "sentences": [{"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "正負", "complexity_tier": "T3", "furigana": "むしろ、それらの相互作用[そうごさよう]が織[お]りなす複雑適応[ふくざつてきおう]システムにおいては、正負[せいふ]のフィードバックを介[かい]した非線形[ひせんけい]なダイナミクスが、予測不可能[よそくふかのう]なマクロな秩序[ちつじょ]、すなわち創発[そうはつ]をもたらすのである。", "sentence_source": "mined"}, {"text": "数直線では、0を境に正負が分かれて並んでいる。", "target_word": "正負", "complexity_tier": "T3", "furigana": "数直線[すうちょくせん]では、0を境[さかい]に正負[せいふ]が分[わ]かれて並[なら]んでいる。", "sentence_source": "generated"}, {"text": "この回路では、電流の向きによって電圧の正負が入れ替わる。", "target_word": "正負", "complexity_tier": "T3", "furigana": "この回路[かいろ]では、電流[でんりゅう]の向[む]きによって電圧[でんあつ]の正負[せいふ]が入[い]れ替[か]わる。", "sentence_source": "generated"}, {"text": "数学の授業で、計算結果の正負を先に確認する習慣をつけた。", "target_word": "正負", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、計算結果[けいさんけっか]の正負[せいふ]を先[さき]に確認[かくにん]する習慣[しゅうかん]をつけた。", "sentence_source": "generated"}, {"text": "電気には正負の二つの性質があり、同じ性質どうしは反発し合う。", "target_word": "正負", "complexity_tier": "T3", "furigana": "電気[でんき]には正負[せいふ]の二[ふた]つの性質[せいしつ]があり、同[おな]じ性質[せいしつ]どうしは反発[はんぱつ]し合[あ]う。", "sentence_source": "generated"}, {"text": "新しい制度には正負の両面があり、導入前に影響を比べる必要がある。", "target_word": "正負", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]には正負[せいふ]の両面[りょうめん]があり、導入前[どうにゅうまえ]に影響[えいきょう]を比[くら]べる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "変化の大きさだけでなく、その正負も調べて、増えたのか減ったのかを判断した。", "target_word": "正負", "complexity_tier": "T3", "furigana": "変化[へんか]の大[おお]きさだけでなく、その正負[せいふ]も調[しら]べて、増[ふ]えたのか減[へ]ったのかを判断[はんだん]した。", "sentence_source": "generated"}, {"text": "気温の差は正負を含めて記録しないと、上がったのか下がったのか分からない。", "target_word": "正負", "complexity_tier": "T3", "furigana": "気温[きおん]の差[さ]は正負[せいふ]を含[ふく]めて記録[きろく]しないと、上[あ]がったのか下[さ]がったのか分[わ]からない。", "sentence_source": "generated"}, {"text": "彼は物事の正負を冷静に見きわめてから、決断をくだす。", "target_word": "正負", "complexity_tier": "T3", "furigana": "彼[かれ]は物事[ものごと]の正負[せいふ]を冷静[れいせい]に見[み]きわめてから、決断[けつだん]をくだす。", "sentence_source": "generated"}, {"text": "この関数は、入力の正負によって出力を求める式が変わる。", "target_word": "正負", "complexity_tier": "T3", "furigana": "この関数[かんすう]は、入力[にゅうりょく]の正負[せいふ]によって出力[しゅつりょく]を求[もと]める式[しき]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "正負", "label": "基本形"}, {"form": "正負の", "label": "連体修飾(の)"}, {"form": "正負を", "label": "目的格"}], "register": "学術的・書き言葉", "sense_fingerprint": "プラスとマイナスの符号・性質、または良い面と悪い面を対にして指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正負", "is_correct": true, "explanation": "ここは〈正負〉（プラスとマイナスの符号、良い面と悪い面の対）の意味。「正負のフィードバック」は効果の向き（促進と抑制）を表し、文脈に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "色の彩りや濃淡を指す語。フィードバックの向きを表すことができず、この文では成り立たない。"}, {"text": "舞台", "is_correct": false, "explanation": "演劇などが行われる場所を指す語。「舞台のフィードバック」では意味が通らない。"}, {"text": "漁獲", "is_correct": false, "explanation": "魚などを捕ることを指す語。フィードバックの性質を表せず、ここには入らない。"}], "explanations": {"正負": "ここは〈正負〉（プラスとマイナスの符号、良い面と悪い面の対）の意味。「正負のフィードバック」は効果の向き（促進と抑制）を表し、文脈に合う。", "色彩": "色の彩りや濃淡を指す語。フィードバックの向きを表すことができず、この文では成り立たない。", "舞台": "演劇などが行われる場所を指す語。「舞台のフィードバック」では意味が通らない。", "漁獲": "魚などを捕ることを指す語。フィードバックの性質を表せず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "正負"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原稿の正負を一つずつ確認した。", "explanation": "正負には〈正誤〉の意味がない。正誤の確認には使えず、この文は成り立たない。"}, {"text": "暗号の正負を解読した。", "explanation": "正負は＋と−の符号を指すが、暗号の文字列には使えず、この文は成り立たない。"}, {"text": "その計画は市に大きな正負をかけた。", "explanation": "正負には〈負担〉の意味がない。人に重さをかける語ではなく、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正負", "is_correct": true, "explanation": "ここは〈正負〉（増加と減少の符号）の意味。変化の向きを表す符号を指し、「その正負も調べて」の文脈に合う。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序を表す語。増えたか減ったかを判断する文脈では、符号の意味にならず合わない。"}, {"text": "由来", "is_correct": false, "explanation": "ものの起こりや来歴を表す語。変化の向きを判断する文脈とは関係しない。"}, {"text": "素材", "is_correct": false, "explanation": "ものを作る材料のこと。変化の大きさや向きを判断する文脈では意味が通らない。"}], "explanations": {"正負": "ここは〈正負〉（増加と減少の符号）の意味。変化の向きを表す符号を指し、「その正負も調べて」の文脈に合う。", "手順": "作業の順序を表す語。増えたか減ったかを判断する文脈では、符号の意味にならず合わない。", "由来": "ものの起こりや来歴を表す語。変化の向きを判断する文脈とは関係しない。", "素材": "ものを作る材料のこと。変化の大きさや向きを判断する文脈では意味が通らない。"}, "sentence_index": 6, "correct_answer": "正負"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の正負を記録した。", "explanation": "正負には〈勝敗〉の意味がない。試合の結果の記録には使えず、この文は成り立たない。"}, {"text": "行く手の正負を乗り越えた。", "explanation": "正負には〈障害〉の意味がない。乗り越える対象にはならず、この文は成り立たない。"}, {"text": "ピアノで正負を練習した。", "explanation": "正負には〈音階〉の意味がない。楽器の練習対象にはならず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電池の正負に間違えると、機械が動かない。", "corrected_sentence": "電池の正負を間違えると、機械が動かない。", "error_description": "「間違える」は目的語に「を」をとる。「正負に」は誤りで、正しくは「正負を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "温度差は正負を含むて記録しないと、傾向がつかめない。", "corrected_sentence": "温度差は正負を含めて記録しないと、傾向がつかめない。", "error_description": "「正負を含める」の て形は「含めて」。「含むて」は活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「気温のダイナミクスを見る」の目的語を示す「を」。見る対象が気温の変化なので、この形が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ダイナミクスがグラフで見る」では見る主体が立たず、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」だと「ダイナミクスでグラフで見る」となり、見る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、見る対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「気温のダイナミクスを見る」の目的語を示す「を」。見る対象が気温の変化なので、この形が正しい。", "が": "「ダイナミクスがグラフで見る」では見る主体が立たず、不自然になる。", "で": "手段の「で」だと「ダイナミクスでグラフで見る」となり、見る対象を示せない。", "へ": "方向の「へ」は、見る対象を示す文には合わない。"}, "error_tags": {"が": "主語の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ダイナミクスを調べる」の目的語を示す「を」。人の流れの変化を調べる文脈に合う。"}, {"text": "が", "is_correct": false, "explanation": "「ダイナミクスが調べ」では調べる主体が立たず、「が」は不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「ダイナミクスに調べ」は動詞「調べる」の対象を示せず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、調べる対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「ダイナミクスを調べる」の目的語を示す「を」。人の流れの変化を調べる文脈に合う。", "が": "「ダイナミクスが調べ」では調べる主体が立たず、「が」は不自然になる。", "に": "「ダイナミクスに調べ」は動詞「調べる」の対象を示せず、不自然になる。", "へ": "方向の「へ」は、調べる対象を示す文には合わない。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが時間とともに変わっていくようすのことです。", "primary_collocate": null, "pronunciation": "だいなみくす", "ipa": "dainamikɯsɯ", "syllable_count": 6, "sentences": [{"text": "川の水の量のダイナミクスを、一年間記録した。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)の量(りょう)のダイナミクスを、一年間(いちねんかん)記録(きろく)した。", "sentence_source": "generated"}, {"text": "気温のダイナミクスをグラフで見ると、春から夏への変化がよくわかる。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "気温(きおん)のダイナミクスをグラフで見(み)ると、春(はる)から夏(なつ)への変化(へんか)がよくわかる。", "sentence_source": "generated"}, {"text": "人口のダイナミクスを調べると、町の将来が見えてくる。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "人口(じんこう)のダイナミクスを調(しら)べると、町(まち)の将来(しょうらい)が見(み)えてくる。", "sentence_source": "generated"}, {"text": "雲のダイナミクスを、早送りの動画で観察した。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "雲(くも)のダイナミクスを、早送り(はやおくり)の動画(どうが)で観察(かんさつ)した。", "sentence_source": "generated"}, {"text": "この授業では、池の生き物の数のダイナミクスを学ぶ。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "この授業(じゅぎょう)では、池(いけ)の生(い)き物(もの)の数(かず)のダイナミクスを学(まな)ぶ。", "sentence_source": "generated"}, {"text": "物価のダイナミクスを知りたくて、十年分のデータを集めた。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "物価(ぶっか)のダイナミクスを知(し)りたくて、十年分(じゅうねんぶん)のデータを集(あつ)めた。", "sentence_source": "generated"}, {"text": "氷がとけるダイナミクスを、写真を並べて説明した。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "氷(こおり)がとけるダイナミクスを、写真(しゃしん)を並(なら)べて説明(せつめい)した。", "sentence_source": "generated"}, {"text": "一日の人の流れのダイナミクスを調べ、駅の混雑を減らす案を考えた。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "一日(いちにち)の人(ひと)の流(なが)れのダイナミクスを調(しら)べ、駅(えき)の混雑(こんざつ)を減(へ)らす案(あん)を考(かんが)えた。", "sentence_source": "generated"}, {"text": "森の木の数のダイナミクスは、長い年月を見ないとわからない。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "森(もり)の木(き)の数(かず)のダイナミクスは、長(なが)い年月(ねんげつ)を見(み)ないとわからない。", "sentence_source": "generated"}, {"text": "季節ごとの魚の量のダイナミクスを、漁師に聞いて表にまとめた。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "季節(きせつ)ごとの魚(さかな)の量(りょう)のダイナミクスを、漁師(りょうし)に聞(き)いて表(ひょう)にまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダイナミクス", "label": "基本形"}], "register": "標準的な書き言葉（中立）", "sense_fingerprint": "ものや量が時間の経過とともに変わっていく様子（変化のようす）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダイナミクス", "is_correct": true, "explanation": "ここは〈ダイナミクス〉（時間とともに変わるようす）の意味。水の量の変化を一年間記録する文脈に合う。"}, {"text": "鉄塔", "is_correct": false, "explanation": "電線を支える高い塔を指す語。水の量の時間変化を表せず、文が成り立たない。"}, {"text": "宝石", "is_correct": false, "explanation": "貴重な鉱物の装飾品を指す語。水の量の変化としては意味が通らない。"}, {"text": "学割", "is_correct": false, "explanation": "学生向けの割引を指す語。水の量を記録する文脈には入らない。"}], "explanations": {"ダイナミクス": "ここは〈ダイナミクス〉（時間とともに変わるようす）の意味。水の量の変化を一年間記録する文脈に合う。", "鉄塔": "電線を支える高い塔を指す語。水の量の時間変化を表せず、文が成り立たない。", "宝石": "貴重な鉱物の装飾品を指す語。水の量の変化としては意味が通らない。", "学割": "学生向けの割引を指す語。水の量を記録する文脈には入らない。"}, "sentence_index": 0, "correct_answer": "ダイナミクス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古いダイナミクスを修理した。", "explanation": "ダイナミクスには〈椅子〉の意味がない。修理できる物ではなく、この文は成り立たない。"}, {"text": "ダイナミクスを糸で縫った。", "explanation": "ダイナミクスには〈服〉の意味がない。糸で縫える物ではなく、この文は成り立たない。"}, {"text": "ダイナミクスを見て道を確かめた。", "explanation": "ダイナミクスには〈地図〉の意味がない。道を確かめる手がかりにはならず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダイナミクス", "is_correct": true, "explanation": "ここは〈ダイナミクス〉（時間とともに変わるようす）の意味。氷が溶けていく変化を写真で説明する文脈に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "布団など寝るための道具を指す語。氷が溶ける変化を説明する語ではない。"}, {"text": "匂い", "is_correct": false, "explanation": "香りの感覚を指す語。氷が溶けるようすを説明する対象にはならない。"}, {"text": "手数料", "is_correct": false, "explanation": "取引で払う費用を指す語。溶ける変化とは関係がなく、文が通らない。"}], "explanations": {"ダイナミクス": "ここは〈ダイナミクス〉（時間とともに変わるようす）の意味。氷が溶けていく変化を写真で説明する文脈に合う。", "寝具": "布団など寝るための道具を指す語。氷が溶ける変化を説明する語ではない。", "匂い": "香りの感覚を指す語。氷が溶けるようすを説明する対象にはならない。", "手数料": "取引で払う費用を指す語。溶ける変化とは関係がなく、文が通らない。"}, "sentence_index": 6, "correct_answer": "ダイナミクス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ダイナミクスを洗って干した。", "explanation": "ダイナミクスには〈ハンカチ〉の意味がない。洗って干せるものではなく、この文は成り立たない。"}, {"text": "ダイナミクスで豆をつまんだ。", "explanation": "ダイナミクスには〈箸〉の意味がない。豆をつまむ道具にはならず、この文は成り立たない。"}, {"text": "ダイナミクスの文字を漁師に読んでもらい、表にまとめた。", "explanation": "ダイナミクスには〈看板〉の意味がない。文字として書かれるものではなく、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湿度のダイナミクスをゆっくり変わっていく。", "corrected_sentence": "湿度のダイナミクスがゆっくり変わっていく。", "error_description": "「変わる」は自動詞で、主語に「が」をとる。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湿度のダイナミクスを記録すったので、傾向がわかった。", "corrected_sentence": "湿度のダイナミクスを記録したので、傾向がわかった。", "error_description": "「記録する」の過去形は「記録した」。「記録すった」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ダイナミクスを理解する」の目的語を示す「を」。理解の対象がダイナミクスなので、この形が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ダイナミクスが理解する」では理解する主体が立たず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ダイナミクスに理解する」は動詞「理解する」の対象を示せず、文の骨組みが崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、理解の対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「ダイナミクスを理解する」の目的語を示す「を」。理解の対象がダイナミクスなので、この形が正しい。", "が": "「ダイナミクスが理解する」では理解する主体が立たず、文が成り立たない。", "に": "「ダイナミクスに理解する」は動詞「理解する」の対象を示せず、文の骨組みが崩れる。", "へ": "方向を示す「へ」は、理解の対象を示す文には合わない。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。感染症の流行のダイナミクスが決まる、という主題を示すのでこの形が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「決まる」は自動詞なので、目的語の「を」は合わず、「ダイナミクスを決まる」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「決まる」の文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」だと「ダイナミクスの、〜が決まる」となり、主題を示せず不自然。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。感染症の流行のダイナミクスが決まる、という主題を示すのでこの形が正しい。", "を": "「決まる」は自動詞なので、目的語の「を」は合わず、「ダイナミクスを決まる」は成り立たない。", "へ": "方向を示す「へ」は「決まる」の文には合わない。", "の": "「の」だと「ダイナミクスの、〜が決まる」となり、主題を示せず不自然。"}, "error_tags": {"を": "自動詞との不一致", "へ": "方向の誤り", "の": "主題の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "システムや状況の中で、時間とともに変化する力や動きのパターン。特に、複数の要素が互いに影響し合いながら全体が変わっていく様子。", "primary_collocate": null, "pronunciation": "だいなみくす", "ipa": "dainamikɯsɯ", "syllable_count": 6, "sentences": [{"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "むしろ、それらの相互作用(そうごさよう)が織(お)りなす複雑適応(ふくざつてきおう)システムにおいては、正負(せいふ)のフィードバックを介(かい)した非線形(ひせんけい)なダイナミクスが、予測不可能(よそくふかのう)なマクロな秩序(ちつじょ)、すなわち創発(そうはつ)をもたらすのである。", "sentence_source": "mined"}, {"text": "気候システムのダイナミクスを理解するには、海と大気の相互作用を同時に調べる必要がある。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "気候(きこう)システムのダイナミクスを理解(りかい)するには、海(うみ)と大気(たいき)の相互作用(そうごさよう)を同時(どうじ)に調(しら)べる必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "市場のダイナミクスは、価格と需要が互いに影響し合うことで刻々と変わっていく。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "市場(しじょう)のダイナミクスは、価格(かかく)と需要(じゅよう)が互(たが)いに影響(えいきょう)し合(あ)うことで刻々(こくこく)と変(か)わっていく。", "sentence_source": "generated"}, {"text": "捕食者と被食者の個体数のダイナミクスを、数理モデルで再現した。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "捕食者(ほしょくしゃ)と被食者(ひしょくしゃ)の個体数(こたいすう)のダイナミクスを、数理(すうり)モデルで再現(さいげん)した。", "sentence_source": "generated"}, {"text": "この研究は、都市の人口移動のダイナミクスを長期的に追跡したものだ。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "この研究(けんきゅう)は、都市(とし)の人口移動(じんこういどう)のダイナミクスを長期的(ちょうきてき)に追跡(ついせき)したものだ。", "sentence_source": "generated"}, {"text": "組織のダイナミクスは、個人の関係が変わるたびに少しずつ書き換わっていく。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "組織(そしき)のダイナミクスは、個人(こじん)の関係(かんけい)が変(か)わるたびに少(すこ)しずつ書(か)き換(か)わっていく。", "sentence_source": "generated"}, {"text": "静的な分析では、時間とともに変化するダイナミクスまでは捉えられない。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "静的(せいてき)な分析(ぶんせき)では、時間(じかん)とともに変化(へんか)するダイナミクスまでは捉(とら)えられない。", "sentence_source": "generated"}, {"text": "感染症の流行のダイナミクスは、人々の行動と政策が影響し合って決まる。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "感染症(かんせんしょう)の流行(りゅうこう)のダイナミクスは、人々(ひとびと)の行動(こうどう)と政策(せいさく)が影響(えいきょう)し合(あ)って決(き)まる。", "sentence_source": "generated"}, {"text": "生態系のダイナミクスを乱すと、予想しなかった変化が連鎖的に広がる。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "生態系(せいたいけい)のダイナミクスを乱(みだ)すと、予想(よそう)しなかった変化(へんか)が連鎖的(れんさてき)に広(ひろ)がる。", "sentence_source": "generated"}, {"text": "経済全体のダイナミクスをシミュレーションで調べ、政策の効果を比べた。", "target_word": "ダイナミクス", "complexity_tier": "T3", "furigana": "経済全体(けいざいぜんたい)のダイナミクスをシミュレーションで調(しら)べ、政策(せいさく)の効果(こうか)を比(くら)べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダイナミクス", "label": "基本形"}], "register": "硬い書き言葉（学術・論文調）", "sense_fingerprint": "システム内の複数要素が影響し合い、時間とともに全体が変化していくパターン（系の力学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダイナミクス", "is_correct": true, "explanation": "ここは〈ダイナミクス〉（時間とともに変わる力や動きのパターン）の意味。非線形な振る舞いが秩序を生む文脈に合う。"}, {"text": "鉄骨", "is_correct": false, "explanation": "建物を支える鋼材を指す語。非線形な変化が秩序をもたらす文脈とは関係しない。"}, {"text": "香水", "is_correct": false, "explanation": "香りのついた化粧品を指す語。システムの振る舞いを表せず、文が成り立たない。"}, {"text": "試験紙", "is_correct": false, "explanation": "薬品の反応を調べるための紙を指す語。システムの時間変化を表せない。"}], "explanations": {"ダイナミクス": "ここは〈ダイナミクス〉（時間とともに変わる力や動きのパターン）の意味。非線形な振る舞いが秩序を生む文脈に合う。", "鉄骨": "建物を支える鋼材を指す語。非線形な変化が秩序をもたらす文脈とは関係しない。", "香水": "香りのついた化粧品を指す語。システムの振る舞いを表せず、文が成り立たない。", "試験紙": "薬品の反応を調べるための紙を指す語。システムの時間変化を表せない。"}, "sentence_index": 0, "correct_answer": "ダイナミクス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダイナミクスを鍋で煮込んだ。", "explanation": "ダイナミクスには〈食材〉の意味がない。鍋で煮込める材料ではなく、この文は成り立たない。"}, {"text": "ダイナミクスを頭にかぶった。", "explanation": "ダイナミクスには〈帽子〉の意味がない。頭にかぶるものではなく、この文は成り立たない。"}, {"text": "駅のダイナミクスを配った。", "explanation": "ダイナミクスには〈時刻表〉の意味がない。配れるものではなく、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダイナミクス", "is_correct": true, "explanation": "ここは〈ダイナミクス〉（時間とともに変わる動き）の意味。静的な分析では捉えられないという文脈に合う。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝るときに使う袋を指す語。時間とともに変化する対象を表せず、文が成り立たない。"}, {"text": "香辛料", "is_correct": false, "explanation": "料理に加える香りや辛みの材料を指す語。時間変化の文脈では意味が通らない。"}, {"text": "路線図", "is_correct": false, "explanation": "鉄道などの路線を示す図を指す語。配置を示すもので、時間とともに変わる動きの意味にはならない。"}], "explanations": {"ダイナミクス": "ここは〈ダイナミクス〉（時間とともに変わる動き）の意味。静的な分析では捉えられないという文脈に合う。", "寝袋": "寝るときに使う袋を指す語。時間とともに変化する対象を表せず、文が成り立たない。", "香辛料": "料理に加える香りや辛みの材料を指す語。時間変化の文脈では意味が通らない。", "路線図": "鉄道などの路線を示す図を指す語。配置を示すもので、時間とともに変わる動きの意味にはならない。"}, "sentence_index": 6, "correct_answer": "ダイナミクス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ダイナミクスに顔を映して比べた。", "explanation": "ダイナミクスには〈鏡〉の意味がない。顔を映せるものではなく、この文は成り立たない。"}, {"text": "ダイナミクスで文字を消した。", "explanation": "ダイナミクスには〈消しゴム〉の意味がない。文字を消せる道具ではなく、この文は成り立たない。"}, {"text": "ダイナミクスの配達日数を比べた。", "explanation": "ダイナミクスには〈郵便〉の意味がない。配達日数を持つものではなく、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場のダイナミクスに、価格と需要が互いに影響し合うことで決まる。", "corrected_sentence": "市場のダイナミクスは、価格と需要が互いに影響し合うことで決まる。", "error_description": "主題を示す「は」を「に」にしたのが誤り。「に」は場所や方向を示すので、主題にならない。正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダイナミクスを捉えらえると、将来の姿が見えてくる。", "corrected_sentence": "ダイナミクスを捉えると、将来の姿が見えてくる。", "error_description": "「捉える」の活用形は「捉えると」。「捉えらえる」は誤った語形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『促す』の目的語を示す。『創発を促す』で、産業の創発を後押しするという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『創発が促す』では創発自体が促す主体になり、ここでは不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す。『創発に促す』は目的語の位置に合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。『創発で促す』は目的語の位置に合わず不自然。"}], "correct_answer": "を", "explanations": {"を": "『促す』の目的語を示す。『創発を促す』で、産業の創発を後押しするという意味になる。", "が": "主語を示す。『創発が促す』では創発自体が促す主体になり、ここでは不自然。", "に": "方向や相手を示す。『創発に促す』は目的語の位置に合わず不自然。", "で": "手段や場所を示す。『創発で促す』は目的語の位置に合わず不自然。"}, "error_tags": {"を": "目的語の格", "が": "主語の格", "に": "方向・相手の格", "で": "手段・場所の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが新しく生まれること。", "primary_collocate": null, "pronunciation": "そうはつ", "ipa": "soːhatsɯ", "syllable_count": 4, "sentences": [{"text": "自由な話し合いの場で、新しいアイデアの創発が期待される。", "target_word": "創発", "complexity_tier": "T3", "furigana": "自由(じゆう)な話(はな)し合(あ)いの場(ば)で、新(あたら)しいアイデアの創発(そうはつ)が期待(きたい)される。", "sentence_source": "generated"}, {"text": "この研究会は、若い人の発想から新しいものが創発する場を大切にしている。", "target_word": "創発", "complexity_tier": "T3", "furigana": "この研究会[けんきゅうかい]は、若い人[わかいひと]の発想[はっそう]から新しい[あたらしい]ものが創発[そうはつ]する場[ば]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "古い考えにとらわれると、新しい発想の創発は難しい。", "target_word": "創発", "complexity_tier": "T3", "furigana": "古(ふる)い考(かんが)えにとらわれると、新(あたら)しい発想(はっそう)の創発(そうはつ)は難(むずか)しい。", "sentence_source": "generated"}, {"text": "失敗を責めない雰囲気が、チームの創発を助ける。", "target_word": "創発", "complexity_tier": "T3", "furigana": "失敗(しっぱい)を責(せ)めない雰囲気(ふんいき)が、チームの創発(そうはつ)を助(たす)ける。", "sentence_source": "generated"}, {"text": "芸術家たちの交流の場で、新しい文化が創発した。", "target_word": "創発", "complexity_tier": "T3", "furigana": "芸術家[げいじゅつか]たちの交流[こうりゅう]の場[ば]で、新しい[あたらしい]文化[ぶんか]が創発[そうはつ]した。", "sentence_source": "generated"}, {"text": "子どもの自由な遊びは、創発の機会に満ちている。", "target_word": "創発", "complexity_tier": "T3", "furigana": "子(こ)どもの自由(じゆう)な遊(あそ)びは、創発(そうはつ)の機会(きかい)に満(み)ちている。", "sentence_source": "generated"}, {"text": "創発には、知識だけでなく、広い視野も必要だ。", "target_word": "創発", "complexity_tier": "T3", "furigana": "創発(そうはつ)には、知識(ちしき)だけでなく、広(ひろ)い視野(しや)も必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "町に新しい産業の創発を促すため、市が起業を支援している。", "target_word": "創発", "complexity_tier": "T3", "furigana": "町(まち)に新(あたら)しい産業(さんぎょう)の創発(そうはつ)を促(うなが)すため、市(し)が起業(きぎょう)を支援(しえん)している。", "sentence_source": "generated"}, {"text": "新しい音楽ジャンルの創発は、いつも異なる文化の出会いから始まる。", "target_word": "創発", "complexity_tier": "T3", "furigana": "新(あたら)しい音楽(おんがく)ジャンルの創発(そうはつ)は、いつも異(こと)なる文化(ぶんか)の出会(であ)いから始(はじ)まる。", "sentence_source": "generated"}, {"text": "会議では、批判を控えて、新しい発想が創発する時間を設けた。", "target_word": "創発", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、批判[ひはん]を控えて[ひかえて]、新しい[あたらしい]発想[はっそう]が創発[そうはつ]する時間[じかん]を設けた[もうけた]。", "sentence_source": "generated"}], "morphological_forms": [{"form": "創発", "label": "基本形"}, {"form": "創発する", "label": "サ変動詞形"}, {"form": "創発的", "label": "形容動詞形"}], "register": "標準的な書き言葉（中立）", "sense_fingerprint": "新しい考えや物事が新しく生まれること（創り出されて現れる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "創発", "is_correct": true, "explanation": "ここは〈創発〉。新しいアイデアが新しく生まれる意味で、話し合いに期待される内容と合う。"}, {"text": "停滞", "is_correct": false, "explanation": "進みが止まる意味で、新しいアイデアが生まれることへの期待とは逆になる。"}, {"text": "消滅", "is_correct": false, "explanation": "なくなる意味で、新しいアイデアの生成を期待する文脈とは合わない。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめる意味で、話し合いで新しいアイデアが生まれることを期待する文には合わない。"}], "explanations": {"創発": "ここは〈創発〉。新しいアイデアが新しく生まれる意味で、話し合いに期待される内容と合う。", "停滞": "進みが止まる意味で、新しいアイデアが生まれることへの期待とは逆になる。", "消滅": "なくなる意味で、新しいアイデアの生成を期待する文脈とは合わない。", "中断": "途中でやめる意味で、話し合いで新しいアイデアが生まれることを期待する文には合わない。"}, "sentence_index": 0, "correct_answer": "創発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い家具を創発して、部屋を広くした。", "explanation": "ここは〈撤去〉の意味。創発は新しく生まれることで、物を取り除く作業には使わない。"}, {"text": "市は駅前に新しい図書館を創発する計画だ。", "explanation": "ここは〈建設〉の意味。計画して建てる行為は、意図せず生まれる創発とは合わない。"}, {"text": "会議で問題を創発して、対策を決めた。", "explanation": "ここは〈解決〉の意味。問題を解く行為は、新しいものが生まれる創発とは別で、『問題を創発』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "創発", "is_correct": true, "explanation": "ここは〈創発〉。知識だけでなく視野も必要だという話題の中で、新しいものが生まれる過程を指す語になる。"}, {"text": "洗濯", "is_correct": false, "explanation": "家事の洗濯を表し、知識や広い視野が必要だという文脈とは結びつかない。"}, {"text": "解凍", "is_correct": false, "explanation": "冷凍品を元に戻す作業で、知識や視野の必要性を述べる文には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "気分転換の行為で、知識や広い視野が必要だという文脈とは結びつかない。"}], "explanations": {"創発": "ここは〈創発〉。知識だけでなく視野も必要だという話題の中で、新しいものが生まれる過程を指す語になる。", "洗濯": "家事の洗濯を表し、知識や広い視野が必要だという文脈とは結びつかない。", "解凍": "冷凍品を元に戻す作業で、知識や視野の必要性を述べる文には合わない。", "散歩": "気分転換の行為で、知識や広い視野が必要だという文脈とは結びつかない。"}, "sentence_index": 6, "correct_answer": "創発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は三年かけて小説を創発した。", "explanation": "ここは〈創作〉の意味。作者が意図して書く行為は、要素の相互作用から性質が生じる創発とは別のもの。"}, {"text": "不要なデータを創発して整理した。", "explanation": "ここは〈削除〉の意味。データを消す行為は、新しく生まれる意味の創発と正反対で合わない。"}, {"text": "パン職人が毎朝、パンを創発している。", "explanation": "ここは〈製造〉の意味。人が計画して作る行為は、自然に生じる創発とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい発想の創発が期待する。", "corrected_sentence": "新しい発想の創発を期待する。", "error_description": "誤り：『創発が期待する』。正しくは『創発を期待する』。『期待する』は目的語に『を』を取り、『が』は主語を示すため合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52637, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい案の創発を役立つ。", "corrected_sentence": "新しい案の創発に役立つ。", "error_description": "誤り：『創発を役立つ』。正しくは『創発に役立つ』。『役立つ』は『に』を取るため、『を』では目的語になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
