INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "個々の要素の相互作用から、予想できなかった新しい性質や秩序が生じること。", "primary_collocate": null, "pronunciation": "そうはつ", "ipa": "soːhatsɯ", "syllable_count": 4, "sentences": [{"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "創発", "complexity_tier": "T3", "furigana": "むしろ、それらの相互作用(そうごさよう)が織(お)りなす複雑適応(ふくざつてきおう)システムにおいては、正負(せいふ)のフィードバックを介(かい)した非線形(ひせんけい)なダイナミクスが、予測不可能(よそくふかのう)なマクロな秩序(ちつじょ)、すなわち創発(そうはつ)をもたらすのである。", "sentence_source": "mined"}, {"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "創発", "complexity_tier": "T3", "furigana": "社会経済現象(しゃかいけいざいげんしょう)の真(しん)の駆動力(くどうりょく)は、還元主義的(かんげんしゅぎてき)な分析(ぶんせき)の彼方(かなた)、ネットワーク全体(ぜんたい)の創発的特性(そうはつてきとくせい)の内(うち)にこそ宿(やど)っていると言(い)えよう。", "sentence_source": "mined"}, {"text": "個々のアリは単純でも、巣全体の高度な分業は創発の一例である。", "target_word": "創発", "complexity_tier": "T3", "furigana": "個々(ここ)のアリは単純(たんじゅん)でも、巣全体(すぜんたい)の高度(こうど)な分業(ぶんぎょう)は創発(そうはつ)の一例(いちれい)である。", "sentence_source": "generated"}, {"text": "脳の意識は、神経細胞の相互作用から創発すると考えられている。", "target_word": "創発", "complexity_tier": "T3", "furigana": "脳(のう)の意識(いしき)は、神経細胞(しんけいさいぼう)の相互作用(そうごさよう)から創発(そうはつ)すると考(かんが)えられている。", "sentence_source": "generated"}, {"text": "設計者が予想しなかった渋滞が、車の動きの相互作用から創発した。", "target_word": "創発", "complexity_tier": "T3", "furigana": "設計者(せっけいしゃ)が予想(よそう)しなかった渋滞(じゅうたい)が、車(くるま)の動(うご)きの相互作用(そうごさよう)から創発(そうはつ)した。", "sentence_source": "generated"}, {"text": "個々の部品を調べるだけでは、システムの創発は説明できない。", "target_word": "創発", "complexity_tier": "T3", "furigana": "個々(ここ)の部品(ぶひん)を調(しら)べるだけでは、システムの創発(そうはつ)は説明(せつめい)できない。", "sentence_source": "generated"}, {"text": "創発とは、要素の単純な足し算では予想できない性質が全体に現れることだ。", "target_word": "創発", "complexity_tier": "T3", "furigana": "創発(そうはつ)とは、要素(ようそ)の単純(たんじゅん)な足(た)し算(ざん)では予想(よそう)できない性質(せいしつ)が全体(ぜんたい)に現(あらわ)れることだ。", "sentence_source": "generated"}, {"text": "魚の群れが乱れず動くのは、一匹ずつの単純な規則から秩序が創発するからだ。", "target_word": "創発", "complexity_tier": "T3", "furigana": "魚(さかな)の群(む)れが乱(みだ)れず動(うご)くのは、一匹(いっぴき)ずつの単純(たんじゅん)な規則(きそく)から秩序(ちつじょ)が創発(そうはつ)するからだ。", "sentence_source": "generated"}, {"text": "市場の価格は、無数の取引の相互作用から創発する現象である。", "target_word": "創発", "complexity_tier": "T3", "furigana": "市場(しじょう)の価格(かかく)は、無数(むすう)の取引(とりひき)の相互作用(そうごさよう)から創発(そうはつ)する現象(げんしょう)である。", "sentence_source": "generated"}, {"text": "言語の文法は、話者同士のやりとりの中から創発したという説がある。", "target_word": "創発", "complexity_tier": "T3", "furigana": "言語(げんご)の文法(ぶんぽう)は、話者同士(わしゃどうし)のやりとりの中(なか)から創発(そうはつ)したという説(せつ)がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "創発", "label": "基本形"}, {"form": "創発する", "label": "サ変動詞形"}, {"form": "創発的", "label": "形容動詞形"}], "register": "硬い書き言葉（学術・論文調）", "sense_fingerprint": "要素同士の相互作用から、個々には無かった新しい性質や秩序が全体に現れること（エマージェンス）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "創発", "is_correct": true, "explanation": "ここは〈創発〉。前の『マクロな秩序』を言い換え、要素の相互作用から新しい秩序が生じるという意味になる。"}, {"text": "屈折", "is_correct": false, "explanation": "光が媒質で曲がる物理現象で、システム全体の秩序を指さないため『すなわち』で言い換えられない。"}, {"text": "偏光", "is_correct": false, "explanation": "光の振動方向がそろう現象で、ここで述べられているシステムの秩序の言い換えにはならない。"}, {"text": "時差", "is_correct": false, "explanation": "地域間の時刻のずれを指し、非線形なダイナミクスの結果として生じる秩序には当たらない。"}], "explanations": {"創発": "ここは〈創発〉。前の『マクロな秩序』を言い換え、要素の相互作用から新しい秩序が生じるという意味になる。", "屈折": "光が媒質で曲がる物理現象で、システム全体の秩序を指さないため『すなわち』で言い換えられない。", "偏光": "光の振動方向がそろう現象で、ここで述べられているシステムの秩序の言い換えにはならない。", "時差": "地域間の時刻のずれを指し、非線形なダイナミクスの結果として生じる秩序には当たらない。"}, "sentence_index": 0, "correct_answer": "創発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい調理器具を創発して、特許を取った。", "explanation": "ここは〈発明〉の意味。創発は要素の相互作用から性質が自然に生じることで、人が意図して道具を作る場合には使わない。"}, {"text": "祖父は十年前、小さな町工場を創発した。", "explanation": "ここは〈創業〉の意味。店や会社を立ち上げる行為には使わず、全体に新しい性質が現れる現象に限って使う。"}, {"text": "この工場では、毎日千個の部品を創発している。", "explanation": "ここは〈製造〉の意味。計画して部品を大量に作る行為は、自然に生じる創発とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "創発", "is_correct": true, "explanation": "ここは〈創発〉。『〜とは、〜ことだ』の定義文の見出し語で、要素の足し算では予想できない性質が全体に現れる意味になる。"}, {"text": "融解", "is_correct": false, "explanation": "固体が液体になる変化で、性質が全体に現れるという定義とは合わない。"}, {"text": "相殺", "is_correct": false, "explanation": "互いに打ち消し合う意味で、新しい性質が現れるという定義には当たらない。"}, {"text": "分裂", "is_correct": false, "explanation": "一つのものが分かれる意味で、要素が組み合わさって新しい性質が現れることとは逆になる。"}], "explanations": {"創発": "ここは〈創発〉。『〜とは、〜ことだ』の定義文の見出し語で、要素の足し算では予想できない性質が全体に現れる意味になる。", "融解": "固体が液体になる変化で、性質が全体に現れるという定義とは合わない。", "相殺": "互いに打ち消し合う意味で、新しい性質が現れるという定義には当たらない。", "分裂": "一つのものが分かれる意味で、要素が組み合わさって新しい性質が現れることとは逆になる。"}, "sentence_index": 6, "correct_answer": "創発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究者が、新しい惑星を創発した。", "explanation": "ここは〈発見〉の意味。惑星は既に存在するものを見つける行為で、要素の相互作用から新しく生じる創発とは合わない。"}, {"text": "その大学は百年前に創発された。", "explanation": "ここは〈創立〉の意味。大学の設立は人が意図して行うもので、創発の『自然に生じる』意味には当たらない。"}, {"text": "彼は三年かけて英語の文法を創発した。", "explanation": "ここは〈習得〉の意味。学習は個人が身につける行為で、要素の相互作用から性質が生じる創発とは別のものを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "要素の相互作用から、新しい秩序が創発なる。", "corrected_sentence": "要素の相互作用から、新しい秩序が創発する。", "error_description": "誤り：『創発なる』。正しくは『創発する』。創発は『する』と結びつく名詞で、『なる』は動詞として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "それは、全体に現れる創発な振る舞いだ。", "corrected_sentence": "それは、全体に現れる創発的な振る舞いだ。", "error_description": "誤り：『創発な』。正しくは『創発的な』。『的』は形容動詞の語尾で、名詞の前では『創発的な』の形にする。『創発な』は活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ミクロ", "is_correct": true, "explanation": "マクロの対義語として辞書に挙がる語。とても大きいまとまりの反対である細かい単位を表す。"}, {"text": "大局", "is_correct": false, "explanation": "全体の見通しを表す近い意味の語で、対義語ではない。"}, {"text": "全体", "is_correct": false, "explanation": "大きいまとまりを指す語で、マクロと近い方向を示すため対義語ではない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}], "correct_answer": "ミクロ", "explanations": {"ミクロ": "マクロの対義語として辞書に挙がる語。とても大きいまとまりの反対である細かい単位を表す。", "大局": "全体の見通しを表す近い意味の語で、対義語ではない。", "全体": "大きいまとまりを指す語で、マクロと近い方向を示すため対義語ではない。", "偶然": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ミクロ", "is_correct": true, "explanation": "マクロの対義語として辞書に挙がる語。とても大きいまとまりの反対である細かい単位を表す。"}, {"text": "偏在", "is_correct": false, "explanation": "一部に偏って存在する意味で、マクロの対義語として挙がる語ではない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}, {"text": "末端", "is_correct": false, "explanation": "端の部分を指す語で、マクロの対義語として挙がる語ではない。"}], "correct_answer": "ミクロ", "explanations": {"ミクロ": "マクロの対義語として辞書に挙がる語。とても大きいまとまりの反対である細かい単位を表す。", "偏在": "一部に偏って存在する意味で、マクロの対義語として挙がる語ではない。", "偶然": "偶然に起きる意味で、大きさや範囲の対義にはならない。", "末端": "端の部分を指す語で、マクロの対義語として挙がる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "とても大きいまとまりのこと。", "primary_collocate": null, "pronunciation": "まくろ", "ipa": "makɯɾo", "syllable_count": 3, "sentences": [{"text": "地球をマクロに見ると、国境はとても小さな線にすぎない。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "地球(ちきゅう)をマクロに見(み)ると、国境(こっきょう)はとても小(ちい)さな線(せん)にすぎない。", "sentence_source": "generated"}, {"text": "宇宙のようなマクロの世界は、顕微鏡では調べられない。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "宇宙(うちゅう)のようなマクロの世界(せかい)は、顕微鏡(けんびきょう)では調(しら)べられない。", "sentence_source": "generated"}, {"text": "細かい部分より、まずマクロな全体像を知りたい。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "細(こま)かい部分(ぶぶん)より、まずマクロな全体像(ぜんたいぞう)を知(し)りたい。", "sentence_source": "generated"}, {"text": "小さな虫の世界と、星のようなマクロの世界は、同じ自然の一部だ。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "小(ちい)さな虫(むし)の世界(せかい)と、星(ほし)のようなマクロの世界(せかい)は、同(おな)じ自然(しぜん)の一部(いちぶ)だ。", "sentence_source": "generated"}, {"text": "町の変化をマクロに見ると、人口が少しずつ減っていることがわかる。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "町(まち)の変化(へんか)をマクロに見(み)ると、人口(じんこう)が少(すこ)しずつ減(へ)っていることがわかる。", "sentence_source": "generated"}, {"text": "山全体を見るマクロな地図と、一本の道を示す細かい地図を比べた。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "山全体(やまぜんたい)を見(み)るマクロな地図(ちず)と、一本(いっぽん)の道(みち)を示(しめ)す細(こま)かい地図(ちず)を比(くら)べた。", "sentence_source": "generated"}, {"text": "先生は、ミクロな話の前にマクロなまとまりを説明してくれた。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "先生(せんせい)は、ミクロな話(はなし)の前(まえ)にマクロなまとまりを説明(せつめい)してくれた。", "sentence_source": "generated"}, {"text": "一本の木ではなく森全体というマクロな単位で、自然を考える。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "一本(いっぽん)の木(き)ではなく森全体(もりぜんたい)というマクロな単位(たんい)で、自然(しぜん)を考(かんが)える。", "sentence_source": "generated"}, {"text": "世界の動きをマクロにとらえる力は、ニュースを読むときに役に立つ。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "世界(せかい)の動(うご)きをマクロにとらえる力(ちから)は、ニュースを読(よ)むときに役(やく)に立(た)つ。", "sentence_source": "generated"}, {"text": "個人の悩みを、社会というマクロな問題として考えることもできる。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "個人(こじん)の悩(なや)みを、社会(しゃかい)というマクロな問題(もんだい)として考(かんが)えることもできる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マクロ", "label": "基本形"}, {"form": "マクロな", "label": "連体形（ナ形容詞的用法）"}, {"form": "マクロに", "label": "連用形（ナ形容詞的用法）"}], "register": "標準的な書き言葉（中立）", "sense_fingerprint": "とても大きなまとまり・大きな規模（ミクロの反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マクロ", "is_correct": true, "explanation": "ここは〈マクロ〉。地球を大きく捉える見方を表し、国境が小さな線に見えるという内容と合う。"}, {"text": "偶発", "is_correct": false, "explanation": "偶然に起きる意味で、見方の大きさを表す語ではなく『偶発に見る』は成り立たない。"}, {"text": "立体", "is_correct": false, "explanation": "形の立体感を表す語で、『立体に見る』は成り立たず、見方の大きさを表さない。"}, {"text": "理想", "is_correct": false, "explanation": "あるべき姿を表す語で、『理想に見る』は成り立たず国境の話と結びつかない。"}], "explanations": {"マクロ": "ここは〈マクロ〉。地球を大きく捉える見方を表し、国境が小さな線に見えるという内容と合う。", "偶発": "偶然に起きる意味で、見方の大きさを表す語ではなく『偶発に見る』は成り立たない。", "立体": "形の立体感を表す語で、『立体に見る』は成り立たず、見方の大きさを表さない。", "理想": "あるべき姿を表す語で、『理想に見る』は成り立たず国境の話と結びつかない。"}, "sentence_index": 0, "correct_answer": "マクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂粒のような、マクロな単位を顕微鏡で観察した。", "explanation": "ここは〈微小〉の意味。マクロは大きいまとまりを表すので、砂粒のような小さなものの観察には使わない。"}, {"text": "ささいなマクロな出来事で、二人は口論になった。", "explanation": "ここは〈小事〉の意味。マクロは大きいまとまりを表すので、小さな出来事に付けると意味が合わない。"}, {"text": "虫の羽の模様を、マクロな規模で一本ずつ書き写した。", "explanation": "ここは〈細密〉の意味。マクロは大きいまとまりを表すので、羽の模様を一本ずつ書き写す細かい作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マクロ", "is_correct": true, "explanation": "ここは〈マクロ〉。ミクロな話の前に示す、大きくまとまった単位を表す。"}, {"text": "ミクロ", "is_correct": false, "explanation": "細かい単位の意味で、同じ文の『ミクロな話』と重なり、大きいまとまりの説明に合わない。"}, {"text": "偶発", "is_correct": false, "explanation": "偶然起きる意味で、まとまりの説明を表す語としては合わない。"}, {"text": "仮想", "is_correct": false, "explanation": "実在しない想定の意味で、説明されるまとまりとは合わない。"}], "explanations": {"マクロ": "ここは〈マクロ〉。ミクロな話の前に示す、大きくまとまった単位を表す。", "ミクロ": "細かい単位の意味で、同じ文の『ミクロな話』と重なり、大きいまとまりの説明に合わない。", "偶発": "偶然起きる意味で、まとまりの説明を表す語としては合わない。", "仮想": "実在しない想定の意味で、説明されるまとまりとは合わない。"}, "sentence_index": 6, "correct_answer": "マクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "個人の悩みを、マクロな問題として一人ずつ相談する。", "explanation": "ここは〈個別〉の意味。マクロは大きいまとまりなので、一人ひとりの悩みを個別に扱う文脈には合わない。"}, {"text": "彼女は、マクロな手さばきで、ピアノの小さな装飾音まで弾き分けた。", "explanation": "ここは〈繊細〉の意味。マクロは大きいまとまりを表すので、細かな装飾音を弾き分ける手さばきには合わない。"}, {"text": "微細な部品の寸法を、マクロな単位で測った。", "explanation": "ここは〈小さな寸法〉の意味。マクロは大きいまとまりを表すので、部品の細かい寸法を測る文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街の変化を、マクロな見てみる。", "corrected_sentence": "街の変化を、マクロに見てみる。", "error_description": "誤り：『マクロな見てみる』。正しくは『マクロに見てみる』。『見る』は連用形『マクロに』で修飾し、連体形『マクロな』は名詞の前に置く。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52639, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海全体というマクロに単位で、気候を考える。", "corrected_sentence": "海全体というマクロな単位で、気候を考える。", "error_description": "誤り：『マクロに単位』。正しくは『マクロな単位』。名詞の前では連体形『マクロな』を使い、連用形『マクロに』は名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『マクロの視点』と名詞を修飾する。『の』は視点の種類を示す正しい接続。"}, {"text": "を", "is_correct": false, "explanation": "『マクロを視点』は目的語として成り立たず、視点を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "『マクロに視点』は視点を修飾できず、不自然な並びになる。"}, {"text": "と", "is_correct": false, "explanation": "『マクロと視点』は並列にならず、視点を修飾する位置に合わない。"}], "correct_answer": "の", "explanations": {"の": "『マクロの視点』と名詞を修飾する。『の』は視点の種類を示す正しい接続。", "を": "『マクロを視点』は目的語として成り立たず、視点を修飾できない。", "に": "『マクロに視点』は視点を修飾できず、不自然な並びになる。", "と": "『マクロと視点』は並列にならず、視点を修飾する位置に合わない。"}, "error_tags": {"の": "名詞修飾の格", "を": "目的語の格", "に": "結果・方向の格", "と": "並列の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ミクロ", "is_correct": true, "explanation": "マクロの対義語として辞書に挙がる語。個々の要素や細部に注目する視点を表す。"}, {"text": "大局", "is_correct": false, "explanation": "全体の見通しを表す近い意味の語で、対義語ではない。"}, {"text": "全体", "is_correct": false, "explanation": "マクロと近い方向を指す語で、対義語として挙がらない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}], "correct_answer": "ミクロ", "explanations": {"ミクロ": "マクロの対義語として辞書に挙がる語。個々の要素や細部に注目する視点を表す。", "大局": "全体の見通しを表す近い意味の語で、対義語ではない。", "全体": "マクロと近い方向を指す語で、対義語として挙がらない。", "偶然": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『マクロの視点』と名詞を修飾する。視点の種類を示す正しい接続。"}, {"text": "が", "is_correct": false, "explanation": "『マクロが視点』は主語として成り立たず、視点を修飾できない。"}, {"text": "で", "is_correct": false, "explanation": "『マクロで視点』は手段の意味になり、視点を修飾する位置に合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『マクロを視点を加える』は目的語が二つ重なり成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『マクロの視点』と名詞を修飾する。視点の種類を示す正しい接続。", "が": "『マクロが視点』は主語として成り立たず、視点を修飾できない。", "で": "『マクロで視点』は手段の意味になり、視点を修飾する位置に合わない。", "を": "目的語を示す。『マクロを視点を加える』は目的語が二つ重なり成り立たない。"}, "error_tags": {"の": "名詞修飾の格", "が": "主語の格", "で": "手段の格", "を": "目的語の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ミクロ", "is_correct": true, "explanation": "マクロの対義語として辞書に挙がる語。細かい要素に注目する視点を表す。"}, {"text": "偏在", "is_correct": false, "explanation": "一部に偏って存在する意味で、マクロの対義語として挙がる語ではない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然に起きる意味で、大きさや範囲の対義にはならない。"}, {"text": "末端", "is_correct": false, "explanation": "端の部分を指す語で、マクロの対義語として挙がる語ではない。"}], "correct_answer": "ミクロ", "explanations": {"ミクロ": "マクロの対義語として辞書に挙がる語。細かい要素に注目する視点を表す。", "偏在": "一部に偏って存在する意味で、マクロの対義語として挙がる語ではない。", "偶然": "偶然に起きる意味で、大きさや範囲の対義にはならない。", "末端": "端の部分を指す語で、マクロの対義語として挙がる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体を大きく捉える視点や規模のこと。ミクロの対義語。経済学やシステム論などで、個別の要素ではなく全体の振る舞いに注目する際に用いる。", "primary_collocate": null, "pronunciation": "まくろ", "ipa": "makɯɾo", "syllable_count": 3, "sentences": [{"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "むしろ、それらの相互作用(そうごさよう)が織(お)りなす複雑適応(ふくざつてきおう)システムにおいては、正負(せいふ)のフィードバックを介(かい)した非線形(ひせんけい)なダイナミクスが、予測不可能(よそくふかのう)なマクロな秩序(ちつじょ)、すなわち創発(そうはつ)をもたらすのである。", "sentence_source": "mined"}, {"text": "マクロの視点で見ると、個々の企業の失敗も景気全体の流れの一部にすぎない。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "マクロの視点(してん)で見(み)ると、個々(ここ)の企業(きぎょう)の失敗(しっぱい)も景気全体(けいきぜんたい)の流(なが)れの一部(いちぶ)にすぎない。", "sentence_source": "generated"}, {"text": "経済学では、個人の消費を扱うミクロに対し、国全体の動きを扱うのがマクロだ。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "経済学(けいざいがく)では、個人(こじん)の消費(しょうひ)を扱(あつか)うミクロに対(たい)し、国全体(くにぜんたい)の動(うご)きを扱(あつか)うのがマクロだ。", "sentence_source": "generated"}, {"text": "気候変動は、マクロな規模で対策を考えなければならない問題だ。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "気候変動(きこうへんどう)は、マクロな規模(きぼ)で対策(たいさく)を考(かんが)えなければならない問題(もんだい)だ。", "sentence_source": "generated"}, {"text": "都市の渋滞は、一台ずつの動きではなくマクロな交通量の流れで分析する。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "都市(とし)の渋滞(じゅうたい)は、一台(いちだい)ずつの動(うご)きではなくマクロな交通量(こうつうりょう)の流(なが)れで分析(ぶんせき)する。", "sentence_source": "generated"}, {"text": "この研究は、細胞ではなくマクロな生態系全体の変化に注目している。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "この研究(けんきゅう)は、細胞(さいぼう)ではなくマクロな生態系全体(せいたいけいぜんたい)の変化(へんか)に注目(ちゅうもく)している。", "sentence_source": "generated"}, {"text": "日々の値動きではなく、マクロな経済指標から今後の景気を予測する。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "日々(ひび)の値動(ねうご)きではなく、マクロな経済指標(けいざいしひょう)から今後(こんご)の景気(けいき)を予測(よそく)する。", "sentence_source": "generated"}, {"text": "ミクロな分析だけでは見えない問題も、マクロの視点を加えると明らかになる。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "ミクロな分析(ぶんせき)だけでは見(み)えない問題(もんだい)も、マクロの視点(してん)を加(くわ)えると明(あき)らかになる。", "sentence_source": "generated"}, {"text": "国の政策を評価するには、マクロの数字を見る必要がある。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "国(くに)の政策(せいさく)を評価(ひょうか)するには、マクロの数字(すうじ)を見(み)る必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "彼はいつも細部にこだわらず、マクロな視点から計画を立てる。", "target_word": "マクロ", "complexity_tier": "T3", "furigana": "彼(かれ)はいつも細部(さいぶ)にこだわらず、マクロな視点(してん)から計画(けいかく)を立(た)てる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マクロ", "label": "基本形"}, {"form": "マクロな", "label": "連体形（ナ形容詞的用法）"}, {"form": "マクロに", "label": "連用形（ナ形容詞的用法）"}], "register": "硬い書き言葉（学術・論文調）", "sense_fingerprint": "個別ではなく全体を大きく捉える視点・規模（ミクロの対義）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 織りなす (Zipf 2.63), 正負 (Zipf 2.09), 非線形 (Zipf 2.6), ダイナミクス (Zipf 2.32), 創発 (Zipf 2.41)']::text[], '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マクロ", "is_correct": true, "explanation": "ここは〈マクロ〉。全体を大きく捉える視点・規模を表し、系の全体の秩序を修飾する。"}, {"text": "消失", "is_correct": false, "explanation": "なくなる意味で、『消失な秩序』は成り立たず、秩序を修飾できない。"}, {"text": "個別", "is_correct": false, "explanation": "一つずつ個々に扱う意味になり、全体の秩序と逆になる。"}, {"text": "混沌", "is_correct": false, "explanation": "乱れた状態を表し、秩序と矛盾するためここでは成り立たない。"}], "explanations": {"マクロ": "ここは〈マクロ〉。全体を大きく捉える視点・規模を表し、系の全体の秩序を修飾する。", "消失": "なくなる意味で、『消失な秩序』は成り立たず、秩序を修飾できない。", "個別": "一つずつ個々に扱う意味になり、全体の秩序と逆になる。", "混沌": "乱れた状態を表し、秩序と矛盾するためここでは成り立たない。"}, "sentence_index": 0, "correct_answer": "マクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この腕時計は、マクロな大きさで、ポケットにすっぽり収まる。", "explanation": "ここは〈小型〉の意味。マクロは大きいまとまりを表すので、ポケットに収まる腕時計の大きさには合わない。"}, {"text": "父は指先の作業にこだわり、いつもマクロな細工で部品を組み立てる。", "explanation": "ここは〈精密〉の意味。マクロは大きな規模や全体の視点を表すので、指先の細かな細工を形容する語としては合わない。"}, {"text": "彼は家計簿の一円ずつの誤差を、マクロに見て確かめた。", "explanation": "ここは〈緻密に〉の意味。マクロは大まかな全体の見方を表すので、一円単位の誤差を確かめる作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マクロ", "is_correct": true, "explanation": "ここは〈マクロ〉。日々の値動きと対比して、経済全体の動きを捉える指標を表す。"}, {"text": "午後", "is_correct": false, "explanation": "時間帯を表す語で、経済指標を修飾すると成り立たない。"}, {"text": "理想", "is_correct": false, "explanation": "あるべき姿を表す語で、経済指標を修飾する意味に合わない。"}, {"text": "仮想", "is_correct": false, "explanation": "実在しない想定の意味で、実際の経済指標を述べる文とは合わない。"}], "explanations": {"マクロ": "ここは〈マクロ〉。日々の値動きと対比して、経済全体の動きを捉える指標を表す。", "午後": "時間帯を表す語で、経済指標を修飾すると成り立たない。", "理想": "あるべき姿を表す語で、経済指標を修飾する意味に合わない。", "仮想": "実在しない想定の意味で、実際の経済指標を述べる文とは合わない。"}, "sentence_index": 6, "correct_answer": "マクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、マクロな町の一軒一軒まで数えて地図を作った。", "explanation": "ここは〈詳細〉の意味。マクロは全体や大きな規模を表すので、一軒ずつ細かく数える作業には合わない。"}, {"text": "彼は、マクロな声で囁くように話し、周りの人を驚かせた。", "explanation": "ここは〈小声〉の意味。マクロは大きな規模を表すので、囁くような小さな声を形容するのには合わない。"}, {"text": "微細な傷を見つけるため、マクロな傷を探した。", "explanation": "ここは〈細かな傷〉の意味。マクロは大きな規模や全体を表すので、小さな傷を形容する語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マクロな見ると、景気は安定している。", "corrected_sentence": "マクロに見ると、景気は安定している。", "error_description": "誤り：『マクロな見る』。正しくは『マクロに見る』。『見る』は連用形『マクロに』で修飾し、連体形『マクロな』は名詞の前にだけ置く。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52640, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経済の動きをマクロ見る。", "corrected_sentence": "経済の動きをマクロに見る。", "error_description": "誤り：『マクロ見る』。正しくは『マクロに見る』。『見る』を修飾する連用形には『に』が必要で、抜けると成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
