INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある量が増えると、それに比例して別の量も増えたり減ったりする関係のこと。", "primary_collocate": null, "pronunciation": "せんけい", "ipa": "seŋkeː", "syllable_count": 4, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "線形", "complexity_tier": "T5", "furigana": "グローバルな金融[きんゆう]市場[しじょう]やサプライチェーンといった社会[しゃかい]経済的[けいざいてき]文脈[ぶんみゃく]において、個々[ここ]の企業[きぎょう]や投資家[とうしか]といったミクロな主体[しゅたい]による局所的[きょくしょてき]な意思[いし]決定[けってい]は、決[けっ]して単純[たんじゅん]な線形[せんけい]モデルでは捉[とら]えきれない。", "sentence_source": "mined"}, {"text": "部品どうしが複雑に影響し合う場合には、線形の関係は成り立たない。", "target_word": "線形", "complexity_tier": "T5", "furigana": "部品[ぶひん]どうしが複雑[ふくざつ]に影響[えいきょう]し合[あ]う場合[ばあい]には、線形[せんけい]の関係[かんけい]は成[な]り立[た]たない。", "sentence_source": "generated"}, {"text": "気温とアイスの売り上げは、一定の範囲では線形に増える。", "target_word": "線形", "complexity_tier": "T3", "furigana": "気温[きおん]とアイスの売[う]り上[あ]げは、一定[いってい]の範囲[はんい]では線形[せんけい]に増[ふ]える。", "sentence_source": "generated"}, {"text": "時間と移動距離は、速度が一定なら線形の関係になる。", "target_word": "線形", "complexity_tier": "T3", "furigana": "時間[じかん]と移動[いどう]距離[きょり]は、速度[そくど]が一定[いってい]なら線形[せんけい]の関係[かんけい]になる。", "sentence_source": "generated"}, {"text": "この実験では、電圧を上げると電流も線形に増加した。", "target_word": "線形", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、電圧[でんあつ]を上[あ]げると電流[でんりゅう]も線形[せんけい]に増加[ぞうか]した。", "sentence_source": "generated"}, {"text": "線形な関係なら、材料を二倍にすれば生産量も二倍になる。", "target_word": "線形", "complexity_tier": "T3", "furigana": "線形[せんけい]な関係[かんけい]なら、材料[ざいりょう]を二倍[にばい]にすれば生産量[せいさんりょう]も二倍[にばい]になる。", "sentence_source": "generated"}, {"text": "グラフが直線になったので、二つのデータは線形だと言える。", "target_word": "線形", "complexity_tier": "T3", "furigana": "グラフが直線[ちょくせん]になったので、二[ふた]つのデータは線形[せんけい]だと言[い]える。", "sentence_source": "generated"}, {"text": "水の量と重さは線形で、量が増えた分だけ重くなる。", "target_word": "線形", "complexity_tier": "T3", "furigana": "水[みず]の量[りょう]と重[おも]さは線形[せんけい]で、量[りょう]が増[ふ]えた分[ぶん]だけ重[おも]くなる。", "sentence_source": "generated"}, {"text": "現実の景気は線形ではなく、小さな変化が大きな結果を生むこともある。", "target_word": "線形", "complexity_tier": "T3", "furigana": "現実[げんじつ]の景気[けいき]は線形[せんけい]ではなく、小[ちい]さな変化[へんか]が大[おお]きな結果[けっか]を生[う]むこともある。", "sentence_source": "generated"}, {"text": "線形の関係を調べるために、まず散布図を作った。", "target_word": "線形", "complexity_tier": "T3", "furigana": "線形[せんけい]の関係[かんけい]を調[しら]べるために、まず散布図[さんぷず]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "線形", "label": "基本形"}, {"form": "線形的", "label": "〜的形"}, {"form": "非線形", "label": "否定形（非〜）"}], "register": "formal", "sense_fingerprint": "数学・科学で、二つの量が比例して変化する関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "線形", "is_correct": true, "explanation": "「単純な線形モデル」は比例的な関係を仮定した基本モデルを指し、「それでは捉えきれない」という文脈と合う。"}, {"text": "対数", "is_correct": false, "explanation": "対数は関数の一型で、この文の論点（局所的な意思決定を捉えられるか）とは関係がない。"}, {"text": "複雑", "is_correct": false, "explanation": "「単純な複雑モデル」は語として矛盾し、「単純なモデルでは捉えきれない」という文の前提を崩す。"}, {"text": "非定常", "is_correct": false, "explanation": "非定常は統計の性質が時間で変わることを指す語で、「単純な非定常モデル」は文の主題（モデルの単純さ）とずれる。"}], "explanations": {"線形": "「単純な線形モデル」は比例的な関係を仮定した基本モデルを指し、「それでは捉えきれない」という文脈と合う。", "対数": "対数は関数の一型で、この文の論点（局所的な意思決定を捉えられるか）とは関係がない。", "複雑": "「単純な複雑モデル」は語として矛盾し、「単純なモデルでは捉えきれない」という文の前提を崩す。", "非定常": "非定常は統計の性質が時間で変わることを指す語で、「単純な非定常モデル」は文の主題（モデルの単純さ）とずれる。"}, "sentence_index": 0, "correct_answer": "線形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この二つの量は線形の関係にあるが、一方が増えても他方は変わらない。", "explanation": "ここは〈無関係で一定のまま〉の意味で使っている。線形は一方が変わると他方も比例して変わる関係を指すので、他方が変わらないという内容とは両立しない。"}, {"text": "毎朝、彼は線形に散歩する。", "explanation": "ここは〈規則正しい〉の意味で使っている。線形は量どうしの比例関係を表す語で、人の習慣の規則性には使わない。"}, {"text": "この表の数字は線形に増えたが、比例はしていない。", "explanation": "ここは〈線形〉を〈非線形的な増え方〉の意味で使っている。線形は比例関係そのものを指すので、比例しない増え方を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "線形", "is_correct": true, "explanation": "直線になったという根拠から「線形だと言える」と続き、比例関係として自然に成り立つ。"}, {"text": "偶然", "is_correct": false, "explanation": "直線になったという規則性を根拠にしているので、「偶然だと言える」は因果が合わず矛盾する。"}, {"text": "曖昧", "is_correct": false, "explanation": "はっきりした直線を根拠にする文で「曖昧だ」と言うと、文の根拠と食い違う。"}, {"text": "不安定", "is_correct": false, "explanation": "直線になったことは安定した関係を示すので、「不安定だと言える」は根拠と逆になる。"}], "explanations": {"線形": "直線になったという根拠から「線形だと言える」と続き、比例関係として自然に成り立つ。", "偶然": "直線になったという規則性を根拠にしているので、「偶然だと言える」は因果が合わず矛盾する。", "曖昧": "はっきりした直線を根拠にする文で「曖昧だ」と言うと、文の根拠と食い違う。", "不安定": "直線になったことは安定した関係を示すので、「不安定だと言える」は根拠と逆になる。"}, "sentence_index": 6, "correct_answer": "線形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の性格は線形で、人の意見によく流される。", "explanation": "ここは〈一直線のようにぶれない〉の意味で使っている。線形は量どうしの比例関係を指す語なので、性格の一貫性を表すことはできない。"}, {"text": "散布図の点は線形に散らばっていて、関係が見えない。", "explanation": "ここは〈一直線に並ぶ〉の意味で使っている。線形は比例関係を指すので、散らばって関係が見えない様子には使えない。"}, {"text": "この装置は線形で、入力と出力の関係が読みにくい。", "explanation": "線形は比例関係を指す語で、入力と出力の関係が読みにくいという内容とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ばねの伸びと力は、一定の範囲で線形を関係になる。", "corrected_sentence": "ばねの伸びと力は、一定の範囲で線形の関係になる。", "error_description": "「線形」は名詞として「関係」を修飾するので、連体修飾の「の」が必要。「を」は目的語の助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "線形が関係なら、投入量を二倍にすれば出力も二倍になる。", "corrected_sentence": "線形な関係なら、投入量を二倍にすれば出力も二倍になる。", "error_description": "「線形」は形容動詞的に使い、名詞「関係」を修飾するには「な」が必要。「が」を付けると主語になり、「関係」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
