INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52643, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "突然に起こること。", "primary_collocate": null, "pronunciation": "とっぱつ", "ipa": "toppatsɯ", "syllable_count": 4, "sentences": [{"text": "突発的に頭痛が起こり、仕事を休んだ。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "突発的[とっぱつてき]に頭痛[ずつう]が起[お]こり、仕事[しごと]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "川の水が突発的に増えて、橋が通れなくなった。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が突発的[とっぱつてき]に増[ふ]えて、橋[はし]が通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "突発した火災で、近くの住民が避難した。", "target_word": "突発", "complexity_tier": "T3", "furigana": "突発[とっぱつ]した火災[かさい]で、近[ちか]くの住民[じゅうみん]が避難[ひなん]した。", "sentence_source": "generated"}, {"text": "彼の怒りは突発的で、周りの人は驚いた。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "彼[かれ]の怒[いか]りは突発的[とっぱつてき]で、周[まわ]りの人[ひと]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "会議中に突発的に大きな笑い声が起こった。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "会議中[かいぎちゅう]に突発的[とっぱつてき]に大[おお]きな笑[わら]い声[ごえ]が起[お]こった。", "sentence_source": "generated"}, {"text": "突発的な揺れを感じて、私は机の下に隠れた。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "突発的[とっぱつてき]な揺[ゆ]れを感[かん]じて、私[わたし]は机[つくえ]の下[した]に隠[かく]れた。", "sentence_source": "generated"}, {"text": "山では天気が突発的に変わるので、注意が必要だ。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "山[やま]では天気[てんき]が突発的[とっぱつてき]に変[か]わるので、注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "突発事故のため、高速道路が通行止めになった。", "target_word": "突発", "complexity_tier": "T3", "furigana": "突発[とっぱつ]事故[じこ]のため、高速[こうそく]道路[どうろ]が通行止[つうこうど]めになった。", "sentence_source": "generated"}, {"text": "犬が突発的に走り出し、飼い主は引っ張られた。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "犬[いぬ]が突発的[とっぱつてき]に走[はし]り出[だ]し、飼[か]い主[ぬし]は引[ひ]っ張[ぱ]られた。", "sentence_source": "generated"}, {"text": "夜中に突発した騒ぎで、近所の人が目を覚ました。", "target_word": "突発", "complexity_tier": "T3", "furigana": "夜中[よなか]に突発[とっぱつ]した騒[さわ]ぎで、近所[きんじょ]の人[ひと]が目[め]を覚[さ]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "突発", "label": "基本形"}, {"form": "突発的", "label": "〜的形"}, {"form": "突発する", "label": "サ変動詞"}, {"form": "突発した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "前触れなく突然に起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52643, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突発的", "is_correct": true, "explanation": "「突発的に頭痛が起こる」は前触れなく急に起きることを表し、仕事を休む流れと合う。"}, {"text": "計画的", "is_correct": false, "explanation": "計画的に頭痛が起こるという言い方は不自然で、突然の不調を表す文脈と合わない。"}, {"text": "意図的", "is_correct": false, "explanation": "意図的に頭痛が起こるという読みは、仕事を休んだ経緯と噛み合わない。"}, {"text": "人為的", "is_correct": false, "explanation": "人為的に頭痛が起こるとすると原因の説明が変わり、ここでは文の流れに合わない。"}], "explanations": {"突発的": "「突発的に頭痛が起こる」は前触れなく急に起きることを表し、仕事を休む流れと合う。", "計画的": "計画的に頭痛が起こるという言い方は不自然で、突然の不調を表す文脈と合わない。", "意図的": "意図的に頭痛が起こるという読みは、仕事を休んだ経緯と噛み合わない。", "人為的": "人為的に頭痛が起こるとすると原因の説明が変わり、ここでは文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "突発的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この旅行は突発的に、一年前から計画されていた。", "explanation": "ここは〈計画的に〉の意味で使っている。突発は前触れなく急に起こる意味で、一年前から計画されていた旅行とは合わない。"}, {"text": "その痛みは突発的に、数年間続いていた。", "explanation": "ここは〈長く続く〉の意味で使っている。突発は一度きりの急な出来事を指すので、数年間続く痛みには使えない。"}, {"text": "川の水は突発的に少しずつ増えていった。", "explanation": "ここは〈徐々に〉の意味で使っている。突発は一気に急に起こる意味なので、少しずつ増える川の水には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52643, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突発的", "is_correct": true, "explanation": "「突発的に変わる」は急に変化することを表し、「注意が必要」という結論に結びつく。"}, {"text": "自発的", "is_correct": false, "explanation": "天気が自発的に変わるという言い方は不自然で、注意が必要という理由づけに合わない。"}, {"text": "慢性的", "is_correct": false, "explanation": "慢性的に変わる天気は長く続く性質を表し、急な変化への注意という文脈とずれる。"}, {"text": "恒久的", "is_correct": false, "explanation": "恒久的に変わる天気は言葉として不自然で、注意を促す理由になりにくい。"}], "explanations": {"突発的": "「突発的に変わる」は急に変化することを表し、「注意が必要」という結論に結びつく。", "自発的": "天気が自発的に変わるという言い方は不自然で、注意が必要という理由づけに合わない。", "慢性的": "慢性的に変わる天気は長く続く性質を表し、急な変化への注意という文脈とずれる。", "恒久的": "恒久的に変わる天気は言葉として不自然で、注意を促す理由になりにくい。"}, "sentence_index": 6, "correct_answer": "突発的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の公園は突発的に、いつもとても静かだ。", "explanation": "ここは〈いつも〉の意味で使っている。突発は急に起こる出来事を指すので、いつも静かな夜の公園という状態には使えない。"}, {"text": "庭の草は突発的に、毎日同じ量だけ伸びる。", "explanation": "〈突発〉は予期せず急に起こる意味。毎日一定量ずつ伸びる規則的な変化とは並ばない。"}, {"text": "この祭りは突発的に、毎年八月に開かれる。", "explanation": "〈突発〉は予期せぬ出来事を指す。毎年決まって開かれる祭りには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52643, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に突発的の笑い声が上がった。", "corrected_sentence": "夜中に突発的な笑い声が上がった。", "error_description": "「突発的」は名詞を修飾するときに「な」が必要。「の」を付けると名詞どうしの連結になり、形が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52643, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池の水が突発的で上がるので、近づかない方がいい。", "corrected_sentence": "池の水が突発的に上がるので、近づかない方がいい。", "error_description": "「上がる」を修飾するには副詞形の「突発的に」が必要。「突発的で」は断定の連用形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
