INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "予期しないことが急に起こること。", "primary_collocate": null, "pronunciation": "とっぱつ", "ipa": "toppatsɯ", "syllable_count": 4, "sentences": [{"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "突発的", "complexity_tier": "T5", "furigana": "なぜならば、無数[むすう]の主体[しゅたい]が限[かぎ]られた情報[じょうほう]に基[もと]づき絶[た]えず適応[てきおう]を繰[く]り返[かえ]す過程[かてい]で、意図[いと]せぬイノベーションやシステミック・リスクが突発的[とっぱつてき]に顕現[けんげん]するからに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "昨夜、突発的な停電が起きて、会議が中断した。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "昨夜[さくや]、突発的[とっぱつてき]な停電[ていでん]が起[お]きて、会議[かいぎ]が中断[ちゅうだん]した。", "sentence_source": "generated"}, {"text": "突発した事故のせいで、電車は一時間遅れた。", "target_word": "突発", "complexity_tier": "T3", "furigana": "突発[とっぱつ]した事故[じこ]のせいで、電車[でんしゃ]は一時間[いちじかん]遅[おく]れた。", "sentence_source": "generated"}, {"text": "突発的な雨に降られたが、折りたたみ傘があって助かった。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "突発的[とっぱつてき]な雨[あめ]に降[ふ]られたが、折[お]りたたみ傘[がさ]があって助[たす]かった。", "sentence_source": "generated"}, {"text": "予定を立てても、突発的な仕事が入ることがある。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "予定[よてい]を立[た]てても、突発的[とっぱつてき]な仕事[しごと]が入[はい]ることがある。", "sentence_source": "generated"}, {"text": "突発事故に備えて、工場では毎月訓練をしている。", "target_word": "突発", "complexity_tier": "T3", "furigana": "突発[とっぱつ]事故[じこ]に備[そな]えて、工場[こうじょう]では毎月[まいつき]訓練[くんれん]をしている。", "sentence_source": "generated"}, {"text": "突発的な病気で入院したため、旅行は取りやめになった。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "突発的[とっぱつてき]な病気[びょうき]で入院[にゅういん]したため、旅行[りょこう]は取[と]りやめになった。", "sentence_source": "generated"}, {"text": "予想もしていなかった突発的な質問に、彼は答えられなかった。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "予想[よそう]もしていなかった突発的[とっぱつてき]な質問[しつもん]に、彼[かれ]は答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "地震は突発的に起こるので、事前に知ることが難しい。", "target_word": "突発的", "complexity_tier": "T3", "furigana": "地震[じしん]は突発的[とっぱつてき]に起[お]こるので、事前[じぜん]に知[し]ることが難[むずか]しい。", "sentence_source": "generated"}, {"text": "突発した出来事にも落ち着いて対応するのが、彼女の強みだ。", "target_word": "突発", "complexity_tier": "T3", "furigana": "突発[とっぱつ]した出来事[できごと]にも落[お]ち着[つ]いて対応[たいおう]するのが、彼女[かのじょ]の強[つよ]みだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "突発", "label": "基本形"}, {"form": "突発的", "label": "〜的形"}, {"form": "突発する", "label": "サ変動詞"}, {"form": "突発した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "予想外の出来事や事故が急に起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突発的", "is_correct": true, "explanation": "「突発的に顕現する」は予期せず急に現れることで、「意図せぬ」現象と合う。"}, {"text": "計画的", "is_correct": false, "explanation": "計画的に顕現すると、前文の「意図せぬ」と矛盾する。"}, {"text": "人為的", "is_correct": false, "explanation": "人為的に顕現するという言い方は、意図せずに起きる現象の説明と食い違う。"}, {"text": "意図的", "is_correct": false, "explanation": "意図的に顕現すると、「意図せぬ」という前提を打ち消してしまう。"}], "explanations": {"突発的": "「突発的に顕現する」は予期せず急に現れることで、「意図せぬ」現象と合う。", "計画的": "計画的に顕現すると、前文の「意図せぬ」と矛盾する。", "人為的": "人為的に顕現するという言い方は、意図せずに起きる現象の説明と食い違う。", "意図的": "意図的に顕現すると、「意図せぬ」という前提を打ち消してしまう。"}, "sentence_index": 0, "correct_answer": "突発的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大会の運営は一年前から突発的に準備されていた。", "explanation": "ここは〈計画的に〉の意味で使っている。突発は予期せず急に起こる意味で、一年前から準備するという計画的な進行とは合わない。"}, {"text": "持病の腰痛は突発的に、もう三年も続いている。", "explanation": "ここは〈長く続く〉の意味で使っている。突発は急に一度起こる出来事を指すので、三年も続く腰痛を表すことはできない。"}, {"text": "この会議は突発的に毎月開かれる。", "explanation": "〈突発〉は予期しない出来事を指すので、毎月定まって開かれる定例会議とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突発的", "is_correct": true, "explanation": "「突発的な病気」は急に発症した病気を指し、入院と旅行の取りやめの原因として自然につながる。"}, {"text": "自発的", "is_correct": false, "explanation": "「自発的な病気」は病気を自分から起こすという意味になり、不自然で文脈に合わない。"}, {"text": "計画的", "is_correct": false, "explanation": "計画的な病気という言い方は不自然で、急な入院の理由として成り立たない。"}, {"text": "人工的", "is_correct": false, "explanation": "人工的な病気は通常の病気の意味から外れ、入院の原因として自然に読めない。"}], "explanations": {"突発的": "「突発的な病気」は急に発症した病気を指し、入院と旅行の取りやめの原因として自然につながる。", "自発的": "「自発的な病気」は病気を自分から起こすという意味になり、不自然で文脈に合わない。", "計画的": "計画的な病気という言い方は不自然で、急な入院の理由として成り立たない。", "人工的": "人工的な病気は通常の病気の意味から外れ、入院の原因として自然に読めない。"}, "sentence_index": 6, "correct_answer": "突発的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の授業は突発して、先生が前もって知らせてくれた。", "explanation": "ここは〈予定どおり〉の意味で使っている。突発は予期せず起こる意味で、前もって知らせた予定の授業とは合わない。"}, {"text": "彼の成績は突発的に、少しずつ上がってきた。", "explanation": "ここは〈徐々に〉の意味で使っている。突発は一気に急に起こる意味なので、少しずつ進む成績の変化には使えない。"}, {"text": "この店の客足は突発的に、いつも一定だ。", "explanation": "ここは〈常に〉の意味で使っている。突発は急に起こる出来事を指すので、いつも一定の客足という状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に突発な停電が起きて、家中が暗くなった。", "corrected_sentence": "夜中に突発的な停電が起きて、家中が暗くなった。", "error_description": "「突発的」は名詞を修飾するときに「的な」の形を取る。「突発な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車が突発的を遅れた。", "corrected_sentence": "電車が突発的に遅れた。", "error_description": "「遅れる」を修飾する副詞の形は「に」。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞「駆動」を修飾する「の」で、「前輪の駆動」として正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「前輪を駆動」では目的語になり、「駆動が弱く」と続かない。"}, {"text": "に", "is_correct": false, "explanation": "「前輪に駆動」は対象・位置を示し、名詞を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "「前輪へ駆動」は方向を示すが、名詞を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "名詞「駆動」を修飾する「の」で、「前輪の駆動」として正しく続く。", "を": "「前輪を駆動」では目的語になり、「駆動が弱く」と続かない。", "に": "「前輪に駆動」は対象・位置を示し、名詞を修飾できない。", "へ": "「前輪へ駆動」は方向を示すが、名詞を修飾する形にならない。"}, "error_tags": {"を": "目的語", "に": "対象・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
