INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを動かす力のこと。", "primary_collocate": null, "pronunciation": "くどう", "ipa": "kɯdoː", "syllable_count": 3, "sentences": [{"text": "エンジンの駆動で、船はゆっくりと港を出た。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "エンジンの駆動[くどう]で、船[ふね]はゆっくりと港[みなと]を出[で]た。", "sentence_source": "generated"}, {"text": "この車は前輪の駆動が弱く、坂道を上りにくい。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "この車[くるま]は前輪[ぜんりん]の駆動[くどう]が弱[よわ]く、坂道[さかみち]を上[のぼ]りにくい。", "sentence_source": "generated"}, {"text": "電池が切れて、おもちゃの駆動が止まった。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れて、おもちゃの駆動[くどう]が止[と]まった。", "sentence_source": "generated"}, {"text": "水車の回転は、粉をひく石臼の駆動に使われている。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "水[すい]車[しゃ]の回[かい]転[てん]は、粉[こな]をひく石[いし]臼[うす]の駆動[くどう]に使[つか]われている。", "sentence_source": "generated"}, {"text": "掃除ロボットは、小さな車輪を駆動して部屋を動き回る。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "掃除[そうじ]ロボットは、小[ちい]さな車輪[しゃりん]を駆動[くどう]して部屋[へや]を動[うご]き回[まわ]る。", "sentence_source": "generated"}, {"text": "駆動に必要な電力は、太陽光でまかなっている。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "駆動[くどう]に必要[ひつよう]な電力[でんりょく]は、太陽光[たいようこう]でまかなっている。", "sentence_source": "generated"}, {"text": "機械の駆動を止める前に、必ず電源を切ってください。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "機械[きかい]の駆動[くどう]を止[と]める前[まえ]に、必[かなら]ず電源[でんげん]を切[き]ってください。", "sentence_source": "generated"}, {"text": "蒸気機関が発明され、重い機械を人の力に頼らず駆動できるようになった。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "蒸気[じょうき]機関[きかん]が発明[はつめい]され、重[おも]い機械[きかい]を人[ひと]の力[ちから]に頼[たよ]らず駆動[くどう]できるようになった。", "sentence_source": "generated"}, {"text": "このクレーンは油圧で駆動するため、重い荷物も持ち上げられる。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "このクレーンは油圧[ゆあつ]で駆動[くどう]するため、重[おも]い荷物[にもつ]も持[も]ち上[あ]げられる。", "sentence_source": "generated"}, {"text": "ベルトが切れたせいで、駆動がタービンに伝わらなかった。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "ベルトが切[き]れたせいで、駆動[くどう]がタービンに伝[つた]わらなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆動", "label": "基本形"}, {"form": "駆動する", "label": "サ変動詞"}, {"form": "駆動される", "label": "受身形"}, {"form": "駆動力", "label": "複合名詞"}], "register": "neutral", "sense_fingerprint": "機械や乗り物などを動かす力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆動", "is_correct": true, "explanation": "「エンジンの駆動」は機械を動かす力の意味で、船が港を出る文脈に合う。"}, {"text": "停止", "is_correct": false, "explanation": "「エンジンの停止で船が出た」は意味が逆で、文脈に合わない。"}, {"text": "洗浄", "is_correct": false, "explanation": "「エンジンの洗浄で船が出た」は不自然で、動かす力の文脈に合わない。"}, {"text": "解体", "is_correct": false, "explanation": "「エンジンの解体で船が出た」は意味が通らず、文に合わない。"}], "explanations": {"駆動": "「エンジンの駆動」は機械を動かす力の意味で、船が港を出る文脈に合う。", "停止": "「エンジンの停止で船が出た」は意味が逆で、文脈に合わない。", "洗浄": "「エンジンの洗浄で船が出た」は不自然で、動かす力の文脈に合わない。", "解体": "「エンジンの解体で船が出た」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "駆動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の駆動に従って、生徒が一斉に席を立った。", "explanation": "ここは〈指示〉（命じること）の意味。駆動は物を動かす力や仕組みを指し、人の命令には使わないので合わない。"}, {"text": "彼女の駆動はいつも控えめで、人に気を遣わせない。", "explanation": "ここは〈性格〉（人柄）の意味。駆動は物を動かす力や仕組みで、人の性質には使わないので合わない。"}, {"text": "店の駆動を、社長が一人で決めた。", "explanation": "ここは〈運営〉（組織を回すこと）の意味。駆動は物を動かす力や仕組みを指すので、店の運営には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆動", "is_correct": true, "explanation": "「機械の駆動」は機械を動かす力や仕組みの意味で、止める対象として文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「機械の散歩」は意味をなさず、止める対象にならない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「機械の挨拶」は言えず、電源を切る文脈に合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "「機械の感謝」は意味をなさず、電源を切る文脈に合わない。"}], "explanations": {"駆動": "「機械の駆動」は機械を動かす力や仕組みの意味で、止める対象として文脈に合う。", "散歩": "「機械の散歩」は意味をなさず、止める対象にならない。", "挨拶": "「機械の挨拶」は言えず、電源を切る文脈に合わない。", "感謝": "「機械の感謝」は意味をなさず、電源を切る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "駆動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニュースの駆動が遅れたせいで、報道が追いつかなかった。", "explanation": "ここは〈伝達〉（情報を届けること）の意味。駆動は機械などを動かす力や仕組みを指し、情報を届ける意味はないので合わない。"}, {"text": "データを駆動して、そのまま残しておいた。", "explanation": "ここは〈保存〉（残しておく）の意味。駆動は物を動かす力や仕組みで、データを残す意味はないので合わない。"}, {"text": "油汚れを駆動して、きれいに落とした。", "explanation": "ここは〈洗浄〉（汚れを洗い落とす）の意味。駆動は動かす力や仕組みを指すので、汚れを落とす意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この電動自転車は、モーターが駆動で坂道を上る。", "corrected_sentence": "この電動自転車は、モーターの駆動で坂道を上る。", "error_description": "「モーターの駆動」が正しい。名詞「駆動」の前には「の」が要る。「が」を付けると主語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ギアの駆動を止まり、車は動かなくなった。", "corrected_sentence": "ギアの駆動が止まり、車は動かなくなった。", "error_description": "「駆動が止まる」が正しい。「止まる」は自動詞なので、直前の「駆動」には主語を示す「が」が付く。「を」は目的語を示すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「駆動する」の対象「後輪」を示す「を」で、直後の動詞に正しく続く。"}, {"text": "に", "is_correct": false, "explanation": "「後輪に駆動する」では対象を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「駆動する」の目的語にならず、文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「後輪と駆動する」は意味が通らず、並列や相手を表す用法にもならない。"}], "correct_answer": "を", "explanations": {"を": "「駆動する」の対象「後輪」を示す「を」で、直後の動詞に正しく続く。", "に": "「後輪に駆動する」では対象を示せず、文が成り立たない。", "へ": "方向を表す「へ」は「駆動する」の目的語にならず、文に合わない。", "と": "「後輪と駆動する」は意味が通らず、並列や相手を表す用法にもならない。"}, "error_tags": {"に": "対象・位置", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「駆動する」の対象「研究」を示す「を」で、直後の動詞に正しく続く。"}, {"text": "から", "is_correct": false, "explanation": "「研究から駆動する」は起点の意味になり、対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「研究より駆動する」で意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「研究で駆動する」の形で対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「駆動する」の対象「研究」を示す「を」で、直後の動詞に正しく続く。", "から": "「研究から駆動する」は起点の意味になり、対象を示せないので合わない。", "より": "比較の「より」は「研究より駆動する」で意味が通らない。", "で": "手段の「で」は「研究で駆動する」の形で対象を示せず、不自然。"}, "error_tags": {"から": "起点", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "機械やシステムを動かすための力や仕組み。また、物事を進める原動力。", "primary_collocate": null, "pronunciation": "くどう", "ipa": "kɯdoː", "syllable_count": 3, "sentences": [{"text": "社会経済現象の真の駆動は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "駆動", "complexity_tier": "T5", "furigana": "社会[しゃかい]経済[けいざい]現象[げんしょう]の真[しん]の駆動[くどう]は、還元[かんげん]主義的[しゅぎてき]な分析[ぶんせき]の彼方[かなた]、ネットワーク全体[ぜんたい]の創発的[そうはつてき]特性[とくせい]の内[うち]にこそ宿[やど]っていると言[い]えよう。", "sentence_source": "generated"}, {"text": "この自転車は、電気モーターで後輪を駆動する仕組みだ。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "この自転車[じてんしゃ]は、電気[でんき]モーターで後輪[こうりん]を駆動[くどう]する仕組[しく]みだ。", "sentence_source": "generated"}, {"text": "駆動に使うエネルギーが足りず、機械が止まった。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "駆動[くどう]に使[つか]うエネルギーが足[た]りず、機械[きかい]が止[と]まった。", "sentence_source": "generated"}, {"text": "工場のラインは、蒸気の力で駆動していた。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "工場[こうじょう]のラインは、蒸気[じょうき]の力[ちから]で駆動[くどう]していた。", "sentence_source": "generated"}, {"text": "新しい技術への期待が、この会社の成長を駆動している。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]への期待[きたい]が、この会社[かいしゃ]の成長[せいちょう]を駆動[くどう]している。", "sentence_source": "generated"}, {"text": "ロボットの腕は、小さなモーターによって駆動される。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "ロボットの腕[うで]は、小[ちい]さなモーターによって駆動[くどう]される。", "sentence_source": "generated"}, {"text": "駆動の仕組みを理解すれば、故障の原因も探しやすい。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "駆動[くどう]の仕組[しく]みを理解[りかい]すれば、故障[こしょう]の原因[げんいん]も探[さが]しやすい。", "sentence_source": "generated"}, {"text": "好奇心こそが、彼の研究を駆動する最大の力だ。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "好奇心[こうきしん]こそが、彼[かれ]の研究[けんきゅう]を駆動[くどう]する最大[さいだい]の力[ちから]だ。", "sentence_source": "generated"}, {"text": "風力で発電機を駆動するために、高い塔が建てられた。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "風力[ふうりょく]で発電機[はつでんき]を駆動[くどう]するために、高[たか]い塔[とう]が建[た]てられた。", "sentence_source": "generated"}, {"text": "古い時計は、ぜんまいの力で針を駆動する。", "target_word": "駆動", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]は、ぜんまいの力[ちから]で針[はり]を駆動[くどう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆動", "label": "基本形"}, {"form": "駆動する", "label": "サ変動詞"}, {"form": "駆動される", "label": "受身形"}, {"form": "駆動力", "label": "複合名詞"}], "register": "formal", "sense_fingerprint": "機械を動かす仕組み、または物事を進める原動力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆動", "is_correct": true, "explanation": "「真の駆動」として、物事を進める原動力を指すので文脈に合う。"}, {"text": "停止", "is_correct": false, "explanation": "「真の停止力」とは言わず、物事を進める原動力の意味に合わない。"}, {"text": "解体", "is_correct": false, "explanation": "「真の解体力」は不自然で、原動力を述べる文脈に合わない。"}, {"text": "散布", "is_correct": false, "explanation": "「真の散布力」は原動力の意味にならず、文に合わない。"}], "explanations": {"駆動": "「真の駆動」として、物事を進める原動力を指すので文脈に合う。", "停止": "「真の停止力」とは言わず、物事を進める原動力の意味に合わない。", "解体": "「真の解体力」は不自然で、原動力を述べる文脈に合わない。", "散布": "「真の散布力」は原動力の意味にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "駆動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小型船は駆動が高く、狭い港でもすばやく向きを変えられる。", "explanation": "ここは〈機動力〉（動きの素早さや小回り）の意味。駆動は力や仕組みを指し、動きの程度を表す語ではないので合わない。"}, {"text": "畑に広がった害虫を駆動した。", "explanation": "ここは〈駆除〉（取り除く）の意味。駆動は機械などを動かす力や仕組みで、害虫を取り除く意味はないので合わない。"}, {"text": "彼の駆動はとても穏やかで、周りを安心させる。", "explanation": "ここは〈性格〉（人柄）の意味。駆動は物を動かす力や仕組みで、人の性質には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆動", "is_correct": true, "explanation": "「駆動の仕組み」は機械を動かす仕組みの意味で、故障の原因を探す文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩の仕組み」とは言わず、故障の原因を探す文脈に合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝の仕組み」は意味をなさず、機械の故障の文脈に合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶の仕組み」とは言えず、故障の原因を探す文脈に合わない。"}], "explanations": {"駆動": "「駆動の仕組み」は機械を動かす仕組みの意味で、故障の原因を探す文脈に合う。", "散歩": "「散歩の仕組み」とは言わず、故障の原因を探す文脈に合わない。", "感謝": "「感謝の仕組み」は意味をなさず、機械の故障の文脈に合わない。", "挨拶": "「挨拶の仕組み」とは言えず、故障の原因を探す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "駆動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店の毎日の駆動は、社長が決めている。", "explanation": "ここは〈運営〉（組織を回すこと）の意味。駆動は機械や物事を動かす力・仕組みを指すので、店の運営には使わない。"}, {"text": "情報の駆動が遅れて、会議に間に合わなかった。", "explanation": "ここは〈伝達〉（情報を届けること）の意味。駆動は機械などを動かす力で、情報を届ける意味はないので合わない。"}, {"text": "汚れを駆動して、きれいに落とした。", "explanation": "ここは〈洗浄〉（汚れを洗い落とす）の意味。駆動は動かす力や仕組みを指すので、汚れを落とす意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この電動工具は、バッテリーで刃を駆動に仕組みだ。", "corrected_sentence": "この電動工具は、バッテリーで刃を駆動する仕組みだ。", "error_description": "「駆動する」が正しい。「駆動」は名詞で、直後に「に」を付けると文が成り立たない。サ変動詞「する」の形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52646, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、電池の力で車輪を駆動ない。", "corrected_sentence": "この機械は、電池の力で車輪を駆動しない。", "error_description": "「駆動しない」が正しい。「駆動」に直接「ない」は続かず、サ変動詞「する」を未然形「し」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
