INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52647, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "システム全体にかかわること。", "primary_collocate": null, "pronunciation": "しすてみっく", "ipa": "ɕisɯtemikːɯ", "syllable_count": 6, "sentences": [{"text": "小さな不具合ではなく、システミックな問題なので、全体の設計を見直す必要がある。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "小[ちい]さな不具合[ふぐあい]ではなく、システミックな問題[もんだい]なので、全体[ぜんたい]の設計[せっけい]を見直[みなお]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "今回の故障はシステミックで、どの部署にも影響が出た。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "今回[こんかい]の故障[こしょう]はシステミックで、どの部署[ぶしょ]にも影響[えいきょう]が出[で]た。", "sentence_source": "generated"}, {"text": "彼はシステミックな見方で、会社全体の流れを説明した。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "彼[かれ]はシステミックな見方[みかた]で、会社[かいしゃ]全体[ぜんたい]の流[なが]れを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "担当者を替えても、システミックな原因が残っていれば同じミスが起こる。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "担当者[たんとうしゃ]を替[か]えても、システミックな原因[げんいん]が残[のこ]っていれば同[おな]じミスが起[お]こる。", "sentence_source": "generated"}, {"text": "新しいソフトの導入で、会社のシステミックな変化が始まった。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "新[あたら]しいソフトの導入[どうにゅう]で、会社[かいしゃ]のシステミックな変化[へんか]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "この報告書は、交通のシステミックな課題をわかりやすくまとめている。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "この報告書[ほうこくしょ]は、交通[こうつう]のシステミックな課題[かだい]をわかりやすくまとめている。", "sentence_source": "generated"}, {"text": "一つの部品だけ直しても、システミックな不具合は直らない。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "一[ひと]つの部品[ぶひん]だけ直[なお]しても、システミックな不具合[ふぐあい]は直[なお]らない。", "sentence_source": "generated"}, {"text": "市の担当者は、ごみ問題をシステミックに考える必要があると話した。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "市[し]の担当者[たんとうしゃ]は、ごみ問題[もんだい]をシステミックに考[かんが]える必要[ひつよう]があると話[はな]した。", "sentence_source": "generated"}, {"text": "銀行のシステミックなリスクについて、先生が授業で説明してくれた。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]のシステミックなリスクについて、先生[せんせい]が授業[じゅぎょう]で説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "問題が一か所だけなら簡単だが、システミックなら対応は難しい。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "問題[もんだい]が一[いっ]か所[しょ]だけなら簡単[かんたん]だが、システミックなら対応[たいおう]は難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "システミックな", "label": "連体形"}, {"form": "システミックで", "label": "連用形"}, {"form": "システミックに", "label": "副詞形"}, {"form": "システミックなら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "一か所だけでなく、仕組み全体にかかわる性質を表す語。問題・原因・不具合などを修飾する。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52647, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "システミック", "is_correct": true, "explanation": "「システミックな問題」は全体にかかわる問題を指し、全体の設計を見直す理由に合う。"}, {"text": "感情的", "is_correct": false, "explanation": "「感情的な問題」では設計の見直しに結びつかず、文脈に合わない。"}, {"text": "情緒的", "is_correct": false, "explanation": "「情緒的な問題」は設計の見直しに結びつかず、文脈に合わない。"}, {"text": "好戦的", "is_correct": false, "explanation": "「好戦的な問題」は意味が通らず、設計の見直しの文脈に合わない。"}], "explanations": {"システミック": "「システミックな問題」は全体にかかわる問題を指し、全体の設計を見直す理由に合う。", "感情的": "「感情的な問題」では設計の見直しに結びつかず、文脈に合わない。", "情緒的": "「情緒的な問題」は設計の見直しに結びつかず、文脈に合わない。", "好戦的": "「好戦的な問題」は意味が通らず、設計の見直しの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "システミック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この参考書は用語をシステミックに整理しており、順番がよく分かる。", "explanation": "ここは〈体系的〉（順序立てて整える）の意味。システミックは組織や仕組み全体に影響が及ぶ性質で、整理の仕方は表さないので合わない。"}, {"text": "その夕立はシステミックなもので、すぐに止んだ。", "explanation": "ここは〈一時的〉（すぐ止む、長く続かない）の意味。システミックは組織や仕組み全体に関わる語で、続く時間の短さは表さないので合わない。"}, {"text": "その再会はシステミックで、本当に驚いた。", "explanation": "ここは〈偶然〉（思いがけず起こる）の意味。システミックは仕組み全体に関わる性質で、出来事の偶然性は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52647, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "システミック", "is_correct": true, "explanation": "「システミックな不具合」は全体に及ぶ不具合の意味で、部品一つでは直らない文脈に合う。"}, {"text": "挑発的", "is_correct": false, "explanation": "「挑発的な不具合」は意味が通らず、文脈に合わない。"}, {"text": "感傷的", "is_correct": false, "explanation": "「感傷的な不具合」は意味が通らず、直る直らないの話にならない。"}, {"text": "利他的", "is_correct": false, "explanation": "「利他的な不具合」は意味をなさず、文脈に合わない。"}], "explanations": {"システミック": "「システミックな不具合」は全体に及ぶ不具合の意味で、部品一つでは直らない文脈に合う。", "挑発的": "「挑発的な不具合」は意味が通らず、文脈に合わない。", "感傷的": "「感傷的な不具合」は意味が通らず、直る直らないの話にならない。", "利他的": "「利他的な不具合」は意味をなさず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "システミック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会議の場で、システミックに食い下がった。", "explanation": "ここは〈感情的〉（気持ちに任せて）の意味。システミックは仕組み全体に関わる語で、感情の動きは表さないので合わない。"}, {"text": "その音はシステミックに一瞬で消えた。", "explanation": "ここは〈瞬間的〉（一瞬で）の意味。システミックは時間の短さを表さず、消え方の表現には使わないので合わない。"}, {"text": "彼は毎朝、システミックに散歩する。", "explanation": "ここは〈規則的〉（決まった間隔で）の意味。システミックは仕組み全体に関わる性質で、行動の周期には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52647, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この欠陥は一台だけでなく、システミックだ広がりを見せている。", "corrected_sentence": "この欠陥は一台だけでなく、システミックな広がりを見せている。", "error_description": "「システミックな広がり」が正しい。名詞「広がり」を修飾する連体形「な」が必要で、「だ」は文末の形のため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "システミックで", "is_correct": true, "explanation": "連用形の「で」で、ここでは文を続ける形として使われている。"}, {"text": "システミックな", "is_correct": false, "explanation": "連体形で名詞を修飾する形。ここは文を続ける形ではないので合わない。"}, {"text": "システミックだ", "is_correct": false, "explanation": "文末の形で、ここでは文を続けられない。"}, {"text": "システミックなら", "is_correct": false, "explanation": "仮定形で条件を表し、ここでは文の流れに合わない。"}], "correct_form": "システミックで", "base_form": "システミック", "form_label": "連用形", "sentence_index": 1, "explanations": {"システミックで": "連用形の「で」で、ここでは文を続ける形として使われている。", "システミックな": "連体形で名詞を修飾する形。ここは文を続ける形ではないので合わない。", "システミックだ": "文末の形で、ここでは文を続けられない。", "システミックなら": "仮定形で条件を表し、ここでは文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52647, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "症状が一か所では収まらず、システミックだ不具合として報告された。", "corrected_sentence": "症状が一か所では収まらず、システミックな不具合として報告された。", "error_description": "誤『システミックだ不具合』→正『システミックな不具合』。名詞「不具合」を修飾するには連体形「な」が要り、「だ」は文末の形のため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "システミックに", "is_correct": true, "explanation": "連用形の副詞形で、動詞「考える」を修飾している。"}, {"text": "システミックで", "is_correct": false, "explanation": "中止形の「で」は動詞を修飾する形にならず、ここでは文が成り立たない。"}, {"text": "システミックだった", "is_correct": false, "explanation": "過去の終止形で、動詞を修飾できない。"}, {"text": "システミックなら", "is_correct": false, "explanation": "仮定形で条件を表し、動詞「考える」を直接修飾できないので合わない。"}], "correct_form": "システミックに", "base_form": "システミック", "form_label": "副詞形", "sentence_index": 7, "explanations": {"システミックに": "連用形の副詞形で、動詞「考える」を修飾している。", "システミックで": "中止形の「で」は動詞を修飾する形にならず、ここでは文が成り立たない。", "システミックだった": "過去の終止形で、動詞を修飾できない。", "システミックなら": "仮定形で条件を表し、動詞「考える」を直接修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
