INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "システム全体に影響を及ぼすさま。組織や構造全体に関わること。", "primary_collocate": null, "pronunciation": "しすてみっく", "ipa": "ɕisɯtemikːɯ", "syllable_count": 6, "sentences": [{"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "システミック", "complexity_tier": "T5", "furigana": "なぜならば、無数[むすう]の主体[しゅたい]が限[かぎ]られた情報[じょうほう]に基[もと]づき絶[た]えず適応[てきおう]を繰[く]り返[かえ]す過程[かてい]で、意図[いと]せぬイノベーションやシステミック・リスクが突発的[とっぱつてき]に顕現[けんげん]するからに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "一つの銀行の破綻が市場全体に広がる、システミックな危機が心配されている。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "一[ひと]つの銀行[ぎんこう]の破綻[はたん]が市場[しじょう]全体[ぜんたい]に広[ひろ]がる、システミックな危機[きき]が心配[しんぱい]されている。", "sentence_source": "generated"}, {"text": "この問題は一部の担当者のミスではなく、組織全体に関わるシステミックな欠陥だ。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "この問題[もんだい]は一部[いちぶ]の担当者[たんとうしゃ]のミスではなく、組織[そしき]全体[ぜんたい]に関[かか]わるシステミックな欠陥[けっかん]だ。", "sentence_source": "generated"}, {"text": "金融当局は、システミックなリスクを減らすために、大手銀行に厳しい規制をかけた。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "金融[きんゆう]当局[とうきょく]は、システミックなリスクを減[へ]らすために、大手[おおて]銀行[ぎんこう]に厳[きび]しい規制[きせい]をかけた。", "sentence_source": "generated"}, {"text": "差別は個人の悪意だけでなく、社会の仕組みに根ざしたシステミックな問題でもある。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "差別[さべつ]は個人[こじん]の悪意[あくい]だけでなく、社会[しゃかい]の仕組[しく]みに根[ね]ざしたシステミックな問題[もんだい]でもある。", "sentence_source": "generated"}, {"text": "病院の事故が続いたため、調査委員会は個人ではなくシステミックな原因を調べた。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "病院[びょういん]の事故[じこ]が続[つづ]いたため、調査[ちょうさ]委員会[いいんかい]は個人[こじん]ではなくシステミックな原因[げんいん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "部分的な修正では足りず、システミックな改革が必要だ。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "部分的[ぶぶんてき]な修正[しゅうせい]では足[た]りず、システミックな改革[かいかく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼女はこの会社の遅れを、システミックな問題として上司に説明した。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はこの会社[かいしゃ]の遅[おく]れを、システミックな問題[もんだい]として上司[じょうし]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "電力網の停止が各地に広がったので、専門家はこれをシステミックな障害と呼んだ。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "電力網[でんりょくもう]の停止[ていし]が各地[かくち]に広[ひろ]がったので、専門家[せんもんか]はこれをシステミックな障害[しょうがい]と呼[よ]んだ。", "sentence_source": "generated"}, {"text": "システミックな視点で見ると、渋滞の原因は一本の道路だけにはない。", "target_word": "システミック", "complexity_tier": "T3", "furigana": "システミックな視点[してん]で見[み]ると、渋滞[じゅうたい]の原因[げんいん]は一本[いっぽん]の道路[どうろ]だけにはない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "システミックな", "label": "連体形"}, {"form": "システミックで", "label": "連用形"}, {"form": "システミックに", "label": "副詞形"}, {"form": "システミックだ", "label": "終止形"}], "register": "formal", "sense_fingerprint": "一部ではなく、システムや組織の全体に影響が及ぶ性質を表す語。リスク・問題・欠陥・改革などを修飾する。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "システミック", "is_correct": true, "explanation": "「システミック・リスク」の形で、全体に波及する性質を表す語として文脈に合う。"}, {"text": "感傷的", "is_correct": false, "explanation": "「感傷的・リスク」は言えず、リスクの説明に合わない。"}, {"text": "好戦的", "is_correct": false, "explanation": "「好戦的・リスク」は意味が通らず、文脈に合わない。"}, {"text": "無関係的", "is_correct": false, "explanation": "「無関係的・リスク」は意味が通らず、文脈に合わない。"}], "explanations": {"システミック": "「システミック・リスク」の形で、全体に波及する性質を表す語として文脈に合う。", "感傷的": "「感傷的・リスク」は言えず、リスクの説明に合わない。", "好戦的": "「好戦的・リスク」は意味が通らず、文脈に合わない。", "無関係的": "「無関係的・リスク」は意味が通らず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "システミック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教科書は知識をシステミックに整理しており、初心者にも分かりやすい。", "explanation": "ここは〈体系的〉（順序立てて整える）の意味。システミックは組織や仕組み全体に影響が及ぶ性質で、整理の仕方は表さないので合わない。"}, {"text": "その雨はシステミックなもので、すぐに止んだ。", "explanation": "ここは〈一時的〉（すぐ止む、長く続かない）の意味。システミックは組織や仕組み全体に関わる語で、続く時間の短さは表さないので合わない。"}, {"text": "その出会いはシステミックで、本当に驚いた。", "explanation": "ここは〈偶然〉（思いがけず起こる）の意味。システミックは仕組み全体に関わる性質で、出来事の偶然性は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "システミック", "is_correct": true, "explanation": "「システミックな改革」は仕組み全体を変える改革の意味で、部分的な修正との対比に合う。"}, {"text": "感情的", "is_correct": false, "explanation": "「感情的な改革」は意味が合わず、部分的な修正との対比にならない。"}, {"text": "情緒的", "is_correct": false, "explanation": "「情緒的な改革」は意味が通らず、文脈に合わない。"}, {"text": "好戦的", "is_correct": false, "explanation": "「好戦的な改革」は意味をなさず、文脈に合わない。"}], "explanations": {"システミック": "「システミックな改革」は仕組み全体を変える改革の意味で、部分的な修正との対比に合う。", "感情的": "「感情的な改革」は意味が合わず、部分的な修正との対比にならない。", "情緒的": "「情緒的な改革」は意味が通らず、文脈に合わない。", "好戦的": "「好戦的な改革」は意味をなさず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "システミック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会議で、システミックに反論した。", "explanation": "ここは〈感情的〉（気持ちに任せて）の意味。システミックは仕組み全体に関わる語で、感情の動きは表さないので合わない。"}, {"text": "その音はシステミックに消えた。", "explanation": "ここは〈瞬間的〉（一瞬で）の意味。システミックは時間の短さを表さず、消え方の表現には使わないので合わない。"}, {"text": "この店は、システミックに一日だけ開いた。", "explanation": "ここは〈一時的〉（短い間だけ）の意味。システミックは仕組み全体に関わる性質で、期間の短さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このトラブルは一部の人だけでなく、システミックだ問題として全社で扱うべきだ。", "corrected_sentence": "このトラブルは一部の人だけでなく、システミックな問題として全社で扱うべきだ。", "error_description": "誤『システミックだ問題』→正『システミックな問題』。名詞「問題」を修飾するには連体形「な」が要り、「だ」は文末の形のため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "システミックな", "is_correct": true, "explanation": "連体形で、名詞「危機」を修飾している。"}, {"text": "システミックで", "is_correct": false, "explanation": "連用形の「で」は名詞を修飾できず、「危機」の前に置けない。"}, {"text": "システミックでなく", "is_correct": false, "explanation": "否定の連用形で、名詞「危機」の前には置けない。"}, {"text": "システミックだ", "is_correct": false, "explanation": "終止形の「だ」は文末で使う形で、名詞の前には置けない。"}], "correct_form": "システミックな", "base_form": "システミック", "form_label": "連体形", "sentence_index": 1, "explanations": {"システミックな": "連体形で、名詞「危機」を修飾している。", "システミックで": "連用形の「で」は名詞を修飾できず、「危機」の前に置けない。", "システミックでなく": "否定の連用形で、名詞「危機」の前には置けない。", "システミックだ": "終止形の「だ」は文末で使う形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このバグは一箇所ではなく、システミックだ原因で起きている。", "corrected_sentence": "このバグは一箇所ではなく、システミックな原因で起きている。", "error_description": "「システミックな原因」が正しい。名詞「原因」を修飾するには連体形「な」が必要で、「だ」は文末の形のため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "システミックな", "is_correct": true, "explanation": "連体形で、名詞「問題」を修飾している。"}, {"text": "システミックなら", "is_correct": false, "explanation": "仮定形の「なら」は条件を表し、名詞を修飾できないので合わない。"}, {"text": "システミックに", "is_correct": false, "explanation": "副詞形で、名詞「問題」を修飾できず、「問題として」の前には置けない。"}, {"text": "システミックさ", "is_correct": false, "explanation": "名詞化した形で、「問題」を直接修飾できず、文が成り立たない。"}], "correct_form": "システミックな", "base_form": "システミック", "form_label": "連体形", "sentence_index": 7, "explanations": {"システミックな": "連体形で、名詞「問題」を修飾している。", "システミックなら": "仮定形の「なら」は条件を表し、名詞を修飾できないので合わない。", "システミックに": "副詞形で、名詞「問題」を修飾できず、「問題として」の前には置けない。", "システミックさ": "名詞化した形で、「問題」を直接修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "『が』は主語。『機械が部品』では還元して考える対象を示せず、文が成り立たない。"}, {"text": "に", "is_correct": true, "explanation": "『部品に還元して考える』の帰着先を示す『に』。『AをBに還元する』の形に合う。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。『機械を』が既に目的語のため、『部品を』と重なって文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。『部品と還元して考える』では帰着先の意味が出ない。"}], "correct_answer": "に", "explanations": {"が": "『が』は主語。『機械が部品』では還元して考える対象を示せず、文が成り立たない。", "に": "『部品に還元して考える』の帰着先を示す『に』。『AをBに還元する』の形に合う。", "を": "『を』は目的語。『機械を』が既に目的語のため、『部品を』と重なって文が崩れる。", "と": "『と』は並列や相手を示す。『部品と還元して考える』では帰着先の意味が出ない。"}, "error_tags": {"が": "主語", "を": "対象", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "より", "is_correct": false, "explanation": "『より』は比較を示す。『家庭ごとの問題より還元して』では帰着先を示せず、意味が通らない。"}, {"text": "に", "is_correct": true, "explanation": "『家庭ごとの問題に還元して考える』の帰着先を示す『に』。『AをBに還元する』の形に合う。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞。『問題の還元して』では動詞の連用形に続かず不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示す。『家庭ごとの問題から還元して』では還元の帰着先を示せない。"}], "correct_answer": "に", "explanations": {"より": "『より』は比較を示す。『家庭ごとの問題より還元して』では帰着先を示せず、意味が通らない。", "に": "『家庭ごとの問題に還元して考える』の帰着先を示す『に』。『AをBに還元する』の形に合う。", "の": "『の』は名詞をつなぐ助詞。『問題の還元して』では動詞の連用形に続かず不自然。", "から": "『から』は起点を示す。『家庭ごとの問題から還元して』では還元の帰着先を示せない。"}, "error_tags": {"より": "比較", "の": "所有・修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを、もっと小さいものに分けて考えること。", "primary_collocate": null, "pronunciation": "かんげん", "ipa": "kaŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "複雑な話を、小さな要素に還元して考えると、理解しやすくなる。", "target_word": "還元", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な話[はなし]を、小[ちい]さな要素[ようそ]に還元[かんげん]して考[かんが]えると、理解[りかい]しやすくなる。", "sentence_source": "generated"}, {"text": "先生は、機械を部品に還元して考える方法を教えてくれた。", "target_word": "還元", "complexity_tier": "T3", "furigana": "先生[せんせい]は、機械[きかい]を部品[ぶひん]に還元[かんげん]して考[かんが]える方法[ほうほう]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "難しい問題を一つずつの小さな問題に還元してから、解き始めた。", "target_word": "還元", "complexity_tier": "T3", "furigana": "難[むずか]しい問題[もんだい]を一[ひと]つずつの小[ちい]さな問題[もんだい]に還元[かんげん]してから、解[と]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "料理の味を、塩や砂糖などの材料に還元して考えてみた。", "target_word": "還元", "complexity_tier": "T3", "furigana": "料理[りょうり]の味[あじ]を、塩[しお]や砂糖[さとう]などの材料[ざいりょう]に還元[かんげん]して考[かんが]えてみた。", "sentence_source": "generated"}, {"text": "全体を細かい部分に還元すれば、仕組みが見えてくることがある。", "target_word": "還元", "complexity_tier": "T3", "furigana": "全体[ぜんたい]を細[こま]かい部分[ぶぶん]に還元[かんげん]すれば、仕組[しく]みが見[み]えてくることがある。", "sentence_source": "generated"}, {"text": "還元して考える方法は、大きな問題を整理するときに役に立つ。", "target_word": "還元", "complexity_tier": "T3", "furigana": "還元[かんげん]して考[かんが]える方法[ほうほう]は、大[おお]きな問題[もんだい]を整理[せいり]するときに役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "彼は複雑な話を、小さな要素に還元して覚えた。", "target_word": "還元", "complexity_tier": "T3", "furigana": "彼[かれ]は複雑[ふくざつ]な話[はなし]を、小[ちい]さな要素[ようそ]に還元[かんげん]して覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "町の問題を家庭ごとの問題に還元して考えるだけでは、答えは出ない。", "target_word": "還元", "complexity_tier": "T3", "furigana": "町[まち]の問題[もんだい]を家庭[かてい]ごとの問題[もんだい]に還元[かんげん]して考[かんが]えるだけでは、答[こた]えは出[で]ない。", "sentence_source": "generated"}, {"text": "先生は、複雑な図形を三角形に還元して面積を求める方法を示した。", "target_word": "還元", "complexity_tier": "T3", "furigana": "先生[せんせい]は、複雑[ふくざつ]な図形[ずけい]を三角形[さんかくけい]に還元[かんげん]して面積[めんせき]を求[もと]める方法[ほうほう]を示[しめ]した。", "sentence_source": "generated"}, {"text": "物事を小さい要素に還元しすぎると、全体の姿を忘れてしまう。", "target_word": "還元", "complexity_tier": "T3", "furigana": "物事[ものごと]を小[ちい]さい要素[ようそ]に還元[かんげん]しすぎると、全体[ぜんたい]の姿[すがた]を忘[わす]れてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "還元", "label": "基本形"}, {"form": "還元する", "label": "サ変動詞形"}, {"form": "還元して", "label": "連用形（テ形）"}, {"form": "還元しすぎる", "label": "過度を表す形"}], "register": "neutral", "sense_fingerprint": "大きなものや複雑なものを、より小さな要素に分けて考えること。「〜に還元して考える」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "還流", "is_correct": false, "explanation": "還流は液体などが循環して戻ること。『小さな要素に還流して考える』は成り立たない。"}, {"text": "逆流", "is_correct": false, "explanation": "逆流は流れが逆向きになること。ものを小さく分けて考える文脈には合わない。"}, {"text": "還元", "is_correct": true, "explanation": "『小さな要素に還元して考える』の動詞。複雑な話を小さな要素に分けて考える意味に合う。"}, {"text": "還付", "is_correct": false, "explanation": "還付は納めたお金を返すこと。要素に分けて考える文脈には入らない。"}], "explanations": {"還流": "還流は液体などが循環して戻ること。『小さな要素に還流して考える』は成り立たない。", "逆流": "逆流は流れが逆向きになること。ものを小さく分けて考える文脈には合わない。", "還元": "『小さな要素に還元して考える』の動詞。複雑な話を小さな要素に分けて考える意味に合う。", "還付": "還付は納めたお金を返すこと。要素に分けて考える文脈には入らない。"}, "sentence_index": 0, "correct_answer": "還元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "書類を還元して、審査を受けた。", "explanation": "ここは〈提出〉の意味。〈還元〉はものを小さなものに分けて考えることで、書類を相手に渡す行為には使わない。"}, {"text": "全国の在庫を一つの倉庫に還元した。", "explanation": "ここは〈集約〉の意味。〈還元〉は大きなものを小さな要素に分けて考えることで、ばらばらのものを一か所にまとめる文には使えない。"}, {"text": "二つの支店を一つの建物に還元した。", "explanation": "ここは〈統合〉の意味。〈還元〉は分けて考える意味なので、二つを一つにまとめる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増幅", "is_correct": false, "explanation": "増幅は勢いや量を大きくすること。『小さな要素に増幅して覚えた』は成り立たない。"}, {"text": "漂流", "is_correct": false, "explanation": "漂流は流されることで、話を覚える方法とは結びつかない。"}, {"text": "脱落", "is_correct": false, "explanation": "脱落は抜け落ちること。覚え方を表す文脈では意味が通らない。"}, {"text": "還元", "is_correct": true, "explanation": "『小さな要素に還元して覚えた』の動詞。複雑な話を小さな要素に分けて覚える意味に合う。"}], "explanations": {"増幅": "増幅は勢いや量を大きくすること。『小さな要素に増幅して覚えた』は成り立たない。", "漂流": "漂流は流されることで、話を覚える方法とは結びつかない。", "脱落": "脱落は抜け落ちること。覚え方を表す文脈では意味が通らない。", "還元": "『小さな要素に還元して覚えた』の動詞。複雑な話を小さな要素に分けて覚える意味に合う。"}, "sentence_index": 6, "correct_answer": "還元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕日を還元して、記念に残した。", "explanation": "ここは〈撮影〉の意味。〈還元〉はものを小さなものに分けて考えることで、景色を写真に収める作業には使わない。"}, {"text": "写真の容量を還元して、ホームページに載せた。", "explanation": "ここは〈圧縮〉の意味。還元は大きなものを小さな要素に分けて考えることで、容量を小さくする操作には使わない。"}, {"text": "作業時間を還元して、昼前に終えた。", "explanation": "ここは〈短縮〉の意味。還元は分けて考える方法を指し、時間を縮める意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械の故障を、部品を還元して調べると、原因が見つかりやすい。", "corrected_sentence": "この機械の故障を、部品に還元して調べると、原因が見つかりやすい。", "error_description": "誤『部品を還元』→正『部品に還元』。『AをBに還元する』の形で、帰着先の『部品』には『に』が要る。『を』を重ねると文の骨組みが崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、大きな問題をいくつかの小問題に還元れば、解き方が見えると言った。", "corrected_sentence": "先生は、大きな問題をいくつかの小問題に還元すれば、解き方が見えると言った。", "error_description": "誤『還元れば』は、サ変動詞『還元する』の語幹に活用語尾『す』が抜けた形。正しくは『還元すれば』（仮定形）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "『が』は主語を示す。『脳の仕組みが還元して』では帰着先を示せず、『説明する』へ続かない。"}, {"text": "に", "is_correct": true, "explanation": "『脳の仕組みに還元する』の帰着先を示す『に』。『AをBに還元する』の形に合う。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。『心の働きを』が既に目的語のため、二つ目の『を』は文法的に入らない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。『脳の仕組みと還元して』では帰着先の意味が出ず、不自然。"}], "correct_answer": "に", "explanations": {"が": "『が』は主語を示す。『脳の仕組みが還元して』では帰着先を示せず、『説明する』へ続かない。", "に": "『脳の仕組みに還元する』の帰着先を示す『に』。『AをBに還元する』の形に合う。", "を": "『を』は目的語。『心の働きを』が既に目的語のため、二つ目の『を』は文法的に入らない。", "と": "『と』は並列や相手を示す。『脳の仕組みと還元して』では帰着先の意味が出ず、不自然。"}, "error_tags": {"が": "主語", "を": "対象", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "より", "is_correct": false, "explanation": "『より』は比較や起点を示す。『分子の運動より還元して』では帰着先を示せず、文が成り立たない。"}, {"text": "に", "is_correct": true, "explanation": "『分子の運動に還元して説明する』の帰着先を示す『に』。『AをBに還元する』の形に合う。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞。『運動の還元して』では動詞の連用形に続かず不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示す。『分子の運動から還元して』では還元の帰着先にならず、意味が通らない。"}], "correct_answer": "に", "explanations": {"より": "『より』は比較や起点を示す。『分子の運動より還元して』では帰着先を示せず、文が成り立たない。", "に": "『分子の運動に還元して説明する』の帰着先を示す『に』。『AをBに還元する』の形に合う。", "の": "『の』は名詞をつなぐ助詞。『運動の還元して』では動詞の連用形に続かず不自然。", "から": "『から』は起点を示す。『分子の運動から還元して』では還元の帰着先にならず、意味が通らない。"}, "error_tags": {"より": "比較", "の": "所有・修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複雑な現象や概念を、より基本的な要素や原理に分解して説明しようとする考え方や方法。", "primary_collocate": null, "pronunciation": "かんげん", "ipa": "kaŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "還元", "complexity_tier": "T5", "furigana": "社会[しゃかい]経済[けいざい]現象[げんしょう]の真[しん]の駆動力[くどうりょく]は、還元[かんげん]主義的[しゅぎてき]な分析[ぶんせき]の彼方[かなた]、ネットワーク全体[ぜんたい]の創発的[そうはつてき]特性[とくせい]の内[うち]にこそ宿[やど]っていると言[い]えよう。", "sentence_source": "mined"}, {"text": "心の働きをすべて脳の仕組みに還元して説明するのは、無理があると批評された。", "target_word": "還元", "complexity_tier": "T3", "furigana": "心[こころ]の働[はたら]きをすべて脳[のう]の仕組[しく]みに還元[かんげん]して説明[せつめい]するのは、無理[むり]があると批評[ひひょう]された。", "sentence_source": "generated"}, {"text": "複雑な社会問題を一つの原因に還元すると、大事な点を見落としてしまう。", "target_word": "還元", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な社会[しゃかい]問題[もんだい]を一[ひと]つの原因[げんいん]に還元[かんげん]すると、大事[だいじ]な点[てん]を見落[みお]としてしまう。", "sentence_source": "generated"}, {"text": "生物の行動を遺伝子の働きに還元する考え方には、反対する研究者も多い。", "target_word": "還元", "complexity_tier": "T3", "furigana": "生物[せいぶつ]の行動[こうどう]を遺伝子[いでんし]の働[はたら]きに還元[かんげん]する考[かんが]え方[かた]には、反対[はんたい]する研究者[けんきゅうしゃ]も多[おお]い。", "sentence_source": "generated"}, {"text": "この理論は、全体の性質を部品の性質に還元できないという立場をとる。", "target_word": "還元", "complexity_tier": "T3", "furigana": "この理論[りろん]は、全体[ぜんたい]の性質[せいしつ]を部品[ぶひん]の性質[せいしつ]に還元[かんげん]できないという立場[たちば]をとる。", "sentence_source": "generated"}, {"text": "還元による説明は分かりやすいが、全体のつながりは見えなくなる。", "target_word": "還元", "complexity_tier": "T3", "furigana": "還元[かんげん]による説明[せつめい]は分[わ]かりやすいが、全体[ぜんたい]のつながりは見[み]えなくなる。", "sentence_source": "generated"}, {"text": "彼は経済の動きを個人の損得に還元して考えるが、それでは社会の流れは説明できない。", "target_word": "還元", "complexity_tier": "T3", "furigana": "彼[かれ]は経済[けいざい]の動[うご]きを個人[こじん]の損得[そんとく]に還元[かんげん]して考[かんが]えるが、それでは社会[しゃかい]の流[なが]れは説明[せつめい]できない。", "sentence_source": "generated"}, {"text": "物理学者は、熱の現象を分子の運動に還元して説明した。", "target_word": "還元", "complexity_tier": "T3", "furigana": "物理学者[ぶつりがくしゃ]は、熱[ねつ]の現象[げんしょう]を分子[ぶんし]の運動[うんどう]に還元[かんげん]して説明[せつめい]した。", "sentence_source": "generated"}, {"text": "社会の現象を単一の原理に還元する試みは、理論としては明快だが、現実の多様さを取りこぼす恐れがある。", "target_word": "還元", "complexity_tier": "T3", "furigana": "社会[しゃかい]の現象[げんしょう]を単一[たんいつ]の原理[げんり]に還元[かんげん]する試[こころ]みは、理論[りろん]としては明快[めいかい]だが、現実[げんじつ]の多様[たよう]さを取[と]りこぼす恐[おそ]れがある。", "sentence_source": "generated"}, {"text": "先生は、言語の意味を単語の意味の足し算に還元できるかと生徒に問いかけた。", "target_word": "還元", "complexity_tier": "T3", "furigana": "先生[せんせい]は、言語[げんご]の意味[いみ]を単語[たんご]の意味[いみ]の足[た]し算[ざん]に還元[かんげん]できるかと生徒[せいと]に問[と]いかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "還元", "label": "基本形"}, {"form": "還元する", "label": "サ変動詞形"}, {"form": "還元して", "label": "連用形（テ形）"}, {"form": "還元できない", "label": "可能否定形"}], "register": "formal", "sense_fingerprint": "複雑な現象を、より基本的な要素や原理に還元して説明する学問上の考え方・方法。「〜に還元する」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 取りこぼす (Zipf 1.96)']::text[], '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "還流", "is_correct": false, "explanation": "還流は液体などが元へ戻る流れを指す。『還流主義的な分析』という語は成り立たず、文に合わない。"}, {"text": "還元", "is_correct": true, "explanation": "『還元主義的』の語幹。複雑な現象を基本的な要素や原理に分けて説明する立場を表し、文脈に合う。"}, {"text": "凝縮", "is_correct": false, "explanation": "凝縮は気体や成分を一つにまとめること。『凝縮主義的』は立場を表す語として成り立たず、この文に入らない。"}, {"text": "増幅", "is_correct": false, "explanation": "増幅は量や勢いを大きくすること。『増幅主義的』は分析の立場を表せず、文の意味が通らない。"}], "explanations": {"還流": "還流は液体などが元へ戻る流れを指す。『還流主義的な分析』という語は成り立たず、文に合わない。", "還元": "『還元主義的』の語幹。複雑な現象を基本的な要素や原理に分けて説明する立場を表し、文脈に合う。", "凝縮": "凝縮は気体や成分を一つにまとめること。『凝縮主義的』は立場を表す語として成り立たず、この文に入らない。", "増幅": "増幅は量や勢いを大きくすること。『増幅主義的』は分析の立場を表せず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "還元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "答案を還元して、生徒に返した。", "explanation": "ここは〈採点〉の意味。〈還元〉は複雑な現象や概念を基本的な原理に帰して説明する考え方で、答案に点数をつける作業には使わない。"}, {"text": "古い時計を、部品ごとに還元して掃除した。", "explanation": "ここは〈分解〉の意味。〈還元〉は現象や概念を基本的な原理に帰して説明することで、物を実際に外して分ける作業には使わない。"}, {"text": "血液の成分を、検査機で還元した。", "explanation": "ここは〈分析〉の意味。〈還元〉は理論の説明を基本的な原理に帰す考え方を指すので、検査機による測定には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "還付", "is_correct": false, "explanation": "還付は納めた税金などを返すこと。『個人の損得に還付して考える』では意味が通らない。"}, {"text": "逆流", "is_correct": false, "explanation": "逆流は流れが逆向きに戻ること。経済の動きを考える文脈には合わない。"}, {"text": "還元", "is_correct": true, "explanation": "『個人の損得に還元して考える』の用法。経済の動きを個人の損得という基本的な要素に分けて考える意味に合う。"}, {"text": "漂流", "is_correct": false, "explanation": "漂流は船などが流されること。『個人の損得に漂流して考える』は成り立たず、文に合わない。"}], "explanations": {"還付": "還付は納めた税金などを返すこと。『個人の損得に還付して考える』では意味が通らない。", "逆流": "逆流は流れが逆向きに戻ること。経済の動きを考える文脈には合わない。", "還元": "『個人の損得に還元して考える』の用法。経済の動きを個人の損得という基本的な要素に分けて考える意味に合う。", "漂流": "漂流は船などが流されること。『個人の損得に漂流して考える』は成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "還元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語の手紙を、すぐ還元して送った。", "explanation": "ここは〈翻訳〉の意味。〈還元〉は複雑な現象や概念を基本的な原理に帰して説明する考え方で、ある言語の文章を別の言語に置き換える作業には使わない。"}, {"text": "月ごとの売上を還元して、合計を出した。", "explanation": "ここは〈集計〉の意味。〈還元〉は複雑な現象や概念を基本的な原理に帰して説明する考え方で、数字を足し合わせて合計を求める作業には使わない。"}, {"text": "ファイルを還元して、メールに添付した。", "explanation": "ここは〈圧縮〉の意味。〈還元〉は説明の方法を指し、データの容量を小さくする操作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事件を個人の性格を還元して考えると、社会の問題が見えなくなる。", "corrected_sentence": "この事件を個人の性格に還元して考えると、社会の問題が見えなくなる。", "error_description": "誤『性格を還元』→正『性格に還元』。『AをBに還元する』の形で、帰着先のBには『に』が付く。『を』を重ねると目的語が二つ続いて文の骨組みが崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52650, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "複雑な問題を一つの原理に還元れば、解き方が見えてくる。", "corrected_sentence": "複雑な問題を一つの原理に還元すれば、解き方が見えてくる。", "error_description": "誤『還元れば』は、サ変動詞『還元する』の語幹に活用語尾『す』が抜けた形。正しくは『還元すれば』（仮定形）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「仏が」は顕現する主体を示す「が」で、「仏が顕現した」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「顕現」は目的語を取らない語なので、「仏を顕現した」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「仏で」は手段や場所を表すが、ここでは主体にならず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「仏より」は比較や起点の意味になり、「仏より顕現した」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「仏が」は顕現する主体を示す「が」で、「仏が顕現した」と自然に続く。", "を": "「顕現」は目的語を取らない語なので、「仏を顕現した」は不自然。", "で": "「仏で」は手段や場所を表すが、ここでは主体にならず文が成り立たない。", "より": "「仏より」は比較や起点の意味になり、「仏より顕現した」は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「星が」は顕現する主体を示す「が」で、「星が顕現した」と自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "「星と」は並列を表すが、「星と顕現した」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「星へ」は方向を表すが、顕現は相手を取らないので「星へ顕現した」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「星の顕現した」は名詞の「の」が動詞につながらず、文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「星が」は顕現する主体を示す「が」で、「星が顕現した」と自然に続く。", "と": "「星と」は並列を表すが、「星と顕現した」では意味が通らない。", "へ": "「星へ」は方向を表すが、顕現は相手を取らないので「星へ顕現した」は不自然。", "の": "「星の顕現した」は名詞の「の」が動詞につながらず、文として成り立たない。"}, "error_tags": {"と": "並列", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "見えなかったものが、急に現れること。", "primary_collocate": null, "pronunciation": "けんげん", "ipa": "keŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "古い物語には、神が人の姿で顕現する場面がある。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "古[ふる]い物語[ものがたり]には、神[かみ]が人[ひと]の姿[すがた]で顕現[けんげん]する場面[ばめん]がある。", "sentence_source": "generated"}, {"text": "祈りの最中に、光の中に仏が顕現したと伝えられる。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "祈[いの]りの最中[さいちゅう]に、光[ひかり]の中[なか]に仏[ほとけ]が顕現[けんげん]したと伝[つた]えられる。", "sentence_source": "generated"}, {"text": "長い間かくれていた才能が、突然顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]かくれていた才能[さいのう]が、突然[とつぜん]顕現[けんげん]した。", "sentence_source": "generated"}, {"text": "山の頂上に、まぼろしの城が顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]に、まぼろしの城[しろ]が顕現[けんげん]した。", "sentence_source": "generated"}, {"text": "雲が切れて、巨大な虹が空に顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "雲[くも]が切[き]れて、巨大[きょだい]な虹[にじ]が空[そら]に顕現[けんげん]した。", "sentence_source": "generated"}, {"text": "その村では、神の顕現を祝う祭りが毎年開かれる。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "その村[むら]では、神[かみ]の顕現[けんげん]を祝[いわ]う祭[まつ]りが毎年[まいとし]開[ひら]かれる。", "sentence_source": "generated"}, {"text": "魔法の力が顕現した瞬間、部屋じゅうが光で満たされた。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "魔法[まほう]の力[ちから]が顕現[けんげん]した瞬間[しゅんかん]、部屋[へや]じゅうが光[ひかり]で満[み]たされた。", "sentence_source": "generated"}, {"text": "日食の間、昼の空に星が顕現した。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "日食[にっしょく]の間[あいだ]、昼[ひる]の空[そら]に星[ほし]が顕現[けんげん]した。", "sentence_source": "generated"}, {"text": "怪物は、霧の中から突然顕現して旅人を襲った。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "怪物[かいぶつ]は、霧[きり]の中[なか]から突然[とつぜん]顕現[けんげん]して旅人[たびびと]を襲[おそ]った。", "sentence_source": "generated"}, {"text": "奇跡の顕現を見たという人が、教会に集まった。", "target_word": "顕現", "complexity_tier": "T3", "furigana": "奇跡[きせき]の顕現[けんげん]を見[み]たという人[ひと]が、教会[きょうかい]に集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕現", "label": "基本形"}, {"form": "顕現する", "label": "する動詞形"}, {"form": "顕現した", "label": "過去形"}, {"form": "顕現して", "label": "て形"}], "register": "formal", "sense_fingerprint": "隠れて見えなかったもの（神・力・才能など）が急にはっきりと姿を現すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顕現", "is_correct": true, "explanation": "隠れていた神が人の姿で急に現れる意味で、この文の内容に合う。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。神が人の姿で現れる場面には意味が通らない。"}, {"text": "撤回", "is_correct": false, "explanation": "一度出した発言や決定を取り消すこと。姿を現す文脈には合わない。"}, {"text": "換気", "is_correct": false, "explanation": "室内の空気を入れかえること。神の出現を述べるこの文とは結びつかない。"}], "explanations": {"顕現": "隠れていた神が人の姿で急に現れる意味で、この文の内容に合う。", "延期": "予定を先に延ばすこと。神が人の姿で現れる場面には意味が通らない。", "撤回": "一度出した発言や決定を取り消すこと。姿を現す文脈には合わない。", "換気": "室内の空気を入れかえること。神の出現を述べるこの文とは結びつかない。"}, "sentence_index": 0, "correct_answer": "顕現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その選手は長い間けがで休み、ついに顕現した。", "explanation": "ここは〈復帰〉の意味。顕現は隠れていたものが姿を現す語で、けがから戦列に戻る選手には使わない。"}, {"text": "新しい法律が顕現した。", "explanation": "ここは〈施行〉の意味。顕現は隠れていたものが姿を現す語で、法律の効力が始まる意味では使わない。"}, {"text": "駅前に新しいビルが顕現した。", "explanation": "ここは〈出現〉の意味。顕現は神や力のように隠れていたものが現れる語で、建物が新しく現れる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顕現", "is_correct": true, "explanation": "隠れていた力が急に現れる意味で、魔法の力が現れて部屋が光で満たされる場面に合う。"}, {"text": "注文", "is_correct": false, "explanation": "商品などを頼むこと。魔法の力が注文するという文は意味をなさない。"}, {"text": "清掃", "is_correct": false, "explanation": "ごみを取り除き、きれいにすること。魔法の力が清掃するという文は合わない。"}, {"text": "返品", "is_correct": false, "explanation": "買った物を店に返すこと。魔法の力が返品するという文は成り立たない。"}], "explanations": {"顕現": "隠れていた力が急に現れる意味で、魔法の力が現れて部屋が光で満たされる場面に合う。", "注文": "商品などを頼むこと。魔法の力が注文するという文は意味をなさない。", "清掃": "ごみを取り除き、きれいにすること。魔法の力が清掃するという文は合わない。", "返品": "買った物を店に返すこと。魔法の力が返品するという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "顕現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一八七一年、新しい国が顕現した。", "explanation": "ここは〈誕生〉の意味。顕現は隠れていたものが姿を現す語で、国が新しく生まれるという意味には使わない。"}, {"text": "村で大きな火事が顕現した。", "explanation": "ここは〈発生〉の意味。顕現は神や力のように隠れていたものが現れる語で、火事のような出来事には使わない。"}, {"text": "夜になると、近くの山にクマが顕現する。", "explanation": "ここは〈出没〉の意味。顕現は隠れていたものが姿を現す語で、動物がうろついて現れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その夜、村人たちは神の顕現が祝った。", "corrected_sentence": "その夜、村人たちは神の顕現を祝った。", "error_description": "「祝う」は目的語を「を」で取るので、「顕現が」は誤り。正しくは「顕現を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜空に、星の顕現な瞬間が訪れた。", "corrected_sentence": "夜空に、星の顕現の瞬間が訪れた。", "error_description": "「顕現」は名詞なので、続けるときは「の」で結ぶ。「な」は形容動詞につく語で、名詞の「顕現」にはつかないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
