INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52653, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "人が作ったもので、自然のままではないこと。", "primary_collocate": null, "pronunciation": "じんこう", "ipa": "dʑiŋkoː", "syllable_count": 4, "sentences": [{"text": "この花は人工です。", "target_word": "人工", "complexity_tier": "T2", "furigana": "この花[はな]は人工[じんこう]です。", "sentence_source": "generated"}, {"text": "この丘は人工だと聞いた。", "target_word": "人工", "complexity_tier": "T3", "furigana": "この丘[おか]は人工[じんこう]だと聞いた。", "sentence_source": "generated"}, {"text": "人工の池で魚を飼う。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の池[いけ]で魚[さかな]を飼[か]う。", "sentence_source": "generated"}, {"text": "自然ではなく人工だ。", "target_word": "人工", "complexity_tier": "T2", "furigana": "自然[しぜん]ではなく人工[じんこう]だ。", "sentence_source": "generated"}, {"text": "人工と自然を比べてみよう。", "target_word": "人工", "complexity_tier": "T2", "furigana": "人工[じんこう]と自然[しぜん]を比[くら]べてみよう。", "sentence_source": "generated"}, {"text": "この海岸は人工だと知らなかった。", "target_word": "人工", "complexity_tier": "T3", "furigana": "この海岸[かいがん]は人工[じんこう]だと知[し]らなかった。", "sentence_source": "generated"}, {"text": "人工の光は、植物にも使える。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の光[ひかり]は、植物[しょくぶつ]にも使[つか]える。", "sentence_source": "generated"}, {"text": "人工の島には、家が並んでいる。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の島[しま]には、家[いえ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "人工でも、本物のように見える。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]でも、本物[ほんもの]のように見[み]える。", "sentence_source": "generated"}, {"text": "これが人工か自然か、わからない。", "target_word": "人工", "complexity_tier": "T3", "furigana": "これが人工[じんこう]か自然[しぜん]か、わからない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工的", "label": "派生"}, {"form": "人工物", "label": "派生"}, {"form": "人工知能", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が作ったもので自然のままではないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52653, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "「この花は人工です」の述語。人が作った花という意味で、文脈に合う。"}, {"text": "法律", "is_correct": false, "explanation": "「この花は法律です」は意味をなさず、文脈に合わない。"}, {"text": "教室", "is_correct": false, "explanation": "「この花は教室です」は文として通らず、花の性質を表さない。"}, {"text": "天気", "is_correct": false, "explanation": "「この花は天気です」は意味をなさず、花の性質を表さない。"}], "explanations": {"人工": "「この花は人工です」の述語。人が作った花という意味で、文脈に合う。", "法律": "「この花は法律です」は意味をなさず、文脈に合わない。", "教室": "「この花は教室です」は文として通らず、花の性質を表さない。", "天気": "「この花は天気です」は意味をなさず、花の性質を表さない。"}, "sentence_index": 0, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の人工は十万人だ。", "explanation": "ここは〈人口〉（住民の数）の意味。人工は人が作った物を指すので、住民の数には使わない。"}, {"text": "彼は人工だと評判の天才だ。", "explanation": "ここは〈生まれつきの優れた才能〉の意味。「人工」は人が作った物を指すので、人の才能の形容には合わない。"}, {"text": "事故は人工によるものだった。", "explanation": "ここは〈人為〉（人の行為による）の意味。人工は人が作った物を指すので、事故の原因には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52653, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "「人工の光」（人が作った光）の意味で、植物に使えるという文脈に合う。"}, {"text": "会議", "is_correct": false, "explanation": "「会議の光」は意味をなさず、植物の文脈に合わない。"}, {"text": "家具", "is_correct": false, "explanation": "「家具の光」は文脈に合わず、植物に使える光の意味にならない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手の光」は不自然で、植物の光の文脈に合わない。"}], "explanations": {"人工": "「人工の光」（人が作った光）の意味で、植物に使えるという文脈に合う。", "会議": "「会議の光」は意味をなさず、植物の文脈に合わない。", "家具": "「家具の光」は文脈に合わず、植物に使える光の意味にならない。", "切手": "「切手の光」は不自然で、植物の光の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は重い荷物を人工で運んだ。", "explanation": "ここは〈人力〉（人の力だけで）の意味。人工は人が作った物を指すので、人の力で運ぶ方法には合わない。"}, {"text": "彼は人工の国籍を持つ。", "explanation": "ここは〈出身・所属〉の意味。「人工」は人が作った物を指すので、人の所属を表す語としては合わない。"}, {"text": "彼は人工があって慕われている。", "explanation": "ここは〈人徳〉（人柄による徳）の意味。人工は人が作った物を指すので、人柄の良さを表す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52653, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この庭の池は人工に掘られた。", "corrected_sentence": "この庭の池は人工的に掘られた。", "error_description": "「人工」を副詞的に使う形は「人工的に」。「人工に掘られた」は誤りで、「的」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
