INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52654, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自然の力ではなく、人間の技術や手によって作られたこと。", "primary_collocate": null, "pronunciation": "じんこう", "ipa": "dʑiŋkoː", "syllable_count": 4, "sentences": [{"text": "この川は人工です。", "target_word": "人工", "complexity_tier": "T2", "furigana": "この川[かわ]は人工[じんこう]です。", "sentence_source": "generated"}, {"text": "この池は人工です。", "target_word": "人工", "complexity_tier": "T2", "furigana": "この池[いけ]は人工[じんこう]です。", "sentence_source": "generated"}, {"text": "人工の島に空港を作った。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の島[しま]に空港[くうこう]を作[つく]った。", "sentence_source": "generated"}, {"text": "人工の光で野菜を育てる。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の光[ひかり]で野菜[やさい]を育[そだ]てる。", "sentence_source": "generated"}, {"text": "自然のままか人工かは、見ればわかる。", "target_word": "人工", "complexity_tier": "T3", "furigana": "自然[しぜん]のままか人工[じんこう]かは、見[み]ればわかる。", "sentence_source": "generated"}, {"text": "この湖は人工だと聞いて驚いた。", "target_word": "人工", "complexity_tier": "T3", "furigana": "この湖[みずうみ]は人工[じんこう]だと聞[き]いて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "人工の雪でスキーを楽しんだ。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の雪[ゆき]でスキーを楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "この滝は自然ではなく人工だ。", "target_word": "人工", "complexity_tier": "T3", "furigana": "この滝[たき]は自然[しぜん]ではなく人工[じんこう]だ。", "sentence_source": "generated"}, {"text": "人工と自然の違いを調べた。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]と自然[しぜん]の違[ちが]いを調[しら]べた。", "sentence_source": "generated"}, {"text": "人工の川が町を流れている。", "target_word": "人工", "complexity_tier": "T3", "furigana": "人工[じんこう]の川[かわ]が町[まち]を流[なが]れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工的", "label": "派生"}, {"form": "人工物", "label": "派生"}, {"form": "人工知能", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自然ではなく人の技術や手で作られたこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "「この川は人工です」の述語。人が作った川という意味で文脈に合う。"}, {"text": "食品", "is_correct": false, "explanation": "「この川は食品です」は意味をなさず、文脈に合わない。"}, {"text": "花束", "is_correct": false, "explanation": "「この川は花束です」は意味をなさず、川の性質を表さない。"}, {"text": "教室", "is_correct": false, "explanation": "「この川は教室です」は文として通らず、川の性質を表さない。"}], "explanations": {"人工": "「この川は人工です」の述語。人が作った川という意味で文脈に合う。", "食品": "「この川は食品です」は意味をなさず、文脈に合わない。", "花束": "「この川は花束です」は意味をなさず、川の性質を表さない。", "教室": "「この川は教室です」は文として通らず、川の性質を表さない。"}, "sentence_index": 0, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は人工が多い。", "explanation": "ここは〈人口〉（住民の数）の意味。人工は人が作った物を指すので、住民の数には使わない。"}, {"text": "彼は人工の才能を持っていて、誰も真似できない。", "explanation": "ここは〈天賦〉（生まれつきの）の意味。人工は人が作ったものを指すので、生まれつきの才能には合わない。"}, {"text": "事故の原因は人工によるものだった。", "explanation": "ここは〈人為〉（人の行為による）の意味。人工は人が作った物を指すので、ミスや事故の原因には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "「人工の雪」（人が作った雪）の意味で、スキーの文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫の雪」は不自然で、スキーに使う雪の意味にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙の雪」は文脈に合わず、意味をなさない。"}, {"text": "雑誌", "is_correct": false, "explanation": "「雑誌の雪」は意味をなさず、スキーの文脈に合わない。"}], "explanations": {"人工": "「人工の雪」（人が作った雪）の意味で、スキーの文脈に合う。", "冷蔵庫": "「冷蔵庫の雪」は不自然で、スキーに使う雪の意味にならない。", "手紙": "「手紙の雪」は文脈に合わず、意味をなさない。", "雑誌": "「雑誌の雪」は意味をなさず、スキーの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は重い荷物を人工で運んだ。", "explanation": "ここは〈人力〉（人の力だけで）の意味。人工は人が作った物を指すので、人の力で運ぶ方法には合わない。"}, {"text": "彼は人工の国籍を持つ。", "explanation": "ここは〈出身・所属〉の意味。「人工」は人が作った物を指すので、人の所属を表す語としては合わない。"}, {"text": "彼は人工だと評判の天才だ。", "explanation": "ここは〈生まれつきの優れた才能〉の意味。「人工」は人が作った物を指すので、人の才能の形容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52654, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この池は人工に作られたものだ。", "corrected_sentence": "この池は人工的に作られたものだ。", "error_description": "「人工」を副詞的に使う形は「人工的に」。「人工に作られる」は誤りで、「的」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52654, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この滝は人工を作られたものだ。", "corrected_sentence": "この滝は人工的に作られたものだ。", "error_description": "「人工」を副詞的に使う形は「人工的に」。「人工を作られた」は誤りで、「的に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52655, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "習熟する対象を示す「に」。"}, {"text": "の", "is_correct": false, "explanation": "「ピアノの習熟しました」は動詞の前で使えない。"}, {"text": "や", "is_correct": false, "explanation": "「ピアノや習熟しました」は並列の形にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ピアノと習熟しました」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "習熟する対象を示す「に」。", "の": "「ピアノの習熟しました」は動詞の前で使えない。", "や": "「ピアノや習熟しました」は並列の形にならず不自然。", "と": "「ピアノと習熟しました」は文として成り立たない。"}, "error_tags": {"の": "possessive", "や": "listing", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未熟", "is_correct": true, "explanation": "まだ上手になっていないこと。習熟の反対。"}, {"text": "熟練", "is_correct": false, "explanation": "習熟と近い意味で、反対ではない。"}, {"text": "上達", "is_correct": false, "explanation": "上手になることで、反対ではない。"}, {"text": "復習", "is_correct": false, "explanation": "学び直すことで、反対ではない。"}], "correct_answer": "未熟", "explanations": {"未熟": "まだ上手になっていないこと。習熟の反対。", "熟練": "習熟と近い意味で、反対ではない。", "上達": "上手になることで、反対ではない。", "復習": "学び直すことで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52655, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不慣れ", "is_correct": true, "explanation": "慣れていないこと。習熟の反対。"}, {"text": "精通", "is_correct": false, "explanation": "詳しく知っていることで、近い意味。"}, {"text": "学習", "is_correct": false, "explanation": "学ぶことで、反対ではない。"}, {"text": "会得", "is_correct": false, "explanation": "身につけることで、近い意味。"}], "correct_answer": "不慣れ", "explanations": {"不慣れ": "慣れていないこと。習熟の反対。", "精通": "詳しく知っていることで、近い意味。", "学習": "学ぶことで、反対ではない。", "会得": "身につけることで、近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52655, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんれんしゅうして、じょうずになること。", "primary_collocate": null, "pronunciation": "しゅうじゅく", "ipa": "ɕɯːdʑɯkɯ", "syllable_count": 4, "sentences": [{"text": "練習で習熟する。", "target_word": "習熟", "complexity_tier": "T1", "furigana": "練習[れんしゅう]で習熟[しゅうじゅく]する。", "sentence_source": "generated"}, {"text": "彼女はピアノに習熟しました。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "彼女[かのじょ]はピアノに習熟[しゅうじゅく]しました。", "sentence_source": "generated"}, {"text": "習熟には練習が大切です。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "習熟[しゅうじゅく]には練習[れんしゅう]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "毎日練習して、やっと習熟した。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]して、やっと習熟[しゅうじゅく]した。", "sentence_source": "generated"}, {"text": "習熟するまで頑張ります。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "習熟[しゅうじゅく]するまで頑張[がんば]ります。", "sentence_source": "generated"}, {"text": "新しい操作に対する習熟の速さは、人によって差がある。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "新[あたら]しい操作[そうさ]に対[たい]する習熟[しゅうじゅく]の速[はや]さは、人[ひと]によって差[さ]がある。", "sentence_source": "generated"}, {"text": "弟は自転車に習熟している。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "弟[おとうと]は自転車[じてんしゃ]に習熟[しゅうじゅく]している。", "sentence_source": "generated"}, {"text": "習熟するのに三年かかった。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "習熟[しゅうじゅく]するのに三年[さんねん]かかった。", "sentence_source": "generated"}, {"text": "習熟すれば、もっと楽しくなる。", "target_word": "習熟", "complexity_tier": "T4", "furigana": "習熟[しゅうじゅく]すれば、もっと楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "この仕事に習熟したいです。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "この仕事[しごと]に習熟[しゅうじゅく]したいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "習熟する", "label": "活用"}, {"form": "習熟した", "label": "活用"}, {"form": "習熟度", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 練習して上手になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "習熟", "is_correct": true, "explanation": "練習によって上手になる意味に合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、練習で結婚するという意味にならない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、練習で散歩するという意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、練習で卒業するという意味が合わない。"}], "explanations": {"習熟": "練習によって上手になる意味に合う。", "結婚": "形は合うが、練習で結婚するという意味にならない。", "散歩": "形は合うが、練習で散歩するという意味が合わない。", "卒業": "形は合うが、練習で卒業するという意味が合わない。"}, "sentence_index": 0, "correct_answer": "習熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食に習熟を作って家族と食べた。", "explanation": "習熟は料理ではない。食べ物の意味で使っている誤り。"}, {"text": "彼女は風邪を引いて、一日中習熟していた。", "explanation": "習熟は「寝て休む」意味ではない。休養の意味で使っている誤り。"}, {"text": "この公園は習熟が広くて、走るのに向いている。", "explanation": "習熟は場所の広さを表さない。面積の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "習熟", "is_correct": true, "explanation": "自転車が上手になっている意味に合う。"}, {"text": "食事", "is_correct": false, "explanation": "形は合うが、自転車に食事するという意味が合わない。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが、自転車に入院するという意味が合わない。"}, {"text": "就職", "is_correct": false, "explanation": "形は合うが、自転車に就職するという意味が合わない。"}], "explanations": {"習熟": "自転車が上手になっている意味に合う。", "食事": "形は合うが、自転車に食事するという意味が合わない。", "入院": "形は合うが、自転車に入院するという意味が合わない。", "就職": "形は合うが、自転車に就職するという意味が合わない。"}, "sentence_index": 6, "correct_answer": "習熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の雨で、傘が習熟してしまった。", "explanation": "習熟は「濡れる」意味ではない。濡れる意味で使っている誤り。"}, {"text": "窓を習熟して、部屋の空気を入れ替えた。", "explanation": "習熟は「開ける」意味ではない。動作の意味を取り違えている。"}, {"text": "駅で習熟に会って、一緒に電車に乗った。", "explanation": "習熟は人を指さない。人物の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
