INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "習熟する対象を示す「に」。"}, {"text": "と", "is_correct": false, "explanation": "「日本語と習熟する」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「日本語の習熟しています」は動詞の前で使えない。"}, {"text": "や", "is_correct": false, "explanation": "「日本語や習熟しています」は並列の形にならず不自然。"}], "correct_answer": "に", "explanations": {"に": "習熟する対象を示す「に」。", "と": "「日本語と習熟する」は文として成り立たない。", "の": "「日本語の習熟しています」は動詞の前で使えない。", "や": "「日本語や習熟しています」は並列の形にならず不自然。"}, "error_tags": {"と": "companion", "の": "possessive", "や": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未熟", "is_correct": true, "explanation": "まだ身についていないこと。習熟の反対。"}, {"text": "熟練", "is_correct": false, "explanation": "習熟と近い意味で、反対ではない。"}, {"text": "上達", "is_correct": false, "explanation": "上手になることで、反対ではない。"}, {"text": "復習", "is_correct": false, "explanation": "学んだことを学び直すことで、反対ではない。"}], "correct_answer": "未熟", "explanations": {"未熟": "まだ身についていないこと。習熟の反対。", "熟練": "習熟と近い意味で、反対ではない。", "上達": "上手になることで、反対ではない。", "復習": "学んだことを学び直すことで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「生徒の習熟」と習熟の主体を示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「生徒を習熟を」と続き、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「生徒へ習熟を」は名詞をつなげず不自然。"}, {"text": "や", "is_correct": false, "explanation": "「生徒や習熟を確かめる」は並列の相手が揃わず不自然。"}], "correct_answer": "の", "explanations": {"の": "「生徒の習熟」と習熟の主体を示す「の」。", "を": "「生徒を習熟を」と続き、文として成り立たない。", "へ": "「生徒へ習熟を」は名詞をつなげず不自然。", "や": "「生徒や習熟を確かめる」は並列の相手が揃わず不自然。"}, "error_tags": {"を": "object", "へ": "direction", "や": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不慣れ", "is_correct": true, "explanation": "慣れていないこと。習熟の反対。"}, {"text": "精通", "is_correct": false, "explanation": "詳しく知っていることで、近い意味。"}, {"text": "学習", "is_correct": false, "explanation": "学ぶことで、反対ではない。"}, {"text": "会得", "is_correct": false, "explanation": "身につけることで、近い意味。"}], "correct_answer": "不慣れ", "explanations": {"不慣れ": "慣れていないこと。習熟の反対。", "精通": "詳しく知っていることで、近い意味。", "学習": "学ぶことで、反対ではない。", "会得": "身につけることで、近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "練習や学習を繰り返して、ある技能や知識を完全に身につけること。また、その程度。", "primary_collocate": null, "pronunciation": "しゅうじゅく", "ipa": "ɕɯːdʑɯkɯ", "syllable_count": 4, "sentences": [{"text": "彼は長い年月をかけて、この技術に習熟した。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "彼[かれ]は長[なが]い年月[ねんげつ]をかけて、この技術[ぎじゅつ]に習熟[しゅうじゅく]した。", "sentence_source": "generated"}, {"text": "彼は日本語に習熟しています。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "彼[かれ]は日本語[にほんご]に習熟[しゅうじゅく]しています。", "sentence_source": "generated"}, {"text": "操作に習熟するまで時間がかかった。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "操作[そうさ]に習熟[しゅうじゅく]するまで時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "習熟には時間が必要です。", "target_word": "習熟", "complexity_tier": "T2", "furigana": "習熟[しゅうじゅく]には時間[じかん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "練習を重ねて、技術に習熟した。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を重[かさ]ねて、技術[ぎじゅつ]に習熟[しゅうじゅく]した。", "sentence_source": "generated"}, {"text": "習熟の程度は人によって違う。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "習熟[しゅうじゅく]の程度[ていど]は人[ひと]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "十分に習熟していれば、失敗は少ないはずだ。", "target_word": "習熟", "complexity_tier": "T4", "furigana": "十分[じゅうぶん]に習熟[しゅうじゅく]していれば、失敗[しっぱい]は少[すく]ないはずだ。", "sentence_source": "generated"}, {"text": "テストで生徒の習熟を確かめる。", "target_word": "習熟", "complexity_tier": "T3", "furigana": "テストで生徒[せいと]の習熟[しゅうじゅく]を確[たし]かめる。", "sentence_source": "generated"}, {"text": "習熟が進むにつれて、作業は速くなった。", "target_word": "習熟", "complexity_tier": "T4", "furigana": "習熟[しゅうじゅく]が進[すす]むにつれて、作業[さぎょう]は速[はや]くなった。", "sentence_source": "generated"}, {"text": "基礎に習熟していない学生には、応用問題は難しすぎる。", "target_word": "習熟", "complexity_tier": "T5", "furigana": "基礎[きそ]に習熟[しゅうじゅく]していない学生[がくせい]には、応用[おうよう]問題[もんだい]は難[むずか]しすぎる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "習熟する", "label": "活用"}, {"form": "習熟した", "label": "活用"}, {"form": "習熟度", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 繰り返して技能を身につけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "習熟", "is_correct": true, "explanation": "見出し語そのもの(しゅうじゅく)。"}, {"text": "収縮", "is_correct": false, "explanation": "しゅうしゅく。「じゅ」が「しゅ」に変わる1モーラ違い。"}, {"text": "執着", "is_correct": false, "explanation": "しゅうちゃく。「じゅ」が「ちゃ」に変わる1モーラ違い。"}, {"text": "収入", "is_correct": false, "explanation": "しゅうにゅう。「じゅ」が「にゅ」に変わる1モーラ違い。"}], "explanations": {"習熟": "見出し語そのもの(しゅうじゅく)。", "収縮": "しゅうしゅく。「じゅ」が「しゅ」に変わる1モーラ違い。", "執着": "しゅうちゃく。「じゅ」が「ちゃ」に変わる1モーラ違い。", "収入": "しゅうにゅう。「じゅ」が「にゅ」に変わる1モーラ違い。"}, "sentence_index": null, "correct_answer": "習熟"}, "level_3": {"options": [{"text": "習熟", "is_correct": true, "explanation": "技術を完全に身につけた、という意味に合う。"}, {"text": "結婚", "is_correct": false, "explanation": "「この技術に結婚した」は意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「この技術に散歩した」は意味が合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、「この技術に教室した」は成り立たない。"}], "explanations": {"習熟": "技術を完全に身につけた、という意味に合う。", "結婚": "「この技術に結婚した」は意味が合わない。", "散歩": "「この技術に散歩した」は意味が合わない。", "教室": "教室は場所で、「この技術に教室した」は成り立たない。"}, "sentence_index": 0, "correct_answer": "習熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、私は友達と習熟を食べに行った。", "explanation": "習熟は食べ物ではない。食べ物の意味で使っている誤り。"}, {"text": "彼は寒い部屋で習熟して眠ってしまった。", "explanation": "習熟は「ぐっすり眠る」意味ではない。熟睡と混同した誤り。"}, {"text": "この荷物は習熟が重くて持てない。", "explanation": "習熟は物の重さを表さない。重量の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "習熟", "is_correct": true, "explanation": "見出し語そのもの(しゅうじゅく)。"}, {"text": "就職", "is_correct": false, "explanation": "しゅうしょく。「じゅ」が「しょ」に変わる1モーラ違い。"}, {"text": "収穫", "is_correct": false, "explanation": "しゅうかく。「じゅ」が「か」に変わる1モーラ違い。"}, {"text": "修学", "is_correct": false, "explanation": "しゅうがく。「じゅ」が「が」に変わる1モーラ違い。"}], "explanations": {"習熟": "見出し語そのもの(しゅうじゅく)。", "就職": "しゅうしょく。「じゅ」が「しょ」に変わる1モーラ違い。", "収穫": "しゅうかく。「じゅ」が「か」に変わる1モーラ違い。", "修学": "しゅうがく。「じゅ」が「が」に変わる1モーラ違い。"}, "sentence_index": null, "correct_answer": "習熟"}, "level_3": {"options": [{"text": "習熟", "is_correct": true, "explanation": "「十分に習熟していれば失敗は少ない」と自然につながる。"}, {"text": "窓", "is_correct": false, "explanation": "「十分に窓していれば」は成り立たず、名詞を「十分に」で修飾して動詞の位置に入れられない。"}, {"text": "食事", "is_correct": false, "explanation": "形は合うが、食事と失敗の少なさが結びつかず意味が合わない。"}, {"text": "大根", "is_correct": false, "explanation": "「十分に大根していれば」は文として成り立たず、習熟の代わりに入る語にならない。"}], "explanations": {"習熟": "「十分に習熟していれば失敗は少ない」と自然につながる。", "窓": "「十分に窓していれば」は成り立たず、名詞を「十分に」で修飾して動詞の位置に入れられない。", "食事": "形は合うが、食事と失敗の少なさが結びつかず意味が合わない。", "大根": "「十分に大根していれば」は文として成り立たず、習熟の代わりに入る語にならない。"}, "sentence_index": 6, "correct_answer": "習熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天気が悪くて、習熟した雨が降り続いている。", "explanation": "習熟は人の技能の習得の程度を表すので、雨の「強さ」の意味で使うのは誤り。"}, {"text": "習熟したバナナは甘くて食べごろだ。", "explanation": "果物が熟す意味ではない。「熟す」と混同した誤り。"}, {"text": "友達の習熟を借りて宿題を終わらせた。", "explanation": "習熟は借りられる物ではない。道具の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械が習熟するまで、毎日練習した。", "corrected_sentence": "新しい機械に習熟するまで、毎日練習した。", "error_description": "習熟するのは人で、対象は「に」で示す。「機械が習熟する」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
