INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52657, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "べんきょうに つかう ほんや どうぐ", "primary_collocate": null, "pronunciation": "きょうざい", "ipa": "kʲoːzai", "syllable_count": 4, "sentences": [{"text": "教材を買う。", "target_word": "教材", "complexity_tier": "T1", "furigana": "教材[きょうざい]を買[か]う。", "sentence_source": "generated"}, {"text": "これは日本語の教材です。", "target_word": "教材", "complexity_tier": "T2", "furigana": "これは日本語[にほんご]の教材[きょうざい]です。", "sentence_source": "generated"}, {"text": "教材を学校に忘れました。", "target_word": "教材", "complexity_tier": "T2", "furigana": "教材[きょうざい]を学校[がっこう]に忘[わす]れました。", "sentence_source": "generated"}, {"text": "友だちに教材を貸した。", "target_word": "教材", "complexity_tier": "T3", "furigana": "友[とも]だちに教材[きょうざい]を貸[か]した。", "sentence_source": "generated"}, {"text": "新しい教材がほしいです。", "target_word": "教材", "complexity_tier": "T2", "furigana": "新[あたら]しい教材[きょうざい]がほしいです。", "sentence_source": "generated"}, {"text": "絵本も教材になる。", "target_word": "教材", "complexity_tier": "T3", "furigana": "絵本[えほん]も教材[きょうざい]になる。", "sentence_source": "generated"}, {"text": "先生は教材を見せている。", "target_word": "教材", "complexity_tier": "T3", "furigana": "先生[せんせい]は教材[きょうざい]を見[み]せている。", "sentence_source": "generated"}, {"text": "教材はかばんに入れてある。", "target_word": "教材", "complexity_tier": "T3", "furigana": "教材[きょうざい]はかばんに入[い]れてある。", "sentence_source": "generated"}, {"text": "教材が多すぎて、持てない。", "target_word": "教材", "complexity_tier": "T4", "furigana": "教材[きょうざい]が多[おお]すぎて、持[も]てない。", "sentence_source": "generated"}, {"text": "英語の教材で勉強したい。", "target_word": "教材", "complexity_tier": "T3", "furigana": "英語[えいご]の教材[きょうざい]で勉強[べんきょう]したい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教材費", "label": "派生"}, {"form": "教材用", "label": "派生"}, {"form": "教材化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 勉強に使う本や道具のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52657, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "「買う」の対象になる、勉強に使う本や道具を指す"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は課された課題で、買うものではないので意味が通らない"}, {"text": "試験", "is_correct": false, "explanation": "試験は受けるもので、買うことはできない"}, {"text": "答案", "is_correct": false, "explanation": "答案は書いて提出する紙で、買う対象として意味が通らない"}], "explanations": {"教材": "「買う」の対象になる、勉強に使う本や道具を指す", "宿題": "宿題は課された課題で、買うものではないので意味が通らない", "試験": "試験は受けるもので、買うことはできない", "答案": "答案は書いて提出する紙で、買う対象として意味が通らない"}, "sentence_index": 0, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食の教材を買いに行った。", "explanation": "ここは〈食材〉の意味。夕食の材料は食材と言い、教材ではない"}, {"text": "台所の教材を洗っておいた。", "explanation": "ここは〈道具〉の意味。鍋や包丁は道具と言い、教育用の教材とは言わない"}, {"text": "寝室の教材を張り替えた。", "explanation": "ここは〈壁紙〉の意味。壁に張るのは壁紙と言い、教材とは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
