INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "教育の目的で使用される、教科書や参考書、問題集などの総称", "primary_collocate": null, "pronunciation": "きょうざい", "ipa": "kʲoːzai", "syllable_count": 4, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "教材", "complexity_tier": "T6", "furigana": "こうした文脈[ぶんみゃく]下[か]、人工[じんこう]知能[ちのう]アルゴリズムによるリアルタイムの習熟度[しゅうじゅくど]分析[ぶんせき]を通[つう]じて学習者[がくしゅうしゃ]の認知[にんち]特性[とくせい]に最適化[さいてきか]された教材[きょうざい]提示[ていじ]を可能[かのう]にするアダプティブラーニングプラットフォームの導入[どうにゅう]は、教育学[きょういくがく]の観点[かんてん]から極[きわ]めて示唆[しさ]に富[と]む。", "sentence_source": "mined"}, {"text": "先生が教材を作りました。", "target_word": "教材", "complexity_tier": "T2", "furigana": "先生[せんせい]が教材[きょうざい]を作[つく]りました。", "sentence_source": "generated"}, {"text": "この教材は初心者向けだ。", "target_word": "教材", "complexity_tier": "T3", "furigana": "この教材[きょうざい]は初心者[しょしんしゃ]向[む]けだ。", "sentence_source": "generated"}, {"text": "新しい教材を選んでいる。", "target_word": "教材", "complexity_tier": "T3", "furigana": "新[あたら]しい教材[きょうざい]を選[えら]んでいる。", "sentence_source": "generated"}, {"text": "教材は図書館で借ります。", "target_word": "教材", "complexity_tier": "T2", "furigana": "教材[きょうざい]は図書館[としょかん]で借[か]ります。", "sentence_source": "generated"}, {"text": "動画も教材として使える。", "target_word": "教材", "complexity_tier": "T3", "furigana": "動画[どうが]も教材[きょうざい]として使[つか]える。", "sentence_source": "generated"}, {"text": "教材が難しすぎると、生徒はやる気を失う。", "target_word": "教材", "complexity_tier": "T4", "furigana": "教材[きょうざい]が難[むずか]しすぎると、生徒[せいと]はやる気[き]を失[うしな]う。", "sentence_source": "generated"}, {"text": "英語の教材を探しています。", "target_word": "教材", "complexity_tier": "T3", "furigana": "英語[えいご]の教材[きょうざい]を探[さが]しています。", "sentence_source": "generated"}, {"text": "先生に勧められた教材で勉強した。", "target_word": "教材", "complexity_tier": "T4", "furigana": "先生[せんせい]に勧[すす]められた教材[きょうざい]で勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "授業の目的に合った教材を選ぶことが、教師の大切な仕事だ。", "target_word": "教材", "complexity_tier": "T5", "furigana": "授業[じゅぎょう]の目的[もくてき]に合[あ]った教材[きょうざい]を選[えら]ぶことが、教師[きょうし]の大切[たいせつ]な仕事[しごと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教材費", "label": "派生"}, {"form": "教材用", "label": "派生"}, {"form": "教材化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 教育に使う教科書や問題集の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "「教材提示」の前の語で、教育用の教科書や問題集を指すため文脈に合う"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所の名前で、提示の対象にならないため「教室提示」は意味が通らない"}, {"text": "学校", "is_correct": false, "explanation": "学校は施設で、最適化して提示する対象にはならないため合わない"}, {"text": "教育", "is_correct": false, "explanation": "教育は活動や分野の名前で、提示されるものを表さないため「教育提示」は不自然"}], "explanations": {"教材": "「教材提示」の前の語で、教育用の教科書や問題集を指すため文脈に合う", "教室": "教室は場所の名前で、提示の対象にならないため「教室提示」は意味が通らない", "学校": "学校は施設で、最適化して提示する対象にはならないため合わない", "教育": "教育は活動や分野の名前で、提示されるものを表さないため「教育提示」は不自然"}, "sentence_index": 0, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カレーの教材を先に炒めて、香りを出しておく。", "explanation": "ここは〈材料〉の意味。料理の食材は教材とは言わないので不自然"}, {"text": "車が故障したので、教材を交換した。", "explanation": "ここは〈部品〉の意味。壊れた車の部品を替えるのは部品の交換で、教材とは言わない"}, {"text": "休日に、教材を着て出かけた。", "explanation": "ここは〈服〉の意味。着るものは服と言い、教材とは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "「難しすぎる」の主語で、難易度が問題になる教育用の教材を指す"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は書く板で、難しすぎるという述語の主語としては意味が通らない"}, {"text": "体育館", "is_correct": false, "explanation": "体育館は施設で、難しさが主語になるとは言えない"}, {"text": "校舎", "is_correct": false, "explanation": "校舎は建物で、難しすぎるという述語と合わない"}], "explanations": {"教材": "「難しすぎる」の主語で、難易度が問題になる教育用の教材を指す", "黒板": "黒板は書く板で、難しすぎるという述語の主語としては意味が通らない", "体育館": "体育館は施設で、難しさが主語になるとは言えない", "校舎": "校舎は建物で、難しすぎるという述語と合わない"}, "sentence_index": 6, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "役所の教材を提出した。", "explanation": "ここは〈書類〉の意味。役所に出す書類は書類と言い、教材とは言わない"}, {"text": "ビールの教材は麦だ。", "explanation": "ここは〈原料〉の意味。ビールの原料は麦で、教育用の教材ではない"}, {"text": "病院の教材を洗った。", "explanation": "ここは〈器具〉の意味。病院で使う器具は器具と言い、教材とは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が教材に準備しました。", "corrected_sentence": "先生が教材を準備しました。", "error_description": "誤りは「教材に」。「準備する」は他動詞なので対象は「を」で示す。「教材に準備する」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は教材を配られた。", "corrected_sentence": "先生は教材を配った。", "error_description": "「配る」は他動詞。受身の「配られる」は「教材が配られた」の形で使うため、「先生は教材を配られた」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
