INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「パスの提示」の「の」で、提示を修飾する自然な形になる。"}, {"text": "が", "is_correct": false, "explanation": "「パスが提示を求められ」では主語が「パス」になり、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「パスより提示」は比較の意味になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「パスを提示を」と目的語が二つ続き、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「パスの提示」の「の」で、提示を修飾する自然な形になる。", "が": "「パスが提示を求められ」では主語が「パス」になり、意味が通らない。", "より": "「パスより提示」は比較の意味になり、文が成り立たない。", "を": "「パスを提示を」と目的語が二つ続き、文として成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "見せること", "primary_collocate": null, "pronunciation": "ていじ", "ipa": "teiʑi", "syllable_count": 3, "sentences": [{"text": "店員に会員証を提示すると、割引が受けられる。", "target_word": "提示", "complexity_tier": "T3", "furigana": "店員[てんいん]に会員証[かいいんしょう]を提示[ていじ]すると、割引[わりびき]が受[う]けられる。", "sentence_source": "generated"}, {"text": "銀行では、本人確認のために身分証の提示が必要だ。", "target_word": "提示", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]では、本人[ほんにん]確認[かくにん]のために身分証[みぶんしょう]の提示[ていじ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "会社は、新入社員に給料などの条件を提示した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、新入[しんにゅう]社員[しゃいん]に給料[きゅうりょう]などの条件[じょうけん]を提示[ていじ]した。", "sentence_source": "generated"}, {"text": "先生は、スライドで三つの案を提示した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "先生[せんせい]は、スライドで三[みっ]つの案[あん]を提示[ていじ]した。", "sentence_source": "generated"}, {"text": "警察官に免許証の提示を求められた。", "target_word": "提示", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]に免許証[めんきょしょう]の提示[ていじ]を求[もと]められた。", "sentence_source": "generated"}, {"text": "入口で、チケットを提示してから中に入ってください。", "target_word": "提示", "complexity_tier": "T3", "furigana": "入口[いりぐち]で、チケットを提示[ていじ]してから中[なか]に入[はい]ってください。", "sentence_source": "generated"}, {"text": "私の意見を裏づける資料を提示したが、相手は納得しなかった。", "target_word": "提示", "complexity_tier": "T3", "furigana": "私[わたし]の意見[いけん]を裏[うら]づける資料[しりょう]を提示[ていじ]したが、相手[あいて]は納得[なっとく]しなかった。", "sentence_source": "generated"}, {"text": "駅員にパスの提示を求められ、かばんの中を探した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "駅員[えきいん]にパスの提示[ていじ]を求[もと]められ、かばんの中[なか]を探[さが]した。", "sentence_source": "generated"}, {"text": "会議で社長が新しい方針を提示し、全員が驚いた。", "target_word": "提示", "complexity_tier": "T3", "furigana": "会議[かいぎ]で社長[しゃちょう]が新[あたら]しい方針[ほうしん]を提示[ていじ]し、全員[ぜんいん]が驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "画面にエラーの内容が提示され、原因がすぐ分かった。", "target_word": "提示", "complexity_tier": "T3", "furigana": "画面[がめん]にエラーの内容[ないよう]が提示[ていじ]され、原因[げんいん]がすぐ分[わ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提示", "label": "基本形"}, {"form": "提示する", "label": "する動詞形"}, {"form": "提示した", "label": "過去形"}, {"form": "提示される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "証明書・条件・資料などを相手に差し出して見せること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 裏づける (Zipf 1.89)']::text[], 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "証明書などを相手に見せること。会員証を店員に見せれば割引が受けられるという文に合う。"}, {"text": "返却", "is_correct": false, "explanation": "借りた物を持ち主に返すこと。会員証を返すと割引が受けられるという内容にはならない。"}, {"text": "破棄", "is_correct": false, "explanation": "不要な物を捨てること。割引につながる行為ではない。"}, {"text": "紛失", "is_correct": false, "explanation": "物をなくすこと。割引の条件としては成り立たない。"}], "explanations": {"提示": "証明書などを相手に見せること。会員証を店員に見せれば割引が受けられるという文に合う。", "返却": "借りた物を持ち主に返すこと。会員証を返すと割引が受けられるという内容にはならない。", "破棄": "不要な物を捨てること。割引につながる行為ではない。", "紛失": "物をなくすこと。割引の条件としては成り立たない。"}, "sentence_index": 0, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は言葉にできない喜びを提示した。", "explanation": "ここは〈表現〉の意味。提示は相手に見せたり差し出したりする語で、感情を外に表すことには使わない。"}, {"text": "ファイルを別の形式に提示した。", "explanation": "ここは〈変換〉の意味。提示は見せる語で、ファイルの形式を別のものに変える意味はない。"}, {"text": "荷物を海外へ提示した。", "explanation": "ここは〈発送〉の意味。提示は相手に見せることで、品物を送り出す意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "資料などを相手に示すこと。自分の意見を裏づける資料を見せたが納得されなかったという文に合う。"}, {"text": "着席", "is_correct": false, "explanation": "席につくこと。資料を席につけるという意味にはならない。"}, {"text": "就寝", "is_correct": false, "explanation": "寝ること。資料に対して使える動作ではなく、文が成り立たない。"}, {"text": "起床", "is_correct": false, "explanation": "起きること。資料が起きるという文は意味をなさない。"}], "explanations": {"提示": "資料などを相手に示すこと。自分の意見を裏づける資料を見せたが納得されなかったという文に合う。", "着席": "席につくこと。資料を席につけるという意味にはならない。", "就寝": "寝ること。資料に対して使える動作ではなく、文が成り立たない。", "起床": "起きること。資料が起きるという文は意味をなさない。"}, "sentence_index": 6, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前の広場をきれいに提示した。", "explanation": "ここは〈掃除〉の意味。提示は見せる語で、場所をきれいに片づける意味はない。"}, {"text": "重い荷物を駅まで提示した。", "explanation": "ここは〈運搬〉の意味。提示は品物を運ぶのではなく見せる語なので、荷物を移すことには使わない。"}, {"text": "大雨で古い校舎の屋根を提示した。", "explanation": "ここは〈損壊〉の意味。提示は見せる語で、屋根が壊れて傷む意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "受付で、来客は名札が提示した。", "corrected_sentence": "受付で、来客は名札を提示した。", "error_description": "「提示する」は目的語を「を」で取るので、「名札が」は誤り。正しくは「名札を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52659, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交番で、警官は身分証の提示されを求めた。", "corrected_sentence": "交番で、警官は身分証の提示を求めた。", "error_description": "「提示を求める」が正しい形。「提示され」を入れると受け身になり、後ろの「を」と続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52661, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ラーニング」と「時間」をつなぐ連体修飾で、学ぶための時間を表す"}, {"text": "を", "is_correct": false, "explanation": "対象を示す。「ラーニングを時間を作った」は目的語が重なり不自然"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「ラーニングと時間を作った」は並列の相手が欠けて不自然"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「ラーニングへ時間を作った」は誤り"}], "correct_answer": "の", "explanations": {"の": "「ラーニング」と「時間」をつなぐ連体修飾で、学ぶための時間を表す", "を": "対象を示す。「ラーニングを時間を作った」は目的語が重なり不自然", "と": "並列を示す。「ラーニングと時間を作った」は並列の相手が欠けて不自然", "へ": "方向を示す。「ラーニングへ時間を作った」は誤り"}, "error_tags": {"を": "対象", "と": "並列・共同", "へ": "方向"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
