INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52661, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まなぶこと。", "primary_collocate": null, "pronunciation": "らーにんぐ", "ipa": "ɾaːniŋɡɯ", "syllable_count": 5, "sentences": [{"text": "ラーニングを楽しむ。", "target_word": "ラーニング", "complexity_tier": "T1", "furigana": "ラーニングを楽[たの]しむ。", "sentence_source": "generated"}, {"text": "ラーニングが好きです。", "target_word": "ラーニング", "complexity_tier": "T2", "furigana": "ラーニングが好[す]きです。", "sentence_source": "generated"}, {"text": "これは新しいラーニングです。", "target_word": "ラーニング", "complexity_tier": "T2", "furigana": "これは新[あたら]しいラーニングです。", "sentence_source": "generated"}, {"text": "ラーニングの時間を作った。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングの時間[じかん]を作[つく]った。", "sentence_source": "generated"}, {"text": "毎日ラーニングをします。", "target_word": "ラーニング", "complexity_tier": "T2", "furigana": "毎日[まいにち]ラーニングをします。", "sentence_source": "generated"}, {"text": "友だちとラーニングしている。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "友[とも]だちとラーニングしている。", "sentence_source": "generated"}, {"text": "ラーニングで英語が上手になった。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングで英語[えいご]が上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "ラーニングは大切だと思う。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングは大切[たいせつ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "ラーニングを続ければ、わかるようになる。", "target_word": "ラーニング", "complexity_tier": "T4", "furigana": "ラーニングを続[つづ]ければ、わかるようになる。", "sentence_source": "generated"}, {"text": "弟のラーニングを手伝う。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "弟[おとうと]のラーニングを手伝[てつだ]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "eラーニング", "label": "派生"}, {"form": "ディープラーニング", "label": "派生"}, {"form": "アクティブラーニング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 学ぶこと、勉強すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52661, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラーニング", "is_correct": true, "explanation": "「楽しむ」の対象として、学ぶことを楽しむという意味になる"}, {"text": "借金", "is_correct": false, "explanation": "借金は楽しむものではなく、意味が通らない"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は楽しむ対象ではなく、意味が通らない"}, {"text": "骨折", "is_correct": false, "explanation": "骨折を楽しむのは不自然で、意味が通らない"}], "explanations": {"ラーニング": "「楽しむ」の対象として、学ぶことを楽しむという意味になる", "借金": "借金は楽しむものではなく、意味が通らない", "寝坊": "寝坊は楽しむ対象ではなく、意味が通らない", "骨折": "骨折を楽しむのは不自然で、意味が通らない"}, "sentence_index": 0, "correct_answer": "ラーニング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝のラーニングでタイムを縮めた。", "explanation": "ここは〈ランニング（走ること）〉の意味。タイムを縮めるのは走ることで、ラーニングとは言わない"}, {"text": "夕食のラーニングを作った。", "explanation": "ここは〈献立・料理〉の意味。夕食を作ることはラーニングとは言わない"}, {"text": "髪のラーニングを頼んだ。", "explanation": "ここは〈散髪（ヘアカット）〉の意味。髪を切ることはラーニングとは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52661, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラーニング", "is_correct": true, "explanation": "「で」の前の手段を表し、学習によって上達したという意味になる"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯では英語は上達しないので意味が通らない"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞で英語が上手になるとは言えない"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足では英語は上達せず、意味が通らない"}], "explanations": {"ラーニング": "「で」の前の手段を表し、学習によって上達したという意味になる", "洗濯": "洗濯では英語は上達しないので意味が通らない", "渋滞": "渋滞で英語が上手になるとは言えない", "寝不足": "寝不足では英語は上達せず、意味が通らない"}, "sentence_index": 6, "correct_answer": "ラーニング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放課後、友だちとラーニングを焼いた。", "explanation": "ここは〈お菓子作り〉の意味。クッキーを焼くことはお菓子作りと言い、ラーニングとは言わない"}, {"text": "カラオケで、ラーニングを一曲歌った。", "explanation": "ここは〈歌〉の意味。歌うことはラーニングとは言わない"}, {"text": "妹にラーニングを描いてもらった。", "explanation": "ここは〈絵〉の意味。絵を描くことはラーニングとは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52661, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日からラーニングに始めた。", "corrected_sentence": "昨日からラーニングを始めた。", "error_description": "「始める」は他動詞なので対象は「を」で示す。「ラーニングに始めた」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
