INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始める」の対象を示す格助詞。ラーニングを始めている"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「ラーニングが始めている」は主語と述語が合わない"}, {"text": "に", "is_correct": false, "explanation": "帰着点や相手を示す。「ラーニングに始めている」は誤り"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す。「ラーニングと始めている」は意味が通らない"}], "correct_answer": "を", "explanations": {"を": "「始める」の対象を示す格助詞。ラーニングを始めている", "が": "主語を示す。「ラーニングが始めている」は主語と述語が合わない", "に": "帰着点や相手を示す。「ラーニングに始めている」は誤り", "と": "並列や共同を示す。「ラーニングと始めている」は意味が通らない"}, "error_tags": {"が": "主語", "に": "帰着点・相手", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい知識や技術を身につけること。学ぶこと。", "primary_collocate": null, "pronunciation": "らーにんぐ", "ipa": "ɾaːniŋɡɯ", "syllable_count": 5, "sentences": [{"text": "社員の学び直しを支えるため、会社は新しいラーニングの仕組みを導入した。", "target_word": "ラーニング", "complexity_tier": "T4", "furigana": "社員[しゃいん]の学[まな]び直[なお]しを支[ささ]えるため、会社[かいしゃ]は新[あたら]しいラーニングの仕組[しく]みを導入[どうにゅう]した。", "sentence_source": "generated"}, {"text": "ラーニングは楽しいです。", "target_word": "ラーニング", "complexity_tier": "T2", "furigana": "ラーニングは楽[たの]しいです。", "sentence_source": "generated"}, {"text": "新しいラーニングの方法を試す。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "新[あたら]しいラーニングの方法[ほうほう]を試[ため]す。", "sentence_source": "generated"}, {"text": "ラーニングを続けることが大切だ。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングを続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "子どものラーニングを助けます。", "target_word": "ラーニング", "complexity_tier": "T2", "furigana": "子[こ]どものラーニングを助[たす]けます。", "sentence_source": "generated"}, {"text": "ラーニングの成果が出てきた。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングの成果[せいか]が出[で]てきた。", "sentence_source": "generated"}, {"text": "ラーニングを重ねれば、力がつく。", "target_word": "ラーニング", "complexity_tier": "T4", "furigana": "ラーニングを重[かさ]ねれば、力[ちから]がつく。", "sentence_source": "generated"}, {"text": "社会人もラーニングを始めている。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "社会人[しゃかいじん]もラーニングを始[はじ]めている。", "sentence_source": "generated"}, {"text": "ラーニングには時間が必要だ。", "target_word": "ラーニング", "complexity_tier": "T3", "furigana": "ラーニングには時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "ラーニングの目標をはっきりさせると、学び方が変わる。", "target_word": "ラーニング", "complexity_tier": "T5", "furigana": "ラーニングの目標[もくひょう]をはっきりさせると、学[まな]び方[かた]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "eラーニング", "label": "派生"}, {"form": "ディープラーニング", "label": "派生"}, {"form": "アクティブラーニング", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 新しい知識や技術を身につけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラーニング", "is_correct": true, "explanation": "「新しい〜の仕組み」の語で、学習の仕組みを表すため文脈に合う"}, {"text": "カフェ", "is_correct": false, "explanation": "カフェは店の名前で、学習の仕組みの語としては合わない"}, {"text": "マッサージ", "is_correct": false, "explanation": "施術を指す語で、学習の仕組みを表す語にはならない"}, {"text": "ジャンプ", "is_correct": false, "explanation": "跳ぶ動作を表す語で、学習の仕組みの語としては意味が通らない"}], "explanations": {"ラーニング": "「新しい〜の仕組み」の語で、学習の仕組みを表すため文脈に合う", "カフェ": "カフェは店の名前で、学習の仕組みの語としては合わない", "マッサージ": "施術を指す語で、学習の仕組みを表す語にはならない", "ジャンプ": "跳ぶ動作を表す語で、学習の仕組みの語としては意味が通らない"}, "sentence_index": 0, "correct_answer": "ラーニング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラーニングのシューズを新調した。", "explanation": "ここは〈ランニング（走ること）〉の意味。走るための靴はランニングシューズと言い、ラーニングとは言わない"}, {"text": "ジムで毎日バーベルのラーニングをしている。", "explanation": "ここは〈トレーニング（鍛錬）〉の意味。筋トレはラーニングとは言わない"}, {"text": "昼休みにラーニングを食べた。", "explanation": "ここは〈ランチ（昼食）〉の意味。昼食は食べるもので、ラーニングとは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラーニング", "is_correct": true, "explanation": "「重ねる」の対象で、学習を積み重ねると力がつくという意味になる"}, {"text": "写真", "is_correct": false, "explanation": "写真を重ねても力がつくとは言えず、意味が通らない"}, {"text": "皿", "is_correct": false, "explanation": "皿を重ねると割れやすくなるが、力がつくとは言えない"}, {"text": "座布団", "is_correct": false, "explanation": "座布団を重ねても力はつかず、意味が通らない"}], "explanations": {"ラーニング": "「重ねる」の対象で、学習を積み重ねると力がつくという意味になる", "写真": "写真を重ねても力がつくとは言えず、意味が通らない", "皿": "皿を重ねると割れやすくなるが、力がつくとは言えない", "座布団": "座布団を重ねても力はつかず、意味が通らない"}, "sentence_index": 6, "correct_answer": "ラーニング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食のラーニングを手早く作った。", "explanation": "ここは〈料理〉の意味。食事を作ることはラーニングとは言わない"}, {"text": "週末に車でラーニングをした。", "explanation": "ここは〈ドライブ〉の意味。車で出かけることはラーニングとは言わない"}, {"text": "ポスターのラーニングを頼んだ。", "explanation": "ここは〈デザイン〉の意味。ポスター制作の依頼はデザインと言い、ラーニングとは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大人もラーニングに続けている。", "corrected_sentence": "大人もラーニングを続けている。", "error_description": "「続ける」は他動詞なので対象は「を」で示す。「ラーニングに続ける」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝、ラーニングを習慣をつける。", "corrected_sentence": "毎朝、ラーニングの習慣をつける。", "error_description": "「ラーニングの習慣」と「の」で修飾する。「を」にすると目的語が二つになり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「教授」を話題として取り上げるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「教授を親切です」は目的語を示す形で、形容動詞の文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「教授で親切です」は手段や場所を表し、人の性質を述べる文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「教授と親切です」は共同や相手を表すが、性質を述べる主語にならない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「教授」を話題として取り上げるので正しい。", "を": "「教授を親切です」は目的語を示す形で、形容動詞の文には合わない。", "で": "「教授で親切です」は手段や場所を表し、人の性質を述べる文には合わない。", "と": "「教授と親切です」は共同や相手を表すが、性質を述べる主語にならない。"}, "error_tags": {"を": "object", "で": "means", "と": "accompaniment"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "動作の主語を示す「が」。「教授が教室に入ってきた」として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「教授を教室に入ってきた」は目的語では意味が通らず、入る動作の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「教授で教室に入ってきた」は手段を表すが、人が入ってくる文には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「教授へ教室に入ってきた」は方向を表すが、主語の動作には使えず不自然。"}], "correct_answer": "が", "explanations": {"が": "動作の主語を示す「が」。「教授が教室に入ってきた」として正しい。", "を": "「教授を教室に入ってきた」は目的語では意味が通らず、入る動作の主語にならない。", "で": "「教授で教室に入ってきた」は手段を表すが、人が入ってくる文には合わない。", "へ": "「教授へ教室に入ってきた」は方向を表すが、主語の動作には使えず不自然。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大学でべんきょうをおしえるひと。", "primary_collocate": null, "pronunciation": "きょうじゅ", "ipa": "kʲoːdʑɯ", "syllable_count": 3, "sentences": [{"text": "教授は先生だ。", "target_word": "教授", "complexity_tier": "T1", "furigana": "教授[きょうじゅ]は先生[せんせい]だ。", "sentence_source": "generated"}, {"text": "教授に会いました。", "target_word": "教授", "complexity_tier": "T2", "furigana": "教授[きょうじゅ]に会[あ]いました。", "sentence_source": "generated"}, {"text": "私の教授は親切です。", "target_word": "教授", "complexity_tier": "T2", "furigana": "私[わたし]の教授[きょうじゅ]は親切[しんせつ]です。", "sentence_source": "generated"}, {"text": "教授の話を聞いている。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]の話[はなし]を聞[き]いている。", "sentence_source": "generated"}, {"text": "教授は大学にいます。", "target_word": "教授", "complexity_tier": "T2", "furigana": "教授[きょうじゅ]は大学[だいがく]にいます。", "sentence_source": "generated"}, {"text": "教授に宿題を出した。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]に宿題[しゅくだい]を出[だ]した。", "sentence_source": "generated"}, {"text": "母は大学の教授だ。", "target_word": "教授", "complexity_tier": "T3", "furigana": "母[はは]は大学[だいがく]の教授[きょうじゅ]だ。", "sentence_source": "generated"}, {"text": "教授が教室に入ってきた。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]が教室[きょうしつ]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "教授に聞けば、答えがわかる。", "target_word": "教授", "complexity_tier": "T4", "furigana": "教授[きょうじゅ]に聞[き]けば、答[こた]えがわかる。", "sentence_source": "generated"}, {"text": "あの教授はとても優しい。", "target_word": "教授", "complexity_tier": "T3", "furigana": "あの教授[きょうじゅ]はとても優[やさ]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教授陣", "label": "派生"}, {"form": "名誉教授", "label": "派生"}, {"form": "准教授", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 大学で勉強を教える人のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教授", "is_correct": true, "explanation": "大学で勉強を教える人を指す語で、「教授は先生だ」と文の主語になれる。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べるは先生だ」は成り立たず、人を主語にできない。"}, {"text": "走る", "is_correct": false, "explanation": "「走るは先生だ」は文として成り立たず、先生を表す名詞の位置に入らない。"}, {"text": "青い", "is_correct": false, "explanation": "「青いは先生だ」は形容詞が名詞として働けず、文が成り立たない。"}], "explanations": {"教授": "大学で勉強を教える人を指す語で、「教授は先生だ」と文の主語になれる。", "食べる": "「食べるは先生だ」は成り立たず、人を主語にできない。", "走る": "「走るは先生だ」は文として成り立たず、先生を表す名詞の位置に入らない。", "青い": "「青いは先生だ」は形容詞が名詞として働けず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中学校の教室で、教授として友達と話している。", "explanation": "ここは〈生徒〉の意味。教授は大学などで教える人を指し、教わる側の中学生には使わないので合わない。"}, {"text": "塾の教室で、教授として数学を教えている。", "explanation": "ここは〈講師〉の意味。教授は大学で教える人を指し、塾で教える人には使わないので合わない。"}, {"text": "彼は町の自動車整備工場で教授として、エンジンの点検をしている。", "explanation": "ここは〈整備士〉の意味。教授は大学などの職名で、工場で車を点検する人には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教授", "is_correct": true, "explanation": "大学の職名で、「母は大学の教授だ」と職業を正しく述べる語。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "「母は大学の泳ぐだ」は成り立たず、職業を表す名詞の位置に入らない。"}, {"text": "寒い", "is_correct": false, "explanation": "「大学の寒いだ」は形容詞を名詞の前に置けず、文が成り立たない。"}, {"text": "歌う", "is_correct": false, "explanation": "「母は大学の歌うだ」は動詞が職業を表せず、文として成り立たない。"}], "explanations": {"教授": "大学の職名で、「母は大学の教授だ」と職業を正しく述べる語。", "泳ぐ": "「母は大学の泳ぐだ」は成り立たず、職業を表す名詞の位置に入らない。", "寒い": "「大学の寒いだ」は形容詞を名詞の前に置けず、文が成り立たない。", "歌う": "「母は大学の歌うだ」は動詞が職業を表せず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの教授は近所の小学校で、一年生の担任をしている。", "explanation": "ここは〈教師〉の意味。教授は大学などの職名で、小学校の先生には使わないので合わない。"}, {"text": "あの教授はレジで会計をしている。", "explanation": "ここは〈店員〉の意味。教授は大学の職名で、店で働く人には使わないので合わない。"}, {"text": "あの教授は交番で、落とし物の届けを受け付けている。", "explanation": "ここは〈警察官〉の意味。教授は大学の教員を指し、交番の勤務者には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、廊下で教授を会いました。", "corrected_sentence": "昨日、廊下で教授に会いました。", "error_description": "「教授」に続く助詞の誤り。「会う」の相手は「に」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は教授で論文を返してもらった。", "corrected_sentence": "私は教授に論文を返してもらった。", "error_description": "「教授」に続く助詞の誤り。「返してもらう」の相手は「に」で示すので、「で」は不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
