INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「教授をしている」で職業を示す「を」。「〜をする」の形で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「教授がしている」は職業を述べる文として成り立たず、主語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「教授にしている」は方向や相手を表す語で、職業を示す文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「教授でしている」は手段や場所を表す語で、職業を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「教授をしている」で職業を示す「を」。「〜をする」の形で正しい。", "が": "「教授がしている」は職業を述べる文として成り立たず、主語にもならない。", "に": "「教授にしている」は方向や相手を表す語で、職業を示す文には合わない。", "で": "「教授でしている」は手段や場所を表す語で、職業を示す文には合わない。"}, "error_tags": {"が": "subject_mismatch", "に": "dative_target", "で": "means_location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大学などの高等教育機関で、専門分野の教育や研究を行う職名や、その人。", "primary_collocate": null, "pronunciation": "きょうじゅ", "ipa": "kʲoːdʑɯ", "syllable_count": 3, "sentences": [{"text": "教授は学生の質問に丁寧に答えてくれる。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]は学生[がくせい]の質問[しつもん]に丁寧[ていねい]に答[こた]えてくれる。", "sentence_source": "generated"}, {"text": "山田教授は有名です。", "target_word": "教授", "complexity_tier": "T2", "furigana": "山田[やまだ]教授[きょうじゅ]は有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "教授に質問に行った。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]に質問[しつもん]に行[い]った。", "sentence_source": "generated"}, {"text": "兄は大学の教授になった。", "target_word": "教授", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]の教授[きょうじゅ]になった。", "sentence_source": "generated"}, {"text": "教授の研究室は三階です。", "target_word": "教授", "complexity_tier": "T2", "furigana": "教授[きょうじゅ]の研究室[けんきゅうしつ]は三階[さんがい]です。", "sentence_source": "generated"}, {"text": "教授が学生に論文を返した。", "target_word": "教授", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]が学生[がくせい]に論文[ろんぶん]を返[かえ]した。", "sentence_source": "generated"}, {"text": "教授に勧められて、大学院に進んだ。", "target_word": "教授", "complexity_tier": "T4", "furigana": "教授[きょうじゅ]に勧[すす]められて、大学院[だいがくいん]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "彼の父は大学で教授をしている。", "target_word": "教授", "complexity_tier": "T3", "furigana": "彼[かれ]の父[ちち]は大学[だいがく]で教授[きょうじゅ]をしている。", "sentence_source": "generated"}, {"text": "教授が来るまで、静かに待った。", "target_word": "教授", "complexity_tier": "T4", "furigana": "教授[きょうじゅ]が来[く]るまで、静[しず]かに待[ま]った。", "sentence_source": "generated"}, {"text": "その教授は、環境問題の研究で世界的に知られている。", "target_word": "教授", "complexity_tier": "T5", "furigana": "その教授[きょうじゅ]は、環境[かんきょう]問題[もんだい]の研究[けんきゅう]で世界的[せかいてき]に知[し]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教授陣", "label": "派生"}, {"form": "名誉教授", "label": "派生"}, {"form": "准教授", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 大学で教育や研究を行う職名、その人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教授", "is_correct": true, "explanation": "大学で教育・研究を担う人を指し、「教授は学生の質問に答える」と主語になれる。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べるは学生の質問に…」は成り立たず、人を主語にできない。"}, {"text": "走る", "is_correct": false, "explanation": "「走るは学生の質問に…」は文として成り立たず、主語の位置に入らない。"}, {"text": "青い", "is_correct": false, "explanation": "「青いは学生の質問に…」は形容詞が主語になれず、文が成り立たない。"}], "explanations": {"教授": "大学で教育・研究を担う人を指し、「教授は学生の質問に答える」と主語になれる。", "食べる": "「食べるは学生の質問に…」は成り立たず、人を主語にできない。", "走る": "「走るは学生の質問に…」は文として成り立たず、主語の位置に入らない。", "青い": "「青いは学生の質問に…」は形容詞が主語になれず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近所の小学校で、教授として子どもたちに算数を教えている。", "explanation": "ここは〈教師〉の意味。教授は大学などの高等教育機関の職名なので、小学校の先生には使わないため合わない。"}, {"text": "彼は来年から駅前の予備校で教授として英語を担当する予定だ。", "explanation": "ここは〈講師〉の意味。教授は大学の職名で、予備校で教える人は講師と呼ぶので合わない。"}, {"text": "彼女は大学の事務部で教授として書類を管理している。", "explanation": "ここは〈職員〉の意味。教授は教育・研究を担う職名で、事務を担当する職員の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教授", "is_correct": true, "explanation": "勧める主体になれる人を指す語で、大学院に進むよう勧めた教員の意味として正しい。"}, {"text": "椅子", "is_correct": false, "explanation": "「椅子に勧められて」は成り立たず、勧める主体になれない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆に勧められて」は文として成り立たず、勧める主体の位置に入らない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は大学院への進学を勧めることができず、意味が合わない。"}], "explanations": {"教授": "勧める主体になれる人を指す語で、大学院に進むよう勧めた教員の意味として正しい。", "椅子": "「椅子に勧められて」は成り立たず、勧める主体になれない。", "鉛筆": "「鉛筆に勧められて」は文として成り立たず、勧める主体の位置に入らない。", "雨": "雨は大学院への進学を勧めることができず、意味が合わない。"}, "sentence_index": 6, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は町の図書館で教授として、本の貸し出し業務を担当している。", "explanation": "ここは〈司書〉の意味。教授は大学などの教育・研究職の名で、図書館の業務担当者には使わないので合わない。"}, {"text": "彼は商社の営業部で教授として働いている。", "explanation": "ここは〈社員〉の意味。教授は大学などで教える職名で、会社員の意味では使わないので合わない。"}, {"text": "彼は自動車教習所で教授として運転を教えている。", "explanation": "ここは〈教官〉の意味。教授は大学などの職名で、教習所の指導員には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、研究室で教授を会った。", "corrected_sentence": "先週、研究室で教授に会った。", "error_description": "「教授」に続く助詞の誤り。「会う」の相手は「に」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52664, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は大学で教授を働いている。", "corrected_sentence": "叔父は大学で教授として働いている。", "error_description": "「教授」に続く助詞の誤り。「働く」の前では職業を「として」で示すので、「を」は不適切。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「のせる」の着点を表し、「プラットホームに」の形で自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「のせる」の着点を示す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「のせる」の着点には合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞で、「のせる」の目標を示す位置には使えない。"}], "correct_answer": "に", "explanations": {"に": "「のせる」の着点を表し、「プラットホームに」の形で自然に続く。", "を": "「を」は動作の対象を表すので、「のせる」の着点を示す位置には入らない。", "で": "「で」は場所や手段を表すので、「のせる」の着点には合わない。", "の": "名詞をつなぐ助詞で、「のせる」の目標を示す位置には使えない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「プラットホームの上に」と、名詞「上」をつなぐ「の」として自然に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、名詞「上」を修飾する形には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すので、「上」の前には続かない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すので、名詞句「上」とは続かない。"}], "correct_answer": "の", "explanations": {"の": "「プラットホームの上に」と、名詞「上」をつなぐ「の」として自然に続く。", "へ": "方向を表すので、名詞「上」を修飾する形には合わない。", "から": "起点を表すので、「上」の前には続かない。", "が": "主語を表すので、名詞句「上」とは続かない。"}, "error_tags": {"へ": "方向", "から": "起点", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かをのせるための、平らな台。", "primary_collocate": null, "pronunciation": "ぷらっとほーむ", "ipa": "pɾattohoːmɯ", "syllable_count": 7, "sentences": [{"text": "作業員は、高いところで使う木のプラットホームの上に道具を置いた。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "作業員[さぎょういん]は、高[たか]いところで使[つか]う木[き]のプラットホームの上[うえ]に道具[どうぐ]を置[お]いた。", "sentence_source": "generated"}, {"text": "倉庫では、荷物を平らなプラットホームにのせて運ぶ。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "倉庫[そうこ]では、荷物[にもつ]を平[たい]らなプラットホームにのせて運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "鉢植えの花を、小さなプラットホームの上に並べた。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "鉢植[はちう]えの花[はな]を、小[ちい]さなプラットホームの上[うえ]に並[なら]べた。", "sentence_source": "generated"}, {"text": "店は、商品を見せるために、少し高いプラットホームを作った。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "店[みせ]は、商品[しょうひん]を見[み]せるために、少[すこ]し高[たか]いプラットホームを作[つく]った。", "sentence_source": "generated"}, {"text": "工事の足場には、人が立てる広いプラットホームがある。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "工事[こうじ]の足場[あしば]には、人[ひと]が立[た]てる広[ひろ]いプラットホームがある。", "sentence_source": "generated"}, {"text": "荷物をトラックにのせるときは、高さの合うプラットホームを使う。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "荷物[にもつ]をトラックにのせるときは、高[たか]さの合[あ]うプラットホームを使[つか]う。", "sentence_source": "generated"}, {"text": "海に浮かぶプラットホームの上に、石油を取る機械が置いてある。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "海[うみ]に浮[う]かぶプラットホームの上[うえ]に、石油[せきゆ]を取[と]る機械[きかい]が置[お]いてある。", "sentence_source": "generated"}, {"text": "重い機械は、丈夫なプラットホームの上に固定してください。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "重[おも]い機械[きかい]は、丈夫[じょうぶ]なプラットホームの上[うえ]に固定[こてい]してください。", "sentence_source": "generated"}, {"text": "撮影のために、小さなプラットホームに三脚を立てた。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "撮影[さつえい]のために、小[ちい]さなプラットホームに三脚[さんきゃく]を立[た]てた。", "sentence_source": "generated"}, {"text": "このプラットホームは平らなので、荷物が落ちにくい。", "target_word": "プラットホーム", "complexity_tier": "T3", "furigana": "このプラットホームは平[たい]らなので、荷物[にもつ]が落[お]ちにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プラットホーム", "label": "基本形"}, {"form": "プラットホームの", "label": "連体(の)"}, {"form": "プラットホームに", "label": "位置(に)"}], "register": "neutral", "sense_fingerprint": "物や人をのせるための平らな台・足場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プラットホーム", "is_correct": true, "explanation": "「木の」に続く平らな台の意味に合い、道具を置く場所として自然。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製品で、「木の」で修飾しても道具を置く台にはならない。"}, {"text": "ガラス", "is_correct": false, "explanation": "木ではない材料なので、「木の」には続かない。"}, {"text": "レンズ", "is_correct": false, "explanation": "光を通す部品で、道具を置く台としては使えない。"}], "explanations": {"プラットホーム": "「木の」に続く平らな台の意味に合い、道具を置く場所として自然。", "ハンカチ": "布製品で、「木の」で修飾しても道具を置く台にはならない。", "ガラス": "木ではない材料なので、「木の」には続かない。", "レンズ": "光を通す部品で、道具を置く台としては使えない。"}, "sentence_index": 0, "correct_answer": "プラットホーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ってきたので、プラットホームを広げて歩いた。", "explanation": "ここは〈傘〉の意味。傘は広げて使うものだが、平らな台のプラットホームは広げられない。"}, {"text": "寒かったので、プラットホームを体にかけて寝た。", "explanation": "ここは〈毛布〉の意味。毛布は体にかけるものだが、平らな台のプラットホームは体にかけて使えない。"}, {"text": "雨の日に、プラットホームをはいて出かけた。", "explanation": "ここは〈靴〉の意味。靴は足にはくものだが、平らな台のプラットホームははけない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プラットホーム", "is_correct": true, "explanation": "海に浮かぶ平らな台の意味に合い、機械を据える構造物として自然。"}, {"text": "トランク", "is_correct": false, "explanation": "旅行用の箱で、海に浮かぶ台にはならない。"}, {"text": "ポスター", "is_correct": false, "explanation": "紙の掲示物で、機械を置く台としては使えない。"}, {"text": "シャンデリア", "is_correct": false, "explanation": "天井から下がる照明器具で、海に浮かぶ台にはならない。"}], "explanations": {"プラットホーム": "海に浮かぶ平らな台の意味に合い、機械を据える構造物として自然。", "トランク": "旅行用の箱で、海に浮かぶ台にはならない。", "ポスター": "紙の掲示物で、機械を置く台としては使えない。", "シャンデリア": "天井から下がる照明器具で、海に浮かぶ台にはならない。"}, "sentence_index": 6, "correct_answer": "プラットホーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道路の横に、大きなプラットホームを立てた。", "explanation": "ここは〈看板〉の意味。看板は立てて使うが、平らな台のプラットホームは立てては使えない。"}, {"text": "プラットホームを開けて部屋に入った。", "explanation": "ここは〈扉〉の意味。扉は開閉するものだが、平らな台のプラットホームは開けられない。"}, {"text": "プラットホームをくぐって中に入った。", "explanation": "ここは〈ゲート〉の意味。くぐれるのは門の形のものだけで、平らな台は通り抜けられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械を、丈夫なプラットホーム置いた。", "corrected_sentence": "機械を、丈夫なプラットホームに置いた。", "error_description": "助詞の欠落。「置く」の置き場所を表す「に」が抜けている。「に」を入れると「台の上に置く」の意味になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物は、平らなプラットホームのせておくと安心だ。", "corrected_sentence": "荷物は、平らなプラットホームにのせておくと安心だ。", "error_description": "助詞の欠落。「のせる」の着点を表す「に」が抜けている。「に」を入れると台の上にのせる意味になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
