INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52667, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "じぶんにあったように かわること。", "primary_collocate": null, "pronunciation": "あだぷてぃぶ", "ipa": "adaptibɯ", "syllable_count": 5, "sentences": [{"text": "アダプティブだ。", "target_word": "アダプティブ", "complexity_tier": "T1", "furigana": "アダプティブだ。", "sentence_source": "generated"}, {"text": "このゲームはアダプティブです。", "target_word": "アダプティブ", "complexity_tier": "T2", "furigana": "このゲームはアダプティブです。", "sentence_source": "generated"}, {"text": "アダプティブなアプリを使います。", "target_word": "アダプティブ", "complexity_tier": "T2", "furigana": "アダプティブなアプリを使[つか]います。", "sentence_source": "generated"}, {"text": "アダプティブに変わる機械だ。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブに変[か]わる機械[きかい]だ。", "sentence_source": "generated"}, {"text": "私に合うアダプティブな方法だ。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "私[わたし]に合[あ]うアダプティブな方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "アダプティブは便利です。", "target_word": "アダプティブ", "complexity_tier": "T2", "furigana": "アダプティブは便利[べんり]です。", "sentence_source": "generated"}, {"text": "アダプティブで便利だ。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブで便利[べんり]だ。", "sentence_source": "generated"}, {"text": "アプリはアダプティブに動く。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アプリはアダプティブに動[うご]く。", "sentence_source": "generated"}, {"text": "アダプティブなら、自分に合わせてくれる。", "target_word": "アダプティブ", "complexity_tier": "T4", "furigana": "アダプティブなら、自分[じぶん]に合[あ]わせてくれる。", "sentence_source": "generated"}, {"text": "アダプティブな授業を受けた。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブな授業[じゅぎょう]を受[う]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アダプティブな", "label": "活用"}, {"form": "アダプティブに", "label": "活用"}, {"form": "アダプティブラーニング", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 自分に合うように変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "自分に合うように変わる性質を表す語で、「アダプティブだ」と述べて正しい。"}, {"text": "走る", "is_correct": false, "explanation": "「走るだ」は文として成り立たず、性質を表す語の位置に入らない。"}, {"text": "眠い", "is_correct": false, "explanation": "「眠いだ」は形容詞を断定の形にできず、文として成り立たない。"}, {"text": "青い", "is_correct": false, "explanation": "「青いだ」は形容詞の終止形に「だ」は付かず、文として成り立たない。"}], "explanations": {"アダプティブ": "自分に合うように変わる性質を表す語で、「アダプティブだ」と述べて正しい。", "走る": "「走るだ」は文として成り立たず、性質を表す語の位置に入らない。", "眠い": "「眠いだ」は形容詞を断定の形にできず、文として成り立たない。", "青い": "「青いだ」は形容詞の終止形に「だ」は付かず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "アダプティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このバッグはアダプティブで、何年使っても壊れない。", "explanation": "ここは〈丈夫〉の意味。アダプティブは自分に合わせて変わる性質で、壊れにくさは指さないので合わない。"}, {"text": "この器はアダプティブなので、職人が一つずつ手で仕上げている。", "explanation": "ここは〈手作り〉の意味。アダプティブは自分に合わせて変わる性質で、職人が手で仕上げる作り方は指さないので合わない。"}, {"text": "この模試はアダプティブに作られていて、どの会場でも同じ問題が出る。", "explanation": "ここは〈標準化〉の意味。アダプティブは自分に合わせて変わる性質で、どの会場でも同じ問題を出す標準化とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "自分に合うように変わる性質を表す語で、「アダプティブで便利だ」と正しく述べる。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べるで便利だ」は動詞の終止形に「で」が続かず、文が成り立たない。"}, {"text": "遠い", "is_correct": false, "explanation": "「遠いで便利だ」は形容詞に「で」を続けられず、文が成り立たない。"}, {"text": "読む", "is_correct": false, "explanation": "「読むで便利だ」は動詞の終止形に「で」が続かず、文として成り立たない。"}], "explanations": {"アダプティブ": "自分に合うように変わる性質を表す語で、「アダプティブで便利だ」と正しく述べる。", "食べる": "「食べるで便利だ」は動詞の終止形に「で」が続かず、文が成り立たない。", "遠い": "「遠いで便利だ」は形容詞に「で」を続けられず、文が成り立たない。", "読む": "「読むで便利だ」は動詞の終止形に「で」が続かず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "アダプティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この機能はアダプティブなので、必要な人だけ後から付けられる。", "explanation": "ここは〈オプション〉の意味。アダプティブは自分に合わせて変わる性質で、後から選んで付ける任意の項目は指さないので合わない。"}, {"text": "このアプリはアダプティブで、ボタン一つで起動できる。", "explanation": "ここは〈ワンタッチ〉の意味。アダプティブは自分に合わせて変わる性質で、操作の手軽さは指さないので合わない。"}, {"text": "このシステムはアダプティブで、離れた場所から操作できる。", "explanation": "ここは〈リモート〉の意味。アダプティブは自分に合わせて変わる性質で、遠隔からの操作は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52667, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業は生徒の力に合わせてアダプティブな変わる。", "corrected_sentence": "授業は生徒の力に合わせてアダプティブに変わる。", "error_description": "「アダプティブ」は形状詞なので、動詞「変わる」を修飾するには「に」が必要。「な」は名詞の前に付く形で誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "文中の形は語幹「アダプティブ」。「です」が続くので語幹のままで正しい。"}, {"text": "アダプティブな", "is_correct": false, "explanation": "「な」は連体形で名詞の前に置く形なので、「です」の前には置けない。"}, {"text": "アダプティブに", "is_correct": false, "explanation": "「に」は連用形で動詞や形容詞を修飾する形なので、「です」の前には来ない。"}, {"text": "アダプティブだ", "is_correct": false, "explanation": "「だ」は常体の断定なので、「です」と重ねると誤りになる。"}], "correct_form": "アダプティブ", "base_form": "アダプティブ", "form_label": "語幹＋です", "sentence_index": 1, "explanations": {"アダプティブ": "文中の形は語幹「アダプティブ」。「です」が続くので語幹のままで正しい。", "アダプティブな": "「な」は連体形で名詞の前に置く形なので、「です」の前には置けない。", "アダプティブに": "「に」は連用形で動詞や形容詞を修飾する形なので、「です」の前には来ない。", "アダプティブだ": "「だ」は常体の断定なので、「です」と重ねると誤りになる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52667, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は自分の使い方に合わせてアダプティブだ動く。", "corrected_sentence": "この機械は自分の使い方に合わせてアダプティブに動く。", "error_description": "「アダプティブ」は形状詞なので、動詞「動く」を修飾するには「に」が必要。「だ」は述語の形で動詞の前には置けず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "アダプティブに", "is_correct": true, "explanation": "文中の形は連用形「アダプティブに」。動詞「動く」を修飾するので正しい。"}, {"text": "アダプティブな", "is_correct": false, "explanation": "「な」は連体形で名詞の前に置く形なので、動詞「動く」の前では成り立たない。"}, {"text": "アダプティブです", "is_correct": false, "explanation": "「です」は丁寧な断定の形で文を終えるので、動詞「動く」の前には置けない。"}, {"text": "アダプティブだった", "is_correct": false, "explanation": "「だった」は過去の断定の形で、動詞を修飾できないので誤り。"}], "correct_form": "アダプティブに", "base_form": "アダプティブ", "form_label": "連用形（動詞修飾）", "sentence_index": 7, "explanations": {"アダプティブに": "文中の形は連用形「アダプティブに」。動詞「動く」を修飾するので正しい。", "アダプティブな": "「な」は連体形で名詞の前に置く形なので、動詞「動く」の前では成り立たない。", "アダプティブです": "「です」は丁寧な断定の形で文を終えるので、動詞「動く」の前には置けない。", "アダプティブだった": "「だった」は過去の断定の形で、動詞を修飾できないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
