INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52668, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "状況や学習者の能力に応じて、自動的に調整・最適化される性質を持つこと。特に、教育や技術の分野で用いられる。", "primary_collocate": null, "pronunciation": "あだぷてぃぶ", "ipa": "adaptibɯ", "syllable_count": 5, "sentences": [{"text": "その教材はアダプティブで、学習者の力に応じて難しさを変える。", "target_word": "アダプティブ", "complexity_tier": "T4", "furigana": "その教材[きょうざい]はアダプティブで、学習者[がくしゅうしゃ]の力[ちから]に応[おう]じて難[むずか]しさを変[か]える。", "sentence_source": "generated"}, {"text": "この教材はアダプティブです。", "target_word": "アダプティブ", "complexity_tier": "T2", "furigana": "この教材[きょうざい]はアダプティブです。", "sentence_source": "generated"}, {"text": "このアプリはアダプティブだ。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "このアプリはアダプティブだ。", "sentence_source": "generated"}, {"text": "アダプティブに難しさが変わる。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブに難[むずか]しさが変[か]わる。", "sentence_source": "generated"}, {"text": "アダプティブな学習が人気です。", "target_word": "アダプティブ", "complexity_tier": "T2", "furigana": "アダプティブな学習[がくしゅう]が人気[にんき]です。", "sentence_source": "generated"}, {"text": "アダプティブな仕組みを導入した。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブな仕組[しく]みを導入[どうにゅう]した。", "sentence_source": "generated"}, {"text": "アダプティブであれば、個人に合わせられる。", "target_word": "アダプティブ", "complexity_tier": "T4", "furigana": "アダプティブであれば、個人[こじん]に合[あ]わせられる。", "sentence_source": "generated"}, {"text": "画面はアダプティブに切り替わる。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "画面[がめん]はアダプティブに切[き]り替[か]わる。", "sentence_source": "generated"}, {"text": "アダプティブなテストを受けた。", "target_word": "アダプティブ", "complexity_tier": "T3", "furigana": "アダプティブなテストを受[う]けた。", "sentence_source": "generated"}, {"text": "学習者の力に応じて、アダプティブに出題する方法が広まっている。", "target_word": "アダプティブ", "complexity_tier": "T5", "furigana": "学習者[がくしゅうしゃ]の力[ちから]に応[おう]じて、アダプティブに出題[しゅつだい]する方法[ほうほう]が広[ひろ]まっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アダプティブな", "label": "活用"}, {"form": "アダプティブに", "label": "活用"}, {"form": "アダプティブラーニング", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 状況や能力に応じて自動調整される性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "状況に応じて調整される性質を表す語で、「アダプティブで、」と続けて正しい。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べるで、」は動詞の終止形に「で」が続かず、文が成り立たない。"}, {"text": "遠い", "is_correct": false, "explanation": "「遠いで、」は形容詞に「で」を続けられず、文が成り立たない。"}, {"text": "読む", "is_correct": false, "explanation": "「読むで、」は動詞の終止形に「で」が続かず、文として成り立たない。"}], "explanations": {"アダプティブ": "状況に応じて調整される性質を表す語で、「アダプティブで、」と続けて正しい。", "食べる": "「食べるで、」は動詞の終止形に「で」が続かず、文が成り立たない。", "遠い": "「遠いで、」は形容詞に「で」を続けられず、文が成り立たない。", "読む": "「読むで、」は動詞の終止形に「で」が続かず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "アダプティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机はアダプティブで、何年使っても傷一つ付かない。", "explanation": "ここは〈丈夫〉の意味。アダプティブは状況に応じて変わる性質で、傷のつきにくさは指さないので合わない。"}, {"text": "このサービスはアダプティブなので、希望者だけ後から申し込める。", "explanation": "ここは〈オプション〉の意味。アダプティブは自動的に調整される性質で、追加で選べる任意の項目は指さないので合わない。"}, {"text": "この部品はアダプティブなので、一個十円で買える。", "explanation": "ここは〈安価〉の意味。アダプティブは状況に応じて変わる性質で、値段の安さは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "状況や能力に応じて調整される性質を表す語で、「アダプティブであれば」と条件を述べて正しい。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べるであれば」は成り立たず、性質を表す語の位置に入らない。"}, {"text": "走る", "is_correct": false, "explanation": "「走るであれば」は文として成り立たず、条件を表す語にならない。"}, {"text": "青い", "is_correct": false, "explanation": "「青いであれば」は形容詞が条件の名詞として働けず、文が成り立たない。"}], "explanations": {"アダプティブ": "状況や能力に応じて調整される性質を表す語で、「アダプティブであれば」と条件を述べて正しい。", "食べる": "「食べるであれば」は成り立たず、性質を表す語の位置に入らない。", "走る": "「走るであれば」は文として成り立たず、条件を表す語にならない。", "青い": "「青いであれば」は形容詞が条件の名詞として働けず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "アダプティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この検定はアダプティブに作られていて、受験者全員に同じ問題が出る。", "explanation": "ここは〈標準化〉の意味。アダプティブは受験者に合わせて出題が変わる性質で、全員に同じ問題を出す標準化とは違うので合わない。"}, {"text": "このアプリはアダプティブで、ボタン一つで起動できる。", "explanation": "ここは〈ワンタッチ〉の意味。アダプティブは状況に応じて変わる性質で、操作の手軽さは指さないので合わない。"}, {"text": "このシステムはアダプティブで、離れた場所から操作できる。", "explanation": "ここは〈リモート〉の意味。アダプティブは状況に応じて変わる性質で、遠隔からの操作は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52668, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テストの難しさに応じて、アダプティブだ出題するシステムが増えている。", "corrected_sentence": "テストの難しさに応じて、アダプティブに出題するシステムが増えている。", "error_description": "「アダプティブ」は形状詞なので、動詞「出題する」を修飾するには連用形「に」が必要。「だ」は述語の形で動詞の前には置けず誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "アダプティブ", "is_correct": true, "explanation": "文中の形は語幹「アダプティブ」。「です」が続くので語幹のままで正しい。"}, {"text": "アダプティブな", "is_correct": false, "explanation": "「な」は連体形で名詞の前に置く形なので、「です」の前には置けない。"}, {"text": "アダプティブに", "is_correct": false, "explanation": "「に」は連用形で動詞や形容詞を修飾する形なので、「です」の前には来ない。"}, {"text": "アダプティブだ", "is_correct": false, "explanation": "「だ」は常体の断定なので、「です」と重ねると「アダプティブだです」となり誤り。"}], "correct_form": "アダプティブ", "base_form": "アダプティブ", "form_label": "語幹＋です", "sentence_index": 1, "explanations": {"アダプティブ": "文中の形は語幹「アダプティブ」。「です」が続くので語幹のままで正しい。", "アダプティブな": "「な」は連体形で名詞の前に置く形なので、「です」の前には置けない。", "アダプティブに": "「に」は連用形で動詞や形容詞を修飾する形なので、「です」の前には来ない。", "アダプティブだ": "「だ」は常体の断定なので、「です」と重ねると「アダプティブだです」となり誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52668, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アダプティブだ教材を使っている。", "corrected_sentence": "アダプティブな教材を使っている。", "error_description": "「アダプティブ」は形状詞なので、名詞「教材」を修飾するには「な」が必要。「だ」は述語の形で名詞の前には置けず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "アダプティブに", "is_correct": true, "explanation": "文中の形は連用形「アダプティブに」。動詞「切り替わる」を修飾するので正しい。"}, {"text": "アダプティブだった", "is_correct": false, "explanation": "「だった」は過去の断定で、動詞「切り替わる」を修飾できない。"}, {"text": "アダプティブではない", "is_correct": false, "explanation": "「ではない」は否定の述語で、動詞を修飾する形ではない。"}, {"text": "アダプティブな", "is_correct": false, "explanation": "「な」は連体形で名詞の前に置く形なので、動詞「切り替わる」の前では成り立たない。"}], "correct_form": "アダプティブに", "base_form": "アダプティブ", "form_label": "連用形（動詞修飾）", "sentence_index": 7, "explanations": {"アダプティブに": "文中の形は連用形「アダプティブに」。動詞「切り替わる」を修飾するので正しい。", "アダプティブだった": "「だった」は過去の断定で、動詞「切り替わる」を修飾できない。", "アダプティブではない": "「ではない」は否定の述語で、動詞を修飾する形ではない。", "アダプティブな": "「な」は連体形で名詞の前に置く形なので、動詞「切り替わる」の前では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「集まった」の主語を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「取材陣を駅に集まった」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「取材陣の駅に集まった」は主語がなく成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「取材陣に駅に集まった」は文法的に成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「集まった」の主語を示す「が」が入る。", "を": "「取材陣を駅に集まった」は文法的に成り立たない。", "の": "「取材陣の駅に集まった」は主語がなく成り立たない。", "に": "「取材陣に駅に集まった」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "の": "possessive_misuse", "に": "target_marker_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かき分ける」の対象を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「報道陣にかき分けて」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「報道陣のかき分けて」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「報道陣とかき分けて」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「かき分ける」の対象を示す「を」が入る。", "に": "「報道陣にかき分けて」は文法的に成り立たない。", "の": "「報道陣のかき分けて」は文法的に成り立たない。", "と": "「報道陣とかき分けて」は文法的に成り立たない。"}, "error_tags": {"に": "target_marker_misuse", "の": "possessive_misuse", "と": "comitative_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "concrete", "definition": "たくさんの人が集まって、一つのグループになったもの。", "primary_collocate": null, "pronunciation": "じん", "ipa": "dʑiɴ", "syllable_count": 2, "sentences": [{"text": "報道陣が来た。", "target_word": "報道陣", "complexity_tier": "T1", "furigana": "報道陣[ほうどうじん]が来[き]た。", "sentence_source": "generated"}, {"text": "取材陣が駅に集まった。", "target_word": "取材陣", "complexity_tier": "T2", "furigana": "取材陣[しゅざいじん]が駅[えき]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "報道陣は何も聞けなかった。", "target_word": "報道陣", "complexity_tier": "T2", "furigana": "報道陣[ほうどうじん]は何[なに]も聞[き]けなかった。", "sentence_source": "generated"}, {"text": "空港で報道陣に囲まれた。", "target_word": "報道陣", "complexity_tier": "T3", "furigana": "空港[くうこう]で報道陣[ほうどうじん]に囲[かこ]まれた。", "sentence_source": "generated"}, {"text": "応援陣の声が球場に響いた。", "target_word": "応援陣", "complexity_tier": "T3", "furigana": "応援陣[おうえんじん]の声[こえ]が球場[きゅうじょう]に響[ひび]いた。", "sentence_source": "generated"}, {"text": "取材陣の前で社長が頭を下げた。", "target_word": "取材陣", "complexity_tier": "T3", "furigana": "取材陣[しゅざいじん]の前[まえ]で社長[しゃちょう]が頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "事故の現場には、多くの報道陣が詰めかけていた。", "target_word": "報道陣", "complexity_tier": "T4", "furigana": "事故[じこ]の現場[げんば]には、多[おお]くの報道陣[ほうどうじん]が詰[つ]めかけていた。", "sentence_source": "generated"}, {"text": "彼は報道陣をかき分けて車に乗り込んだ。", "target_word": "報道陣", "complexity_tier": "T4", "furigana": "彼[かれ]は報道陣[ほうどうじん]をかき分[わ]けて車[くるま]に乗[の]り込[こ]んだ。", "sentence_source": "generated"}, {"text": "記者会見が始まる前から、会場の外は取材陣でいっぱいだった。", "target_word": "取材陣", "complexity_tier": "T5", "furigana": "記者会見[きしゃかいけん]が始[はじ]まる前[まえ]から、会場[かいじょう]の外[そと]は取材陣[しゅざいじん]でいっぱいだった。", "sentence_source": "generated"}, {"text": "警備陣が入口を守る。", "target_word": "警備陣", "complexity_tier": "T2", "furigana": "警備陣[けいびじん]が入口[いりぐち]を守[まも]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "報道陣", "label": "派生"}, {"form": "取材陣", "label": "派生"}, {"form": "応援陣", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 集まった人々の一団を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: かき分け (Zipf 2.46)']::text[], 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陣", "is_correct": true, "explanation": "「じん」と読む正解の語。"}, {"text": "心", "is_correct": false, "explanation": "「しん」で、「じ」が「し」に変わる一音違い。"}, {"text": "銀", "is_correct": false, "explanation": "「ぎん」で、最初の一音だけが違う。"}, {"text": "金", "is_correct": false, "explanation": "「きん」で、最初の一音だけが違う。"}, {"text": "賃", "is_correct": false, "explanation": "「ちん」で、最初の一音だけが違う。"}, {"text": "民", "is_correct": false, "explanation": "「みん」で、最初の一音だけが違う。"}], "explanations": {"陣": "「じん」と読む正解の語。", "心": "「しん」で、「じ」が「し」に変わる一音違い。", "銀": "「ぎん」で、最初の一音だけが違う。", "金": "「きん」で、最初の一音だけが違う。", "賃": "「ちん」で、最初の一音だけが違う。", "民": "「みん」で、最初の一音だけが違う。"}, "sentence_index": null, "correct_answer": "陣"}, "level_3": {"options": [{"text": "報道陣", "is_correct": true, "explanation": "記者たちの集団が来たという意味で自然。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、「値段が来た」は意味が合わない。"}, {"text": "規則", "is_correct": false, "explanation": "形は合うが、「規則が来た」は意味が合わない。"}, {"text": "勉強", "is_correct": false, "explanation": "形は合うが、「勉強が来た」は意味が合わない。"}], "explanations": {"報道陣": "記者たちの集団が来たという意味で自然。", "値段": "形は合うが、「値段が来た」は意味が合わない。", "規則": "形は合うが、「規則が来た」は意味が合わない。", "勉強": "形は合うが、「勉強が来た」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "報道陣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "報道陣が記者会見で新しい方針を発表した。", "explanation": "ここは〈報道官〉（政府などの発表を担当する一人の人）の意味。報道陣は取材する記者たちの集まりなので、発表する立場ではない。"}, {"text": "報道陣が一人だけ椅子に座っている。", "explanation": "ここは〈個人〉（記者一人）の意味で使っている。報道陣は多くの人の集まりを指すので、一人だけを指すとは言えない。"}, {"text": "その報道陣を新聞に掲載して、読者に伝えた。", "explanation": "ここは〈記事〉（新聞に載る文章）の意味。報道陣は記者たちの集まりなので、新聞に掲載するものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "陣", "is_correct": true, "explanation": "「じん」と読む正解の語。"}, {"text": "瓶", "is_correct": false, "explanation": "「びん」で、最初の一音だけが違う。"}, {"text": "輪", "is_correct": false, "explanation": "「りん」で、最初の一音だけが違う。"}, {"text": "缶", "is_correct": false, "explanation": "「かん」で、最初の一音だけが違う。"}, {"text": "品", "is_correct": false, "explanation": "「ひん」で、最初の一音だけが違う。"}, {"text": "天", "is_correct": false, "explanation": "「てん」で、最初の一音だけが違う。"}], "explanations": {"陣": "「じん」と読む正解の語。", "瓶": "「びん」で、最初の一音だけが違う。", "輪": "「りん」で、最初の一音だけが違う。", "缶": "「かん」で、最初の一音だけが違う。", "品": "「ひん」で、最初の一音だけが違う。", "天": "「てん」で、最初の一音だけが違う。"}, "sentence_index": null, "correct_answer": "陣"}, "level_3": {"options": [{"text": "報道陣", "is_correct": true, "explanation": "事故現場に詰めかけるのは記者の集団で意味が合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「季節が詰めかける」は意味が合わない。"}, {"text": "資料", "is_correct": false, "explanation": "形は合うが、「資料が詰めかける」は意味が合わない。"}, {"text": "弁当", "is_correct": false, "explanation": "「弁当が詰めかけていた」は物が人のように集まるとは言えず、意味が通らない。"}], "explanations": {"報道陣": "事故現場に詰めかけるのは記者の集団で意味が合う。", "季節": "形は合うが、「季節が詰めかける」は意味が合わない。", "資料": "形は合うが、「資料が詰めかける」は意味が合わない。", "弁当": "「弁当が詰めかけていた」は物が人のように集まるとは言えず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "報道陣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警備陣が事件の捜査を始めた。", "explanation": "ここは〈警察〉（事件を捜査する組織）の意味。警備陣は施設などを守る人たちなので、捜査は担当しない。"}, {"text": "警備陣が大声で声援を送った。", "explanation": "ここは〈応援団〉（声援を送る集団）の意味。警備陣は安全を守る人たちなので、声援を送る役割にはならない。"}, {"text": "警備陣は一人で門を守っている。", "explanation": "ここは〈警備員〉（一人の警備員）の意味。警備陣は複数の人の集団を指すので、一人で守るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "報道陣が一人で空港に来た。", "corrected_sentence": "報道陣が大勢で空港に来た。", "error_description": "「報道陣」は多くの人の集まりなので、「一人で」は合わない。「大勢で」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52669, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日の応援陣は晴れだ。", "corrected_sentence": "今日の天気は晴れだ。", "error_description": "「応援陣」は人の集団で天気を表さない。「天気」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
