INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「期待をかける」の対象を示す「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「首脳陣を」では後ろの「期待をかけている」とつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「首脳陣の、国民は」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「首脳陣で、国民は期待をかける」は対象を示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「期待をかける」の対象を示す「に」が入る。", "を": "「首脳陣を」では後ろの「期待をかけている」とつながらない。", "の": "「首脳陣の、国民は」は文として成り立たない。", "で": "「首脳陣で、国民は期待をかける」は対象を示せず不自然。"}, "error_tags": {"を": "object_marker_misuse", "の": "possessive_misuse", "で": "location_means_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "concrete", "definition": "ある目的のために組織された、複数の人々の集まり。特に、専門的な知識や役割を持つ人々の集団。", "primary_collocate": null, "pronunciation": "じん", "ipa": "dʑiɴ", "syllable_count": 2, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "教授陣", "complexity_tier": "T6", "furigana": "大学[だいがく]教育[きょういく]の現場[げんば]において、教授陣[きょうじゅじん]が個々[ここ]の学修[がくしゅう]到達度[とうたつど]を最大化[さいだいか]するためにこのシステムを如何[いかん]に設計[せっけい]し、運用[うんよう]するかが問[と]われているのである。", "sentence_source": "mined"}, {"text": "経営陣が新しい計画を発表した。", "target_word": "経営陣", "complexity_tier": "T2", "furigana": "経営陣[けいえいじん]が新[あたら]しい計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "医師陣は毎日会議をする。", "target_word": "医師陣", "complexity_tier": "T2", "furigana": "医師陣[いしじん]は毎日[まいにち]会議[かいぎ]をする。", "sentence_source": "generated"}, {"text": "開発陣の努力で、製品が完成した。", "target_word": "開発陣", "complexity_tier": "T3", "furigana": "開発陣[かいはつじん]の努力[どりょく]で、製品[せいひん]が完成[かんせい]した。", "sentence_source": "generated"}, {"text": "この学校は教授陣がとても豪華だ。", "target_word": "教授陣", "complexity_tier": "T3", "furigana": "この学校[がっこう]は教授陣[きょうじゅじん]がとても豪華[ごうか]だ。", "sentence_source": "generated"}, {"text": "執筆陣には有名な作家が何人も入っている。", "target_word": "執筆陣", "complexity_tier": "T3", "furigana": "執筆陣[しっぴつじん]には有名[ゆうめい]な作家[さっか]が何人[なんにん]も入[はい]っている。", "sentence_source": "generated"}, {"text": "講師陣を紹介する。", "target_word": "講師陣", "complexity_tier": "T2", "furigana": "講師陣[こうしじん]を紹介[しょうかい]する。", "sentence_source": "generated"}, {"text": "新しい首脳陣に、国民は大きな期待をかけている。", "target_word": "首脳陣", "complexity_tier": "T4", "furigana": "新[あたら]しい首脳陣[しゅのうじん]に、国民[こくみん]は大[おお]きな期待[きたい]をかけている。", "sentence_source": "generated"}, {"text": "監督と投手陣が来年の計画を話し合った。", "target_word": "投手陣", "complexity_tier": "T3", "furigana": "監督[かんとく]と投手陣[とうしゅじん]が来年[らいねん]の計画[けいかく]を話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "教授陣の指導のおかげで、学生たちは自信を持って発表できた。", "target_word": "教授陣", "complexity_tier": "T4", "furigana": "教授陣[きょうじゅじん]の指導[しどう]のおかげで、学生[がくせい]たちは自信[じしん]を持[も]って発表[はっぴょう]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "経営陣", "label": "派生"}, {"form": "教授陣", "label": "派生"}, {"form": "執筆陣", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 専門家の集団を表す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教授陣", "is_correct": true, "explanation": "大学教育の設計と運用を担う専門家の集団なので意味が合う。"}, {"text": "報道陣", "is_correct": false, "explanation": "形は合うが、報道関係者が学修システムを設計するのは意味が合わない。"}, {"text": "応援陣", "is_correct": false, "explanation": "形は合うが、応援団が教育システムを設計するのは意味が合わない。"}, {"text": "警備陣", "is_correct": false, "explanation": "形は合うが、警備担当者が学修到達度を扱うのは意味が合わない。"}], "explanations": {"教授陣": "大学教育の設計と運用を担う専門家の集団なので意味が合う。", "報道陣": "形は合うが、報道関係者が学修システムを設計するのは意味が合わない。", "応援陣": "形は合うが、応援団が教育システムを設計するのは意味が合わない。", "警備陣": "形は合うが、警備担当者が学修到達度を扱うのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "教授陣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一人の開発陣として、一人で製品を完成させた。", "explanation": "ここは〈開発者〉（一人の技術者）の意味で使っている。開発陣は複数の人の集団を指すので、一人は表せない。"}, {"text": "会社は新しい市場に開発陣を張り、拠点を広げた。", "explanation": "「陣を張る」は陣地（構えを置く場所）の意味で使う表現。〈陣地〉と混同しているが、開発陣は人の集団なので場所の構えにはならない。"}, {"text": "この製品はまだ開発陣だ。", "explanation": "ここは〈開発中〉（作っている途中の状態）の意味。開発陣は人の集団なので、製品の状態は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "講師陣", "is_correct": true, "explanation": "講師の集団を紹介するので意味が合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが、「渋滞を紹介する」は意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「地震を紹介する」は意味が合わない。"}, {"text": "頭痛", "is_correct": false, "explanation": "形は合うが、「頭痛を紹介する」は意味が合わない。"}], "explanations": {"講師陣": "講師の集団を紹介するので意味が合う。", "渋滞": "形は合うが、「渋滞を紹介する」は意味が合わない。", "地震": "形は合うが、「地震を紹介する」は意味が合わない。", "頭痛": "形は合うが、「頭痛を紹介する」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "講師陣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教授陣という一人の先生が、私を丁寧に指導してくれた。", "explanation": "ここは〈教授〉（一人の大学教員）の意味で使っている。教授陣は複数の教授の集団を指すので、一人は表せない。"}, {"text": "私は将来、小学校の教授陣になりたい。", "explanation": "ここは〈教師〉（小学校で教える人）の意味で使っている。教授陣は大学の教授の集団なので、小学校には合わない。"}, {"text": "父は小学校の教授陣として働いている。", "explanation": "ここは〈教師〉の意味。教授は大学の職位なので、小学校の教員の集団には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "講師陣が一人で授業をした。", "corrected_sentence": "講師が一人で授業をした。", "error_description": "「講師陣」は複数の講師の集団なので、「一人で」とは使えない。「講師」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52670, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人の首脳陣が会議を開いた。", "corrected_sentence": "首脳陣が会議を開いた。", "error_description": "「首脳陣」は複数の人の集団なので「一人の」とは合わない。「一人の」を外す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「励む」の対象を示す「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「励む」は「学修を励む」の形では使わない。"}, {"text": "が", "is_correct": false, "explanation": "「学修が励んでいます」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「学修の励んでいます」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「励む」の対象を示す「に」が入る。", "を": "「励む」は「学修を励む」の形では使わない。", "が": "「学修が励んでいます」は文法的に成り立たない。", "の": "「学修の励んでいます」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "subject_marker_misuse", "の": "possessive_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「終える」の目的語を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「学修が終えて」は他動詞に合わず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「学修に終えて」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「学修の終えて」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「終える」の目的語を示す「を」が入る。", "が": "「学修が終えて」は他動詞に合わず成り立たない。", "に": "「学修に終えて」は文法的に成り立たない。", "の": "「学修の終えて」は文法的に成り立たない。"}, "error_tags": {"が": "subject_object_confusion", "に": "target_marker_misuse", "の": "possessive_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "学校で勉強すること", "primary_collocate": null, "pronunciation": "がくしゅう", "ipa": "ɡakɯɕɯː", "syllable_count": 4, "sentences": [{"text": "学修が始まる。", "target_word": "学修", "complexity_tier": "T1", "furigana": "学修[がくしゅう]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "毎日、学修に励んでいます。", "target_word": "学修", "complexity_tier": "T2", "furigana": "毎日[まいにち]、学修[がくしゅう]に励[はげ]んでいます。", "sentence_source": "generated"}, {"text": "学修は楽しいです。", "target_word": "学修", "complexity_tier": "T2", "furigana": "学修[がくしゅう]は楽[たの]しいです。", "sentence_source": "generated"}, {"text": "兄は大学で学修を続けている。", "target_word": "学修", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]で学修[がくしゅう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "学修の場所は図書館です。", "target_word": "学修", "complexity_tier": "T2", "furigana": "学修[がくしゅう]の場所[ばしょ]は図書館[としょかん]です。", "sentence_source": "generated"}, {"text": "学修に必要な本を買った。", "target_word": "学修", "complexity_tier": "T3", "furigana": "学修[がくしゅう]に必要[ひつよう]な本[ほん]を買[か]った。", "sentence_source": "generated"}, {"text": "学修が進まないときは、少し休むといい。", "target_word": "学修", "complexity_tier": "T4", "furigana": "学修[がくしゅう]が進[すす]まないときは、少[すこ]し休[やす]むといい。", "sentence_source": "generated"}, {"text": "学校での学修を終えて、彼は仕事を探し始めた。", "target_word": "学修", "complexity_tier": "T4", "furigana": "学校[がっこう]での学修[がくしゅう]を終[お]えて、彼[かれ]は仕事[しごと]を探[さが]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "学修について先生に相談した。", "target_word": "学修", "complexity_tier": "T3", "furigana": "学修[がくしゅう]について先生[せんせい]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "学修を通して、友だちの大切さも学んだ。", "target_word": "学修", "complexity_tier": "T4", "furigana": "学修[がくしゅう]を通[とお]して、友[とも]だちの大切[たいせつ]さも学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学修する", "label": "活用"}, {"form": "学修者", "label": "派生"}, {"form": "学修課程", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 学校で授業を受けて勉強すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学修", "is_correct": true, "explanation": "学校での勉強が始まるという意味で自然。"}, {"text": "合格", "is_correct": false, "explanation": "形は合うが、「合格が始まる」は意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、「卒業が始まる」は意味が合わない。"}, {"text": "退学", "is_correct": false, "explanation": "形は合うが、「退学が始まる」は意味が合わない。"}], "explanations": {"学修": "学校での勉強が始まるという意味で自然。", "合格": "形は合うが、「合格が始まる」は意味が合わない。", "卒業": "形は合うが、「卒業が始まる」は意味が合わない。", "退学": "形は合うが、「退学が始まる」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "学修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は大学で学修の店を開いている。", "explanation": "ここは〈店〉（商品を売る場所）の意味。学修は学ぶ行為なので、店として開けるものではない。"}, {"text": "兄は大学で学修の車を買って、毎日運転している。", "explanation": "ここは〈車〉（運転する乗り物）の意味。学修は行為なので、運転できる物ではない。"}, {"text": "兄は大学で学修の紙を三枚、財布に入れている。", "explanation": "ここは〈紙幣〉（財布に入れる物）の意味。学修は行為なので、財布に入れられる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学修", "is_correct": true, "explanation": "勉強が進まないときは休むという意味で自然。"}, {"text": "合格", "is_correct": false, "explanation": "形は合うが、「合格が進まない」は意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、「気温が進まない」は意味が合わない。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが、「身長が進まない」は意味が合わない。"}], "explanations": {"学修": "勉強が進まないときは休むという意味で自然。", "合格": "形は合うが、「合格が進まない」は意味が合わない。", "気温": "形は合うが、「気温が進まない」は意味が合わない。", "身長": "形は合うが、「身長が進まない」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "学修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生から学修を出されて、今夜中に提出した。", "explanation": "ここは〈課題〉（先生が出す宿題）の意味。学修は行為なので、出されるものではない。"}, {"text": "学修を借りて、図書館に返した。", "explanation": "ここは〈本〉（借りて返す物）の意味。学修は行為なので、借りて返せる物ではない。"}, {"text": "学修で予算を決めた。", "explanation": "ここは〈会議〉（決定を行う場）の意味。学修は学ぶ行為なので、予算を決める場にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は学校で学修を飲んでいる。", "corrected_sentence": "兄は学校で学修を続けている。", "error_description": "「学修」は勉強する行為なので「飲む」とは使えない。「続ける」などにする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
