INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「学修の成果」と名詞をつなぐ「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「学修を成果は」は文法的に成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「学修が成果は」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「学修に成果は」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「学修の成果」と名詞をつなぐ「の」が入る。", "を": "「学修を成果は」は文法的に成り立たない。", "が": "「学修が成果は」は文法的に成り立たない。", "に": "「学修に成果は」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "subject_marker_misuse", "に": "target_marker_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "学問や技術を自分から進んで学び、身につけること。特に、大学などの教育機関で行う自発的な学習を指す。", "primary_collocate": null, "pronunciation": "がくしゅう", "ipa": "ɡakɯɕɯː", "syllable_count": 4, "sentences": [{"text": "授業の後も、毎日二時間、学修の時間を取っている。", "target_word": "学修", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の後[あと]も、毎日[まいにち]二時間[にじかん]、学修[がくしゅう]の時間[じかん]を取[と]っている。", "sentence_source": "generated"}, {"text": "学修の記録をつけます。", "target_word": "学修", "complexity_tier": "T2", "furigana": "学修[がくしゅう]の記録[きろく]をつけます。", "sentence_source": "generated"}, {"text": "大学では主体的な学修が求められる。", "target_word": "学修", "complexity_tier": "T3", "furigana": "大学[だいがく]では主体的[しゅたいてき]な学修[がくしゅう]が求[もと]められる。", "sentence_source": "generated"}, {"text": "学修の時間が足りないと感じている。", "target_word": "学修", "complexity_tier": "T3", "furigana": "学修[がくしゅう]の時間[じかん]が足[た]りないと感[かん]じている。", "sentence_source": "generated"}, {"text": "先生は学生の学修を支援している。", "target_word": "学修", "complexity_tier": "T3", "furigana": "先生[せんせい]は学生[がくせい]の学修[がくしゅう]を支援[しえん]している。", "sentence_source": "generated"}, {"text": "学修を計画的に進めた。", "target_word": "学修", "complexity_tier": "T2", "furigana": "学修[がくしゅう]を計画的[けいかくてき]に進[すす]めた。", "sentence_source": "generated"}, {"text": "自分で目標を決めて学修を進める習慣をつけたい。", "target_word": "学修", "complexity_tier": "T4", "furigana": "自分[じぶん]で目標[もくひょう]を決[き]めて学修[がくしゅう]を進[すす]める習慣[しゅうかん]をつけたい。", "sentence_source": "generated"}, {"text": "学修の成果は、試験だけでなく発表でも評価される。", "target_word": "学修", "complexity_tier": "T4", "furigana": "学修[がくしゅう]の成果[せいか]は、試験[しけん]だけでなく発表[はっぴょう]でも評価[ひょうか]される。", "sentence_source": "generated"}, {"text": "毎日の学修が力になる。", "target_word": "学修", "complexity_tier": "T3", "furigana": "毎日[まいにち]の学修[がくしゅう]が力[ちから]になる。", "sentence_source": "generated"}, {"text": "学修の成果を確かめるために、学生はレポートを書いた。", "target_word": "学修", "complexity_tier": "T4", "furigana": "学修[がくしゅう]の成果[せいか]を確[たし]かめるために、学生[がくせい]はレポートを書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学修する", "label": "活用"}, {"form": "学修者", "label": "派生"}, {"form": "学修成果", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 大学で自発的に学び身につけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学修", "is_correct": true, "explanation": "学修の時間を取るという意味で自然。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、「気温の時間」は意味が合わない。"}, {"text": "天候", "is_correct": false, "explanation": "形は合うが、「天候の時間」は意味が合わない。"}, {"text": "合格", "is_correct": false, "explanation": "形は合うが、「合格の時間」は意味が合わない。"}], "explanations": {"学修": "学修の時間を取るという意味で自然。", "気温": "形は合うが、「気温の時間」は意味が合わない。", "天候": "形は合うが、「天候の時間」は意味が合わない。", "合格": "形は合うが、「合格の時間」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "学修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎週火曜日に学修を受けている。", "explanation": "ここは〈授業〉（先生が教える時間）の意味。学修は自分から学ぶ行為なので、受けるものとは言えない。"}, {"text": "毎晩、学修をつけてから寝ている。", "explanation": "ここは〈日記〉（書き留める文章）の意味。学修は学ぶ行為そのものなので、つけるものではない。"}, {"text": "昨日の学修に勝った。", "explanation": "ここは〈試合〉（勝ち負けを競う場）の意味。学修は勝負をする行為ではないので、勝つ対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学修", "is_correct": true, "explanation": "自分で目標を決めて進めるのは学びなので意味が合う。"}, {"text": "運賃", "is_correct": false, "explanation": "形は合うが、「運賃を進める」は意味が合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "形は合うが、「包丁を進める」は意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気を進める」は意味が合わない。"}], "explanations": {"学修": "自分で目標を決めて進めるのは学びなので意味が合う。", "運賃": "形は合うが、「運賃を進める」は意味が合わない。", "包丁": "形は合うが、「包丁を進める」は意味が合わない。", "天気": "形は合うが、「天気を進める」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "学修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話で学修を注文した。", "explanation": "ここは〈商品〉（注文して買う物）の意味。学修は学ぶ行為なので、注文して手に入れるものではない。"}, {"text": "学修を借りて、図書館に返した。", "explanation": "ここは〈本〉（借りて返す物）の意味。学修は行為なので、借りて返せる物ではない。"}, {"text": "学修で予算を決めた。", "explanation": "ここは〈会議〉（決定を行う場）の意味。学修は学ぶ行為なので、予算を決める場にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学修を食べて元気になった。", "corrected_sentence": "学修を続けて元気になった。", "error_description": "「学修」は学ぶ行為なので「食べる」とは使えない。「続ける」などにする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日の学修が雨になる。", "corrected_sentence": "毎日の学修が身になる。", "error_description": "「学修」は学ぶ行為なので「雨になる」とは言えない。「身になる」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52673, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「島に到達した」と到達先を表す「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、ここで到達先を表すことはできない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すため、「到達」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、到達先には使わない。"}], "correct_answer": "に", "explanations": {"に": "「島に到達した」と到達先を表す「に」が正しい。", "が": "「が」は主語を示すため、ここで到達先を表すことはできない。", "を": "「を」は対象を示すため、「到達」は取らない。", "で": "「で」は場所や手段を示すため、到達先には使わない。"}, "error_tags": {"が": "主語", "を": "対象", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
