INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52673, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるところに着くこと。", "primary_collocate": null, "pronunciation": "とうたつ", "ipa": "toːtatsɯ", "syllable_count": 4, "sentences": [{"text": "嵐の中、救助隊は無事に遭難者のいる谷底に到達した。", "target_word": "到達", "complexity_tier": "T3", "furigana": "嵐[あらし]の中[なか]、救助隊[きゅうじょたい]は無事[ぶじ]に遭難者[そうなんしゃ]のいる谷底[たにぞこ]に到達[とうたつ]した。", "sentence_source": "generated"}, {"text": "船が島に到達した。", "target_word": "到達した", "complexity_tier": "T2", "furigana": "船[ふね]が島[しま]に到達[とうたつ]した。", "sentence_source": "generated"}, {"text": "探検隊が洞窟の入口に到達したのは、夜遅くのことだった。", "target_word": "到達", "complexity_tier": "T3", "furigana": "探検隊[たんけんたい]が洞窟[どうくつ]の入口[いりぐち]に到達[とうたつ]したのは、夜遅[よるおそ]くのことだった。", "sentence_source": "generated"}, {"text": "手紙が相手に到達しなかった。", "target_word": "到達しなかった", "complexity_tier": "T3", "furigana": "手紙[てがみ]が相手[あいて]に到達[とうたつ]しなかった。", "sentence_source": "generated"}, {"text": "到達までの時間を計った。", "target_word": "到達", "complexity_tier": "T3", "furigana": "到達[とうたつ]までの時間[じかん]を計[はか]った。", "sentence_source": "generated"}, {"text": "光は地球に到達するまで八分かかる。", "target_word": "到達する", "complexity_tier": "T3", "furigana": "光[ひかり]は地球[ちきゅう]に到達[とうたつ]するまで八分[はっぷん]かかる。", "sentence_source": "generated"}, {"text": "一行は日が暮れる前に目的地に到達した。", "target_word": "到達した", "complexity_tier": "T4", "furigana": "一行[いっこう]は日[ひ]が暮[く]れる前[まえ]に目的地[もくてきち]に到達[とうたつ]した。", "sentence_source": "generated"}, {"text": "雪のため、救援物資が被災地に到達するのが大幅に遅れた。", "target_word": "到達", "complexity_tier": "T3", "furigana": "雪[ゆき]のため、救援物資[きゅうえんぶっし]が被災地[ひさいち]に到達[とうたつ]するのが大幅[おおはば]に遅[おく]れた。", "sentence_source": "generated"}, {"text": "先に到達した人から食事をする。", "target_word": "到達した", "complexity_tier": "T3", "furigana": "先[さき]に到達[とうたつ]した人[ひと]から食事[しょくじ]をする。", "sentence_source": "generated"}, {"text": "山小屋に到達したとき、みんな疲れ切っていた。", "target_word": "到達した", "complexity_tier": "T4", "furigana": "山小屋[やまごや]に到達[とうたつ]したとき、みんな疲[つか]れ切[き]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "到達する", "label": "活用"}, {"form": "到達した", "label": "活用"}, {"form": "到達しない", "label": "活用"}, {"form": "到達点", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ある場所にたどり着くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52673, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到達", "is_correct": true, "explanation": "「谷底に〇〇した」で、谷底という場所に着いたことを表す「到達」が入る。"}, {"text": "応答", "is_correct": false, "explanation": "応答は返事をすることで、場所に着く意味にはならない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを終えることで、谷底に着く意味にはならない。"}, {"text": "謝罪", "is_correct": false, "explanation": "謝罪は詫びることで、場所への到着を表さない。"}], "explanations": {"到達": "「谷底に〇〇した」で、谷底という場所に着いたことを表す「到達」が入る。", "応答": "応答は返事をすることで、場所に着く意味にはならない。", "解散": "解散は集まりを終えることで、谷底に着く意味にはならない。", "謝罪": "謝罪は詫びることで、場所への到着を表さない。"}, "sentence_index": 0, "correct_answer": "到達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は夜中に布団に到達して、すぐに寝た。", "explanation": "ここは〈就寝〉の意味。到達は場所に着くことで、横になって眠る動作には使わない。"}, {"text": "先生は生徒の答案に、ついに到達した。", "explanation": "ここは〈採点〉の意味。到達は着くことを表し、答案を読んで評価する行為には使わない。"}, {"text": "雨は朝に到達して、やがて止んだ。", "explanation": "ここは〈降る〉の意味。到達は目標や場所に着くことで、天候の経過には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52673, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到達した", "is_correct": true, "explanation": "「目的地に〇〇」の空欄には、目的地に着いたことを表す「到達した」が入る。"}, {"text": "解散した", "is_correct": false, "explanation": "解散は集まりを終えることで、目的地に着く意味にならない。"}, {"text": "応答した", "is_correct": false, "explanation": "応答は返事をすることで、場所への到着を表さない。"}, {"text": "謝罪した", "is_correct": false, "explanation": "謝罪は詫びることで、目的地に着く意味にはならない。"}], "explanations": {"到達した": "「目的地に〇〇」の空欄には、目的地に着いたことを表す「到達した」が入る。", "解散した": "解散は集まりを終えることで、目的地に着く意味にならない。", "応答した": "応答は返事をすることで、場所への到着を表さない。", "謝罪した": "謝罪は詫びることで、目的地に着く意味にはならない。"}, "sentence_index": 6, "correct_answer": "到達した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもは寝る前に、お風呂に到達した。", "explanation": "ここは〈入る〉の意味。到達は着くことを表し、入浴の行為には使わない。"}, {"text": "父は週末、庭の草取りに到達した。", "explanation": "ここは〈作業〉の意味。到達は目標や場所に着くことで、草取りをする意味では使わない。"}, {"text": "弟は宿題のノートを、ついに先生に到達させた。", "explanation": "ここは〈届ける〉の意味。到達は着くことを表し、人に物を渡す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
