INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "目標や目的地に達すること。また、その程度。", "primary_collocate": null, "pronunciation": "とうたつ", "ipa": "toːtatsɯ", "syllable_count": 4, "sentences": [{"text": "試験の評価は、目標への到達の程度で決まる。", "target_word": "到達", "complexity_tier": "T3", "furigana": "試験[しけん]の評価[ひょうか]は、目標[もくひょう]への到達[とうたつ]の程度[ていど]で決[き]まる。", "sentence_source": "generated"}, {"text": "山頂に到達しました。", "target_word": "到達しました", "complexity_tier": "T2", "furigana": "山頂[さんちょう]に到達[とうたつ]しました。", "sentence_source": "generated"}, {"text": "目標への到達は難しい。", "target_word": "到達", "complexity_tier": "T2", "furigana": "目標[もくひょう]への到達[とうたつ]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "探査機が火星に到達した。", "target_word": "到達した", "complexity_tier": "T2", "furigana": "探査機[たんさき]が火星[かせい]に到達[とうたつ]した。", "sentence_source": "generated"}, {"text": "水準への到達を目指して練習する。", "target_word": "到達", "complexity_tier": "T3", "furigana": "水準[すいじゅん]への到達[とうたつ]を目指[めざ]して練習[れんしゅう]する。", "sentence_source": "generated"}, {"text": "到達までに三時間かかる。", "target_word": "到達", "complexity_tier": "T2", "furigana": "到達[とうたつ]までに三時間[さんじかん]かかる。", "sentence_source": "generated"}, {"text": "このバスは終点に到達すると、運転手が交代する。", "target_word": "到達する", "complexity_tier": "T4", "furigana": "このバスは終点[しゅうてん]に到達[とうたつ]すると、運転手[うんてんしゅ]が交代[こうたい]する。", "sentence_source": "generated"}, {"text": "目標に到達するには、毎日の努力が欠かせない。", "target_word": "到達する", "complexity_tier": "T4", "furigana": "目標[もくひょう]に到達[とうたつ]するには、毎日[まいにち]の努力[どりょく]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "到達の程度は人によって違う。", "target_word": "到達", "complexity_tier": "T3", "furigana": "到達[とうたつ]の程度[ていど]は人[ひと]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "彼らは世界で初めて南極点に到達した。", "target_word": "到達した", "complexity_tier": "T4", "furigana": "彼[かれ]らは世界[せかい]で初[はじ]めて南極点[なんきょくてん]に到達[とうたつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "到達する", "label": "活用"}, {"form": "到達した", "label": "活用"}, {"form": "到達点", "label": "派生"}, {"form": "到達度", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目標や程度に達すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到達", "is_correct": true, "explanation": "目標に達するという意味で、「目標への到達の程度」の空欄に入る。"}, {"text": "出発", "is_correct": false, "explanation": "出発は目的地へ向けて出ることで、程度の語にはならない。"}, {"text": "停止", "is_correct": false, "explanation": "停止は動きを止めることで、程度を表す語ではない。"}, {"text": "撤退", "is_correct": false, "explanation": "撤退は引き下がることで、程度を表す語ではない。"}], "explanations": {"到達": "目標に達するという意味で、「目標への到達の程度」の空欄に入る。", "出発": "出発は目的地へ向けて出ることで、程度の語にはならない。", "停止": "停止は動きを止めることで、程度を表す語ではない。", "撤退": "撤退は引き下がることで、程度を表す語ではない。"}, "sentence_index": 0, "correct_answer": "到達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹が空いたので、昼ごはんに到達した。", "explanation": "ここは〈食べる〉の意味。到達は目標や目的地に達することで、食事には使わない。"}, {"text": "その難事件は、警察の努力でついに到達した。", "explanation": "ここは〈解決〉の意味。到達は場所や目標に着くことで、事件の決着には使わない。"}, {"text": "兄は週末、車の修理に到達した。", "explanation": "ここは〈完了〉の意味。到達は目的地に着くことで、作業をやり終える意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到達する", "is_correct": true, "explanation": "「終点に到達すると」の空欄に入る。終点を目指して着くことを表す。"}, {"text": "撤退する", "is_correct": false, "explanation": "撤退は引き返すことで、終点に着く意味にならない。"}, {"text": "発酵する", "is_correct": false, "explanation": "発酵は微生物による変化で、バスの動きには合わない。"}, {"text": "反映する", "is_correct": false, "explanation": "反映は影響が表れることで、場所への到着の意味にならない。"}], "explanations": {"到達する": "「終点に到達すると」の空欄に入る。終点を目指して着くことを表す。", "撤退する": "撤退は引き返すことで、終点に着く意味にならない。", "発酵する": "発酵は微生物による変化で、バスの動きには合わない。", "反映する": "反映は影響が表れることで、場所への到着の意味にならない。"}, "sentence_index": 6, "correct_answer": "到達する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は寝る前に、歯みがきに到達した。", "explanation": "ここは〈歯みがき〉の意味。到達は目標や目的地に達することで、作業を行う意味では使わない。"}, {"text": "私は夕食を作ったあと、家の掃除に到達した。", "explanation": "ここは〈終了〉の意味。到達は目的地に着くことで、家事を終える意味では使わない。"}, {"text": "妹は宿題を始めて、すぐ昼寝に到達した。", "explanation": "ここは〈寝る〉の意味。到達は目的地に達することで、眠る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小型機が島を到達した。", "corrected_sentence": "小型機が島に到達した。", "error_description": "〈到達〉は「〜に到達する」と使い、到達先には「に」を付ける。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
