INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不公平", "is_correct": true, "explanation": "「公平」の対義語。特定の誰かに有利・不利がある状態を表す。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかは落ち着いたさまで、公平の対義語ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "厳格は決まりに厳しいことで、公平の対義語ではない。"}, {"text": "柔軟", "is_correct": false, "explanation": "柔軟は融通がきくことで、公平の対義語ではない。"}], "correct_answer": "不公平", "explanations": {"不公平": "「公平」の対義語。特定の誰かに有利・不利がある状態を表す。", "穏やか": "穏やかは落ち着いたさまで、公平の対義語ではない。", "厳格": "厳格は決まりに厳しいことで、公平の対義語ではない。", "柔軟": "柔軟は融通がきくことで、公平の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不公平", "is_correct": true, "explanation": "「公平」の対義語。偏りがあり、特定の誰かに有利・不利が生じる状態を表す。"}, {"text": "有利", "is_correct": false, "explanation": "有利は一方に都合がよいことで、対義語ではなく関連語。"}, {"text": "平等", "is_correct": false, "explanation": "平等は同じに扱うことで、公平の類義語にあたり対義語ではない。"}, {"text": "公正", "is_correct": false, "explanation": "公正は公平と近い意味の類義語で、対義語ではない。"}], "correct_answer": "不公平", "explanations": {"不公平": "「公平」の対義語。偏りがあり、特定の誰かに有利・不利が生じる状態を表す。", "有利": "有利は一方に都合がよいことで、対義語ではなく関連語。", "平等": "平等は同じに扱うことで、公平の類義語にあたり対義語ではない。", "公正": "公正は公平と近い意味の類義語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "みんなが同じようにあつかわれること。", "primary_collocate": null, "pronunciation": "こうへい", "ipa": "koːheː", "syllable_count": 4, "sentences": [{"text": "公平に分けた。", "target_word": "公平に", "complexity_tier": "T1", "furigana": "公平[こうへい]に分[わ]けた。", "sentence_source": "generated"}, {"text": "ケーキの切り方は公平だった。", "target_word": "公平だった", "complexity_tier": "T2", "furigana": "ケーキの切[き]り方[かた]は公平[こうへい]だった。", "sentence_source": "generated"}, {"text": "これは公平ではない。", "target_word": "公平では", "complexity_tier": "T2", "furigana": "これは公平[こうへい]ではない。", "sentence_source": "generated"}, {"text": "公平なゲームをしよう。", "target_word": "公平な", "complexity_tier": "T2", "furigana": "公平[こうへい]なゲームをしよう。", "sentence_source": "generated"}, {"text": "先生は誰にでも公平だ。", "target_word": "公平だ", "complexity_tier": "T3", "furigana": "先生[せんせい]は誰[だれ]にでも公平[こうへい]だ。", "sentence_source": "generated"}, {"text": "兄弟みんなに公平におやつをあげた。", "target_word": "公平に", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]みんなに公平[こうへい]におやつをあげた。", "sentence_source": "generated"}, {"text": "公平でいたいと母は言った。", "target_word": "公平で", "complexity_tier": "T3", "furigana": "公平[こうへい]でいたいと母[はは]は言[い]った。", "sentence_source": "generated"}, {"text": "みんなが公平に扱われる学校にしたい。", "target_word": "公平に", "complexity_tier": "T4", "furigana": "みんなが公平[こうへい]に扱[あつか]われる学校[がっこう]にしたい。", "sentence_source": "generated"}, {"text": "くじ引きは公平な方法だと思う。", "target_word": "公平な", "complexity_tier": "T3", "furigana": "くじ引[び]きは公平[こうへい]な方法[ほうほう]だと思[おも]う。", "sentence_source": "generated"}, {"text": "公平だと感じなかった生徒は、先生に意見を伝えた。", "target_word": "公平だ", "complexity_tier": "T4", "furigana": "公平[こうへい]だと感[かん]じなかった生徒[せいと]は、先生[せんせい]に意見[いけん]を伝[つた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公平な", "label": "活用"}, {"form": "公平に", "label": "活用"}, {"form": "公平さ", "label": "派生"}, {"form": "不公平", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 皆が同じように扱われるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公平に", "is_correct": true, "explanation": "「〇〇分けた」の空欄に入り、同じように分けたことを表す。"}, {"text": "公平な", "is_correct": false, "explanation": "「公平な」は名詞を修飾する形で、動詞「分けた」を修飾できない。"}, {"text": "公平だ", "is_correct": false, "explanation": "「公平だ」は述語の形で、動詞の前には置けない。"}, {"text": "公平さ", "is_correct": false, "explanation": "「公平さ」は名詞で、「分けた」を修飾する位置には入らない。"}], "explanations": {"公平に": "「〇〇分けた」の空欄に入り、同じように分けたことを表す。", "公平な": "「公平な」は名詞を修飾する形で、動詞「分けた」を修飾できない。", "公平だ": "「公平だ」は述語の形で、動詞の前には置けない。", "公平さ": "「公平さ」は名詞で、「分けた」を修飾する位置には入らない。"}, "sentence_index": 0, "correct_answer": "公平に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅までの道は公平だ。", "explanation": "ここは〈平ら〉の意味。公平は人の扱いについて使い、道の状態には使わない。"}, {"text": "彼は公平に走るのが速い。", "explanation": "ここは〈速度〉の意味。公平は扱いの同等性を表し、走る速度には使わない。"}, {"text": "この写真は公平な味がする。", "explanation": "ここは〈味〉の意味。公平は扱いの同等性を表し、味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公平で", "is_correct": true, "explanation": "「〇〇でいたい」の空欄に入り、公平であり続けたいという意味になる。"}, {"text": "公平性", "is_correct": false, "explanation": "「公平性でいたい」は名詞に「でいたい」を続けても自然な意味にならない。"}, {"text": "偏り", "is_correct": false, "explanation": "偏りは公平と反対の状態で、「でいたい」と続けても文意に合わない。"}, {"text": "片寄り", "is_correct": false, "explanation": "片寄りは偏ることで、「でいたい」と続けると文意が逆になる。"}], "explanations": {"公平で": "「〇〇でいたい」の空欄に入り、公平であり続けたいという意味になる。", "公平性": "「公平性でいたい」は名詞に「でいたい」を続けても自然な意味にならない。", "偏り": "偏りは公平と反対の状態で、「でいたい」と続けても文意に合わない。", "片寄り": "片寄りは偏ることで、「でいたい」と続けると文意が逆になる。"}, "sentence_index": 6, "correct_answer": "公平で"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は公平な字で黒板に書いた。", "explanation": "ここは〈丁寧〉の意味。公平は扱いの同等性を表し、字の丁寧さには使わない。"}, {"text": "彼女は歌が公平だ。", "explanation": "ここは〈上手さ〉の意味。公平は扱いについて使い、歌の出来には使わない。"}, {"text": "母は料理をして、公平に笑った。", "explanation": "ここは〈朗らか〉の意味。公平は扱いの同等性を表し、笑い方の様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このやり方は公平だ決まりだ。", "corrected_sentence": "このやり方は公平な決まりだ。", "error_description": "名詞を修飾するときは「公平な」。「公平だ」は名詞の前に置けず、「だ」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "公平だった", "is_correct": true, "explanation": "「ケーキの切り方は〇〇」の述語として、過去の断定「公平だった」が入る。"}, {"text": "公平な", "is_correct": false, "explanation": "「公平な」は名詞を修飾する形で、文の述語にはならない。"}, {"text": "公平に", "is_correct": false, "explanation": "「公平に」は動詞を修飾する形で、述語にはならない。"}, {"text": "公平で", "is_correct": false, "explanation": "「公平で」は言い切れない形で、過去の述語として成り立たない。"}], "correct_form": "公平だった", "base_form": "公平", "form_label": "過去形（述語用法）", "sentence_index": 1, "explanations": {"公平だった": "「ケーキの切り方は〇〇」の述語として、過去の断定「公平だった」が入る。", "公平な": "「公平な」は名詞を修飾する形で、文の述語にはならない。", "公平に": "「公平に」は動詞を修飾する形で、述語にはならない。", "公平で": "「公平で」は言い切れない形で、過去の述語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は生徒を公平で扱った。", "corrected_sentence": "先生は生徒を公平に扱った。", "error_description": "〈公平〉は副詞の「公平に」で動詞「扱う」を修飾する。「公平で」は誤りで、「公平に扱った」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "公平に", "is_correct": true, "explanation": "「扱われる」を修飾する副詞用法で、文に合う。"}, {"text": "公平", "is_correct": false, "explanation": "語幹のままでは「公平扱われる」となり、「に」が抜けて文が成り立たない。"}, {"text": "公平だ", "is_correct": false, "explanation": "「公平だ」は述語の形で、「扱われる」を修飾する位置には入らない。"}, {"text": "公平さ", "is_correct": false, "explanation": "「公平さ」は名詞で、「扱われる」を修飾する副詞の位置には入らない。"}], "correct_form": "公平に", "base_form": "公平", "form_label": "連用形（副詞用法）", "sentence_index": 7, "explanations": {"公平に": "「扱われる」を修飾する副詞用法で、文に合う。", "公平": "語幹のままでは「公平扱われる」となり、「に」が抜けて文が成り立たない。", "公平だ": "「公平だ」は述語の形で、「扱われる」を修飾する位置には入らない。", "公平さ": "「公平さ」は名詞で、「扱われる」を修飾する副詞の位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
