INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52676, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "偏りがなく、特定の誰かに有利にならないようにすること。公正であること。", "primary_collocate": null, "pronunciation": "こうへい", "ipa": "koːheː", "syllable_count": 4, "sentences": [{"text": "学校は子どもたちの公平を守る責任がある。", "target_word": "公平", "complexity_tier": "T3", "furigana": "学校[がっこう]は子[こ]どもたちの公平[こうへい]を守[まも]る責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "先生は公平に点をつけた。", "target_word": "公平に", "complexity_tier": "T2", "furigana": "先生[せんせい]は公平[こうへい]に点[てん]をつけた。", "sentence_source": "generated"}, {"text": "公平な審判が求められている。", "target_word": "公平な", "complexity_tier": "T3", "furigana": "公平[こうへい]な審判[しんぱん]が求[もと]められている。", "sentence_source": "generated"}, {"text": "採用は公平でなければならない。", "target_word": "公平で", "complexity_tier": "T3", "furigana": "採用[さいよう]は公平[こうへい]でなければならない。", "sentence_source": "generated"}, {"text": "公平を保つのは難しい。", "target_word": "公平", "complexity_tier": "T2", "furigana": "公平[こうへい]を保[たも]つのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "裁判では、双方の主張を公平に聞くことが大切だ。", "target_word": "公平に", "complexity_tier": "T4", "furigana": "裁判[さいばん]では、双方[そうほう]の主張[しゅちょう]を公平[こうへい]に聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "その決め方は公平だ。", "target_word": "公平だ", "complexity_tier": "T2", "furigana": "その決[き]め方[かた]は公平[こうへい]だ。", "sentence_source": "generated"}, {"text": "機会の公平を守るために、新しい制度が作られた。", "target_word": "公平", "complexity_tier": "T4", "furigana": "機会[きかい]の公平[こうへい]を守[まも]るために、新[あたら]しい制度[せいど]が作[つく]られた。", "sentence_source": "generated"}, {"text": "公平な評価を受けて、彼は安心した。", "target_word": "公平な", "complexity_tier": "T3", "furigana": "公平[こうへい]な評価[ひょうか]を受[う]けて、彼[かれ]は安心[あんしん]した。", "sentence_source": "generated"}, {"text": "誰にとっても公平なルールを作ることが、組織の信頼につながる。", "target_word": "公平な", "complexity_tier": "T5", "furigana": "誰[だれ]にとっても公平[こうへい]なルールを作[つく]ることが、組織[そしき]の信頼[しんらい]につながる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公平な", "label": "活用"}, {"form": "公平に", "label": "活用"}, {"form": "公平性", "label": "派生"}, {"form": "不公平", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 偏りがなく公正であるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公平", "is_correct": true, "explanation": "「子どもたちの〇〇を守る」の空欄に入る「公平」だけが、偏りのなさを表す語として文意に合う。"}, {"text": "単純", "is_correct": false, "explanation": "「子どもたちの単純を守る」は意味が通らず、公正さを表さない。"}, {"text": "迅速", "is_correct": false, "explanation": "「子どもたちの迅速を守る」は意味が通らず、公正さを表さない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色の取り合わせで、子どもたちの扱いの公正さを表さない。"}], "explanations": {"公平": "「子どもたちの〇〇を守る」の空欄に入る「公平」だけが、偏りのなさを表す語として文意に合う。", "単純": "「子どもたちの単純を守る」は意味が通らず、公正さを表さない。", "迅速": "「子どもたちの迅速を守る」は意味が通らず、公正さを表さない。", "色彩": "色彩は色の取り合わせで、子どもたちの扱いの公正さを表さない。"}, "sentence_index": 0, "correct_answer": "公平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の天気は公平だ。", "explanation": "ここは〈均一〉の意味。公平は人の扱いについて偏りがないことで、天気の状態には使わない。"}, {"text": "二つの品質は公平だ。", "explanation": "ここは〈同等〉の意味。公平は偏りのなさを表し、品質が同じであることは言わない。"}, {"text": "彼は公平な絵を描いた。", "explanation": "ここは〈上手さ〉の意味。公平は扱いの偏りのなさを表し、作品の出来には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公平だ", "is_correct": true, "explanation": "「その決め方は〇〇。」の述語として、断定の「公平だ」が入る。"}, {"text": "公平な", "is_correct": false, "explanation": "「公平な」は名詞を修飾する形で、文を言い切れない。"}, {"text": "公平に", "is_correct": false, "explanation": "「公平に」は動詞を修飾する形で、述語にはならない。"}, {"text": "公平で", "is_correct": false, "explanation": "「公平で」は言い切れない形で、文の述語として成り立たない。"}], "explanations": {"公平だ": "「その決め方は〇〇。」の述語として、断定の「公平だ」が入る。", "公平な": "「公平な」は名詞を修飾する形で、文を言い切れない。", "公平に": "「公平に」は動詞を修飾する形で、述語にはならない。", "公平で": "「公平で」は言い切れない形で、文の述語として成り立たない。"}, "sentence_index": 6, "correct_answer": "公平だ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は公平な大きさの部屋に住んでいる。", "explanation": "ここは〈適度〉の意味。公平は扱いの偏りのなさを表し、部屋の広さの程度には使わない。"}, {"text": "彼女は走るのが公平だ。", "explanation": "ここは〈速さ〉の意味。公平は扱いの偏りのなさを表し、能力の高さには使わない。"}, {"text": "父は昨日、公平に大喜びした。", "explanation": "ここは〈非常に〉の意味。公平は扱いの偏りのなさを表し、程度を強める副詞としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は公平を意見を聞いた。", "corrected_sentence": "彼は公平に意見を聞いた。", "error_description": "〈公平〉は副詞的に「公平に」と使う。「公平を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "公平に", "is_correct": true, "explanation": "「点をつけた」を修飾する副詞用法の形で、文に合う。"}, {"text": "公平な", "is_correct": false, "explanation": "「公平な」は名詞を修飾する形で、動詞「つけた」を修飾できない。"}, {"text": "公平だ", "is_correct": false, "explanation": "「公平だ」は述語の形で、動詞を修飾する位置には入らない。"}, {"text": "公平", "is_correct": false, "explanation": "語幹のままでは「公平点をつけた」となり、「に」が抜けて文が成り立たない。"}], "correct_form": "公平に", "base_form": "公平", "form_label": "連用形（副詞用法）", "sentence_index": 1, "explanations": {"公平に": "「点をつけた」を修飾する副詞用法の形で、文に合う。", "公平な": "「公平な」は名詞を修飾する形で、動詞「つけた」を修飾できない。", "公平だ": "「公平だ」は述語の形で、動詞を修飾する位置には入らない。", "公平": "語幹のままでは「公平点をつけた」となり、「に」が抜けて文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52676, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公平だ評価を求めて、彼は声を上げた。", "corrected_sentence": "公平な評価を求めて、彼は声を上げた。", "error_description": "名詞を修飾するときは「公平な」。「公平だ」は名詞の前に置けず、「だ」が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "公平", "is_correct": true, "explanation": "「機会の〇〇を守る」の空欄に入る名詞用法の「公平」だけが文に合う。"}, {"text": "公平で", "is_correct": false, "explanation": "「公平で」は連用の「て」形で、「機会の」の後の名詞の位置には入らない。"}, {"text": "公平だった", "is_correct": false, "explanation": "「公平だった」は述語の過去形で、「機会の」の後に続く名詞の位置には入らない。"}, {"text": "公平ならば", "is_correct": false, "explanation": "「公平ならば」は条件節の形で、「機会の」の後の名詞の位置には入らない。"}], "correct_form": "公平", "base_form": "公平", "form_label": "名詞用法（語幹）", "sentence_index": 7, "explanations": {"公平": "「機会の〇〇を守る」の空欄に入る名詞用法の「公平」だけが文に合う。", "公平で": "「公平で」は連用の「て」形で、「機会の」の後の名詞の位置には入らない。", "公平だった": "「公平だった」は述語の過去形で、「機会の」の後に続く名詞の位置には入らない。", "公平ならば": "「公平ならば」は条件節の形で、「機会の」の後の名詞の位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『制度そのものに存する』の『に』。存する対象の所在・帰属先を示す。"}, {"text": "を", "is_correct": false, "explanation": "『存する』は目的語を取らないので、『を』は文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は移動の方向を表すが、存在の所在には使わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は動作の場所を表すので、『制度そのもので存する』は不自然。"}], "correct_answer": "に", "explanations": {"に": "『制度そのものに存する』の『に』。存する対象の所在・帰属先を示す。", "を": "『存する』は目的語を取らないので、『を』は文が成立しない。", "へ": "『へ』は移動の方向を表すが、存在の所在には使わない。", "で": "『で』は動作の場所を表すので、『制度そのもので存する』は不自然。"}, "error_tags": {"を": "対格", "へ": "方向", "で": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『細部に存する』の『に』。所在・帰属先を示す。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や引用に使い、『細部と存する』は文として成立しない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は動作の場所に使うので、『細部で存する』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞で、『細部の存する』は文が途切れる。"}], "correct_answer": "に", "explanations": {"に": "『細部に存する』の『に』。所在・帰属先を示す。", "と": "『と』は並列や引用に使い、『細部と存する』は文として成立しない。", "で": "『で』は動作の場所に使うので、『細部で存する』は不自然。", "の": "『の』は名詞をつなぐ助詞で、『細部の存する』は文が途切れる。"}, "error_tags": {"と": "引用", "で": "場所", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "存在する。ある。", "primary_collocate": null, "pronunciation": "そんする", "ipa": "soɴsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "存する", "complexity_tier": "T6", "furigana": "すなわち、技術的[ぎじゅつてき]革新[かくしん]は単[たん]なる効率化[こうりつか]の道具[どうぐ]にとどまらず、教育[きょういく]の公平性[こうへいせい]と個別[こべつ]最適化[さいてきか]を両立[りょうりつ]させる新[あら]たな認識論的[にんしきろんてき]枠組[わくぐ]みを構築[こうちく]し得[う]るという点[てん]に、その本質的[ほんしつてき]な教育的[きょういくてき]示唆[しさ]が存[そん]すると言[い]えよう。", "sentence_source": "mined"}, {"text": "問題の原因は制度そのものに存する。", "target_word": "存する", "complexity_tier": "T3", "furigana": "問題[もんだい]の原因[げんいん]は制度[せいど]そのものに存[そん]する。", "sentence_source": "generated"}, {"text": "古い建物が今も町に存している。", "target_word": "存している", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]が今[いま]も町[まち]に存[そん]している。", "sentence_source": "generated"}, {"text": "責任は経営者にも存する。", "target_word": "存する", "complexity_tier": "T2", "furigana": "責任[せきにん]は経営者[けいえいしゃ]にも存[そん]する。", "sentence_source": "generated"}, {"text": "この制度の価値は、公平さに存すると考える。", "target_word": "存する", "complexity_tier": "T4", "furigana": "この制度[せいど]の価値[かち]は、公平[こうへい]さに存[そん]すると考[かんが]える。", "sentence_source": "generated"}, {"text": "古代の遺跡が各地に存した。", "target_word": "存した", "complexity_tier": "T3", "furigana": "古代[こだい]の遺跡[いせき]が各地[かくち]に存[そん]した。", "sentence_source": "generated"}, {"text": "疑う余地は存しない。", "target_word": "存しない", "complexity_tier": "T2", "furigana": "疑[うたが]う余地[よち]は存[そん]しない。", "sentence_source": "generated"}, {"text": "重要な意味は細部に存すると思われる。", "target_word": "存する", "complexity_tier": "T4", "furigana": "重要[じゅうよう]な意味[いみ]は細部[さいぶ]に存[そん]すると思[おも]われる。", "sentence_source": "generated"}, {"text": "両者の意見の違いは、目的の捉え方に存しているようだ。", "target_word": "存している", "complexity_tier": "T4", "furigana": "両者[りょうしゃ]の意見[いけん]の違[ちが]いは、目的[もくてき]の捉[とら]え方[かた]に存[そん]しているようだ。", "sentence_source": "generated"}, {"text": "他に方法が存しなければ、これを使うしかない。", "target_word": "存しなければ", "complexity_tier": "T4", "furigana": "他[ほか]に方法[ほうほう]が存[そん]しなければ、これを使[つか]うしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "存し", "label": "活用"}, {"form": "存した", "label": "活用"}, {"form": "存して", "label": "活用"}, {"form": "存しない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 物事が書き言葉で存在する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存する", "is_correct": true, "explanation": "「示唆が存する」は『示唆がそこにある』の意味で、文脈に合う。"}, {"text": "逸れる", "is_correct": false, "explanation": "「逸れる」は道筋から外れる意味で、『示唆が逸れる』は文として通らない。"}, {"text": "澄む", "is_correct": false, "explanation": "「澄む」は液体や空気が透明になる意味で、抽象的な示唆には当てはまらない。"}, {"text": "濡れる", "is_correct": false, "explanation": "「濡れる」は水などで湿る意味で、示唆を主語にすると不自然。"}], "explanations": {"存する": "「示唆が存する」は『示唆がそこにある』の意味で、文脈に合う。", "逸れる": "「逸れる」は道筋から外れる意味で、『示唆が逸れる』は文として通らない。", "澄む": "「澄む」は液体や空気が透明になる意味で、抽象的な示唆には当てはまらない。", "濡れる": "「濡れる」は水などで湿る意味で、示唆を主語にすると不自然。"}, "sentence_index": 0, "correct_answer": "存する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その件は、先生が存じていた。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}, {"text": "先生のお名前は存じております。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}, {"text": "ご事情は存じません。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存しない", "is_correct": true, "explanation": "『疑う余地は存しない』の否定形で、『余地がない』の意味になる。"}, {"text": "凍らない", "is_correct": false, "explanation": "「凍る」は液体が固まる意味で、『余地が凍らない』は文脈に合わない。"}, {"text": "漂わない", "is_correct": false, "explanation": "「漂う」は空中や水上にとどまる意味で、『疑う余地は漂わない』は意味が通らない。"}, {"text": "砕けない", "is_correct": false, "explanation": "「砕ける」は固いものが割れる意味で、抽象的な余地には当てはまらない。"}], "explanations": {"存しない": "『疑う余地は存しない』の否定形で、『余地がない』の意味になる。", "凍らない": "「凍る」は液体が固まる意味で、『余地が凍らない』は文脈に合わない。", "漂わない": "「漂う」は空中や水上にとどまる意味で、『疑う余地は漂わない』は意味が通らない。", "砕けない": "「砕ける」は固いものが割れる意味で、抽象的な余地には当てはまらない。"}, "sentence_index": 6, "correct_answer": "存しない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の住所は存じておりました。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}, {"text": "その事実は私も存じていた。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}, {"text": "ご都合は存じておりません。", "explanation": "ここは〈存じる（知っている）〉の意味。存する（存在する）ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の不安の源は家庭環境で存する。", "corrected_sentence": "彼の不安の源は家庭環境に存する。", "error_description": "助詞の誤り。『存する』は『〜に存する』の形で場所・所在の『に』を取る。『で』は動作の場所を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その説の正しさには、疑う余地は存せない。", "corrected_sentence": "その説の正しさには、疑う余地は存しない。", "error_description": "活用の誤り。サ変『存する』の否定は『存しない』。『存せない』は文語『存せず』と混同した誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「公園の日溜まり」の「の」で、日溜まりを修飾する自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「公園を日溜まり」は続かず、目的語としても成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「公園へ日溜まり」は方向として続かず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「公園で日溜まり」は場所が二つ並んで不自然で、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「公園の日溜まり」の「の」で、日溜まりを修飾する自然な形になる。", "を": "「公園を日溜まり」は続かず、目的語としても成り立たない。", "へ": "「公園へ日溜まり」は方向として続かず、意味が通らない。", "で": "「公園で日溜まり」は場所が二つ並んで不自然で、文の意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「校舎の壁の日溜まりに集まる」の「に」で、子どもたちが集まる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「日溜まりが集まって」では集まる主体が日溜まりになり、子どもたちが集まる場所を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「日溜まりを集まって」は、自動詞の「集まる」が目的語を取れないので続かない。"}, {"text": "より", "is_correct": false, "explanation": "「日溜まりより集まって」は比較の意味になり、場所を示す文として意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「校舎の壁の日溜まりに集まる」の「に」で、子どもたちが集まる場所を示す。", "が": "「日溜まりが集まって」では集まる主体が日溜まりになり、子どもたちが集まる場所を示せない。", "を": "「日溜まりを集まって」は、自動詞の「集まる」が目的語を取れないので続かない。", "より": "「日溜まりより集まって」は比較の意味になり、場所を示す文として意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日が当たって暖かい場所のことです。", "primary_collocate": null, "pronunciation": "ひだまり", "ipa": "çidamaɾi", "syllable_count": 4, "sentences": [{"text": "冬の朝、猫が日溜まりで気持ちよさそうに寝ている。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、猫[ねこ]が日溜[ひだ]まりで気持[きも]ちよさそうに寝[ね]ている。", "sentence_source": "generated"}, {"text": "公園の日溜まりに、おじいさんがすわってお茶を飲んでいる。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "公園[こうえん]の日溜[ひだ]まりに、おじいさんがすわってお茶[ちゃ]を飲[の]んでいる。", "sentence_source": "generated"}, {"text": "風が冷たいので、庭の日溜まりへ出て洗濯物を干した。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "風[かぜ]が冷[つめ]たいので、庭[にわ]の日溜[ひだ]まりへ出[で]て洗濯物[せんたくもの]を干[ほ]した。", "sentence_source": "generated"}, {"text": "窓ぎわの日溜まりは、犬のいちばん好きな場所だ。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "窓[まど]ぎわの日溜[ひだ]まりは、犬[いぬ]のいちばん好[す]きな場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "寒かったので、日溜まりを探して歩いた。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "寒[さむ]かったので、日溜[ひだ]まりを探[さが]して歩[ある]いた。", "sentence_source": "generated"}, {"text": "日溜まりの中は、まるで春のように暖かい。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "日溜[ひだ]まりの中[なか]は、まるで春[はる]のように暖[あたた]かい。", "sentence_source": "generated"}, {"text": "ベンチは日溜まりにあって、冬でも座っていられる。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "ベンチは日溜[ひだ]まりにあって、冬[ふゆ]でも座[すわ]っていられる。", "sentence_source": "generated"}, {"text": "子どもたちは、校舎の壁の日溜まりに集まって話していた。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、校舎[こうしゃ]の壁[かべ]の日溜[ひだ]まりに集[あつ]まって話[はな]していた。", "sentence_source": "generated"}, {"text": "雪の中に、小さな日溜まりができていた。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "雪[ゆき]の中[なか]に、小[ちい]さな日溜[ひだ]まりができていた。", "sentence_source": "generated"}, {"text": "日溜まりで本を読んでいたら、つい眠くなってしまった。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "日溜[ひだ]まりで本[ほん]を読[よ]んでいたら、つい眠[ねむ]くなってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日溜まり", "label": "基本形"}, {"form": "日溜まりの", "label": "連体修飾形"}, {"form": "日溜まりで", "label": "場所を表す形"}, {"form": "日溜まりに", "label": "存在場所を表す形"}], "register": "neutral", "sense_fingerprint": "日光が当たって暖かくなっている場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日溜まり", "is_correct": true, "explanation": "日が当たって暖かい場所。猫が気持ちよさそうに寝ている場所として自然に合う。"}, {"text": "チーズ", "is_correct": false, "explanation": "食べ物の名前。場所を表さないので「チーズで寝ている」と意味が通らない。"}, {"text": "ボール", "is_correct": false, "explanation": "遊び道具。寝ている場所を示せないので文に合わない。"}, {"text": "電卓", "is_correct": false, "explanation": "計算に使う機械。場所ではないので「電卓で寝ている」は成り立たない。"}], "explanations": {"日溜まり": "日が当たって暖かい場所。猫が気持ちよさそうに寝ている場所として自然に合う。", "チーズ": "食べ物の名前。場所を表さないので「チーズで寝ている」と意味が通らない。", "ボール": "遊び道具。寝ている場所を示せないので文に合わない。", "電卓": "計算に使う機械。場所ではないので「電卓で寝ている」は成り立たない。"}, "sentence_index": 0, "correct_answer": "日溜まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "真夏の昼、日溜まりで涼んだ。", "explanation": "ここは〈木陰〉の意味。日溜まりは日が当たって暖かい場所なので、涼むための場所には合わない。"}, {"text": "寒い夜は日溜まりを布団に入れて寝る。", "explanation": "ここは〈湯たんぽ〉の意味。日溜まりは場所であり、布団に入れて温める道具ではない。"}, {"text": "冬の夜は日溜まりの火で体を温める。", "explanation": "ここは〈暖炉〉の意味。日溜まりは火を燃やす設備ではないので、暖を取る手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日溜まり", "is_correct": true, "explanation": "日が当たって暖かい場所。ベンチが冬でも座れるほど暖かい場所にある、という文に合う。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製の小物。場所ではないので、ベンチがその中にあるという意味にならない。"}, {"text": "チョーク", "is_correct": false, "explanation": "黒板に書くための道具。場所を表さないので文が成り立たない。"}, {"text": "水筒", "is_correct": false, "explanation": "飲み物を入れる容器。ベンチがその中にあるという文は意味をなさない。"}], "explanations": {"日溜まり": "日が当たって暖かい場所。ベンチが冬でも座れるほど暖かい場所にある、という文に合う。", "ハンカチ": "布製の小物。場所ではないので、ベンチがその中にあるという意味にならない。", "チョーク": "黒板に書くための道具。場所を表さないので文が成り立たない。", "水筒": "飲み物を入れる容器。ベンチがその中にあるという文は意味をなさない。"}, "sentence_index": 6, "correct_answer": "日溜まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が激しくなったので、日溜まりで雨宿りをした。", "explanation": "ここは〈雨宿り〉の場所の意味。日溜まりは日が当たる場所で、雨をしのげる場所ではないので合わない。"}, {"text": "夏は日溜まりで野菜を冷やしておく。", "explanation": "ここは〈冷蔵庫〉の意味。日溜まりは日が当たって暖かい場所で、食べ物を冷やす場所にはならない。"}, {"text": "日溜まりが地面を冷たく覆っていた。", "explanation": "ここは〈影〉の意味。日溜まりは日が当たって暖かい場所で、冷たく地面を覆うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは日溜まりが探して走り回った。", "corrected_sentence": "子どもたちは日溜まりを探して走り回った。", "error_description": "「探す」は目的語を「を」で取るので、「日溜まりが」は誤り。正しくは「日溜まりを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の午後、庭の日溜まり暖かくて、猫が丸まって寝ていた。", "corrected_sentence": "冬の午後、庭の日溜まりは暖かくて、猫が丸まって寝ていた。", "error_description": "「日溜まりは」の「は」が抜けている。主題を示す助詞が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「軒下の日溜まり」の「の」で、日溜まりを修飾する自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「軒下を日溜まり」は続かず、目的語としても成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「軒下へ日溜まり」は方向として続かず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「軒下より日溜まり」は比較の意味になり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「軒下の日溜まり」の「の」で、日溜まりを修飾する自然な形になる。", "を": "「軒下を日溜まり」は続かず、目的語としても成り立たない。", "へ": "「軒下へ日溜まり」は方向として続かず、意味が通らない。", "より": "「軒下より日溜まり」は比較の意味になり、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「日溜まりに」は置き場所を示し、「鉢植えを並べた」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「日溜まりが」は主語になり、「鉢植えを並べた」と続かない。"}, {"text": "を", "is_correct": false, "explanation": "「日溜まりを」は「鉢植えを」と目的語が二つ重なり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「日溜まりの」は連体修飾で、後ろに名詞が必要なので文が続かない。"}], "correct_answer": "に", "explanations": {"に": "「日溜まりに」は置き場所を示し、「鉢植えを並べた」と自然に続く。", "が": "「日溜まりが」は主語になり、「鉢植えを並べた」と続かない。", "を": "「日溜まりを」は「鉢植えを」と目的語が二つ重なり、文が成り立たない。", "の": "「日溜まりの」は連体修飾で、後ろに名詞が必要なので文が続かない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日が当たって暖かい場所。特に、冬の日差しが当たる軒下や縁側など。", "primary_collocate": null, "pronunciation": "ひだまり", "ipa": "çidamaɾi", "syllable_count": 4, "sentences": [{"text": "縁側の日溜まりで、祖母は毎日編み物をしている。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "縁側[えんがわ]の日溜[ひだ]まりで、祖母[そぼ]は毎日[まいにち]編[あ]み物[もの]をしている。", "sentence_source": "generated"}, {"text": "冬になると、軒下の日溜まりにスズメが集まってくる。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、軒下[のきした]の日溜[ひだ]まりにスズメが集[あつ]まってくる。", "sentence_source": "generated"}, {"text": "古い家の縁側にできた日溜まりは、猫の特等席だ。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]の縁側[えんがわ]にできた日溜[ひだ]まりは、猫[ねこ]の特等席[とくとうせき]だ。", "sentence_source": "generated"}, {"text": "寒い日でも、軒先の日溜まりは不思議なほど暖かかった。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]でも、軒先[のきさき]の日溜[ひだ]まりは不思議[ふしぎ]なほど暖[あたた]かかった。", "sentence_source": "generated"}, {"text": "縁側の日溜まりで、祖父はゆっくりお茶を飲んだ。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "縁側[えんがわ]の日溜[ひだ]まりで、祖父[そふ]はゆっくりお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "北風が吹く中、家の南側の日溜まりだけが暖かかった。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "北風[きたかぜ]が吹[ふ]く中[なか]、家[いえ]の南側[みなみがわ]の日溜[ひだ]まりだけが暖[あたた]かかった。", "sentence_source": "generated"}, {"text": "洗濯物を取り込んでから、しばらく縁側の日溜まりでぼんやりした。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を取[と]り込[こ]んでから、しばらく縁側[えんがわ]の日溜[ひだ]まりでぼんやりした。", "sentence_source": "generated"}, {"text": "冬の低い日差しが作る日溜まりに、鉢植えを並べた。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "冬[ふゆ]の低[ひく]い日差[ひざ]しが作[つく]る日溜[ひだ]まりに、鉢植[はちう]えを並[なら]べた。", "sentence_source": "generated"}, {"text": "昼になると縁側に日溜まりができ、母は布団を干す。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "昼[ひる]になると縁側[えんがわ]に日溜[ひだ]まりができ、母[はは]は布団[ふとん]を干[ほ]す。", "sentence_source": "generated"}, {"text": "軒下の日溜まりは、雪の日でも雪がとけていた。", "target_word": "日溜まり", "complexity_tier": "T3", "furigana": "軒下[のきした]の日溜[ひだ]まりは、雪[ゆき]の日[ひ]でも雪[ゆき]がとけていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日溜まり", "label": "基本形"}, {"form": "日溜まりの", "label": "連体修飾形"}, {"form": "日溜まりで", "label": "場所を表す形"}, {"form": "日溜まりが", "label": "主語を表す形"}], "register": "neutral", "sense_fingerprint": "冬の日差しで暖かくなった軒下や縁側などの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日溜まり", "is_correct": true, "explanation": "冬の日差しで暖かくなった縁側の場所。祖母が編み物をする場所として合う。"}, {"text": "せんべい", "is_correct": false, "explanation": "米菓の一種。場所を表さないので「縁側のせんべいで」と意味が通らない。"}, {"text": "ゆで卵", "is_correct": false, "explanation": "食べ物の一つ。縁側の場所を示せないので文が成り立たない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "書類をとじる文房具。場所ではないので、編み物の場所として合わない。"}], "explanations": {"日溜まり": "冬の日差しで暖かくなった縁側の場所。祖母が編み物をする場所として合う。", "せんべい": "米菓の一種。場所を表さないので「縁側のせんべいで」と意味が通らない。", "ゆで卵": "食べ物の一つ。縁側の場所を示せないので文が成り立たない。", "ホッチキス": "書類をとじる文房具。場所ではないので、編み物の場所として合わない。"}, "sentence_index": 0, "correct_answer": "日溜まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップに日溜まりを入れて、ジュースを冷やした。", "explanation": "ここは〈氷〉の意味。日溜まりは場所であって、コップに入れて冷やす物にはならない。"}, {"text": "寒い夜は日溜まりを重ねて寝た。", "explanation": "ここは〈毛布〉の意味。日溜まりは場所で、重ねて体を包む布ではない。"}, {"text": "お風呂の日溜まりが立ちのぼった。", "explanation": "ここは〈湯気〉の意味。日溜まりは日が当たる場所で、立ちのぼる湯気とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日溜まり", "is_correct": true, "explanation": "冬の日差しで暖かくなった縁側の場所。しばらくぼんやり過ごした場所として合う。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "食べ物の一つ。場所を表さないので「縁側のヨーグルトで」と意味が通らない。"}, {"text": "ドライヤー", "is_correct": false, "explanation": "髪を乾かす家電。場所ではないので、ぼんやりする場所として合わない。"}, {"text": "ぞうきん", "is_correct": false, "explanation": "掃除に使う布。場所を表さないので文が成り立たない。"}], "explanations": {"日溜まり": "冬の日差しで暖かくなった縁側の場所。しばらくぼんやり過ごした場所として合う。", "ヨーグルト": "食べ物の一つ。場所を表さないので「縁側のヨーグルトで」と意味が通らない。", "ドライヤー": "髪を乾かす家電。場所ではないので、ぼんやりする場所として合わない。", "ぞうきん": "掃除に使う布。場所を表さないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "日溜まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の日溜まりで、道が見えなくなった。", "explanation": "ここは〈吹雪〉の意味。日溜まりは日が当たる暖かい場所で、視界をさえぎるものではない。"}, {"text": "日溜まりが詰まって、水があふれた。", "explanation": "ここは〈雨樋〉の意味。日溜まりは場所であって、水の通り道をふさぐものではない。"}, {"text": "日溜まりが古くなって、ぐらぐら揺れる。", "explanation": "ここは〈洗濯機〉の意味。日溜まりは場所なので、古くなって揺れる機械にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午後、父は軒先の日溜まりが新聞を読んでいた。", "corrected_sentence": "午後、父は軒先の日溜まりで新聞を読んでいた。", "error_description": "「日溜まりで」は場所を表す。「日溜まりが」は主語になり、「新聞を読んでいた」と続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52680, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の午後、縁側の日溜まり暖かくて、祖母がうとうとしていた。", "corrected_sentence": "冬の午後、縁側の日溜まりは暖かくて、祖母がうとうとしていた。", "error_description": "「日溜まりは」の「は」が抜けている。主題を示す助詞が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52681, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「陶器の茶わん」で材料や種類を表す助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「陶器が茶わん」では名詞を修飾できません。"}, {"text": "を", "is_correct": false, "explanation": "「陶器を茶わん」では名詞を修飾できません。"}, {"text": "に", "is_correct": false, "explanation": "「陶器に茶わん」では名詞を修飾できません。"}], "correct_answer": "の", "explanations": {"の": "「陶器の茶わん」で材料や種類を表す助詞です。", "が": "「陶器が茶わん」では名詞を修飾できません。", "を": "「陶器を茶わん」では名詞を修飾できません。", "に": "「陶器に茶わん」では名詞を修飾できません。"}, "error_tags": {"が": "subject", "を": "object", "に": "target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52681, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「土でできている」で材料を表す助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「土をできている」は自動詞に対象を示せず不自然です。"}, {"text": "に", "is_correct": false, "explanation": "「土にできている」では材料を表せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「土へできている」は方向を表せず不自然です。"}], "correct_answer": "で", "explanations": {"で": "「土でできている」で材料を表す助詞です。", "を": "「土をできている」は自動詞に対象を示せず不自然です。", "に": "「土にできている」では材料を表せず不自然です。", "へ": "「土へできている」は方向を表せず不自然です。"}, "error_tags": {"を": "object", "に": "target", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52681, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "つちやどろをかためて、かまどでやいてかたくしたもの。うつわやかざりにします。", "primary_collocate": null, "pronunciation": "とうき", "ipa": "toːki", "syllable_count": 3, "sentences": [{"text": "陶器は土でできている。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "陶器[とうき]は土[つち]でできている。", "sentence_source": "generated"}, {"text": "これは陶器の茶わんです。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "これは陶器[とうき]の茶[ちゃ]わんです。", "sentence_source": "generated"}, {"text": "母は陶器が好きです。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "母[はは]は陶器[とうき]が好[す]きです。", "sentence_source": "generated"}, {"text": "陶器を買いました。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "陶器[とうき]を買[か]いました。", "sentence_source": "generated"}, {"text": "陶器を窯で焼く。", "target_word": "陶器", "complexity_tier": "T1", "furigana": "陶器[とうき]を窯[かま]で焼[や]く。", "sentence_source": "generated"}, {"text": "机の上に陶器がある。", "target_word": "陶器", "complexity_tier": "T1", "furigana": "机[つくえ]の上[うえ]に陶器[とうき]がある。", "sentence_source": "generated"}, {"text": "陶器の花びんを落とした。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "陶器[とうき]の花[か]びんを落[お]とした。", "sentence_source": "generated"}, {"text": "この陶器は重いです。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "この陶器[とうき]は重[おも]いです。", "sentence_source": "generated"}, {"text": "店には陶器がたくさん並んでいる。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "店[みせ]には陶器[とうき]がたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "陶器で作った皿でご飯を食べた。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "陶器[とうき]で作[つく]った皿[さら]でご飯[はん]を食[た]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "陶器製", "label": "派生"}, {"form": "陶器類", "label": "派生"}, {"form": "陶器店", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 土を窯で焼いて固めた器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52681, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陶器", "is_correct": true, "explanation": "見出し語そのものの発音です。"}, {"text": "動機", "is_correct": false, "explanation": "「どうき」で、最初の1拍だけが濁音になっています。"}, {"text": "後期", "is_correct": false, "explanation": "「こうき」で、最初の1拍だけが違います。"}, {"text": "早期", "is_correct": false, "explanation": "「そうき」で、最初の1拍だけが違います。"}, {"text": "箒", "is_correct": false, "explanation": "「ほうき」で、最初の1拍だけが違います。"}], "explanations": {"陶器": "見出し語そのものの発音です。", "動機": "「どうき」で、最初の1拍だけが濁音になっています。", "後期": "「こうき」で、最初の1拍だけが違います。", "早期": "「そうき」で、最初の1拍だけが違います。", "箒": "「ほうき」で、最初の1拍だけが違います。"}, "sentence_index": null, "correct_answer": "陶器"}, "level_3": {"options": [{"text": "陶器", "is_correct": true, "explanation": "土でできた器として文に合います。"}, {"text": "音楽", "is_correct": false, "explanation": "形は合うが意味が合わない。音楽は土でできていません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は土でできていません。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが意味が合わない。時間は土でできていません。"}], "explanations": {"陶器": "土でできた器として文に合います。", "音楽": "形は合うが意味が合わない。音楽は土でできていません。", "天気": "形は合うが意味が合わない。天気は土でできていません。", "時間": "形は合うが意味が合わない。時間は土でできていません。"}, "sentence_index": 0, "correct_answer": "陶器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "陶器は毎朝七時に起きて散歩します。", "explanation": "陶器は物で、起きて散歩することはできません。"}, {"text": "陶器を食べて、おなかがいっぱいになった。", "explanation": "陶器は器で、食べ物ではありません。"}, {"text": "陶器は空にうかんで、雲の上を歩く。", "explanation": "陶器は土でできた重い器で、空にうかんで歩きません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52681, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "陶器", "is_correct": true, "explanation": "見出し語そのものの発音です。"}, {"text": "討議", "is_correct": false, "explanation": "「とうぎ」で、最後の1拍だけが濁音になっています。"}, {"text": "投資", "is_correct": false, "explanation": "「とうし」で、最後の1拍だけが違います。"}, {"text": "投下", "is_correct": false, "explanation": "「とうか」で、最後の1拍だけが違います。"}, {"text": "当時", "is_correct": false, "explanation": "「とうじ」で、最後の1拍だけが違います。"}], "explanations": {"陶器": "見出し語そのものの発音です。", "討議": "「とうぎ」で、最後の1拍だけが濁音になっています。", "投資": "「とうし」で、最後の1拍だけが違います。", "投下": "「とうか」で、最後の1拍だけが違います。", "当時": "「とうじ」で、最後の1拍だけが違います。"}, "sentence_index": null, "correct_answer": "陶器"}, "level_3": {"options": [{"text": "陶器", "is_correct": true, "explanation": "落とすことのできる花びんの素材として合います。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが意味が合わない。気持ちの花びんはありません。"}, {"text": "言葉", "is_correct": false, "explanation": "形は合うが意味が合わない。言葉の花びんはありません。"}, {"text": "意見", "is_correct": false, "explanation": "形は合うが意味が合わない。意見の花びんはありません。"}], "explanations": {"陶器": "落とすことのできる花びんの素材として合います。", "気持ち": "形は合うが意味が合わない。気持ちの花びんはありません。", "言葉": "形は合うが意味が合わない。言葉の花びんはありません。", "意見": "形は合うが意味が合わない。意見の花びんはありません。"}, "sentence_index": 6, "correct_answer": "陶器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陶器は私に手紙を書いて、遠くの町へ引っ越した。", "explanation": "陶器は物で、手紙を書いたり引っ越したりしません。"}, {"text": "雨がふってきたので、陶器をさして歩いた。", "explanation": "雨のときにさすのは傘で、陶器はさせません。"}, {"text": "陶器を聞くと心が落ち着くので、毎晩ヘッドホンで流す。", "explanation": "陶器は音楽ではなく、聞くものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valid