INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52682, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "もらった相手（祖母）を示す助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「祖母をもらった」は人をもらう意味になり、文意が合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「祖母へもらった」は不自然です。"}, {"text": "で", "is_correct": false, "explanation": "「祖母でもらった」は相手を示せず不自然です。"}], "correct_answer": "から", "explanations": {"から": "もらった相手（祖母）を示す助詞です。", "を": "「祖母をもらった」は人をもらう意味になり、文意が合いません。", "へ": "「祖母へもらった」は不自然です。", "で": "「祖母でもらった」は相手を示せず不自然です。"}, "error_tags": {"を": "object", "へ": "direction", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52682, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「並んでいる」の主語（陶器）を示す助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「陶器を並んでいる」は自動詞に対象を示せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「陶器へ並んでいる」は意味が通りません。"}, {"text": "で", "is_correct": false, "explanation": "「陶器で並んでいる」は主語を示せず不自然です。"}], "correct_answer": "が", "explanations": {"が": "「並んでいる」の主語（陶器）を示す助詞です。", "を": "「陶器を並んでいる」は自動詞に対象を示せず不自然です。", "へ": "「陶器へ並んでいる」は意味が通りません。", "で": "「陶器で並んでいる」は主語を示せず不自然です。"}, "error_tags": {"を": "object", "へ": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "粘土を高温で焼いて硬くした、器や装飾品の総称。食器や植木鉢などに使われる。", "primary_collocate": null, "pronunciation": "とうき", "ipa": "toːki", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "陶器", "complexity_tier": "T6", "furigana": "陽[ひ]だまりの縁側[えんがわ]にて、幼[おさな]き童子[どうじ]は陶器[とうき]の鉢[はち]に植[う]えられた一株[ひとかぶ]の植物[しょくぶつ]へと、無心[むしん]なる眼差[まなざ]しを注[そそ]いでいる。", "sentence_source": "mined"}, {"text": "この陶器は祖母からもらった。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "この陶器[とうき]は祖母[そぼ]からもらった。", "sentence_source": "generated"}, {"text": "陶器の皿を割ってしまった。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "陶器[とうき]の皿[さら]を割[わ]ってしまった。", "sentence_source": "generated"}, {"text": "店で陶器を買いました。", "target_word": "陶器", "complexity_tier": "T2", "furigana": "店[みせ]で陶器[とうき]を買[か]いました。", "sentence_source": "generated"}, {"text": "陶器は落とすと割れやすい。", "target_word": "陶器", "complexity_tier": "T4", "furigana": "陶器[とうき]は落[お]とすと割[わ]れやすい。", "sentence_source": "generated"}, {"text": "自分で陶器を作る体験をしてみたい。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "自分[じぶん]で陶器[とうき]を作[つく]る体験[たいけん]をしてみたい。", "sentence_source": "generated"}, {"text": "有名な陶器の産地を旅した。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な陶器[とうき]の産地[さんち]を旅[たび]した。", "sentence_source": "generated"}, {"text": "棚に古い陶器が並んでいる。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "棚[たな]に古[ふる]い陶器[とうき]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "陶器と磁器では、焼く温度が違う。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "陶器[とうき]と磁器[じき]では、焼[や]く温度[おんど]が違[ちが]う。", "sentence_source": "generated"}, {"text": "土を高温で焼いて陶器にする。", "target_word": "陶器", "complexity_tier": "T3", "furigana": "土[つち]を高温[こうおん]で焼[や]いて陶器[とうき]にする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "陶器製", "label": "派生"}, {"form": "陶器類", "label": "派生"}, {"form": "陶器店", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 粘土を焼いて作った器の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
