INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もの を いれる ための いれもの。", "primary_collocate": null, "pronunciation": "うつわ", "ipa": "ɯtsɯwa", "syllable_count": 3, "sentences": [{"text": "器に水を入れます。", "target_word": "器", "complexity_tier": "T2", "furigana": "器[うつわ]に水[みず]を入[い]れます。", "sentence_source": "generated"}, {"text": "これは小さい器です。", "target_word": "器", "complexity_tier": "T2", "furigana": "これは小[ちい]さい器[うつわ]です。", "sentence_source": "generated"}, {"text": "器が落ちた。", "target_word": "器", "complexity_tier": "T1", "furigana": "器[うつわ]が落[お]ちた。", "sentence_source": "generated"}, {"text": "母は新しい器を買った。", "target_word": "器", "complexity_tier": "T2", "furigana": "母[はは]は新[あたら]しい器[うつわ]を買[か]った。", "sentence_source": "generated"}, {"text": "器の中にあめがある。", "target_word": "器", "complexity_tier": "T1", "furigana": "器[うつわ]の中[なか]にあめがある。", "sentence_source": "generated"}, {"text": "器でご飯を食べます。", "target_word": "器", "complexity_tier": "T2", "furigana": "器[うつわ]でご飯[はん]を食[た]べます。", "sentence_source": "generated"}, {"text": "大きな器にスープを入れた。", "target_word": "器", "complexity_tier": "T2", "furigana": "大[おお]きな器[うつわ]にスープを入[い]れた。", "sentence_source": "generated"}, {"text": "器は机の上に置いてある。", "target_word": "器", "complexity_tier": "T3", "furigana": "器[うつわ]は机[つくえ]の上[うえ]に置[お]いてある。", "sentence_source": "generated"}, {"text": "割れた器は使えません。", "target_word": "器", "complexity_tier": "T3", "furigana": "割[わ]れた器[うつわ]は使[つか]えません。", "sentence_source": "generated"}, {"text": "犬の器に水をあげた。", "target_word": "器", "complexity_tier": "T2", "furigana": "犬[いぬ]の器[うつわ]に水[みず]をあげた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物を入れるための入れもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed