INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52684, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を入れたり盛ったりするための道具。茶碗や鉢など。", "primary_collocate": null, "pronunciation": "うつわ", "ipa": "ɯtsɯwa", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "器", "complexity_tier": "T6", "furigana": "陽[ひ]だまりの縁側[えんがわ]にて、幼[おさな]き童子[どうじ]は陶器[とうき]の鉢[はち]に植[う]えられた一株[ひとかぶ]の植物[しょくぶつ]へと、無心[むしん]なる眼差[まなざ]しを注[そそ]いでいる。", "sentence_source": "mined"}, {"text": "その手には小さな器に汲まれた水。", "target_word": "器", "complexity_tier": "T4", "furigana": "その手[て]には小[ちい]さな器[うつわ]に汲[く]まれた水[みず]。", "sentence_source": "mined"}, {"text": "器に水を入れて、窓辺に置いた。", "target_word": "器", "complexity_tier": "T3", "furigana": "器[うつわ]に水[みず]を入[い]れて、窓辺[まどべ]に置[お]いた。", "sentence_source": "generated"}, {"text": "小さな器に果物を盛る。", "target_word": "器", "complexity_tier": "T3", "furigana": "小[ちい]さな器[うつわ]に果物[くだもの]を盛[も]る。", "sentence_source": "generated"}, {"text": "この器は祖父が作ったものだ。", "target_word": "器", "complexity_tier": "T3", "furigana": "この器[うつわ]は祖父[そふ]が作[つく]ったものだ。", "sentence_source": "generated"}, {"text": "料理に合う器を選ぶのは楽しい。", "target_word": "器", "complexity_tier": "T3", "furigana": "料理[りょうり]に合[あ]う器[うつわ]を選[えら]ぶのは楽[たの]しい。", "sentence_source": "generated"}, {"text": "割れた器を接着剤で直した。", "target_word": "器", "complexity_tier": "T3", "furigana": "割[わ]れた器[うつわ]を接着剤[せっちゃくざい]で直[なお]した。", "sentence_source": "generated"}, {"text": "器の底に少しだけスープが残っている。", "target_word": "器", "complexity_tier": "T3", "furigana": "器[うつわ]の底[そこ]に少[すこ]しだけスープが残[のこ]っている。", "sentence_source": "generated"}, {"text": "食事の後、器を洗いました。", "target_word": "器", "complexity_tier": "T2", "furigana": "食事[しょくじ]の後[あと]、器[うつわ]を洗[あら]いました。", "sentence_source": "generated"}, {"text": "茶道では、器の形や色も楽しみの一つだ。", "target_word": "器", "complexity_tier": "T4", "furigana": "茶道[さどう]では、器[うつわ]の形[かたち]や色[いろ]も楽[たの]しみの一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物を入れ盛る茶碗や鉢などの道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 縁側 (Zipf 3.0), 幼き (Zipf 2.71), 童子 (Zipf 3.27), 鉢 (Zipf 3.59), 無心 (Zipf 3.09), 眼差し (Zipf 3.38)','sentence 1 above tier T2: contains vocabulary far above tier T2: 汲ま (Zipf 1.71)']::text[], '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52684, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "器", "is_correct": true, "explanation": "見出し語「うつわ」そのもの。"}, {"text": "団扇", "is_correct": false, "explanation": "「うちわ」は2音目が違う別語。"}, {"text": "腕輪", "is_correct": false, "explanation": "「うでわ」は2音目が違う別語。"}, {"text": "空ろ", "is_correct": false, "explanation": "「うつろ」は3音目が違う別語。"}], "explanations": {"器": "見出し語「うつわ」そのもの。", "団扇": "「うちわ」は2音目が違う別語。", "腕輪": "「うでわ」は2音目が違う別語。", "空ろ": "「うつろ」は3音目が違う別語。"}, "sentence_index": null, "correct_answer": "器"}, "level_3": {"options": [{"text": "器", "is_correct": true, "explanation": "「陶器」で、物を入れる道具の意味に合う。"}, {"text": "芸", "is_correct": false, "explanation": "形は合うが、「芸の鉢」では意味が合わない。"}, {"text": "窯", "is_correct": false, "explanation": "形は合うが、「窯の鉢」では意味が合わない。"}, {"text": "土", "is_correct": false, "explanation": "形は合うが、「土の鉢」では意味が合わない。"}], "explanations": {"器": "「陶器」で、物を入れる道具の意味に合う。", "芸": "形は合うが、「芸の鉢」では意味が合わない。", "窯": "形は合うが、「窯の鉢」では意味が合わない。", "土": "形は合うが、「土の鉢」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で器に乗って会社へ行った。", "explanation": "器は乗り物ではないので、「器に乗る」は誤用。"}, {"text": "昨日の夜、器が大きな声で歌っていた。", "explanation": "器は物を入れる道具で、歌う主体にはならない。"}, {"text": "器を耳にあてて、電話で話した。", "explanation": "器は電話の道具ではなく、この意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
