INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52685, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出てきます」の主語を表す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「童子を出てきます」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「童子に出てきます」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「童子へ出てきます」は文法的に成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「出てきます」の主語を表す「が」。", "を": "「童子を出てきます」は文法的に成り立たない。", "に": "「童子に出てきます」は文法的に成り立たない。", "へ": "「童子へ出てきます」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "に": "location_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
