INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52685, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "子どものことを、昔の言い方で言った言葉です。", "primary_collocate": null, "pronunciation": "どうじ", "ipa": "doːdʑi", "syllable_count": 3, "sentences": [{"text": "童子は子どもの古い言い方です。", "target_word": "童子", "complexity_tier": "T2", "furigana": "童子[どうじ]は子[こ]どもの古[ふる]い言[い]い方[かた]です。", "sentence_source": "generated"}, {"text": "昔話に童子が出てきます。", "target_word": "童子", "complexity_tier": "T2", "furigana": "昔話[むかしばなし]に童子[どうじ]が出[で]てきます。", "sentence_source": "generated"}, {"text": "童子が山道を歩いている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子[どうじ]が山道[やまみち]を歩[ある]いている。", "sentence_source": "generated"}, {"text": "童子と犬が川で遊んだ。", "target_word": "童子", "complexity_tier": "T2", "furigana": "童子[どうじ]と犬[いぬ]が川[かわ]で遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "かわいい童子の絵を見た。", "target_word": "童子", "complexity_tier": "T2", "furigana": "かわいい童子[どうじ]の絵[え]を見[み]た。", "sentence_source": "generated"}, {"text": "童子はにこにこ笑っていた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子[どうじ]はにこにこ笑[わら]っていた。", "sentence_source": "generated"}, {"text": "祖父は私を童子と呼んだ。", "target_word": "童子", "complexity_tier": "T2", "furigana": "祖父[そふ]は私[わたし]を童子[どうじ]と呼[よ]んだ。", "sentence_source": "generated"}, {"text": "昔の人は子どもを童子と言った。", "target_word": "童子", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は子[こ]どもを童子[どうじ]と言[い]った。", "sentence_source": "generated"}, {"text": "この童子は赤い服を着ている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "この童子[どうじ]は赤[あか]い服[ふく]を着[き]ている。", "sentence_source": "generated"}, {"text": "童子の歌を聞くと、心が静かになる。", "target_word": "童子", "complexity_tier": "T4", "furigana": "童子[どうじ]の歌[うた]を聞[き]くと、心[こころ]が静[しず]かになる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 子どもを指す昔風の古い言い方", "collocat