INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "子供。特に、男の子を親しみを込めて呼ぶ語。", "primary_collocate": null, "pronunciation": "どうじ", "ipa": "doːdʑi", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "童子", "complexity_tier": "T6", "furigana": "陽[ひ]だまりの縁側[えんがわ]にて、幼[おさな]き童子[どうじ]は陶器[とうき]の鉢[はち]に植[う]えられた一株[ひとかぶ]の植物[しょくぶつ]へと、無心[むしん]なる眼差[まなざ]しを注[そそ]いでいる。", "sentence_source": "mined"}, {"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "童子", "complexity_tier": "T6", "furigana": "童子[どうじ]の行為[こうい]は、単[たん]なる日常的[にちじょうてき]な営[いとな]みの模倣[もほう]を超[こ]え、生命[せいめい]の循環[じゅんかん]に対[たい]する原初的[げんしょてき]な祈[いの]りにも似[に]た、崇高[すうこう]な儀式[ぎしき]としてそこに刻[きざ]まれるのである。", "sentence_source": "mined"}, {"text": "童子は庭で遊んでいた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子[どうじ]は庭[にわ]で遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "昔話に出てくる童子は、いつも元気だ。", "target_word": "童子", "complexity_tier": "T3", "furigana": "昔話[むかしばなし]に出[で]てくる童子[どうじ]は、いつも元気[げんき]だ。", "sentence_source": "generated"}, {"text": "縁側で童子が絵を描いている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "縁側[えんがわ]で童子[どうじ]が絵[え]を描[か]いている。", "sentence_source": "generated"}, {"text": "童子の笑い声が山にひびいた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子[どうじ]の笑[わら]い声[ごえ]が山[やま]にひびいた。", "sentence_source": "generated"}, {"text": "寺には小さな童子の像がある。", "target_word": "童子", "complexity_tier": "T3", "furigana": "寺[てら]には小[ちい]さな童子[どうじ]の像[ぞう]がある。", "sentence_source": "generated"}, {"text": "老人は童子を呼んで、お茶を運ばせた。", "target_word": "童子", "complexity_tier": "T4", "furigana": "老人[ろうじん]は童子[どうじ]を呼[よ]んで、お茶[ちゃ]を運[はこ]ばせた。", "sentence_source": "generated"}, {"text": "絵巻には、赤い着物を着た童子が描かれている。", "target_word": "童子", "complexity_tier": "T4", "furigana": "絵巻[えまき]には、赤[あか]い着物[きもの]を着[き]た童子[どうじ]が描[えが]かれている。", "sentence_source": "generated"}, {"text": "童子のように素直な心を持ちたい。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子[どうじ]のように素直[すなお]な心[こころ]を持[も]ちたい。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 親しみを込めて呼ぶ男の子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
