INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52687, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水を手ですくって、別の入れ物に入れること。", "primary_collocate": "水", "pronunciation": "くむ", "ipa": "kɯmɯ", "syllable_count": 2, "sentences": [{"text": "水を汲む。", "target_word": "汲む", "complexity_tier": "T1", "furigana": "水[みず]を汲[く]む。", "sentence_source": "generated"}, {"text": "手で水を汲みます。", "target_word": "汲みます", "complexity_tier": "T2", "furigana": "手[て]で水[みず]を汲[く]みます。", "sentence_source": "generated"}, {"text": "川の水を汲んで、鍋に入れた。", "target_word": "汲んで", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]を汲[く]んで、鍋[なべ]に入[い]れた。", "sentence_source": "generated"}, {"text": "朝早く、母は井戸水を汲んでいる。", "target_word": "汲んでいる", "complexity_tier": "T3", "furigana": "朝早[あさはや]く、母[はは]は井戸水[いどみず]を汲[く]んでいる。", "sentence_source": "generated"}, {"text": "水を汲みたいです。", "target_word": "汲みたい", "complexity_tier": "T2", "furigana": "水[みず]を汲[く]みたいです。", "sentence_source": "generated"}, {"text": "やかんに汲んだ水を沸かす。", "target_word": "汲んだ", "complexity_tier": "T3", "furigana": "やかんに汲[く]んだ水[みず]を沸[わ]かす。", "sentence_source": "generated"}, {"text": "水を汲まないと、花が枯れてしまう。", "target_word": "汲まない", "complexity_tier": "T4", "furigana": "水[みず]を汲[く]まないと、花[はな]が枯[か]れてしまう。", "sentence_source": "generated"}, {"text": "汲んでおいた水が、もうなくなった。", "target_word": "汲んで", "complexity_tier": "T3", "furigana": "汲[く]んでおいた水[みず]が、もうなくなった。", "sentence_source": "generated"}, {"text": "だれかが水を汲みに来た。", "target_word": "汲み", "complexity_tier": "T3", "furigana": "だれかが水[みず]を汲[く]みに来[き]た。", "sentence_source": "generated"}, {"text": "この桶なら、たくさん汲める。", "target_word": "汲める", "complexity_tier": "T3", "furigana": "この桶[おけ]なら、たくさん汲[く]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲みます", "label": "活用"}, {"form": "汲んだ", "label": "活用"}, {"form": "汲まない", "label": "活用"}, {"form": "汲める", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 水をすくって入れ物に入れる", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
