INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動作の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「水に汲み」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「水と汲み」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「水の汲み」では動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "動作の対象を示す。", "に": "「水に汲み」は成り立たない。", "と": "「水と汲み」は成り立たない。", "の": "「水の汲み」では動作の対象を示せない。"}, "error_tags": {"に": "target_vs_location", "と": "accompaniment", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体を、手や道具を使って、別の容器に移し取る。", "primary_collocate": "水", "pronunciation": "くむ", "ipa": "kɯmɯ", "syllable_count": 2, "sentences": [{"text": "小さな器に汲まれた水を飲んだ。", "target_word": "汲まれた", "complexity_tier": "T4", "furigana": "小[ちい]さな器[うつわ]に汲[く]まれた水[みず]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "井戸から水を汲む。", "target_word": "汲む", "complexity_tier": "T1", "furigana": "井戸[いど]から水[みず]を汲[く]む。", "sentence_source": "generated"}, {"text": "毎朝、川で水を汲みます。", "target_word": "汲みます", "complexity_tier": "T2", "furigana": "毎朝[まいあさ]、川[かわ]で水[みず]を汲[く]みます。", "sentence_source": "generated"}, {"text": "バケツで水を汲んで、庭にまいた。", "target_word": "汲んで", "complexity_tier": "T3", "furigana": "バケツで水[みず]を汲[く]んで、庭[にわ]にまいた。", "sentence_source": "generated"}, {"text": "おじいさんは桶に酒を汲んでくれた。", "target_word": "汲んで", "complexity_tier": "T3", "furigana": "おじいさんは桶[おけ]に酒[さけ]を汲[く]んでくれた。", "sentence_source": "generated"}, {"text": "水を汲もうとしたが、桶が重かった。", "target_word": "汲もう", "complexity_tier": "T3", "furigana": "水[みず]を汲[く]もうとしたが、桶[おけ]が重[おも]かった。", "sentence_source": "generated"}, {"text": "ひしゃくで汲んだ水を飲む。", "target_word": "汲んだ", "complexity_tier": "T3", "furigana": "ひしゃくで汲[く]んだ水[みず]を飲[の]む。", "sentence_source": "generated"}, {"text": "水を汲み、顔を洗った。", "target_word": "汲み", "complexity_tier": "T2", "furigana": "水[みず]を汲[く]み、顔[かお]を洗[あら]った。", "sentence_source": "generated"}, {"text": "子どもに水を汲ませた。", "target_word": "汲ませた", "complexity_tier": "T4", "furigana": "子[こ]どもに水[みず]を汲[く]ませた。", "sentence_source": "generated"}, {"text": "谷の水は冷たくて、汲むだけで手がしびれる。", "target_word": "汲む", "complexity_tier": "T4", "furigana": "谷[たに]の水[みず]は冷[つめ]たくて、汲[く]むだけで手[て]がしびれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲まれる", "label": "活用"}, {"form": "汲んだ", "label": "活用"}, {"form": "汲ませる", "label": "活用"}, {"form": "汲める", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 液体を手や道具で容器に移す", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汲む", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "噛む", "is_correct": false, "explanation": "かむ。最初の1拍が違う別の語。"}, {"text": "積む", "is_correct": false, "explanation": "つむ。最初の1拍が違う別の語。"}, {"text": "住む", "is_correct": false, "explanation": "すむ。最初の1拍が違う別の語。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "くも。最後の1拍だけが違う別の語。"}, {"text": "熊", "is_correct": false, "explanation": "くま。最後の1拍だけが違う別の語。"}, {"text": "来る", "is_correct": false, "explanation": "くる。最後の1拍だけが違う別の語。"}], "explanations": {"汲む": "見出し語そのもの。", "噛む": "かむ。最初の1拍が違う別の語。", "積む": "つむ。最初の1拍が違う別の語。", "住む": "すむ。最初の1拍が違う別の語。", "蜘蛛": "くも。最後の1拍だけが違う別の語。", "熊": "くま。最後の1拍だけが違う別の語。", "来る": "くる。最後の1拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "汲む"}, "level_3": {"options": [{"text": "汲まれた", "is_correct": true, "explanation": "器に水が移し取られた意味で合う。"}, {"text": "切られた", "is_correct": false, "explanation": "形は合うが、水が器に「切られる」では意味が合わない。"}, {"text": "燃やされた", "is_correct": false, "explanation": "形は合うが、水を燃やすことはできず意味が合わない。"}, {"text": "破られた", "is_correct": false, "explanation": "形は合うが、水は破るものではなく意味が合わない。"}], "explanations": {"汲まれた": "器に水が移し取られた意味で合う。", "切られた": "形は合うが、水が器に「切られる」では意味が合わない。", "燃やされた": "形は合うが、水を燃やすことはできず意味が合わない。", "破られた": "形は合うが、水は破るものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "汲まれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本を汲んで、棚に並べた。", "explanation": "「汲む」は液体を移し取る語で、本には使えない。"}, {"text": "財布から金を汲んで、買い物に行った。", "explanation": "「汲む」の対象は液体で、お金には使えない。"}, {"text": "犬を汲んで、公園を散歩した。", "explanation": "「汲む」は生き物を対象にできない。液体に限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "汲む", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "飲む", "is_correct": false, "explanation": "のむ。最初の1拍が違う。"}, {"text": "読む", "is_correct": false, "explanation": "よむ。最初の1拍が違う。"}, {"text": "踏む", "is_correct": false, "explanation": "ふむ。最初の1拍が違う。"}, {"text": "産む", "is_correct": false, "explanation": "うむ。最初の1拍が違う。"}, {"text": "済む", "is_correct": false, "explanation": "すむ。最初の1拍が違う。"}, {"text": "食う", "is_correct": false, "explanation": "くう。最後の1拍が違う。"}], "explanations": {"汲む": "見出し語そのもの。", "飲む": "のむ。最初の1拍が違う。", "読む": "よむ。最初の1拍が違う。", "踏む": "ふむ。最初の1拍が違う。", "産む": "うむ。最初の1拍が違う。", "済む": "すむ。最初の1拍が違う。", "食う": "くう。最後の1拍が違う。"}, "sentence_index": null, "correct_answer": "汲む"}, "level_3": {"options": [{"text": "汲んだ", "is_correct": true, "explanation": "ひしゃくで水を移し取った意味で合う。"}, {"text": "焼いた", "is_correct": false, "explanation": "形は合うが、ひしゃくで水を焼くことはなく意味が合わない。"}, {"text": "貼った", "is_correct": false, "explanation": "形は合うが、水は貼るものではなく意味が合わない。"}, {"text": "折った", "is_correct": false, "explanation": "形は合うが、水は折れないので意味が合わない。"}], "explanations": {"汲んだ": "ひしゃくで水を移し取った意味で合う。", "焼いた": "形は合うが、ひしゃくで水を焼くことはなく意味が合わない。", "貼った": "形は合うが、水は貼るものではなく意味が合わない。", "折った": "形は合うが、水は折れないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "汲んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谷の水は冷たくて、紙を汲むだけで手がしびれる。", "explanation": "「汲む」は液体に使う語で、紙には使えない。"}, {"text": "谷の水は冷たくて、歌を汲むだけで手がしびれる。", "explanation": "歌は液体ではなく、「汲む」の対象にならない。"}, {"text": "谷の水は冷たくて、靴を汲むだけで手がしびれる。", "explanation": "靴は移し取るものではなく、「汲む」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桶で水に汲んだ。", "corrected_sentence": "桶で水を汲んだ。", "error_description": "「汲む」の対象を示す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汲む", "is_correct": true, "explanation": "文末の終止形として自然。"}, {"text": "汲ま", "is_correct": false, "explanation": "未然形だけでは文が終わらない。"}, {"text": "汲み", "is_correct": false, "explanation": "連用形では文が終わらない。"}, {"text": "汲ませ", "is_correct": false, "explanation": "使役の連用形で、文末にならない。"}], "correct_form": "汲む", "base_form": "汲む", "form_label": "終止形", "sentence_index": 1, "explanations": {"汲む": "文末の終止形として自然。", "汲ま": "未然形だけでは文が終わらない。", "汲み": "連用形では文が終わらない。", "汲ませ": "使役の連用形で、文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52688, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の水を汲むで、顔を洗った。", "corrected_sentence": "川の水を汲んで、顔を洗った。", "error_description": "「汲む」のて形は「汲んで」。「汲むで」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汲み", "is_correct": true, "explanation": "連用形で、読点の前に文をつなぐ。"}, {"text": "汲もう", "is_correct": false, "explanation": "意志形は読点でつなぐ位置に合わない。"}, {"text": "汲める", "is_correct": false, "explanation": "可能形で「水を汲める、顔を洗った」とはならない。"}, {"text": "汲まれる", "is_correct": false, "explanation": "受身形は、この文脈に合わない。"}], "correct_form": "汲み", "base_form": "汲む", "form_label": "連用形", "sentence_index": 7, "explanations": {"汲み": "連用形で、読点の前に文をつなぐ。", "汲もう": "意志形は読点でつなぐ位置に合わない。", "汲める": "可能形で「水を汲める、顔を洗った」とはならない。", "汲まれる": "受身形は、この文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
