INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52689, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "二つのものが同じように見えること。", "primary_collocate": null, "pronunciation": "にる", "ipa": "niɾɯ", "syllable_count": 2, "sentences": [{"text": "この子は笑った顔が母親によく似ている。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "この子[こ]は笑[わら]った顔[かお]が母親[ははおや]によく似[に]ている。", "sentence_source": "generated"}, {"text": "この二匹の猫は毛の色や模様がとてもよく似ている。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "この二匹[にひき]の猫[ねこ]は毛[け]の色[いろ]や模様[もよう]がとてもよく似[に]ている。", "sentence_source": "generated"}, {"text": "二人は顔立ちがよく似ているので、初対面なのに兄弟だとすぐにわかった。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "二人[ふたり]は顔立[かおだ]ちがよく似[に]ているので、初対面[しょたいめん]なのに兄弟[きょうだい]だとすぐにわかった。", "sentence_source": "generated"}, {"text": "その絵は有名な画家の作品によく似ているが、別人が描いた。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "その絵[え]は有名[ゆうめい]な画家[がか]の作品[さくひん]によく似[に]ているが、別人[べつじん]が描[えが]いた。", "sentence_source": "generated"}, {"text": "私の字は父の字に似ていると、よく言われる。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "私[わたし]の字[じ]は父[ちち]の字[じ]に似[に]ていると、よく言[い]われる。", "sentence_source": "generated"}, {"text": "この果物は見た目がりんごに似ているが、味はまったく違う。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "この果物[くだもの]は見[み]た目[め]がりんごに似[に]ているが、味[あじ]はまったく違[ちが]う。", "sentence_source": "generated"}, {"text": "双子なのに、二人はあまり似ていない。", "target_word": "似ていない", "complexity_tier": "T3", "furigana": "双子[ふたご]なのに、二人[ふたり]はあまり似[に]ていない。", "sentence_source": "generated"}, {"text": "この町の家並みは、私の生まれた町によく似ている。", "target_word": "似ている", "complexity_tier": "T3", "furigana": "この町[まち]の家並[やな]みは、私[わたし]の生[う]まれた町[まち]によく似[に]ている。", "sentence_source": "generated"}, {"text": "似た服を着ていたので、友だちとまちがえられた。", "target_word": "似た", "complexity_tier": "T3", "furigana": "似[に]た服[ふく]を着[き]ていたので、友[とも]だちとまちがえられた。", "sentence_source": "generated"}, {"text": "犬の中には、飼い主に似てくるものもいる。", "target_word": "似て", "complexity_tier": "T3", "furigana": "犬[いぬ]の中[なか]には、飼[か]い主[ぬし]に似[に]てくるものもいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "似る", "label": "辞書形"}, {"form": "似ている", "label": "継続形"}, {"form": "似た", "label": "過去形・連体形"}, {"form": "似ていない", "label": "否定形"}, {"form": "似て", "label": "て形"}], "register": "neutral", "sense_fingerprint": "人やものの顔・性格・見た目などが互いによく似通っている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52689, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "似ている", "is_correct": true, "explanation": "継続形。「よく似ている」と状態を述べて文を言い切れる。"}, {"text": "似ろ", "is_correct": false, "explanation": "命令形なので、状態の説明として文を言い切る形にならない。"}, {"text": "似よう", "is_correct": false, "explanation": "意向形で意図を表し、見た目が似ているという状態の説明とずれる。"}, {"text": "似て", "is_correct": false, "explanation": "て形で、文末が言い切れず不完全な文になる。"}], "explanations": {"似ている": "継続形。「よく似ている」と状態を述べて文を言い切れる。", "似ろ": "命令形なので、状態の説明として文を言い切る形にならない。", "似よう": "意向形で意図を表し、見た目が似ているという状態の説明とずれる。", "似て": "て形で、文末が言い切れず不完全な文になる。"}, "sentence_index": 0, "correct_answer": "似ている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この作業は、ふつうの二倍の時間に似ている。", "explanation": "ここは〈時間がかかる〉の意味。似るは見た目や性質が似ることで、所要時間を表す使い方はしない。"}, {"text": "この靴は、サイズが足によく似ている。", "explanation": "ここは〈合う〉の意味。似るは二つのものが類似することで、大きさがぴったり合う意味には使わない。"}, {"text": "私の家は、駅に似ていて便利だ。", "explanation": "ここは〈近い〉の意味。似るは性質や見た目の類似を表し、場所の近さは近いと言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52689, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "似ていない", "is_correct": true, "explanation": "否定形。双子なのにあまり似ていない、という逆接の文を完成させる。"}, {"text": "似させる", "is_correct": false, "explanation": "使役形で、人に似させるという意味になり、二人の様子の説明と合わない。"}, {"text": "似ていれば", "is_correct": false, "explanation": "仮定形で、条件節のまま文が終わらず、不完全な文になる。"}, {"text": "似させない", "is_correct": false, "explanation": "使役の否定形で、似せることを禁じる意味になり、文意に合わない。"}], "explanations": {"似ていない": "否定形。双子なのにあまり似ていない、という逆接の文を完成させる。", "似させる": "使役形で、人に似させるという意味になり、二人の様子の説明と合わない。", "似ていれば": "仮定形で、条件節のまま文が終わらず、不完全な文になる。", "似させない": "使役の否定形で、似せることを禁じる意味になり、文意に合わない。"}, "sentence_index": 6, "correct_answer": "似ていない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい学校の生活に、もうすっかり似てきた。", "explanation": "ここは〈慣れる〉の意味。似るは見た目や性質が似ることで、環境や生活に慣れることは表さない。"}, {"text": "その言葉が彼の胸に似て、涙が出た。", "explanation": "ここは〈届く〉の意味。似るは類似を表す語で、言葉が心に伝わる意味には使わない。"}, {"text": "雨が一週間ずっと似ている。", "explanation": "ここは〈続く〉の意味。似るは二つのものの類似を表し、期間が続く意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52689, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は母親を似て、料理がとても上手だ。", "corrected_sentence": "彼女は母親に似て、料理がとても上手だ。", "error_description": "助詞の誤り。似るは「〜に似る」と相手を表すので、「母親を」は誤り。正しくは「母親に似て」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "似ている", "is_correct": true, "explanation": "継続形。毛の色や模様が似ているという状態を示し、文として成立する。"}, {"text": "似よう", "is_correct": false, "explanation": "意向形で、意志や推量の文になり、猫の状態を説明する文として成り立たない。"}, {"text": "似ていない", "is_correct": false, "explanation": "否定形で、似ていないという逆の内容になり、「よく似ている」と合わない。"}, {"text": "似れば", "is_correct": false, "explanation": "仮定形で、条件を述べるだけで文が続かず、文として完結しない。"}], "correct_form": "似ている", "base_form": "似る", "form_label": "継続形", "sentence_index": 1, "explanations": {"似ている": "継続形。毛の色や模様が似ているという状態を示し、文として成立する。", "似よう": "意向形で、意志や推量の文になり、猫の状態を説明する文として成り立たない。", "似ていない": "否定形で、似ていないという逆の内容になり、「よく似ている」と合わない。", "似れば": "仮定形で、条件を述べるだけで文が続かず、文として完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52689, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの兄弟は、考え方がどことなく似いていて、よく意気投合する。", "corrected_sentence": "あの兄弟は、考え方がどことなく似ていて、よく意気投合する。", "error_description": "活用の誤り。「似いて」は誤りで、似るの活用は「似て」「似ていて」。正しくは「似ていて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "似ている", "is_correct": true, "explanation": "継続形。家並みが似ているという状態を述べ、文として言い切れる。"}, {"text": "似ない", "is_correct": false, "explanation": "否定の基本形で、似ていないという逆の内容になり、「によく」と合わない。"}, {"text": "似させる", "is_correct": false, "explanation": "使役形で、町に似させるという不自然な意味になり、文意に合わない。"}, {"text": "似ていれば", "is_correct": false, "explanation": "仮定形で、条件節のまま文が終わらず、不完全な文になる。"}], "correct_form": "似ている", "base_form": "似る", "form_label": "継続形", "sentence_index": 7, "explanations": {"似ている": "継続形。家並みが似ているという状態を述べ、文として言い切れる。", "似ない": "否定の基本形で、似ていないという逆の内容になり、「によく」と合わない。", "似させる": "使役形で、町に似させるという不自然な意味になり、文意に合わない。", "似ていれば": "仮定形で、条件節のまま文が終わらず、不完全な文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「畏敬を込めて頭を下げた」で、込める対象の「畏敬」を示す「を」が入る。"}, {"text": "で", "is_correct": false, "explanation": "「畏敬で込めて」は意味が通らない。「で」は手段や場所を示すので、ここには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「畏敬へ込めて」は成り立たない。「へ」は方向を示すので、ここには入らない。"}, {"text": "から", "is_correct": false, "explanation": "「畏敬から込めて」は意味が通らない。「から」は起点を示すので、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "「畏敬を込めて頭を下げた」で、込める対象の「畏敬」を示す「を」が入る。", "で": "「畏敬で込めて」は意味が通らない。「で」は手段や場所を示すので、ここには合わない。", "へ": "「畏敬へ込めて」は成り立たない。「へ」は方向を示すので、ここには入らない。", "から": "「畏敬から込めて」は意味が通らない。「から」は起点を示すので、ここでは使えない。"}, "error_tags": {"で": "手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「深い畏敬をもって王に仕えた」で、持つ対象の「畏敬」を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「畏敬がもって」は主語と動詞が合わない。「が」では文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「畏敬にもって」は成り立たない。「に」は場所や相手を示すので、ここでは使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「畏敬へもって」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}], "correct_answer": "を", "explanations": {"を": "「深い畏敬をもって王に仕えた」で、持つ対象の「畏敬」を示す「を」が入る。", "が": "「畏敬がもって」は主語と動詞が合わない。「が」では文が成立しない。", "に": "「畏敬にもって」は成り立たない。「に」は場所や相手を示すので、ここでは使えない。", "へ": "「畏敬へもって」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}, "error_tags": {"が": "主語", "に": "場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すごくえらい人や神さまを、こわいけれども、ちゃんとたいせつに思う気持ち。", "primary_collocate": null, "pronunciation": "いけい", "ipa": "ikeː", "syllable_count": 3, "sentences": [{"text": "登山者たちは、雄大な山の姿に畏敬の念を抱いた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]たちは、雄大[ゆうだい]な山[やま]の姿[すがた]に畏敬[いけい]の念[ねん]を抱[いだ]いた。", "sentence_source": "generated"}, {"text": "彼は偉大な学者に畏敬を込めて頭を下げた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "彼[かれ]は偉大[いだい]な学者[がくしゃ]に畏敬[いけい]を込[こ]めて頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "昔の人々は、雷や嵐に畏敬の気持ちを持っていた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "昔[むかし]の人々[ひとびと]は、雷[かみなり]や嵐[あらし]に畏敬[いけい]の気持[きも]ちを持[も]っていた。", "sentence_source": "generated"}, {"text": "私は祖父の生き方に、畏敬に近い思いを感じている。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "私[わたし]は祖父[そふ]の生[い]き方[かた]に、畏敬[いけい]に近[ちか]い思[おも]いを感[かん]じている。", "sentence_source": "generated"}, {"text": "神社では、自然への畏敬を忘れないことが大切だと教わった。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "神社[じんじゃ]では、自然[しぜん]への畏敬[いけい]を忘[わす]れないことが大切[たいせつ]だと教[おそ]わった。", "sentence_source": "generated"}, {"text": "弟子たちは師匠を畏敬しており、その言葉を決して軽く扱わなかった。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "弟子[でし]たちは師匠[ししょう]を畏敬[いけい]しており、その言葉[ことば]を決[けっ]して軽[かる]く扱[あつか]わなかった。", "sentence_source": "generated"}, {"text": "星空の広さを前にして、畏敬の念で言葉が出なかった。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "星空[ほしぞら]の広[ひろ]さを前[まえ]にして、畏敬[いけい]の念[ねん]で言葉[ことば]が出[で]なかった。", "sentence_source": "generated"}, {"text": "彼女は恐れではなく、深い畏敬をもって王に仕えた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は恐[おそ]れではなく、深[ふか]い畏敬[いけい]をもって王[おう]に仕[つか]えた。", "sentence_source": "generated"}, {"text": "大きな滝の音に、人々は畏敬のまなざしを向けた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "大[おお]きな滝[たき]の音[おと]に、人々[ひとびと]は畏敬[いけい]のまなざしを向[む]けた。", "sentence_source": "generated"}, {"text": "命の不思議さに対する畏敬が、彼の研究の出発点だった。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "命[いのち]の不思議[ふしぎ]さに対[たい]する畏敬[いけい]が、彼[かれ]の研究[けんきゅう]の出発点[しゅっぱつてん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "畏敬", "label": "基本形"}, {"form": "畏敬する", "label": "サ変動詞形"}], "register": "formal", "sense_fingerprint": "偉大なものを恐れつつ敬う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "畏敬", "is_correct": true, "explanation": "「雄大な山の姿に畏敬の念を抱いた」で、偉大なものを恐れつつ敬う気持ちを表す。ここに入る語。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音の念」は意味が通らない。騒音は不快な音で、敬う気持ちとは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の念」は成り立たない。天気は空模様で、気持ちの名詞に続かない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布の念」は文脈に合わない。財布は金銭を入れる物なので、心の気持ちとは結びつかない。"}], "explanations": {"畏敬": "「雄大な山の姿に畏敬の念を抱いた」で、偉大なものを恐れつつ敬う気持ちを表す。ここに入る語。", "騒音": "「騒音の念」は意味が通らない。騒音は不快な音で、敬う気持ちとは結びつかない。", "天気": "「天気の念」は成り立たない。天気は空模様で、気持ちの名詞に続かない。", "財布": "「財布の念」は文脈に合わない。財布は金銭を入れる物なので、心の気持ちとは結びつかない。"}, "sentence_index": 0, "correct_answer": "畏敬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部下の失敗を、彼は畏敬の目で冷たく笑い飛ばした。", "explanation": "ここは〈軽蔑〉の意味になるはず。「畏敬」は敬う気持ちで、見下して笑う態度とは正反対なので合わない。"}, {"text": "同じ年の友人を、畏敬の念をもって叱りつけた。", "explanation": "ここは〈見下し〉の意味になるはず。「畏敬」は敬う気持ちで、相手を見下す態度とは合わない。"}, {"text": "会社の方針に畏敬を抱き、毎日不満を言っている。", "explanation": "ここは〈反感〉の意味になるはず。「畏敬」は敬う気持ちで、反感や文句とは正反対なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "畏敬", "is_correct": true, "explanation": "「星空の広さを前にして、畏敬の念で言葉が出なかった」で、偉大なものへの敬う気持ちを表す。ここに入る語。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便の念」は成り立たない。郵便は送る仕組みを指し、気持ちの名詞に続かない。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車の念」は意味が通らない。自転車は乗り物なので、心の気持ちとは結びつかない。"}, {"text": "雷", "is_correct": false, "explanation": "「雷の念」は文脈に合わない。雷は自然現象で、気持ちの名詞として使えない。"}], "explanations": {"畏敬": "「星空の広さを前にして、畏敬の念で言葉が出なかった」で、偉大なものへの敬う気持ちを表す。ここに入る語。", "郵便": "「郵便の念」は成り立たない。郵便は送る仕組みを指し、気持ちの名詞に続かない。", "自転車": "「自転車の念」は意味が通らない。自転車は乗り物なので、心の気持ちとは結びつかない。", "雷": "「雷の念」は文脈に合わない。雷は自然現象で、気持ちの名詞として使えない。"}, "sentence_index": 6, "correct_answer": "畏敬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究者は、集めた証拠を畏敬して、すぐに捨ててしまった。", "explanation": "ここは〈軽視〉の意味になるはず。「畏敬」は敬う気持ちで、証拠を軽んじて捨てる態度とは合わない。"}, {"text": "この料理は、畏敬の味がする。", "explanation": "ここは〈特徴〉の意味になるはず。「畏敬」は心の気持ちを表すので、料理の特徴を説明する語としては使わない。"}, {"text": "新しい計画に畏敬を込めて、会議でふざけて話した。", "explanation": "ここは〈冗談〉の意味になるはず。「畏敬」は真剣に敬う気持ちなので、ふざけた態度とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52691, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅人たちは、雄大な滝の姿に畏敬を念を抱いた。", "corrected_sentence": "旅人たちは、雄大な滝の姿に畏敬の念を抱いた。", "error_description": "誤りは「畏敬」の後の助詞。「畏敬の念」と名詞を続けるので、連体修飾の「の」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
