INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花や木を植えるための、丸い入れ物のことです。", "primary_collocate": null, "pronunciation": "はち", "ipa": "hatɕi", "syllable_count": 2, "sentences": [{"text": "鉢を買う。", "target_word": "鉢", "complexity_tier": "T1", "furigana": "鉢[はち]を買[か]う。", "sentence_source": "generated"}, {"text": "この鉢は丸いです。", "target_word": "鉢", "complexity_tier": "T2", "furigana": "この鉢[はち]は丸[まる]いです。", "sentence_source": "generated"}, {"text": "小さな鉢に花を植えた。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "小[ちい]さな鉢[はち]に花[はな]を植[う]えた。", "sentence_source": "generated"}, {"text": "ベランダに鉢が三つ並んでいる。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "ベランダに鉢[はち]が三[みっ]つ並[なら]んでいる。", "sentence_source": "generated"}, {"text": "鉢の土が乾いたので、水をやった。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "鉢[はち]の土[つち]が乾[かわ]いたので、水[みず]をやった。", "sentence_source": "generated"}, {"text": "先生は鉢を両手で持ち上げた。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "先生[せんせい]は鉢[はち]を両手[りょうて]で持[も]ち上[あ]げた。", "sentence_source": "generated"}, {"text": "この鉢には、赤いバラが植えてあります。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "この鉢[はち]には、赤[あか]いバラが植[う]えてあります。", "sentence_source": "generated"}, {"text": "重い鉢は、一人では運べない。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "重[おも]い鉢[はち]は、一人[ひとり]では運[はこ]べない。", "sentence_source": "generated"}, {"text": "雨が降ると、鉢を軒下に入れる。", "target_word": "鉢", "complexity_tier": "T4", "furigana": "雨[あめ]が降[ふ]ると、鉢[はち]を軒下[のきした]に入[い]れる。", "sentence_source": "generated"}, {"text": "祖母は毎年、同じ鉢で朝顔を育てている。", "target_word": "鉢", "complexity_tier": "T4", "furigana": "祖母[そぼ]は毎年[まいとし]、同[おな]じ鉢[はち]で朝顔[あさがお]を育[そだ]てている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一鉢", "label": "助数詞"}, {"form": "小鉢", "label": "派生"}, {"form": "大鉢", "label": "派生"}, {"form": "鉢植え", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 花や木を植える丸い入れ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
