INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52694, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物を植えたり、水を入れたりするのに使う、口の広い容器。特に、陶器やプラスチック製のもの。", "primary_collocate": null, "pronunciation": "はち", "ipa": "hatɕi", "syllable_count": 2, "sentences": [{"text": "陶器の鉢に、小さな植物が植えられている。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "陶器[とうき]の鉢[はち]に、小[ちい]さな植物[しょくぶつ]が植[う]えられている。", "sentence_source": "generated"}, {"text": "鉢という入れ物で、花を育てています。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "鉢[はち]という入[い]れ物[もの]で、花[はな]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "鉢に水をやる。", "target_word": "鉢", "complexity_tier": "T1", "furigana": "鉢[はち]に水[みず]をやる。", "sentence_source": "generated"}, {"text": "大きな鉢を買いました。", "target_word": "鉢", "complexity_tier": "T2", "furigana": "大[おお]きな鉢[はち]を買[か]いました。", "sentence_source": "generated"}, {"text": "この鉢は陶器でできている。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "この鉢[はち]は陶器[とうき]でできている。", "sentence_source": "generated"}, {"text": "窓のそばに鉢を置いた。", "target_word": "鉢", "complexity_tier": "T2", "furigana": "窓[まど]のそばに鉢[はち]を置[お]いた。", "sentence_source": "generated"}, {"text": "鉢が割れてしまって、土がこぼれた。", "target_word": "鉢", "complexity_tier": "T3", "furigana": "鉢[はち]が割[わ]れてしまって、土[つち]がこぼれた。", "sentence_source": "generated"}, {"text": "母が育てている花は、小さな鉢の中で咲いた。", "target_word": "鉢", "complexity_tier": "T4", "furigana": "母[はは]が育[そだ]てている花[はな]は、小[ちい]さな鉢[はち]の中[なか]で咲[さ]いた。", "sentence_source": "generated"}, {"text": "鉢の底に穴があるので、水がたまりません。", "target_word": "鉢", "complexity_tier": "T4", "furigana": "鉢[はち]の底[そこ]に穴[あな]があるので、水[みず]がたまりません。", "sentence_source": "generated"}, {"text": "古い鉢から新しい鉢へ、植物を移した。", "target_word": "鉢", "complexity_tier": "T4", "furigana": "古[ふる]い鉢[はち]から新[あたら]しい鉢[はち]へ、植物[しょくぶつ]を移[うつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一鉢", "label": "助数詞"}, {"form": "小鉢", "label": "派生"}, {"form": "大鉢", "label": "派生"}, {"form": "鉢植え", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 植物を植える口の広い容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
