INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52695, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄の所作に落ち着いている。", "corrected_sentence": "兄の所作は落ち着いている。", "error_description": "「所作」について述べる主題・主語の位置なので「に」は誤り。「は」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52695, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員の所作が、とても高いです。", "corrected_sentence": "店員の所作が、とても丁寧です。", "error_description": "「所作」の様子を「高い」とは言えない。所作には「丁寧だ」「優雅だ」などを使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「慎ましやかな所作で注ぎ下ろす」で、動作のしかた（様態）を表す。"}, {"text": "を", "is_correct": false, "explanation": "後に「それを注ぎ下ろす」があり、「所作を」を入れると目的語が二重になって非文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語は「彼は」で示されており、「所作が注ぎ下ろす」は成り立たず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向はすでに「表面へと」で示されており、「所作へ」は意味をなさず非文になる。"}], "correct_answer": "で", "explanations": {"で": "「慎ましやかな所作で注ぎ下ろす」で、動作のしかた（様態）を表す。", "を": "後に「それを注ぎ下ろす」があり、「所作を」を入れると目的語が二重になって非文になる。", "が": "主語は「彼は」で示されており、「所作が注ぎ下ろす」は成り立たず非文になる。", "へ": "方向はすでに「表面へと」で示されており、「所作へ」は意味をなさず非文になる。"}, "error_tags": {"を": "double_object", "が": "subject_mismatch", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「基本の所作から教える」で、教え始める起点を表す。"}, {"text": "が", "is_correct": false, "explanation": "「所作が教えます」では所作が教える側になってしまい、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「所作へ教えます」は方向の助詞が合わず、非文になる。"}, {"text": "の", "is_correct": false, "explanation": "「基本の所作の教えます」は連体の「の」が動詞に続けられず、非文になる。"}], "correct_answer": "から", "explanations": {"から": "「基本の所作から教える」で、教え始める起点を表す。", "が": "「所作が教えます」では所作が教える側になってしまい、文が成り立たない。", "へ": "「所作へ教えます」は方向の助詞が合わず、非文になる。", "の": "「基本の所作の教えます」は連体の「の」が動詞に続けられず、非文になる。"}, "error_tags": {"が": "subject_mismatch", "へ": "direction", "の": "attributive_before_verb"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "動作や振る舞い。特に、その人の態度や礼儀が表れるような動作。", "primary_collocate": null, "pronunciation": "しょさ", "ipa": "ɕosa", "syllable_count": 2, "sentences": [{"text": "彼は畏敬の念にも似た慎ましやかな所作で、乾いた土の表面へとそれを静かに注ぎ下ろす。", "target_word": "所作", "complexity_tier": "T6", "furigana": "彼[かれ]は畏敬[いけい]の念[ねん]にも似[に]た慎[つつ]ましやかな所作[しょさ]で、乾[かわ]いた土[つち]の表面[ひょうめん]へとそれを静[しず]かに注[そそ]ぎ下[お]ろす。", "sentence_source": "mined"}, {"text": "美しい所作に見とれた。", "target_word": "所作", "complexity_tier": "T2", "furigana": "美[うつく]しい所作[しょさ]に見[み]とれた。", "sentence_source": "generated"}, {"text": "茶道では所作が大切です。", "target_word": "所作", "complexity_tier": "T2", "furigana": "茶道[さどう]では所作[しょさ]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "彼女の所作は上品だ。", "target_word": "所作", "complexity_tier": "T1", "furigana": "彼女[かのじょ]の所作[しょさ]は上品[じょうひん]だ。", "sentence_source": "generated"}, {"text": "お茶の先生は、所作がとても丁寧だった。", "target_word": "所作", "complexity_tier": "T3", "furigana": "お茶[ちゃ]の先生[せんせい]は、所作[しょさ]がとても丁寧[ていねい]だった。", "sentence_source": "generated"}, {"text": "一つ一つの所作に気持ちがこもっている。", "target_word": "所作", "complexity_tier": "T3", "furigana": "一[ひと]つ一[ひと]つの所作[しょさ]に気持[きも]ちがこもっている。", "sentence_source": "generated"}, {"text": "客を迎える女将の所作を、じっと見ていた。", "target_word": "所作", "complexity_tier": "T3", "furigana": "客[きゃく]を迎[むか]える女将[おかみ]の所作[しょさ]を、じっと見[み]ていた。", "sentence_source": "generated"}, {"text": "新人には、基本の所作から教えます。", "target_word": "所作", "complexity_tier": "T3", "furigana": "新人[しんじん]には、基本[きほん]の所作[しょさ]から教[おし]えます。", "sentence_source": "generated"}, {"text": "所作を見れば、育ちのよさが分かる。", "target_word": "所作", "complexity_tier": "T4", "furigana": "所作[しょさ]を見[み]れば、育[そだ]ちのよさが分[わ]かる。", "sentence_source": "generated"}, {"text": "礼儀正しい所作を身につけるために、毎日練習した。", "target_word": "所作", "complexity_tier": "T4", "furigana": "礼儀正[れいぎただ]しい所作[しょさ]を身[み]につけるために、毎日[まいにち]練習[れんしゅう]した。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 礼儀や態度が表れる動作や振る舞い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所作", "is_correct": true, "explanation": "「しょさ」で、見出し語そのもの。"}, {"text": "補佐", "is_correct": false, "explanation": "「ほさ」で、最初の一拍だけが違う別語。"}, {"text": "誤差", "is_correct": false, "explanation": "「ごさ」で、最初の一拍だけが違う別語。"}, {"text": "書架", "is_correct": false, "explanation": "「しょか」で、最後の一拍だけが違う別語。"}, {"text": "書記", "is_correct": false, "explanation": "「しょき」で、最後の一拍だけが違う別語。"}, {"text": "示唆", "is_correct": false, "explanation": "「しさ」で、最初の一拍だけが違う別語。"}], "explanations": {"所作": "「しょさ」で、見出し語そのもの。", "補佐": "「ほさ」で、最初の一拍だけが違う別語。", "誤差": "「ごさ」で、最初の一拍だけが違う別語。", "書架": "「しょか」で、最後の一拍だけが違う別語。", "書記": "「しょき」で、最後の一拍だけが違う別語。", "示唆": "「しさ」で、最初の一拍だけが違う別語。"}, "sentence_index": null, "correct_answer": "所作"}, "level_3": {"options": [{"text": "所作", "is_correct": true, "explanation": "「慎ましやかな所作」で、礼儀や態度が表れる動作として文意に合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「慎ましやかな季節で土に注ぐ」は意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、「慎ましやかな値段で注ぎ下ろす」は動作の様子を表せず意味が合わない。"}, {"text": "記憶", "is_correct": false, "explanation": "形は合うが、「記憶で注ぎ下ろす」は動作の仕方にならず意味が合わない。"}], "explanations": {"所作": "「慎ましやかな所作」で、礼儀や態度が表れる動作として文意に合う。", "季節": "形は合うが、「慎ましやかな季節で土に注ぐ」は意味が合わない。", "値段": "形は合うが、「慎ましやかな値段で注ぎ下ろす」は動作の様子を表せず意味が合わない。", "記憶": "形は合うが、「記憶で注ぎ下ろす」は動作の仕方にならず意味が合わない。"}, "sentence_index": 0, "correct_answer": "所作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の会議の所作は、来週の火曜日に決まった。", "explanation": "「所作」を「日程・予定」の意味で使っており、人の動きや振る舞いという意味に合わない。"}, {"text": "この料理は所作が甘くて、とても美味しい。", "explanation": "「所作」を味の性質のように使っているが、所作は人の動作や振る舞いを指す。"}, {"text": "駅から家までの所作は、歩いて十分です。", "explanation": "「所作」を距離や道のりの意味で使っており、誤用である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
