INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の所作は、とても甘い味がする。", "corrected_sentence": "彼女の所作は、とても上品だ。", "error_description": "「所作」は人の動作や振る舞いなので、「甘い味がする」とは言えない。所作は「上品だ」「丁寧だ」などで評価する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52696, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基本の所作が身につけた。", "corrected_sentence": "基本の所作を身につけた。", "error_description": "「身につける」は他動詞なので、身につける対象の「所作」には「を」を使う。「所作が身につけた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出しゃばりな", "is_correct": true, "explanation": "でしゃばって自分を前に出す様子で、控えめでおとなしいことの反対にあたる。"}, {"text": "内気な", "is_correct": false, "explanation": "おとなしい性格という類義で、反対ではない。"}, {"text": "素直な", "is_correct": false, "explanation": "控えめさとは別の性質で、反対の関係ではない。"}, {"text": "静かな", "is_correct": false, "explanation": "おとなしいという近い意味で、反対ではない。"}], "correct_answer": "出しゃばりな", "explanations": {"出しゃばりな": "でしゃばって自分を前に出す様子で、控えめでおとなしいことの反対にあたる。", "内気な": "おとなしい性格という類義で、反対ではない。", "素直な": "控えめさとは別の性質で、反対の関係ではない。", "静かな": "おとなしいという近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚かましい", "is_correct": true, "explanation": "遠慮せず自分を前に出す様子で、控えめでおとなしいことの反対にあたる。"}, {"text": "素朴な", "is_correct": false, "explanation": "飾らない様子で、反対の関係ではない。"}, {"text": "従順な", "is_correct": false, "explanation": "おとなしく従う様子で、反対ではない。"}, {"text": "気弱な", "is_correct": false, "explanation": "控えめな性格に近く、反対の関係ではない。"}], "correct_answer": "厚かましい", "explanations": {"厚かましい": "遠慮せず自分を前に出す様子で、控えめでおとなしいことの反対にあたる。", "素朴な": "飾らない様子で、反対の関係ではない。", "従順な": "おとなしく従う様子で、反対ではない。", "気弱な": "控えめな性格に近く、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "じぶんのことをあまりみせないで、おとなしくすること。", "primary_collocate": null, "pronunciation": "つつましやか", "ipa": "tsɯtsɯmaɕijaka", "syllable_count": 6, "sentences": [{"text": "慎ましやかな子だ。", "target_word": "慎ましやかな", "complexity_tier": "T1", "furigana": "慎[つつ]ましやかな子[こ]だ。", "sentence_source": "generated"}, {"text": "妹は慎ましやかです。", "target_word": "慎ましやか", "complexity_tier": "T2", "furigana": "妹[いもうと]は慎[つつ]ましやかです。", "sentence_source": "generated"}, {"text": "彼は慎ましやかに話した。", "target_word": "慎ましやかに", "complexity_tier": "T2", "furigana": "彼[かれ]は慎[つつ]ましやかに話[はな]した。", "sentence_source": "generated"}, {"text": "慎ましやかな態度が好かれている。", "target_word": "慎ましやかな", "complexity_tier": "T3", "furigana": "慎[つつ]ましやかな態度[たいど]が好[す]かれている。", "sentence_source": "generated"}, {"text": "慎ましやかな彼女は、自分のことをあまり話さない。", "target_word": "慎ましやかな", "complexity_tier": "T4", "furigana": "慎[つつ]ましやかな彼女[かのじょ]は、自分[じぶん]のことをあまり話[はな]さない。", "sentence_source": "generated"}, {"text": "兄は成功しても、慎ましやかなままだった。", "target_word": "慎ましやかな", "complexity_tier": "T3", "furigana": "兄[あに]は成功[せいこう]しても、慎[つつ]ましやかなままだった。", "sentence_source": "generated"}, {"text": "慎ましやかに座って、順番を待った。", "target_word": "慎ましやかに", "complexity_tier": "T3", "furigana": "慎[つつ]ましやかに座[すわ]って、順番[じゅんばん]を待[ま]った。", "sentence_source": "generated"}, {"text": "この町の人々は、控えめで慎ましやかだ。", "target_word": "慎ましやか", "complexity_tier": "T3", "furigana": "この町[まち]の人々[ひとびと]は、控[ひか]えめで慎[つつ]ましやかだ。", "sentence_source": "generated"}, {"text": "慎ましやかであるべきだと、母は言った。", "target_word": "慎ましやか", "complexity_tier": "T4", "furigana": "慎[つつ]ましやかであるべきだと、母[はは]は言[い]った。", "sentence_source": "generated"}, {"text": "あの人ほど慎ましやかな人は見たことがない。", "target_word": "慎ましやかな", "complexity_tier": "T4", "furigana": "あの人[ひと]ほど慎[つつ]ましやかな人[ひと]は見[み]たことがない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慎ましやかな", "label": "活用"}, {"form": "慎ましやかに", "label": "活用"}, {"form": "慎ましやかだ", "label": "活用"}, {"form": "慎ましやかさ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 控えめでおとなしい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慎ましやかな", "is_correct": true, "explanation": "「子」を修飾し、控えめでおとなしい子という意味に合う。"}, {"text": "新鮮な", "is_correct": false, "explanation": "形は合うが、「新鮮な子」は人の性格として意味が合わない。"}, {"text": "豊富な", "is_correct": false, "explanation": "形は合うが、「豊富な子」は意味が合わない。"}, {"text": "平坦な", "is_correct": false, "explanation": "形は合うが、「平坦な子」は人を表す語として意味が合わない。"}], "explanations": {"慎ましやかな": "「子」を修飾し、控えめでおとなしい子という意味に合う。", "新鮮な": "形は合うが、「新鮮な子」は人の性格として意味が合わない。", "豊富な": "形は合うが、「豊富な子」は意味が合わない。", "平坦な": "形は合うが、「平坦な子」は人を表す語として意味が合わない。"}, "sentence_index": 0, "correct_answer": "慎ましやかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "慎ましやかな大声が、教室中に響いた。", "explanation": "「慎ましやか」は控えめでおとなしい様子で、「大声が響く」とは矛盾する。"}, {"text": "このナイフは慎ましやかで、よく切れる。", "explanation": "「慎ましやか」は控えめでおとなしい様子を表す語で、刃物の切れ味を表すことはできない。"}, {"text": "慎ましやかな彼は、会議でいつも一番に自分の意見を叫ぶ。", "explanation": "「慎ましやか」は自分をあまり出さないことで、「一番に叫ぶ」とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慎ましやかに", "is_correct": true, "explanation": "「座って」を修飾し、控えめでおとなしい座り方に合う。"}, {"text": "豊富に", "is_correct": false, "explanation": "形は合うが、「豊富に座る」は意味が合わない。"}, {"text": "新鮮に", "is_correct": false, "explanation": "形は合うが、「新鮮に座る」は意味が合わない。"}, {"text": "頑丈に", "is_correct": false, "explanation": "形は合うが、「頑丈に座って順番を待つ」は意味が合わない。"}], "explanations": {"慎ましやかに": "「座って」を修飾し、控えめでおとなしい座り方に合う。", "豊富に": "形は合うが、「豊富に座る」は意味が合わない。", "新鮮に": "形は合うが、「新鮮に座る」は意味が合わない。", "頑丈に": "形は合うが、「頑丈に座って順番を待つ」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "慎ましやかに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この辞書は慎ましやかで、五千ページもある。", "explanation": "「慎ましやか」は控えめな様子を表すので、五千ページもある大きな辞書の様子とは矛盾する。"}, {"text": "慎ましやかな彼は、パーティーで一番目立つ服を着て踊り回った。", "explanation": "「慎ましやか」は自分を見せないことで、目立って踊り回るのとは矛盾する。"}, {"text": "今日の空は慎ましやかで、雲ひとつなく青い。", "explanation": "「慎ましやか」は人の態度を表す語で、空模様には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は慎ましやかで、いつも大声で自慢する。", "corrected_sentence": "弟は慎ましやかで、いつも黙って控えている。", "error_description": "「慎ましやか」は自分を見せないおとなしさを表すので、「大声で自慢する」とは意味が矛盾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "慎ましやか", "is_correct": true, "explanation": "語幹に「です」が付いて、「慎ましやかです」になる。"}, {"text": "慎ましやかな", "is_correct": false, "explanation": "連体形で、「です」の前には置けず非文になる。"}, {"text": "慎ましやかに", "is_correct": false, "explanation": "連用形で、「慎ましやかにです」は非文になる。"}, {"text": "慎ましやかだ", "is_correct": false, "explanation": "終止形で、「です」と重なり「慎ましやかだです」は非文になる。"}], "correct_form": "慎ましやか", "base_form": "慎ましやか", "form_label": "語幹", "sentence_index": 1, "explanations": {"慎ましやか": "語幹に「です」が付いて、「慎ましやかです」になる。", "慎ましやかな": "連体形で、「です」の前には置けず非文になる。", "慎ましやかに": "連用形で、「慎ましやかにです」は非文になる。", "慎ましやかだ": "終止形で、「です」と重なり「慎ましやかだです」は非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52697, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は慎ましやかな人で、自分の成功を何度も自慢する。", "corrected_sentence": "兄は慎ましやかな人で、自分の成功をあまり話さない。", "error_description": "「慎ましやか」は自分をあまり見せないことなので、「何度も自慢する」とは意味が矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "慎ましやか", "is_correct": true, "explanation": "語幹に「だ」が付いて、「慎ましやかだ」になる。"}, {"text": "慎ましやかな", "is_correct": false, "explanation": "連体形で、「だ」の前には置けず非文になる。"}, {"text": "慎ましやかに", "is_correct": false, "explanation": "連用形で、「慎ましやかにだ」は非文になる。"}, {"text": "慎ましやかで", "is_correct": false, "explanation": "連用形（で）で、「慎ましやかでだ」は非文になる。"}], "correct_form": "慎ましやか", "base_form": "慎ましやか", "form_label": "語幹", "sentence_index": 7, "explanations": {"慎ましやか": "語幹に「だ」が付いて、「慎ましやかだ」になる。", "慎ましやかな": "連体形で、「だ」の前には置けず非文になる。", "慎ましやかに": "連用形で、「慎ましやかにだ」は非文になる。", "慎ましやかで": "連用形（で）で、「慎ましやかでだ」は非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
