INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52698, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "控えめで、品があり、他人に対して礼儀正しい態度をとる様子。", "primary_collocate": null, "pronunciation": "つつましやか", "ipa": "tsɯtsɯmaɕijaka", "syllable_count": 6, "sentences": [{"text": "彼は畏敬の念にも似た慎ましやかな所作で、乾いた土の表面へとそれを静かに注ぎ下ろす。", "target_word": "慎ましやかな", "complexity_tier": "T6", "furigana": "彼[かれ]は畏敬[いけい]の念[ねん]にも似[に]た慎[つつ]ましやかな所作[しょさ]で、乾[かわ]いた土[つち]の表面[ひょうめん]へとそれを静[しず]かに注[そそ]ぎ下[お]ろす。", "sentence_source": "mined"}, {"text": "慎ましやかな人だ。", "target_word": "慎ましやかな", "complexity_tier": "T1", "furigana": "慎[つつ]ましやかな人[ひと]だ。", "sentence_source": "generated"}, {"text": "彼女は慎ましやかです。", "target_word": "慎ましやか", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は慎[つつ]ましやかです。", "sentence_source": "generated"}, {"text": "慎ましやかに頭を下げた。", "target_word": "慎ましやかに", "complexity_tier": "T2", "furigana": "慎[つつ]ましやかに頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "慎ましやかな服を着て、式に出た。", "target_word": "慎ましやかな", "complexity_tier": "T3", "furigana": "慎[つつ]ましやかな服[ふく]を着[き]て、式[しき]に出[で]た。", "sentence_source": "generated"}, {"text": "母は慎ましやかで、人前では多くを語らない。", "target_word": "慎ましやか", "complexity_tier": "T3", "furigana": "母[はは]は慎[つつ]ましやかで、人前[ひとまえ]では多[おお]くを語[かた]らない。", "sentence_source": "generated"}, {"text": "慎ましやかな言葉づかいが印象的だった。", "target_word": "慎ましやかな", "complexity_tier": "T3", "furigana": "慎[つつ]ましやかな言葉[ことば]づかいが印象的[いんしょうてき]だった。", "sentence_source": "generated"}, {"text": "彼女の笑い方は、いつも慎ましやかだ。", "target_word": "慎ましやか", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑[わら]い方[かた]は、いつも慎[つつ]ましやかだ。", "sentence_source": "generated"}, {"text": "新婦は慎ましやかに微笑んで、席に着いた。", "target_word": "慎ましやかに", "complexity_tier": "T3", "furigana": "新婦[しんぷ]は慎[つつ]ましやかに微笑[ほほえ]んで、席[せき]に着[つ]いた。", "sentence_source": "generated"}, {"text": "慎ましやかであろうとする心が、彼を上品に見せる。", "target_word": "慎ましやか", "complexity_tier": "T4", "furigana": "慎[つつ]ましやかであろうとする心[こころ]が、彼[かれ]を上品[じょうひん]に見[み]せる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慎ましやかな", "label": "活用"}, {"form": "慎ましやかに", "label": "活用"}, {"form": "慎ましやかだ", "label": "活用"}, {"form": "慎ましやかさ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 控えめで品があり礼儀正しい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慎ましやかな", "is_correct": true, "explanation": "「畏敬の念にも似た」所作を修飾し、控えめで礼儀正しい様子に合う。"}, {"text": "乱暴な", "is_correct": false, "explanation": "形は合うが、畏敬の念に似た静かな所作とは意味が合わない。"}, {"text": "無神経な", "is_correct": false, "explanation": "形は合うが、畏敬の念に似た所作とは意味が合わない。"}, {"text": "粗雑な", "is_correct": false, "explanation": "形は合うが、土に静かに注ぐ丁寧な場面とは意味が合わない。"}], "explanations": {"慎ましやかな": "「畏敬の念にも似た」所作を修飾し、控えめで礼儀正しい様子に合う。", "乱暴な": "形は合うが、畏敬の念に似た静かな所作とは意味が合わない。", "無神経な": "形は合うが、畏敬の念に似た所作とは意味が合わない。", "粗雑な": "形は合うが、土に静かに注ぐ丁寧な場面とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "慎ましやかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は慎ましやかに、大声で怒鳴り散らした。", "explanation": "「慎ましやか」は控えめな様子で、「大声で怒鳴り散らす」とは正反対で矛盾する。"}, {"text": "慎ましやかな夏の暑さで、汗が止まらない。", "explanation": "「慎ましやか」は人の態度の控えめさを表し、気候の暑さには使えない。"}, {"text": "慎ましやかな機械が、工場で大きな音を立てている。", "explanation": "「慎ましやか」は機械の音の大きさを表す語ではなく、大きな音とも矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慎ましやかな", "is_correct": true, "explanation": "「言葉づかい」を修飾し、控えめで礼儀正しい印象に合う。"}, {"text": "頑丈な", "is_correct": false, "explanation": "形は合うが、言葉づかいが「頑丈」という意味は合わない。"}, {"text": "安全な", "is_correct": false, "explanation": "形は合うが、「安全な言葉づかい」では印象的という文脈に意味が合わない。"}, {"text": "豊富な", "is_correct": false, "explanation": "形は合うが、言葉づかいを「豊富」とは普通言わず、意味が合わない。"}], "explanations": {"慎ましやかな": "「言葉づかい」を修飾し、控えめで礼儀正しい印象に合う。", "頑丈な": "形は合うが、言葉づかいが「頑丈」という意味は合わない。", "安全な": "形は合うが、「安全な言葉づかい」では印象的という文脈に意味が合わない。", "豊富な": "形は合うが、言葉づかいを「豊富」とは普通言わず、意味が合わない。"}, "sentence_index": 6, "correct_answer": "慎ましやかな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "慎ましやかな犯人は、人前で堂々と自慢した。", "explanation": "「慎ましやか」は控えめな態度を表し、「堂々と自慢する」とは矛盾する。"}, {"text": "このスープは慎ましやかで、とても辛くて熱い。", "explanation": "「慎ましやか」は人の態度の控えめさで、料理の辛さや熱さには使えない。"}, {"text": "慎ましやかな嵐が、町の屋根を吹き飛ばした。", "explanation": "「慎ましやか」は人の控えめな態度を表す語で、破壊的な嵐とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は慎ましやかに大声で笑った。", "corrected_sentence": "彼女は慎ましやかに小さく笑った。", "error_description": "「慎ましやかに」は控えめな様子を表すので、「大声で」とは意味が矛盾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "慎ましやかな", "is_correct": true, "explanation": "名詞「人」を修飾する連体形で、「慎ましやかな人だ」になる。"}, {"text": "慎ましやかに", "is_correct": false, "explanation": "連用形は動詞を修飾する形で、名詞「人」にはつながらない。"}, {"text": "慎ましやかだ", "is_correct": false, "explanation": "終止形は名詞の前に置けず、「慎ましやかだ人」は非文になる。"}, {"text": "慎ましやかさ", "is_correct": false, "explanation": "派生名詞で、「慎ましやかさ人だ」は形が合わない。"}], "correct_form": "慎ましやかな", "base_form": "慎ましやか", "form_label": "連体形", "sentence_index": 1, "explanations": {"慎ましやかな": "名詞「人」を修飾する連体形で、「慎ましやかな人だ」になる。", "慎ましやかに": "連用形は動詞を修飾する形で、名詞「人」にはつながらない。", "慎ましやかだ": "終止形は名詞の前に置けず、「慎ましやかだ人」は非文になる。", "慎ましやかさ": "派生名詞で、「慎ましやかさ人だ」は形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は慎ましやかで、いつも派手な服を着ている。", "corrected_sentence": "彼女は慎ましやかで、いつも地味な服を着ている。", "error_description": "「慎ましやか」は控えめな様子を表すので、「派手な服」とは意味が矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "慎ましやか", "is_correct": true, "explanation": "語幹に「だ」が付いて、「慎ましやかだ」になる。"}, {"text": "慎ましやかな", "is_correct": false, "explanation": "連体形で、「だ」の前には置けず「慎ましやかなだ」は非文になる。"}, {"text": "慎ましやかに", "is_correct": false, "explanation": "連用形で、「慎ましやかにだ」は非文になる。"}, {"text": "慎ましやかだ", "is_correct": false, "explanation": "終止形で、すでに「だ」を含むので「慎ましやかだだ」になってしまう。"}], "correct_form": "慎ましやか", "base_form": "慎ましやか", "form_label": "語幹", "sentence_index": 7, "explanations": {"慎ましやか": "語幹に「だ」が付いて、「慎ましやかだ」になる。", "慎ましやかな": "連体形で、「だ」の前には置けず「慎ましやかなだ」は非文になる。", "慎ましやかに": "連用形で、「慎ましやかにだ」は非文になる。", "慎ましやかだ": "終止形で、すでに「だ」を含むので「慎ましやかだだ」になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
