INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52699, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目をパッと閉じてすぐに開けること。", "primary_collocate": "目", "pronunciation": "しばたたく", "ipa": "ɕibatatakɯ", "syllable_count": 5, "sentences": [{"text": "彼は瞬いた。", "target_word": "瞬いた", "complexity_tier": "T1", "furigana": "彼[かれ]は瞬[しばたた]いた。", "sentence_source": "generated"}, {"text": "少女は目を瞬きました。", "target_word": "瞬き", "complexity_tier": "T2", "furigana": "少女[しょうじょ]は目[め]を瞬[しばたた]きました。", "sentence_source": "generated"}, {"text": "光に驚いて、目を瞬いた。", "target_word": "瞬いた", "complexity_tier": "T3", "furigana": "光[ひかり]に驚[おどろ]いて、目[め]を瞬[しばたた]いた。", "sentence_source": "generated"}, {"text": "彼は二、三度瞬いてから、口を開いた。", "target_word": "瞬いて", "complexity_tier": "T3", "furigana": "彼[かれ]は二[に]、三度[さんど]瞬[しばたた]いてから、口[くち]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "犬が眩しそうに瞬いている。", "target_word": "瞬いている", "complexity_tier": "T3", "furigana": "犬[いぬ]が眩[まぶ]しそうに瞬[しばたた]いている。", "sentence_source": "generated"}, {"text": "瞬くと、涙が一粒ほおを伝った。", "target_word": "瞬く", "complexity_tier": "T3", "furigana": "瞬[しばたた]くと、涙[なみだ]が一粒[ひとつぶ]ほおを伝[つた]った。", "sentence_source": "generated"}, {"text": "赤ちゃんは大きな目をぱちぱちと瞬いた。", "target_word": "瞬いた", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは大[おお]きな目[め]をぱちぱちと瞬[しばたた]いた。", "sentence_source": "generated"}, {"text": "目に砂が入ったので、何度も瞬いてみた。", "target_word": "瞬いて", "complexity_tier": "T3", "furigana": "目[め]に砂[すな]が入[はい]ったので、何度[なんど]も瞬[しばたた]いてみた。", "sentence_source": "generated"}, {"text": "瞬かないようにがんばったが、すぐ目が痛くなった。", "target_word": "瞬かない", "complexity_tier": "T4", "furigana": "瞬[しばたた]かないようにがんばったが、すぐ目[め]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "眠そうに瞬く子どもを、そっと布団に寝かせた。", "target_word": "瞬く", "complexity_tier": "T4", "furigana": "眠[ねむ]そうに瞬[しばたた]く子[こ]どもを、そっと布団[ふとん]に寝[ね]かせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞬いた", "label": "活用"}, {"form": "瞬かない", "label": "活用"}, {"form": "瞬かせる", "label": "活用"}, {"form": "瞬き", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 目をぱっと閉じてすぐ開ける", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞬いた", "is_correct": true, "explanation": "人の動作として自然に成り立つ。"}, {"text": "咲いた", "is_correct": false, "explanation": "形は合うが、人には使えず意味が合わない。"}, {"text": "溶けた", "is_correct": false, "explanation": "形は合うが、人が溶けることはなく意味が合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "形は合うが、人が割れることはなく意味が合わない。"}], "explanations": {"瞬いた": "人の動作として自然に成り立つ。", "咲いた": "形は合うが、人には使えず意味が合わない。", "溶けた": "形は合うが、人が溶けることはなく意味が合わない。", "割れた": "形は合うが、人が割れることはなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "瞬いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は重い荷物を瞬いて運んだ。", "explanation": "「瞬く」は荷物を運ぶ動作を表さない。"}, {"text": "雨が屋根を瞬いて降った。", "explanation": "「瞬く」は雨が降る様子には使えない。"}, {"text": "私は昨日の宿題を瞬いて終えた。", "explanation": "「瞬く」は宿題を終える意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞬いた", "is_correct": true, "explanation": "赤ちゃんが目をぱちぱちさせる動作に合う。"}, {"text": "溶けた", "is_correct": false, "explanation": "形は合うが、赤ちゃんの目の動きとして意味が合わない。"}, {"text": "枯れた", "is_correct": false, "explanation": "形は合うが、「ぱちぱちと」と意味が合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "形は合うが、目を対象とする動作として意味が合わない。"}], "explanations": {"瞬いた": "赤ちゃんが目をぱちぱちさせる動作に合う。", "溶けた": "形は合うが、赤ちゃんの目の動きとして意味が合わない。", "枯れた": "形は合うが、「ぱちぱちと」と意味が合わない。", "割れた": "形は合うが、目を対象とする動作として意味が合わない。"}, "sentence_index": 6, "correct_answer": "瞬いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもは眠くて、足を瞬きながら歩いた。", "explanation": "「瞬く」は目の動作で、足には使えない。"}, {"text": "彼は紙を瞬いて折り畳んだ。", "explanation": "「瞬く」は紙を折る動作を表さない。"}, {"text": "犬が嬉しそうにしっぽを瞬いている。", "explanation": "しっぽを振る動作に「瞬く」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "光に驚いて、口を瞬いた。", "corrected_sentence": "光に驚いて、目を瞬いた。", "error_description": "「瞬く」の対象は目で、「口」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "瞬き", "is_correct": true, "explanation": "「ました」につながる連用形。"}, {"text": "瞬く", "is_correct": false, "explanation": "終止形は「ました」につながらない。"}, {"text": "瞬いた", "is_correct": false, "explanation": "過去形は「ました」につながらない。"}, {"text": "瞬いて", "is_correct": false, "explanation": "て形は「ました」につながらない。"}], "correct_form": "瞬き", "base_form": "瞬く", "form_label": "連用形", "sentence_index": 1, "explanations": {"瞬き": "「ました」につながる連用形。", "瞬く": "終止形は「ました」につながらない。", "瞬いた": "過去形は「ました」につながらない。", "瞬いて": "て形は「ました」につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
