INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52701, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みずがなくなること。", "primary_collocate": null, "pronunciation": "かわく", "ipa": "kawaku", "syllable_count": 3, "sentences": [{"text": "晴れた日は、洗った服がすぐに乾く。", "target_word": "乾く", "complexity_tier": "T3", "furigana": "晴(は)れた日(ひ)は、洗(あら)った服(ふく)がすぐに乾(かわ)く。", "sentence_source": "generated"}, {"text": "洗濯物は天気がいいので、すぐに乾きます。", "target_word": "乾きます", "complexity_tier": "T3", "furigana": "洗濯物(せんたくもの)は天気(てんき)がいいので、すぐに乾(かわ)きます。", "sentence_source": "generated"}, {"text": "雨がふらなくて、庭の土が乾いてしまいました。", "target_word": "乾いて", "complexity_tier": "T3", "furigana": "雨(あめ)がふらなくて、庭(にわ)の土(つち)が乾(かわ)いてしまいました。", "sentence_source": "generated"}, {"text": "ペンキが乾くまで、さわらないでください。", "target_word": "乾く", "complexity_tier": "T3", "furigana": "ペンキが乾(かわ)くまで、さわらないでください。", "sentence_source": "generated"}, {"text": "髪がまだ乾いていないので、外へ出ません。", "target_word": "乾いて", "complexity_tier": "T3", "furigana": "髪(かみ)がまだ乾(かわ)いていないので、外(そと)へ出(で)ません。", "sentence_source": "generated"}, {"text": "雨の日は部屋の中に干しても、なかなか乾かない。", "target_word": "乾かない", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)は部屋(へや)の中(なか)に干(ほ)しても、なかなか乾(かわ)かない。", "sentence_source": "generated"}, {"text": "絵の具が乾いてから、次の色をぬりましょう。", "target_word": "乾いて", "complexity_tier": "T3", "furigana": "絵(え)の具(ぐ)が乾(かわ)いてから、次(つぎ)の色(いろ)をぬりましょう。", "sentence_source": "generated"}, {"text": "タオルがよく乾いたので、たたんでしまいました。", "target_word": "乾いた", "complexity_tier": "T3", "furigana": "タオルがよく乾(かわ)いたので、たたんでしまいました。", "sentence_source": "generated"}, {"text": "風が強いと、洗濯物は早く乾きます。", "target_word": "乾きます", "complexity_tier": "T3", "furigana": "風(かぜ)が強(つよ)いと、洗濯物(せんたくもの)は早(はや)く乾(かわ)きます。", "sentence_source": "generated"}, {"text": "川の水が少なくなり、底が乾いて白くなりました。", "target_word": "乾いて", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)が少(すく)なくなり、底(そこ)が乾(かわ)いて白(しろ)くなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾く", "label": "基本形"}, {"form": "乾いた", "label": "た形"}, {"form": "乾いて", "label": "て形"}, {"form": "乾かない", "label": "ない形"}, {"form": "乾きます", "label": "ます形"}, {"form": "乾けば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "洗濯物・髪・絵の具・土などから水分がなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乾く", "is_correct": true, "explanation": "洗った服から水気がなくなる意味で、「すぐに」と合う。"}, {"text": "燃える", "is_correct": false, "explanation": "服が燃えることは、洗った服の水気がなくなる話として意味が合わない。"}, {"text": "割れる", "is_correct": false, "explanation": "割れるは物が壊れる意味で、服の状態変化として合わない。"}, {"text": "光る", "is_correct": false, "explanation": "光るは輝く意味で、洗った服が「すぐに」そうなる文にはならない。"}], "explanations": {"乾く": "洗った服から水気がなくなる意味で、「すぐに」と合う。", "燃える": "服が燃えることは、洗った服の水気がなくなる話として意味が合わない。", "割れる": "割れるは物が壊れる意味で、服の状態変化として合わない。", "光る": "光るは輝く意味で、洗った服が「すぐに」そうなる文にはならない。"}, "sentence_index": 0, "correct_answer": "乾く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になって、屋根の雪が乾いて、川に流れていった。", "explanation": "ここは〈溶ける〉の意味。乾くは水分が減ることで、雪が液体になって流れる変化は表さないので合わない。"}, {"text": "大雨の中を歩いて、服がぐっしょり乾いた。", "explanation": "ここは〈濡れる〉の意味。乾くは水分がなくなることなので、水を含んだ状態には使えない。"}, {"text": "スープが熱すぎるので、乾くまで待った。", "explanation": "ここは〈冷める〉の意味。乾くは水分がなくなることで、温度が下がる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乾いて", "is_correct": true, "explanation": "「絵の具が」を受けて「から」に続く、乾いた状態を表すて形。"}, {"text": "凍って", "is_correct": false, "explanation": "絵の具が凍るという状態は文の流れに合わず、次の色を塗る前提にならない。"}, {"text": "縮んで", "is_correct": false, "explanation": "絵の具が縮むという変化は、塗る前の状態として不自然。"}, {"text": "曲がって", "is_correct": false, "explanation": "絵の具が曲がるという言い方は、塗る前の状態として意味が通らない。"}], "explanations": {"乾いて": "「絵の具が」を受けて「から」に続く、乾いた状態を表すて形。", "凍って": "絵の具が凍るという状態は文の流れに合わず、次の色を塗る前提にならない。", "縮んで": "絵の具が縮むという変化は、塗る前の状態として不自然。", "曲がって": "絵の具が曲がるという言い方は、塗る前の状態として意味が通らない。"}, "sentence_index": 6, "correct_answer": "乾いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕日が乾いて、海の向こうへ沈んでいった。", "explanation": "ここは〈沈む〉の意味。乾くは水分がなくなることで、太陽が沈む動きには使わない。"}, {"text": "寒い朝は窓が乾いて、外が見えない。", "explanation": "ここは〈曇る〉の意味。乾くは水気が減ることで、表面が白くかすむ現象には使わない。"}, {"text": "夜空で星が乾いて、とてもきれいだった。", "explanation": "ここは〈光る〉の意味。乾くは水気がなくなることで、星の輝きには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンキが乾くに、窓を開けておいてください。", "corrected_sentence": "ペンキが乾くまで、窓を開けておいてください。", "error_description": "時間の終点を表すには「まで」を使う。「乾くに」は動詞に「に」が直接ついており誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "乾きます", "is_correct": true, "explanation": "文末のていねい形で、「洗濯物は…いいので」に続く丁寧な文体に合う。"}, {"text": "乾いて", "is_correct": false, "explanation": "て形は文を言い切れないため、文末には置けない。"}, {"text": "乾けば", "is_correct": false, "explanation": "仮定形は「～ば」の後に続く形で、この文を終えられない。"}, {"text": "乾いたら", "is_correct": false, "explanation": "たら形は条件を表し、「すぐに乾いたら」で文を言い切れないため不自然。"}], "correct_form": "乾きます", "base_form": "乾く", "form_label": "ます形", "sentence_index": 1, "explanations": {"乾きます": "文末のていねい形で、「洗濯物は…いいので」に続く丁寧な文体に合う。", "乾いて": "て形は文を言い切れないため、文末には置けない。", "乾けば": "仮定形は「～ば」の後に続く形で、この文を終えられない。", "乾いたら": "たら形は条件を表し、「すぐに乾いたら」で文を言い切れないため不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "糊が乾いていから、紙を重ねてください。", "corrected_sentence": "糊が乾いてから、紙を重ねてください。", "error_description": "「乾いて」に「から」を続けるのが正しい。「乾いてい」と余分な「い」を付けると、活用が誤りになる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "乾いた", "is_correct": true, "explanation": "た形で、「ので」の前に過去の結果を置く形になり、「たたんでしまいました」と時制が合う。"}, {"text": "乾け", "is_correct": false, "explanation": "命令形は「乾けので」と続けられず、文として成り立たない。"}, {"text": "乾いたり", "is_correct": false, "explanation": "「たり」は並列の列挙形で、「ので」に直接続かないため、文が成り立たない。"}, {"text": "乾こう", "is_correct": false, "explanation": "意志形は「乾こうので」と続けられず、文が成り立たない。"}], "correct_form": "乾いた", "base_form": "乾く", "form_label": "た形", "sentence_index": 7, "explanations": {"乾いた": "た形で、「ので」の前に過去の結果を置く形になり、「たたんでしまいました」と時制が合う。", "乾け": "命令形は「乾けので」と続けられず、文として成り立たない。", "乾いたり": "「たり」は並列の列挙形で、「ので」に直接続かないため、文が成り立たない。", "乾こう": "意志形は「乾こうので」と続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52703, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「闇色の夜」で名詞を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「闇色を夜」では修飾関係にならない。"}, {"text": "ね", "is_correct": false, "explanation": "終助詞のため名詞の間には入らない。"}, {"text": "ば", "is_correct": false, "explanation": "条件の「ば」は名詞の後にこの形で入らない。"}], "correct_answer": "の", "explanations": {"の": "「闇色の夜」で名詞を修飾する。", "を": "「闇色を夜」では修飾関係にならない。", "ね": "終助詞のため名詞の間には入らない。", "ば": "条件の「ば」は名詞の後にこの形で入らない。"}, "error_tags": {"を": "object_marker", "ね": "sentence_final", "ば": "conditional"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52703, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「闇色の使うと」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「闇色と使う」では「使う」の対象にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「闇色へ使う」は方向になり意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の対象を示す。", "の": "「闇色の使うと」は文法的に成り立たない。", "と": "「闇色と使う」では「使う」の対象にならず文が成り立たない。", "へ": "「闇色へ使う」は方向になり意味が通らない。"}, "error_tags": {"の": "possessive", "と": "quotation_or_comitative", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52703, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "やみいろは、くらい、まっくろな色のことです。", "primary_collocate": null, "pronunciation": "やみいろ", "ipa": "jamiiɾo", "syllable_count": 4, "sentences": [{"text": "闇色は黒い色だ。", "target_word": "闇色", "complexity_tier": "T1", "furigana": "闇色[やみいろ]は黒[くろ]い色[いろ]だ。", "sentence_source": "generated"}, {"text": "闇色の夜が来た。", "target_word": "闇色", "complexity_tier": "T1", "furigana": "闇色[やみいろ]の夜[よる]が来[き]た。", "sentence_source": "generated"}, {"text": "部屋の中は闇色だった。", "target_word": "闇色", "complexity_tier": "T2", "furigana": "部屋[へや]の中[なか]は闇色[やみいろ]だった。", "sentence_source": "generated"}, {"text": "古い扉を闇色に塗った。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "古[ふる]い扉[とびら]を闇色[やみいろ]に塗[ぬ]った。", "sentence_source": "generated"}, {"text": "彼は闇色の服ばかり着る。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "彼[かれ]は闇色[やみいろ]の服[ふく]ばかり着[き]る。", "sentence_source": "generated"}, {"text": "森の奥は、闇色に沈んでいた。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]は、闇色[やみいろ]に沈[しず]んでいた。", "sentence_source": "generated"}, {"text": "闇色が濃くなると、星がよく見える。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "闇色[やみいろ]が濃[こ]くなると、星[ほし]がよく見[み]える。", "sentence_source": "generated"}, {"text": "闇色を使うと、絵が引き締まる。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "闇色[やみいろ]を使[つか]うと、絵[え]が引[ひ]き締[し]まる。", "sentence_source": "generated"}, {"text": "闇色の猫が、音もなく塀を歩いていく。", "target_word": "闇色", "complexity_tier": "T4", "furigana": "闇色[やみいろ]の猫[ねこ]が、音[おと]もなく塀[へい]を歩[ある]いていく。", "sentence_source": "generated"}, {"text": "湖は闇色をたたえて、静かに横たわっていた。", "target_word": "闇色", "complexity_tier": "T4", "furigana": "湖[みずうみ]は闇色[やみいろ]をたたえて、静[しず]かに横[よこ]たわっていた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 暗くて真っ黒な色", 