INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闇色", "is_correct": true, "explanation": "「黒い色だ」と説明できる色の名称。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段は「黒い色」ではなく意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節は「黒い色」ではなく意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、時間は「黒い色」ではなく意味が合わない。"}], "explanations": {"闇色": "「黒い色だ」と説明できる色の名称。", "値段": "形は合うが、値段は「黒い色」ではなく意味が合わない。", "季節": "形は合うが、季節は「黒い色」ではなく意味が合わない。", "時間": "形は合うが、時間は「黒い色」ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "闇色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "闇色の音が窓から聞こえてきた。", "explanation": "「闇色」は色であり、音を修飾できない。"}, {"text": "私は闇色を持って電車に乗った。", "explanation": "「闇色」は色の名称で、持てる物ではない。"}, {"text": "先生は闇色に宿題を出した。", "explanation": "「闇色」は人ではなく色で、宿題を出す相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b7bddc-7d45-4858-8be6-dcf487a42af0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
