INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "暗闇のような色、すなわち深い黒色。", "primary_collocate": null, "pronunciation": "やみいろ", "ipa": "jamiiɾo", "syllable_count": 4, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "闇色", "complexity_tier": "T6", "furigana": "水[みず]は瞬[またた]く間[ま]に闇色[やみいろ]の大地[だいち]へと吸[す]い込[こ]まれ、やがて目[め]に見[み]えぬ根[ね]の網目[あみめ]へと伝[つた]わっていくだろう。", "sentence_source": "mined"}, {"text": "闇色の空だ。", "target_word": "闇色", "complexity_tier": "T1", "furigana": "闇色[やみいろ]の空[そら]だ。", "sentence_source": "generated"}, {"text": "闇色の布を買った。", "target_word": "闇色", "complexity_tier": "T2", "furigana": "闇色[やみいろ]の布[ぬの]を買[か]った。", "sentence_source": "generated"}, {"text": "空はやがて闇色に染まった。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "空[そら]はやがて闇色[やみいろ]に染[そ]まった。", "sentence_source": "generated"}, {"text": "彼女の瞳は闇色をしている。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の瞳[ひとみ]は闇色[やみいろ]をしている。", "sentence_source": "generated"}, {"text": "闇色が部屋の隅に広がっていた。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "闇色[やみいろ]が部屋[へや]の隅[すみ]に広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "闇色の髪が風に揺れた。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "闇色[やみいろ]の髪[かみ]が風[かぜ]に揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "闇色は、深い黒を表す言葉だ。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "闇色[やみいろ]は、深[ふか]い黒[くろ]を表[あらわ]す言葉[ことば]だ。", "sentence_source": "generated"}, {"text": "絵の具を混ぜて、闇色を作ってみた。", "target_word": "闇色", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]を混[ま]ぜて、闇色[やみいろ]を作[つく]ってみた。", "sentence_source": "generated"}, {"text": "窓の外には闇色の海が広がり、波の音だけが聞こえた。", "target_word": "闇色", "complexity_tier": "T4", "furigana": "窓[まど]の外[そと]には闇色[やみいろ]の海[うみ]が広[ひろ]がり、波[なみ]の音[おと]だけが聞[き]こえた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 暗闇のような深い黒色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b821092b-d82e-4161-8a52-bbf4d4a990b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
