INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52705, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手に持ったものを下の方へ動かす。", "primary_collocate": null, "pronunciation": "おろす", "ipa": "oɾosɯ", "syllable_count": 3, "sentences": [{"text": "荷物を下ろす。", "target_word": "下ろす", "complexity_tier": "T1", "furigana": "荷物[にもつ]を下[お]ろす。", "sentence_source": "generated"}, {"text": "彼は鞄を床に下ろした。", "target_word": "下ろした", "complexity_tier": "T2", "furigana": "彼[かれ]は鞄[かばん]を床[ゆか]に下[お]ろした。", "sentence_source": "generated"}, {"text": "かばんを下ろして、座った。", "target_word": "下ろして", "complexity_tier": "T3", "furigana": "かばんを下[お]ろして、座[すわ]った。", "sentence_source": "generated"}, {"text": "重い箱を机に下ろします。", "target_word": "下ろします", "complexity_tier": "T2", "furigana": "重[おも]い箱[はこ]を机[つくえ]に下[お]ろします。", "sentence_source": "generated"}, {"text": "手に持った傘を下ろしてください。", "target_word": "下ろして", "complexity_tier": "T3", "furigana": "手[て]に持[も]った傘[かさ]を下[お]ろしてください。", "sentence_source": "generated"}, {"text": "花瓶をそっと下ろしている。", "target_word": "下ろしている", "complexity_tier": "T3", "furigana": "花瓶[かびん]をそっと下[お]ろしている。", "sentence_source": "generated"}, {"text": "両手の荷物を下ろせば、楽になる。", "target_word": "下ろせば", "complexity_tier": "T4", "furigana": "両手[りょうて]の荷物[にもつ]を下[お]ろせば、楽[らく]になる。", "sentence_source": "generated"}, {"text": "彼が下ろした箱は、とても大きかった。", "target_word": "下ろした", "complexity_tier": "T3", "furigana": "彼[かれ]が下[お]ろした箱[はこ]は、とても大[おお]きかった。", "sentence_source": "generated"}, {"text": "弟に荷物を下ろさせた。", "target_word": "下ろさせた", "complexity_tier": "T4", "furigana": "弟[おとうと]に荷物[にもつ]を下[お]ろさせた。", "sentence_source": "generated"}, {"text": "重くて、すぐには下ろせない。", "target_word": "下ろせない", "complexity_tier": "T3", "furigana": "重[おも]くて、すぐには下[お]ろせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下ろした", "label": "活用"}, {"form": "下ろして", "label": "活用"}, {"form": "下ろせる", "label": "活用"}, {"form": "下ろさせる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 手に持った物を下へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52705, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下ろす", "is_correct": true, "explanation": "荷物を下へ動かす意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、荷物を食べるという意味が合わない。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが、荷物を読むという意味が合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが、荷物を歌うという意味が合わない。"}], "explanations": {"下ろす": "荷物を下へ動かす意味に合う。", "食べる": "形は合うが、荷物を食べるという意味が合わない。", "読む": "形は合うが、荷物を読むという意味が合わない。", "歌う": "形は合うが、荷物を歌うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "下ろす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒って、大きな声を床に下ろした。", "explanation": "声は手に持つ物ではなく、「声を下ろす」という言い方は成り立たない。"}, {"text": "先生は黒板の文字を机に下ろしてから、授業を始めた。", "explanation": "文字は手に持って動かせず、下ろすの対象にならない。"}, {"text": "軽い羽を空の上へ下ろします。", "explanation": "「下ろす」は下へ動かすので、空の上へという方向が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52705, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下ろせば", "is_correct": true, "explanation": "荷物を下へ置けば楽になる、という意味に合う。"}, {"text": "食べれば", "is_correct": false, "explanation": "形は合うが、荷物を食べるという意味が合わない。"}, {"text": "読めば", "is_correct": false, "explanation": "形は合うが、荷物を読むという意味が合わない。"}, {"text": "洗えば", "is_correct": false, "explanation": "形は合うが、両手の荷物を洗うでは楽になる文脈に意味が合わない。"}], "explanations": {"下ろせば": "荷物を下へ置けば楽になる、という意味に合う。", "食べれば": "形は合うが、荷物を食べるという意味が合わない。", "読めば": "形は合うが、荷物を読むという意味が合わない。", "洗えば": "形は合うが、両手の荷物を洗うでは楽になる文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "下ろせば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は悲しい気持ちを机に下ろして、泣き出した。", "explanation": "気持ちは手に持つ物ではなく、「気持ちを下ろす」とは言えない。"}, {"text": "窓から見える星を下ろして、ポケットに入れた。", "explanation": "星は手に持って下ろせる物ではなく、対象を誤っている。"}, {"text": "電話が鳴ったので、ベルを下ろして出た。", "explanation": "ベルを下ろすとは言わず、手に持った物を下へ動かす意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
