INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52706, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を高い位置から低い位置へ移動させる。または、体の一部を上から下へ動かす。", "primary_collocate": null, "pronunciation": "おろす", "ipa": "oɾosɯ", "syllable_count": 3, "sentences": [{"text": "上げた手を静かに下ろす。", "target_word": "下ろす", "complexity_tier": "T2", "furigana": "上[あ]げた手[て]を静[しず]かに下[お]ろす。", "sentence_source": "generated"}, {"text": "棚から箱を下ろす。", "target_word": "下ろす", "complexity_tier": "T1", "furigana": "棚[たな]から箱[はこ]を下[お]ろす。", "sentence_source": "generated"}, {"text": "荷物を下ろしました。", "target_word": "下ろしました", "complexity_tier": "T2", "furigana": "荷物[にもつ]を下[お]ろしました。", "sentence_source": "generated"}, {"text": "腕をゆっくり下ろしてください。", "target_word": "下ろして", "complexity_tier": "T3", "furigana": "腕[うで]をゆっくり下[お]ろしてください。", "sentence_source": "generated"}, {"text": "旗を下ろす時間になった。", "target_word": "下ろす", "complexity_tier": "T2", "furigana": "旗[はた]を下[お]ろす時間[じかん]になった。", "sentence_source": "generated"}, {"text": "重い荷物を車から下ろしている。", "target_word": "下ろしている", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を車[くるま]から下[お]ろしている。", "sentence_source": "generated"}, {"text": "手を下ろしても、まだ腕が震えていた。", "target_word": "下ろしても", "complexity_tier": "T3", "furigana": "手[て]を下[お]ろしても、まだ腕[うで]が震[ふる]えていた。", "sentence_source": "generated"}, {"text": "背中のリュックを下ろせば、少し楽になる。", "target_word": "下ろせば", "complexity_tier": "T4", "furigana": "背中[せなか]のリュックを下[お]ろせば、少[すこ]し楽[らく]になる。", "sentence_source": "generated"}, {"text": "箱は昨日、店の人に棚から下ろされた。", "target_word": "下ろされた", "complexity_tier": "T4", "furigana": "箱[はこ]は昨日[きのう]、店[みせ]の人[ひと]に棚[たな]から下[お]ろされた。", "sentence_source": "generated"}, {"text": "彼は肩の荷物を下ろさなかった。", "target_word": "下ろさなかった", "complexity_tier": "T3", "furigana": "彼[かれ]は肩[かた]の荷物[にもつ]を下[お]ろさなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下ろした", "label": "活用"}, {"form": "下ろして", "label": "活用"}, {"form": "下ろせる", "label": "活用"}, {"form": "下ろされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物や体の一部を上から下へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下ろす", "is_correct": true, "explanation": "上げた手を下へ動かす意味に合う。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが、手を読むという意味が合わない。"}, {"text": "聞く", "is_correct": false, "explanation": "形は合うが、手を聞くという意味が合わない。"}, {"text": "飲む", "is_correct": false, "explanation": "形は合うが、手を飲むという意味が合わない。"}], "explanations": {"下ろす": "上げた手を下へ動かす意味に合う。", "読む": "形は合うが、手を読むという意味が合わない。", "聞く": "形は合うが、手を聞くという意味が合わない。", "飲む": "形は合うが、手を飲むという意味が合わない。"}, "sentence_index": 0, "correct_answer": "下ろす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "気球をゆっくり空の高い所へ下ろした。", "explanation": "「下ろす」は上から下へ動かすので、高い所へ動かす文には使えない。"}, {"text": "友達に電話を下ろして、明日の予定を聞いた。", "explanation": "「電話を下ろす」とは言わず、「かける」を使うべきで、下ろすの用法を誤っている。"}, {"text": "窓の外の景色を下ろして、写真を撮った。", "explanation": "景色は手で動かせる物ではなく、「下ろす」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下ろしても", "is_correct": true, "explanation": "手を下げても腕が震える、という意味に合う。"}, {"text": "食べても", "is_correct": false, "explanation": "形は合うが、手を食べるという意味が合わない。"}, {"text": "買っても", "is_correct": false, "explanation": "形は合うが、手を買うという意味が合わない。"}, {"text": "数えても", "is_correct": false, "explanation": "形は合うが、手を数えるでは文脈に意味が合わない。"}], "explanations": {"下ろしても": "手を下げても腕が震える、という意味に合う。", "食べても": "形は合うが、手を食べるという意味が合わない。", "買っても": "形は合うが、手を買うという意味が合わない。", "数えても": "形は合うが、手を数えるでは文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "下ろしても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は夢を下ろして、将来の計画を立てた。", "explanation": "「夢を下ろす」という言い方はなく、下ろすの対象を誤っている。"}, {"text": "空に浮かぶ雲を下ろして、袋に詰めた。", "explanation": "雲は手で動かせる物ではなく、「下ろす」の対象にならない。"}, {"text": "電話が鳴ったので、ベルを下ろして出た。", "explanation": "ベルを下ろすとは言わず、物を下へ動かす意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷物が棚から下ろした。", "corrected_sentence": "荷物を棚から下ろした。", "error_description": "「下ろす」の対象を示す助詞は「が」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下ろす", "is_correct": true, "explanation": "文末の終止形で文が成り立つ。"}, {"text": "下ろし", "is_correct": false, "explanation": "連用形だけでは文が終わらない。"}, {"text": "下ろされ", "is_correct": false, "explanation": "受身の連用形では文が終わらない。"}, {"text": "下ろさ", "is_correct": false, "explanation": "未然形の語幹だけでは文が終わらない。"}], "correct_form": "下ろす", "base_form": "下ろす", "form_label": "終止形", "sentence_index": 1, "explanations": {"下ろす": "文末の終止形で文が成り立つ。", "下ろし": "連用形だけでは文が終わらない。", "下ろされ": "受身の連用形では文が終わらない。", "下ろさ": "未然形の語幹だけでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "肩のかばんを頭の上へ下ろした。", "corrected_sentence": "肩のかばんを足元へ下ろした。", "error_description": "「下ろす」は下へ動かすので、「頭の上へ」という行き先が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下ろせば", "is_correct": true, "explanation": "仮定形で「少し楽になる」へつながる。"}, {"text": "下ろされた", "is_correct": false, "explanation": "受身の過去形では「、少し楽になる」へ条件としてつながらない。"}, {"text": "下ろさせた", "is_correct": false, "explanation": "使役の過去形では後の文につながらない。"}, {"text": "下ろさ", "is_correct": false, "explanation": "未然形の語幹だけでは文が成り立たない。"}], "correct_form": "下ろせば", "base_form": "下ろす", "form_label": "仮定形", "sentence_index": 7, "explanations": {"下ろせば": "仮定形で「少し楽になる」へつながる。", "下ろされた": "受身の過去形では「、少し楽になる」へ条件としてつながらない。", "下ろさせた": "使役の過去形では後の文につながらない。", "下ろさ": "未然形の語幹だけでは文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
