INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52707, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水や空気が中に入っていくこと。", "primary_collocate": null, "pronunciation": "すいこむ", "ipa": "sɯikomɯ", "syllable_count": 4, "sentences": [{"text": "深く息を吸い込む。", "target_word": "吸い込む", "complexity_tier": "T1", "furigana": "深[ふか]く息[いき]を吸[す]い込[こ]む。", "sentence_source": "generated"}, {"text": "冷たい空気を吸い込みました。", "target_word": "吸い込みました", "complexity_tier": "T2", "furigana": "冷[つめ]たい空気[くうき]を吸[す]い込[こ]みました。", "sentence_source": "generated"}, {"text": "森の空気を吸い込んで、歩いた。", "target_word": "吸い込んで", "complexity_tier": "T3", "furigana": "森[もり]の空気[くうき]を吸[す]い込[こ]んで、歩[ある]いた。", "sentence_source": "generated"}, {"text": "煙を吸い込まないでください。", "target_word": "吸い込まないで", "complexity_tier": "T3", "furigana": "煙[けむり]を吸[す]い込[こ]まないでください。", "sentence_source": "generated"}, {"text": "赤ちゃんが大きく息を吸い込んでいる。", "target_word": "吸い込んでいる", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが大[おお]きく息[いき]を吸[す]い込[こ]んでいる。", "sentence_source": "generated"}, {"text": "水を吸い込んでしまって、むせた。", "target_word": "吸い込んで", "complexity_tier": "T3", "furigana": "水[みず]を吸[す]い込[こ]んでしまって、むせた。", "sentence_source": "generated"}, {"text": "空気を吸い込めば、気持ちが落ち着く。", "target_word": "吸い込めば", "complexity_tier": "T4", "furigana": "空気[くうき]を吸[す]い込[こ]めば、気持[きも]ちが落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "粉を吸い込んだ人は、せきが出た。", "target_word": "吸い込んだ", "complexity_tier": "T3", "furigana": "粉[こな]を吸[す]い込[こ]んだ人[ひと]は、せきが出[で]た。", "sentence_source": "generated"}, {"text": "掃除機が埃を吸い込む音がした。", "target_word": "吸い込む", "complexity_tier": "T3", "furigana": "掃除機[そうじき]が埃[ほこり]を吸[す]い込[こ]む音[おと]がした。", "sentence_source": "generated"}, {"text": "息を吸い込んでから、水にもぐった。", "target_word": "吸い込んで", "complexity_tier": "T3", "furigana": "息[いき]を吸[す]い込[こ]んでから、水[みず]にもぐった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸い込んだ", "label": "活用"}, {"form": "吸い込まれる", "label": "活用"}, {"form": "吸い込める", "label": "活用"}, {"form": "吸い込み", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 水や空気が体や物の中に入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52707, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吸い込む", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "かいこむ", "is_correct": false, "explanation": "一拍目だけが違う別の語(買い込む)。"}, {"text": "おいこむ", "is_correct": false, "explanation": "一拍目だけが違う別の語(追い込む)。"}, {"text": "すりこむ", "is_correct": false, "explanation": "二拍目だけが違う別の語(刷り込む)。"}], "explanations": {"吸い込む": "見出し語そのもの。", "かいこむ": "一拍目だけが違う別の語(買い込む)。", "おいこむ": "一拍目だけが違う別の語(追い込む)。", "すりこむ": "二拍目だけが違う別の語(刷り込む)。"}, "sentence_index": null, "correct_answer": "吸い込む"}, "level_3": {"options": [{"text": "吸い込む", "is_correct": true, "explanation": "息を体の中に入れる意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、息を食べるという意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、息を洗うという意味が合わない。"}, {"text": "数える", "is_correct": false, "explanation": "形は合うが、深く息を数えるでは意味が合わない。"}], "explanations": {"吸い込む": "息を体の中に入れる意味に合う。", "食べる": "形は合うが、息を食べるという意味が合わない。", "洗う": "形は合うが、息を洗うという意味が合わない。", "数える": "形は合うが、深く息を数えるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "吸い込む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は手紙を机に吸い込んで、封筒に入れた。", "explanation": "手紙は気体や液体ではなく、「吸い込む」の対象にならない。"}, {"text": "彼は大きな声を吸い込んで、歌を歌った。", "explanation": "声は外へ出すもので、体に入れる「吸い込む」とは合わない。"}, {"text": "ボールを手で吸い込んで、遠くへ投げた。", "explanation": "ボールは気体や液体ではなく、吸い込むの対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52707, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吸い込む", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "まいこむ", "is_correct": false, "explanation": "一拍目だけが違う別の語(舞い込む)。"}, {"text": "すみこむ", "is_correct": false, "explanation": "二拍目だけが違う別の語(住み込む)。"}, {"text": "すいこう", "is_correct": false, "explanation": "最後の一拍だけが違う別の語(遂行)。"}], "explanations": {"吸い込む": "見出し語そのもの。", "まいこむ": "一拍目だけが違う別の語(舞い込む)。", "すみこむ": "二拍目だけが違う別の語(住み込む)。", "すいこう": "最後の一拍だけが違う別の語(遂行)。"}, "sentence_index": null, "correct_answer": "吸い込む"}, "level_3": {"options": [{"text": "吸い込めば", "is_correct": true, "explanation": "空気を体に入れれば落ち着く、という意味に合う。"}, {"text": "数えれば", "is_correct": false, "explanation": "形は合うが、空気を数えるでは意味が合わない。"}, {"text": "洗えば", "is_correct": false, "explanation": "形は合うが、空気を洗うでは落ち着く文脈に意味が合わない。"}, {"text": "切れば", "is_correct": false, "explanation": "形は合うが、空気を切るでは意味が合わない。"}], "explanations": {"吸い込めば": "空気を体に入れれば落ち着く、という意味に合う。", "数えれば": "形は合うが、空気を数えるでは意味が合わない。", "洗えば": "形は合うが、空気を洗うでは落ち着く文脈に意味が合わない。", "切れば": "形は合うが、空気を切るでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "吸い込めば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、傘を吸い込んでから、駅まで歩いた。", "explanation": "傘は気体や液体ではなく、「吸い込む」の対象にならない。"}, {"text": "彼は大きな荷物を頭の上に吸い込んで、山を登った。", "explanation": "荷物を持ち上げる意味で「吸い込む」は使えない。"}, {"text": "先生は難しい問題を黒板に吸い込んで、生徒に見せた。", "explanation": "問題を書くことを「吸い込む」とは言わず、用法が誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
