INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "雨が吸い込まれる先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「土を吸い込まれて」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「土の吸い込まれて」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「土と吸い込まれて」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "雨が吸い込まれる先を示す。", "を": "「土を吸い込まれて」は文として成り立たない。", "の": "「土の吸い込まれて」は文として成り立たない。", "と": "「土と吸い込まれて」は文として成り立たない。"}, "error_tags": {"を": "目的格", "の": "連体修飾", "と": "並列・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弾く", "is_correct": true, "explanation": "水を内部に入れず跳ね返す意味で、「吸い込む」と反対。"}, {"text": "注ぐ", "is_correct": false, "explanation": "液体を入れる動作で、吸い込むの反対ではない。"}, {"text": "包む", "is_correct": false, "explanation": "外から覆う動作で、反対の関係ではない。"}, {"text": "浴びる", "is_correct": false, "explanation": "水を受ける意味で、反対の関係ではない。"}], "correct_answer": "弾く", "explanations": {"弾く": "水を内部に入れず跳ね返す意味で、「吸い込む」と反対。", "注ぐ": "液体を入れる動作で、吸い込むの反対ではない。", "包む": "外から覆う動作で、反対の関係ではない。", "浴びる": "水を受ける意味で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体や気体などが、物の内部に入り込むこと。", "primary_collocate": null, "pronunciation": "すいこむ", "ipa": "sɯikomɯ", "syllable_count": 4, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "吸い込まれ", "complexity_tier": "T6", "furigana": "水[みず]は瞬[またた]く間[ま]に闇色[やみいろ]の大地[だいち]へと吸[す]い込[こ]まれ、やがて目[め]に見[み]えぬ根[ね]の網目[あみめ]へと伝[つた]わっていくだろう。", "sentence_source": "mined"}, {"text": "土が水を吸い込む。", "target_word": "吸い込む", "complexity_tier": "T1", "furigana": "土[つち]が水[みず]を吸[す]い込[こ]む。", "sentence_source": "generated"}, {"text": "スポンジは水をよく吸い込みます。", "target_word": "吸い込みます", "complexity_tier": "T2", "furigana": "スポンジは水[みず]をよく吸[す]い込[こ]みます。", "sentence_source": "generated"}, {"text": "布が汗を吸い込んでいる。", "target_word": "吸い込んでいる", "complexity_tier": "T3", "furigana": "布[ぬの]が汗[あせ]を吸[す]い込[こ]んでいる。", "sentence_source": "generated"}, {"text": "砂は雨を吸い込んで、すぐに乾いた。", "target_word": "吸い込んで", "complexity_tier": "T3", "furigana": "砂[すな]は雨[あめ]を吸[す]い込[こ]んで、すぐに乾[かわ]いた。", "sentence_source": "generated"}, {"text": "水を吸い込まない紙は、使いにくい。", "target_word": "吸い込まない", "complexity_tier": "T3", "furigana": "水[みず]を吸[す]い込[こ]まない紙[かみ]は、使[つか]いにくい。", "sentence_source": "generated"}, {"text": "この土は、雨水を吸い込みやすい。", "target_word": "吸い込みやすい", "complexity_tier": "T3", "furigana": "この土[つち]は、雨水[あまみず]を吸[す]い込[こ]みやすい。", "sentence_source": "generated"}, {"text": "雨が土に吸い込まれて、跡も残らなかった。", "target_word": "吸い込まれて", "complexity_tier": "T4", "furigana": "雨[あめ]が土[つち]に吸[す]い込[こ]まれて、跡[あと]も残[のこ]らなかった。", "sentence_source": "generated"}, {"text": "水を吸い込めば、パンは重くなる。", "target_word": "吸い込めば", "complexity_tier": "T4", "furigana": "水[みず]を吸[す]い込[こ]めば、パンは重[おも]くなる。", "sentence_source": "generated"}, {"text": "水を吸い込んだタオルを絞った。", "target_word": "吸い込んだ", "complexity_tier": "T3", "furigana": "水[みず]を吸[す]い込[こ]んだタオルを絞[しぼ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸い込んだ", "label": "活用"}, {"form": "吸い込まれる", "label": "活用"}, {"form": "吸い込める", "label": "活用"}, {"form": "吸い込み", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 液体や気体が物の内部に染み入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸い込まれ", "is_correct": true, "explanation": "水が大地の内部に入る意味に合う。"}, {"text": "笑われ", "is_correct": false, "explanation": "形は合うが、水が大地へ笑われるという意味が合わない。"}, {"text": "読まれ", "is_correct": false, "explanation": "形は合うが、水が読まれるという意味が合わない。"}, {"text": "閉ざされ", "is_correct": false, "explanation": "形は合うが、水が大地へ入る意味に合わない。"}], "explanations": {"吸い込まれ": "水が大地の内部に入る意味に合う。", "笑われ": "形は合うが、水が大地へ笑われるという意味が合わない。", "読まれ": "形は合うが、水が読まれるという意味が合わない。", "閉ざされ": "形は合うが、水が大地へ入る意味に合わない。"}, "sentence_index": 0, "correct_answer": "吸い込まれ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい服を店で吸い込んで、家に帰った。", "explanation": "服を買う意味で「吸い込む」は使えず、意味を誤っている。"}, {"text": "彼は友達に手紙を吸い込んで、返事を待った。", "explanation": "手紙を送ることを「吸い込む」とは言わず、液体や気体が入る意味にならない。"}, {"text": "ペンが紙に文字を吸い込んで、きれいに書いた。", "explanation": "文字を書くことを「吸い込む」とは言わず、用法が誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸い込みやすい", "is_correct": true, "explanation": "土が雨水を内部に染み入らせやすい意味に合う。"}, {"text": "食べやすい", "is_correct": false, "explanation": "形は合うが、雨水を食べるという意味が合わない。"}, {"text": "読みやすい", "is_correct": false, "explanation": "形は合うが、雨水を読むという意味が合わない。"}, {"text": "歌いやすい", "is_correct": false, "explanation": "形は合うが、雨水を歌うという意味が合わない。"}], "explanations": {"吸い込みやすい": "土が雨水を内部に染み入らせやすい意味に合う。", "食べやすい": "形は合うが、雨水を食べるという意味が合わない。", "読みやすい": "形は合うが、雨水を読むという意味が合わない。", "歌いやすい": "形は合うが、雨水を歌うという意味が合わない。"}, "sentence_index": 6, "correct_answer": "吸い込みやすい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は大きな石を吸い込んで、棚の上に置かれた。", "explanation": "石は液体や気体ではなく、内部に染み入らないので吸い込むが合わない。"}, {"text": "先生は黒板に書いた字を吸い込んで、生徒に読ませた。", "explanation": "字を書くことや示すことに「吸い込む」は使えない。"}, {"text": "彼は友達の悪口を吸い込んで、大声で笑った。", "explanation": "悪口は液体や気体ではなく、「吸い込む」の用法として誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "タオルが汗に吸い込んでいる。", "corrected_sentence": "タオルが汗を吸い込んでいる。", "error_description": "吸い込む対象は「に」ではなく「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "吸い込む", "is_correct": true, "explanation": "文末の終止形で文が成り立つ。"}, {"text": "吸い込んで", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "吸い込め", "is_correct": false, "explanation": "命令形・可能の語幹では、この平叙文に合わない。"}, {"text": "吸い込ま", "is_correct": false, "explanation": "未然形の語幹だけでは文が終わらない。"}], "correct_form": "吸い込む", "base_form": "吸い込む", "form_label": "終止形", "sentence_index": 1, "explanations": {"吸い込む": "文末の終止形で文が成り立つ。", "吸い込んで": "て形では文が終わらない。", "吸い込め": "命令形・可能の語幹では、この平叙文に合わない。", "吸い込ま": "未然形の語幹だけでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙はインクで吸い込んで、黒くなった。", "corrected_sentence": "紙はインクを吸い込んで、黒くなった。", "error_description": "吸い込む対象は「で」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "吸い込まれて", "is_correct": true, "explanation": "受身のて形で「土に」と自然につながる。"}, {"text": "吸い込んで", "is_correct": false, "explanation": "能動のため、雨が土に入る意味にならず合わない。"}, {"text": "吸い込ませて", "is_correct": false, "explanation": "使役のため、この文の意味に合わない。"}, {"text": "吸い込めて", "is_correct": false, "explanation": "可能のため、この文の意味に合わない。"}], "correct_form": "吸い込まれて", "base_form": "吸い込む", "form_label": "受身形+て", "sentence_index": 7, "explanations": {"吸い込まれて": "受身のて形で「土に」と自然につながる。", "吸い込んで": "能動のため、雨が土に入る意味にならず合わない。", "吸い込ませて": "使役のため、この文の意味に合わない。", "吸い込めて": "可能のため、この文の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大地を走り回りました」で、走り回る場所を目的語として示す「を」が入る。"}, {"text": "の", "is_correct": false, "explanation": "「大地の」は名詞を修飾する形で、動詞「走り回りました」の前には続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「大地へ走り回りました」は方向の「へ」で、この動詞の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「大地と走り回りました」は並列の「と」で、走り回る対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「大地を走り回りました」で、走り回る場所を目的語として示す「を」が入る。", "の": "「大地の」は名詞を修飾する形で、動詞「走り回りました」の前には続かず文が成り立たない。", "へ": "「大地へ走り回りました」は方向の「へ」で、この動詞の目的語にならない。", "と": "「大地と走り回りました」は並列の「と」で、走り回る対象として成り立たない。"}, "error_tags": {"の": "修飾", "へ": "方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「広い大地の上」で、大地を「上」の場所として修飾する「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「広い大地が上に」は大地を主語にすると場所の意味にならず、文が不自然。"}, {"text": "を", "is_correct": false, "explanation": "「広い大地を上に」は目的語の「を」を取り、位置を表す「上に」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「広い大地で上に」は手段・場所の「で」が「上」に続かず不自然。"}], "correct_answer": "の", "explanations": {"の": "「広い大地の上」で、大地を「上」の場所として修飾する「の」が入る。", "が": "「広い大地が上に」は大地を主語にすると場所の意味にならず、文が不自然。", "を": "「広い大地を上に」は目的語の「を」を取り、位置を表す「上に」と合わない。", "で": "「広い大地で上に」は手段・場所の「で」が「上」に続かず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面のこと。", "primary_collocate": null, "pronunciation": "だいち", "ipa": "daitɕi", "syllable_count": 3, "sentences": [{"text": "雨のあとの大地は、土のにおいがします。", "target_word": "大地", "complexity_tier": "T3", "furigana": "雨(あめ)のあとの大地(だいち)は、土(つち)のにおいがします。", "sentence_source": "generated"}, {"text": "子どもたちは、はだしで大地を走り回りました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "子(こ)どもたちは、はだしで大地(だいち)を走(はし)り回(まわ)りました。", "sentence_source": "generated"}, {"text": "大地がゆれて、棚の物が落ちました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "大地(だいち)がゆれて、棚(たな)の物(もの)が落(お)ちました。", "sentence_source": "generated"}, {"text": "長い船の旅のあと、やっと大地に足をつけて安心しました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "長(なが)い船(ふね)の旅(たび)のあと、やっと大地(だいち)に足(あし)をつけて安心(あんしん)しました。", "sentence_source": "generated"}, {"text": "農家の人たちは、大地に種をまいて、春を待ちます。", "target_word": "大地", "complexity_tier": "T3", "furigana": "農家(のうか)の人(ひと)たちは、大地(だいち)に種(たね)をまいて、春(はる)を待(ま)ちます。", "sentence_source": "generated"}, {"text": "雪がとけて、大地に緑の草がはえてきました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "雪(ゆき)がとけて、大地(だいち)に緑(みどり)の草(くさ)がはえてきました。", "sentence_source": "generated"}, {"text": "飛行機が着陸して、ひさしぶりに大地を踏みました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "飛行機(ひこうき)が着陸(ちゃくりく)して、ひさしぶりに大地(だいち)を踏(ふ)みました。", "sentence_source": "generated"}, {"text": "広い大地の上に、牛がゆっくり歩いています。", "target_word": "大地", "complexity_tier": "T3", "furigana": "広(ひろ)い大地(だいち)の上(うえ)に、牛(うし)がゆっくり歩(ある)いています。", "sentence_source": "generated"}, {"text": "日照りが続き、大地はひび割れてしまいました。", "target_word": "大地", "complexity_tier": "T3", "furigana": "日照(ひで)りが続(つづ)き、大地(だいち)はひび割(わ)れてしまいました。", "sentence_source": "generated"}, {"text": "木は大地に根をはって、強い風にたえます。", "target_word": "大地", "complexity_tier": "T3", "furigana": "木(き)は大地(だいち)に根(ね)をはって、強(つよ)い風(かぜ)にたえます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大地", "label": "基本形"}], "register": "中立（やや文章語的）", "sense_fingerprint": "人や動物が立つ、広い地面・土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "雨で土のにおいがする地面を指し、「雨のあとの」に続いて文の主語になる。"}, {"text": "空", "is_correct": false, "explanation": "空は上にある広がりで、土のにおいがするものとしては合わない。"}, {"text": "海", "is_correct": false, "explanation": "海は水の広がりで、雨のあとに土のにおいがするものとは言えない。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、雨のあとに土のにおいがするものとしては文が成り立たない。"}], "explanations": {"大地": "雨で土のにおいがする地面を指し、「雨のあとの」に続いて文の主語になる。", "空": "空は上にある広がりで、土のにおいがするものとしては合わない。", "海": "海は水の広がりで、雨のあとに土のにおいがするものとは言えない。", "机": "机は家具で、雨のあとに土のにおいがするものとしては文が成り立たない。"}, "sentence_index": 0, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の午後、窓にかけた大地のおかげで、部屋は涼しかった。", "explanation": "ここは〈カーテン〉の意味。大地は地面を指すので、窓にかける布の意味では使わない。"}, {"text": "寒かったので、厚手の大地を一枚羽織って出かけた。", "explanation": "ここは〈上着〉の意味。大地は地面を指すので、羽織る服の意味では使わない。"}, {"text": "部屋の大地が汚れたので、雑巾でふいた。", "explanation": "ここは〈床〉の意味。大地は屋外の地面を指し、部屋の床には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "飛行機を降りて踏む地面を指し、「ひさしぶりに」「踏みました」と合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は踏めるものではなく、「踏みました」の対象にならない。"}, {"text": "風", "is_correct": false, "explanation": "風は踏めるものではなく、「踏みました」と組み合わせると意味が通らない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は踏むことができず、「踏みました」の対象として不自然。"}], "explanations": {"大地": "飛行機を降りて踏む地面を指し、「ひさしぶりに」「踏みました」と合う。", "歌": "歌は踏めるものではなく、「踏みました」の対象にならない。", "風": "風は踏めるものではなく、「踏みました」と組み合わせると意味が通らない。", "空気": "空気は踏むことができず、「踏みました」の対象として不自然。"}, "sentence_index": 6, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大地に絵をかけて、部屋を明るくした。", "explanation": "ここは〈壁〉の意味。大地は地面なので、絵をかける壁の代わりには使わない。"}, {"text": "大地に大きな電球がついていて、部屋が明るい。", "explanation": "ここは〈天井〉の意味。大地は地面なので、部屋の上にある天井の代わりには使わない。"}, {"text": "大地に顔がうつり、髪の乱れに気づいた。", "explanation": "ここは〈鏡〉の意味。大地は地面で、顔を映す鏡の役割はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52709, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震で大地を亀裂が入った。", "corrected_sentence": "地震で大地に亀裂が入った。", "error_description": "「入る」は場所を示す「に」を取る。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
